/* v14: محتوى (أحاديث + قصص + سيرة) — ملف بيانات فقط */
window.MORE_HADITHS=[["h31", "مَنْ أَحْدَثَ فِي أَمْرِنَا هَذَا مَا لَيْسَ مِنْهُ فَهُوَ رَدٌّ", "عن عائشة رضي الله عنها — متفق عليه", "لا يُقبل عمل حتى يكون خالصًا لله وموافقًا لهدي النبي ﷺ، فاعرض أعمالك على السنة قبل أن تتعب فيها."], ["h32", "دَعْ مَا يَرِيبُكَ إِلَى مَا لَا يَرِيبُكَ، فَإِنَّ الصِّدْقَ طُمَأْنِينَةٌ وَإِنَّ الْكَذِبَ رِيبَةٌ", "عن الحسن بن علي رضي الله عنهما — رواه الترمذي وقال: حسن صحيح", "إذا تردد قلبك في أمر فاتركه إلى ما يطمئن إليه قلبك، فالورع حفظ للدين والقلب."], ["h33", "مِنْ حُسْنِ إِسْلَامِ الْمَرْءِ تَرْكُهُ مَا لَا يَعْنِيهِ", "عن أبي هريرة رضي الله عنه — رواه الترمذي وابن ماجه، وهو حديث حسن", "وفِّر وقتك وجهدك بترك الفضول وما لا نفع فيه، وانشغل بما ينفعك في دينك ودنياك."], ["h35", "مَنْ رَأَى مِنْكُمْ مُنْكَرًا فَلْيُغَيِّرْهُ بِيَدِهِ، فَإِنْ لَمْ يَسْتَطِعْ فَبِلِسَانِهِ، فَإِنْ لَمْ يَسْتَطِعْ فَبِقَلْبِهِ، وَذَلِكَ أَضْعَفُ الْإِيمَانِ", "عن أبي سعيد الخدري رضي الله عنه — رواه مسلم", "أنكر المنكر بحسب قدرتك وبالحكمة والرفق، ولا يكن قلبك راضيًا بما يغضب الله."], ["h37", "لَا تَقَاطَعُوا وَلَا تَدَابَرُوا وَلَا تَبَاغَضُوا وَلَا تَحَاسَدُوا، وَكُونُوا عِبَادَ اللَّهِ إِخْوَانًا، وَلَا يَحِلُّ لِمُسْلِمٍ أَنْ يَهْجُرَ أَخَاهُ فَوْقَ ثَلَاثٍ", "عن أنس بن مالك رضي الله عنه — متفق عليه", "بادر بالصلح ولا تدع الخصومة تطول، وطهِّر قلبك من الحسد والبغضاء."], ["h38", "مَا زَالَ جِبْرِيلُ يُوصِينِي بِالْجَارِ حَتَّى ظَنَنْتُ أَنَّهُ سَيُوَرِّثُهُ", "عن عائشة وابن عمر رضي الله عنهم — متفق عليه", "أحسن إلى جارك بالسلام والهدية وكفِّ الأذى وتفقُّد حاله، فحقه عظيم."], ["h39", "لَا يَدْخُلُ الْجَنَّةَ مَنْ لَا يَأْمَنُ جَارُهُ بَوَائِقَهُ", "عن أبي هريرة رضي الله عنه — رواه مسلم", "اجعل جارك آمنًا من شرك وصوتك وأذاك، فإيذاء الجار من كبائر الأخلاق."], ["h40", "خَيْرُ الْأَصْحَابِ عِنْدَ اللَّهِ خَيْرُهُمْ لِصَاحِبِهِ، وَخَيْرُ الْجِيرَانِ عِنْدَ اللَّهِ خَيْرُهُمْ لِجَارِهِ", "عن عبد الله بن عمرو رضي الله عنهما — رواه الترمذي وقال: حسن غريب", "ميزان الخيرية عند الله حسن معاملتك لصاحبك وجارك، فكن الأفضل لهما."], ["h41", "إِنَّ اللَّهَ كَتَبَ الْإِحْسَانَ عَلَى كُلِّ شَيْءٍ، فَإِذَا قَتَلْتُمْ فَأَحْسِنُوا الْقِتْلَةَ، وَإِذَا ذَبَحْتُمْ فَأَحْسِنُوا الذِّبْحَةَ، وَلْيُحِدَّ أَحَدُكُمْ شَفْرَتَهُ، وَلْيُرِحْ ذَبِيحَتَهُ", "عن شداد بن أوس رضي الله عنه — رواه مسلم", "الإحسان والإتقان خلق شامل في كل عمل حتى في أصعب المواقف، فأتقن عملك وارفق بمن تتعامل معه."], ["h42", "الْمُؤْمِنُ الْقَوِيُّ خَيْرٌ وَأَحَبُّ إِلَى اللَّهِ مِنَ الْمُؤْمِنِ الضَّعِيفِ، وَفِي كُلٍّ خَيْرٌ، احْرِصْ عَلَى مَا يَنْفَعُكَ وَاسْتَعِنْ بِاللَّهِ وَلَا تَعْجِزْ", "عن أبي هريرة رضي الله عنه — رواه مسلم", "خذ بالأسباب واجتهد فيما ينفعك، واستعن بالله، ولا تستسلم للكسل أو العجز."], ["h43", "عَجَبًا لِأَمْرِ الْمُؤْمِنِ إِنَّ أَمْرَهُ كُلَّهُ خَيْرٌ، وَلَيْسَ ذَاكَ لِأَحَدٍ إِلَّا لِلْمُؤْمِنِ: إِنْ أَصَابَتْهُ سَرَّاءُ شَكَرَ فَكَانَ خَيْرًا لَهُ، وَإِنْ أَصَابَتْهُ ضَرَّاءُ صَبَرَ فَكَانَ خَيْرًا لَهُ", "عن صهيب بن سنان رضي الله عنه — رواه مسلم", "اجعل الشكر عند النعمة والصبر عند البلاء عادتك، تكن أحوالك كلها خيرًا."], ["h44", "وَمَنْ يَتَصَبَّرْ يُصَبِّرْهُ اللَّهُ، وَمَا أُعْطِيَ أَحَدٌ عَطَاءً خَيْرًا وَأَوْسَعَ مِنَ الصَّبْرِ", "عن أبي سعيد الخدري رضي الله عنه — متفق عليه", "تكلَّف الصبر وجاهد نفسك عليه، فالله يعين من يتصبر، وهو أوسع عطاء."], ["h45", "إِنَّمَا الصَّبْرُ عِنْدَ الصَّدْمَةِ الْأُولَى", "عن أنس بن مالك رضي الله عنه — متفق عليه", "الصبر الحقيقي في لحظة وقوع المصيبة، فاضبط نفسك عند أول الخبر ولا تجزع."], ["h46", "مَا يُصِيبُ الْمُسْلِمَ مِنْ نَصَبٍ وَلَا وَصَبٍ وَلَا هَمٍّ وَلَا حُزْنٍ وَلَا أَذًى وَلَا غَمٍّ، حَتَّى الشَّوْكَةِ يُشَاكُهَا، إِلَّا كَفَّرَ اللَّهُ بِهَا مِنْ خَطَايَاهُ", "عن أبي سعيد وأبي هريرة رضي الله عنهما — متفق عليه", "تذكَّر عند الهم والتعب أن الله يكفر بهما الخطايا، فاحتسب أجرك."], ["h47", "لَوْ أَنَّكُمْ تَتَوَكَّلُونَ عَلَى اللَّهِ حَقَّ تَوَكُّلِهِ لَرَزَقَكُمْ كَمَا يَرْزُقُ الطَّيْرَ، تَغْدُو خِمَاصًا وَتَرُوحُ بِطَانًا", "عن عمر بن الخطاب رضي الله عنه — رواه الترمذي وقال: حسن صحيح", "التوكل أن تأخذ بالسبب وتعلق قلبك بالله، فالطير تسعى صباحًا ثم يرزقها الله."], ["h48", "يَا ابْنَ آدَمَ إِنَّكَ مَا دَعَوْتَنِي وَرَجَوْتَنِي غَفَرْتُ لَكَ عَلَى مَا كَانَ مِنْكَ وَلَا أُبَالِي، يَا ابْنَ آدَمَ لَوْ بَلَغَتْ ذُنُوبُكَ عَنَانَ السَّمَاءِ ثُمَّ اسْتَغْفَرْتَنِي غَفَرْتُ لَكَ وَلَا أُبَالِي", "عن أنس بن مالك رضي الله عنه — رواه الترمذي وقال: حسن غريب", "لا تيأس من كثرة الذنوب، فباب الاستغفار مفتوح، فأكثر من الدعاء والرجاء."], ["h49", "وَاللَّهِ إِنِّي لَأَسْتَغْفِرُ اللَّهَ وَأَتُوبُ إِلَيْهِ فِي الْيَوْمِ أَكْثَرَ مِنْ سَبْعِينَ مَرَّةً", "عن أبي هريرة رضي الله عنه — رواه البخاري", "إذا كان النبي ﷺ المغفور له يكثر من الاستغفار، فنحن أولى؛ فاجعل لك وردًا يوميًا منه."], ["h50", "كُلُّ ابْنِ آدَمَ خَطَّاءٌ، وَخَيْرُ الْخَطَّائِينَ التَّوَّابُونَ", "عن أنس بن مالك رضي الله عنه — رواه الترمذي وابن ماجه، وهو حديث حسن", "الخطأ طبيعة بشرية، والعيب في الإصرار عليه؛ فسارع بالتوبة بعد كل زلة."], ["h51", "يَا عِبَادِي إِنِّي حَرَّمْتُ الظُّلْمَ عَلَى نَفْسِي وَجَعَلْتُهُ بَيْنَكُمْ مُحَرَّمًا فَلَا تَظَالَمُوا", "عن أبي ذر الغفاري رضي الله عنه عن النبي ﷺ فيما يرويه عن ربه — رواه مسلم", "الظلم محرم بين الناس كلهم، فراجع نفسك في حقوق من حولك وأدِّها."], ["h52", "اتَّقُوا النَّارَ وَلَوْ بِشِقِّ تَمْرَةٍ، فَمَنْ لَمْ يَجِدْ فَبِكَلِمَةٍ طَيِّبَةٍ", "عن عدي بن حاتم رضي الله عنه — متفق عليه", "لا تستقل القليل من الصدقة، فإن لم تجد مالًا فالكلمة الطيبة تقوم مقامه."], ["h55", "مَا نَقَصَتْ صَدَقَةٌ مِنْ مَالٍ، وَمَا زَادَ اللَّهُ عَبْدًا بِعَفْوٍ إِلَّا عِزًّا، وَمَا تَوَاضَعَ أَحَدٌ لِلَّهِ إِلَّا رَفَعَهُ اللَّهُ", "عن أبي هريرة رضي الله عنه — رواه مسلم", "الصدقة تبارك المال، والعفو يرفع صاحبه، والتواضع رفعة؛ فاعمل بها ثقةً بوعد الله."], ["h56", "مَا مِنْ يَوْمٍ يُصْبِحُ الْعِبَادُ فِيهِ إِلَّا مَلَكَانِ يَنْزِلَانِ، فَيَقُولُ أَحَدُهُمَا: اللَّهُمَّ أَعْطِ مُنْفِقًا خَلَفًا، وَيَقُولُ الْآخَرُ: اللَّهُمَّ أَعْطِ مُمْسِكًا تَلَفًا", "عن أبي هريرة رضي الله عنه — متفق عليه", "أنفق في وجوه الخير ولا تخش الفقر، فالملائكة تدعو للمنفق كل صباح."], ["h57", "الْيَدُ الْعُلْيَا خَيْرٌ مِنَ الْيَدِ السُّفْلَى", "عن عبد الله بن عمر رضي الله عنهما — متفق عليه", "كن معطيًا لا سائلًا ما استطعت، واعمل لتستغني عن الناس وتنفق عليهم."], ["h58", "سَبْعَةٌ يُظِلُّهُمُ اللَّهُ فِي ظِلِّهِ يَوْمَ لَا ظِلَّ إِلَّا ظِلُّهُ: الْإِمَامُ الْعَادِلُ، وَشَابٌّ نَشَأَ فِي عِبَادَةِ رَبِّهِ، وَرَجُلٌ قَلْبُهُ مُعَلَّقٌ فِي الْمَسَاجِدِ، وَرَجُلَانِ تَحَابَّا فِي اللَّهِ اجْتَمَعَا عَلَيْهِ وَتَفَرَّقَا عَلَيْهِ، وَرَجُلٌ طَلَبَتْهُ امْرَأَةٌ ذَاتُ مَنْصِبٍ وَجَمَالٍ فَقَالَ: إِنِّي أَخَافُ اللَّهَ، وَرَجُلٌ تَصَدَّقَ بِصَدَقَةٍ فَأَخْفَاهَا حَتَّى لَا تَعْلَمَ شِمَالُهُ مَا تُنْفِقُ يَمِينُهُ، وَرَجُلٌ ذَكَرَ اللَّهَ خَالِيًا فَفَاضَتْ عَيْنَاهُ", "عن أبي هريرة رضي الله عنه — متفق عليه", "أخفِ صدقتك واذكر الله في خلوتك، فالإخلاص في السر طريق الظل يوم القيامة."], ["h59", "إِنَّ الصِّدْقَ يَهْدِي إِلَى الْبِرِّ، وَإِنَّ الْبِرَّ يَهْدِي إِلَى الْجَنَّةِ، وَمَا يَزَالُ الرَّجُلُ يَصْدُقُ حَتَّى يُكْتَبَ عِنْدَ اللَّهِ صِدِّيقًا، وَإِنَّ الْكَذِبَ يَهْدِي إِلَى الْفُجُورِ، وَإِنَّ الْفُجُورَ يَهْدِي إِلَى النَّارِ، وَمَا يَزَالُ الرَّجُلُ يَكْذِبُ حَتَّى يُكْتَبَ عِنْدَ اللَّهِ كَذَّابًا", "عن عبد الله بن مسعود رضي الله عنه — متفق عليه", "تحرَّ الصدق في كل كلمة حتى يصير سجية لك، وابتعد عن الكذب ولو كان صغيرًا."], ["h60", "آيَةُ الْمُنَافِقِ ثَلَاثٌ: إِذَا حَدَّثَ كَذَبَ، وَإِذَا وَعَدَ أَخْلَفَ، وَإِذَا اؤْتُمِنَ خَانَ", "عن أبي هريرة رضي الله عنه — متفق عليه", "صدق الحديث والوفاء بالوعد وأداء الأمانة علامات الإيمان، فراقب نفسك فيها."], ["h61", "إِذَا ضُيِّعَتِ الْأَمَانَةُ فَانْتَظِرِ السَّاعَةَ", "عن أبي هريرة رضي الله عنه — رواه البخاري", "الأمانة قوام المجتمع، فأدِّ ما ائتُمنت عليه من مال وعمل وسر ومسؤولية."], ["h62", "رَغِمَ أَنْفُهُ ثُمَّ رَغِمَ أَنْفُهُ ثُمَّ رَغِمَ أَنْفُهُ، قِيلَ: مَنْ يَا رَسُولَ اللَّهِ؟ قَالَ: مَنْ أَدْرَكَ وَالِدَيْهِ عِنْدَ الْكِبَرِ، أَحَدَهُمَا أَوْ كِلَيْهِمَا، ثُمَّ لَمْ يَدْخُلِ الْجَنَّةَ", "عن أبي هريرة رضي الله عنه — رواه مسلم", "كِبَر الوالدين فرصة عظيمة لدخول الجنة بخدمتهما، فلا تفرِّط فيها بالتقصير."], ["h63", "جَاءَ رَجُلٌ إِلَى رَسُولِ اللَّهِ ﷺ فَقَالَ: يَا رَسُولَ اللَّهِ، مَنْ أَحَقُّ النَّاسِ بِحُسْنِ صَحَابَتِي؟ قَالَ: أُمُّكَ، قَالَ: ثُمَّ مَنْ؟ قَالَ: ثُمَّ أُمُّكَ، قَالَ: ثُمَّ مَنْ؟ قَالَ: ثُمَّ أُمُّكَ، قَالَ: ثُمَّ مَنْ؟ قَالَ: ثُمَّ أَبُوكَ", "عن أبي هريرة رضي الله عنه — متفق عليه", "قدِّم برَّ الأم وأكثر من الإحسان إليها، ثم الأب، بالصحبة الحسنة والخدمة والدعاء."], ["h64", "سَأَلْتُ النَّبِيَّ ﷺ: أَيُّ الْعَمَلِ أَحَبُّ إِلَى اللَّهِ؟ قَالَ: الصَّلَاةُ عَلَى وَقْتِهَا، قُلْتُ: ثُمَّ أَيٌّ؟ قَالَ: ثُمَّ بِرُّ الْوَالِدَيْنِ، قُلْتُ: ثُمَّ أَيٌّ؟ قَالَ: الْجِهَادُ فِي سَبِيلِ اللَّهِ", "عن عبد الله بن مسعود رضي الله عنه — متفق عليه", "حافظ على الصلاة في وقتها، وقرن ذلك ببر الوالدين فهو من أحب الأعمال إلى الله."], ["h65", "الْوَالِدُ أَوْسَطُ أَبْوَابِ الْجَنَّةِ، فَأَضِعْ ذَلِكَ الْبَابَ أَوِ احْفَظْهُ", "عن أبي الدرداء رضي الله عنه — رواه الترمذي وقال: حسن صحيح", "رضا الوالدين باب إلى الجنة، فاحرص على إبقائه مفتوحًا بالطاعة والإحسان."], ["h66", "مَنْ أَحَبَّ أَنْ يُبْسَطَ لَهُ فِي رِزْقِهِ، وَيُنْسَأَ لَهُ فِي أَثَرِهِ، فَلْيَصِلْ رَحِمَهُ", "عن أنس بن مالك رضي الله عنه — متفق عليه", "صلة الرحم سبب لسعة الرزق وبركة العمر، فتواصل مع أقاربك بالزيارة والاتصال."], ["h67", "لَا يَدْخُلُ الْجَنَّةَ قَاطِعٌ", "عن جبير بن مطعم رضي الله عنه — متفق عليه (والمراد قاطع الرحم)", "احذر قطيعة الرحم مهما كان بينكم، وسارع إلى الصلح والسؤال."], ["h68", "لَيْسَ الْوَاصِلُ بِالْمُكَافِئِ، وَلَكِنَّ الْوَاصِلَ الَّذِي إِذَا قُطِعَتْ رَحِمُهُ وَصَلَهَا", "عن عبد الله بن عمرو رضي الله عنهما — رواه البخاري", "صِل من قطعك، فالوصل الحقيقي ألا تنتظر المقابل بل تبدأ أنت بالإحسان."], ["h69", "إِنَّ مِنْ خِيَارِكُمْ أَحْسَنَكُمْ أَخْلَاقًا", "عن عبد الله بن عمرو رضي الله عنهما — متفق عليه", "اجعل الخلق الحسن مقياس خيريتك، وتعامل مع الناس بما تحب أن يعاملوك به."], ["h70", "مَا مِنْ شَيْءٍ أَثْقَلُ فِي مِيزَانِ الْمُؤْمِنِ يَوْمَ الْقِيَامَةِ مِنْ خُلُقٍ حَسَنٍ، وَإِنَّ اللَّهَ لَيُبْغِضُ الْفَاحِشَ الْبَذِيءَ", "عن أبي الدرداء رضي الله عنه — رواه الترمذي وقال: حسن صحيح", "حسن الخلق أثقل ما في الميزان، فاستثمر كل موقف يومي في تحسين خلقك."], ["h71", "أَكْمَلُ الْمُؤْمِنِينَ إِيمَانًا أَحْسَنُهُمْ خُلُقًا، وَخِيَارُكُمْ خِيَارُكُمْ لِنِسَائِهِمْ", "عن أبي هريرة رضي الله عنه — رواه الترمذي وقال: حسن صحيح", "كمال الإيمان يظهر في المعاملة، وأول من يستحق حسن خلقك أهل بيتك."], ["h72", "خَيْرُكُمْ خَيْرُكُمْ لِأَهْلِهِ، وَأَنَا خَيْرُكُمْ لِأَهْلِي", "عن عائشة رضي الله عنها — رواه الترمذي وابن ماجه، وهو حديث صحيح", "كن لطيفًا مع أهلك وشاركهم وأدخل السرور عليهم، فهذه هي الخيرية الحقة."], ["h73", "لَا يَفْرَكْ مُؤْمِنٌ مُؤْمِنَةً، إِنْ كَرِهَ مِنْهَا خُلُقًا رَضِيَ مِنْهَا آخَرَ", "عن أبي هريرة رضي الله عنه — رواه مسلم", "انظر إلى محاسن شريك حياتك ولا تجعل عيبًا واحدًا يُنسيك فضائله."], ["h74", "كُلُّكُمْ رَاعٍ، وَكُلُّكُمْ مَسْئُولٌ عَنْ رَعِيَّتِهِ؛ الْإِمَامُ رَاعٍ وَمَسْئُولٌ عَنْ رَعِيَّتِهِ، وَالرَّجُلُ رَاعٍ فِي أَهْلِهِ وَهُوَ مَسْئُولٌ عَنْ رَعِيَّتِهِ، وَالْمَرْأَةُ رَاعِيَةٌ فِي بَيْتِ زَوْجِهَا وَمَسْئُولَةٌ عَنْ رَعِيَّتِهَا، وَالْخَادِمُ رَاعٍ فِي مَالِ سَيِّدِهِ وَمَسْئُولٌ عَنْ رَعِيَّتِهِ", "عن عبد الله بن عمر رضي الله عنهما — متفق عليه", "كل واحد مسؤول عمن تحت يده في بيته وعمله، فأحسن رعايتهم وأدِّ حقوقهم."], ["h75", "إِنَّ الرِّفْقَ لَا يَكُونُ فِي شَيْءٍ إِلَّا زَانَهُ، وَلَا يُنْزَعُ مِنْ شَيْءٍ إِلَّا شَانَهُ", "عن عائشة رضي الله عنها — رواه مسلم", "اجعل الرفق شعارك في القول والعمل مع أهلك وزملائك، فهو زينة لكل أمر."], ["h76", "مَنْ يُحْرَمِ الرِّفْقَ يُحْرَمِ الْخَيْرَ", "عن جرير بن عبد الله رضي الله عنه — رواه مسلم", "ترك الرفق حرمان من خير كثير، فتمهَّل في معاملاتك ولاطف من تخاطبه."], ["h77", "لَيْسَ الشَّدِيدُ بِالصُّرَعَةِ، إِنَّمَا الشَّدِيدُ الَّذِي يَمْلِكُ نَفْسَهُ عِنْدَ الْغَضَبِ", "عن أبي هريرة رضي الله عنه — متفق عليه", "القوة في ضبط النفس لا في الغلبة، فإذا ثار غضبك فتوقف وتنفس ولا تتكلم."], ["h78", "لَيْسَ الْمُؤْمِنُ بِالطَّعَّانِ وَلَا اللَّعَّانِ وَلَا الْفَاحِشِ وَلَا الْبَذِيءِ", "عن عبد الله بن مسعود رضي الله عنه — رواه الترمذي وقال: حسن غريب", "نزِّه لسانك عن الطعن والسباب والفحش، وعوِّده الكلام الطيب."], ["h79", "إِنَّ الْعَبْدَ لَيَتَكَلَّمُ بِالْكَلِمَةِ مِنْ رِضْوَانِ اللَّهِ، لَا يُلْقِي لَهَا بَالًا، يَرْفَعُهُ اللَّهُ بِهَا دَرَجَاتٍ، وَإِنَّ الْعَبْدَ لَيَتَكَلَّمُ بِالْكَلِمَةِ مِنْ سَخَطِ اللَّهِ، لَا يُلْقِي لَهَا بَالًا، يَهْوِي بِهَا فِي جَهَنَّمَ", "عن أبي هريرة رضي الله عنه — رواه البخاري", "كلمة عابرة قد ترفعك أو تهلكك، فزِن كلامك قبل النطق واستحضر مراقبة الله."], ["h80", "مَنْ يَضْمَنْ لِي مَا بَيْنَ لَحْيَيْهِ وَمَا بَيْنَ رِجْلَيْهِ أَضْمَنْ لَهُ الْجَنَّةَ", "عن سهل بن سعد رضي الله عنه — رواه البخاري", "حفظ اللسان والفرج طريق مضمون إلى الجنة، فاجعل هذين الأمرين أولوية في مجاهدة نفسك."], ["h81", "أَتَدْرُونَ مَا الْغِيبَةُ؟ قَالُوا: اللَّهُ وَرَسُولُهُ أَعْلَمُ، قَالَ: ذِكْرُكَ أَخَاكَ بِمَا يَكْرَهُ، قِيلَ: أَفَرَأَيْتَ إِنْ كَانَ فِي أَخِي مَا أَقُولُ؟ قَالَ: إِنْ كَانَ فِيهِ مَا تَقُولُ فَقَدِ اغْتَبْتَهُ، وَإِنْ لَمْ يَكُنْ فِيهِ فَقَدْ بَهَتَّهُ", "عن أبي هريرة رضي الله عنه — رواه مسلم", "إذا جرى ذكر غائب بما يكره فانهَ عنه أو غيِّر الحديث أو اترك المجلس."], ["h82", "لَا يَدْخُلُ الْجَنَّةَ نَمَّامٌ", "عن حذيفة بن اليمان رضي الله عنه — متفق عليه", "لا تنقل كلام الناس بقصد الإفساد، وكن مصلحًا بين الناس لا مفرِّقًا."], ["h83", "إِيَّاكُمْ وَالظَّنَّ، فَإِنَّ الظَّنَّ أَكْذَبُ الْحَدِيثِ، وَلَا تَجَسَّسُوا وَلَا تَحَسَّسُوا وَلَا تَنَافَسُوا وَلَا تَحَاسَدُوا وَلَا تَبَاغَضُوا وَلَا تَدَابَرُوا، وَكُونُوا عِبَادَ اللَّهِ إِخْوَانًا", "عن أبي هريرة رضي الله عنه — متفق عليه", "احمل أخاك على أحسن المحامل ولا تتبع عوراته، تسلَم من الشحناء ويصفُ قلبك."], ["h84", "كَفَى بِالْمَرْءِ كَذِبًا أَنْ يُحَدِّثَ بِكُلِّ مَا سَمِعَ", "عن أبي هريرة رضي الله عنه — رواه مسلم", "تثبَّت قبل أن تنقل أي خبر، فليس كل ما يُسمع صحيحًا ولا كل صحيح يُقال."], ["h86", "مَنْ يُرِدِ اللَّهُ بِهِ خَيْرًا يُفَقِّهْهُ فِي الدِّينِ", "عن معاوية بن أبي سفيان رضي الله عنه — متفق عليه", "الفقه في الدين علامة إرادة الله بك الخير، فتعلَّم أحكام دينك وسل أهل العلم."], ["h87", "إِذَا مَاتَ الْإِنْسَانُ انْقَطَعَ عَنْهُ عَمَلُهُ إِلَّا مِنْ ثَلَاثَةٍ: إِلَّا مِنْ صَدَقَةٍ جَارِيَةٍ، أَوْ عِلْمٍ يُنْتَفَعُ بِهِ، أَوْ وَلَدٍ صَالِحٍ يَدْعُو لَهُ", "عن أبي هريرة رضي الله عنه — رواه مسلم", "ازرع ما يبقى أثره بعد موتك: صدقة جارية وعلم تنشره وولد صالح تربيه."], ["h88", "بَلِّغُوا عَنِّي وَلَوْ آيَةً", "عن عبد الله بن عمرو رضي الله عنهما — رواه البخاري", "لا تحتقر ما تعلمته، بلِّغه لغيرك ولو قليلًا، فالدعوة والتعليم متاحان للجميع."], ["h89", "نَضَّرَ اللَّهُ امْرَأً سَمِعَ مِنَّا شَيْئًا فَبَلَّغَهُ كَمَا سَمِعَهُ، فَرُبَّ مُبَلَّغٍ أَوْعَى مِنْ سَامِعٍ", "عن عبد الله بن مسعود رضي الله عنه — رواه الترمذي وقال: حسن صحيح", "أدِّ العلم بأمانة دون تحريف، فقد يكون من يبلغه أفهم وأنفع منك."], ["h90", "نِعْمَتَانِ مَغْبُونٌ فِيهِمَا كَثِيرٌ مِنَ النَّاسِ: الصِّحَّةُ وَالْفَرَاغُ", "عن عبد الله بن عباس رضي الله عنهما — رواه البخاري", "استثمر صحتك ووقت فراغك فيما ينفعك قبل أن تُحرم منهما."], ["h91", "لَا تَزُولُ قَدَمَا عَبْدٍ يَوْمَ الْقِيَامَةِ حَتَّى يُسْأَلَ عَنْ عُمُرِهِ فِيمَا أَفْنَاهُ، وَعَنْ عِلْمِهِ فِيمَ فَعَلَ، وَعَنْ مَالِهِ مِنْ أَيْنَ اكْتَسَبَهُ وَفِيمَ أَنْفَقَهُ، وَعَنْ جِسْمِهِ فِيمَ أَبْلَاهُ", "عن أبي برزة الأسلمي رضي الله عنه — رواه الترمذي وقال: حسن صحيح", "حاسب نفسك على وقتك وعلمك ومالك وصحتك قبل أن تُحاسَب عليها."], ["h92", "إِنَّ الْحَلَالَ بَيِّنٌ، وَإِنَّ الْحَرَامَ بَيِّنٌ، وَبَيْنَهُمَا أُمُورٌ مُشْتَبِهَاتٌ لَا يَعْلَمُهُنَّ كَثِيرٌ مِنَ النَّاسِ، فَمَنِ اتَّقَى الشُّبُهَاتِ فَقَدِ اسْتَبْرَأَ لِدِينِهِ وَعِرْضِهِ، وَمَنْ وَقَعَ فِي الشُّبُهَاتِ وَقَعَ فِي الْحَرَامِ، كَالرَّاعِي يَرْعَى حَوْلَ الْحِمَى يُوشِكُ أَنْ يَرْتَعَ فِيهِ، أَلَا وَإِنَّ لِكُلِّ مَلِكٍ حِمًى، أَلَا وَإِنَّ حِمَى اللَّهِ مَحَارِمُهُ، أَلَا وَإِنَّ فِي الْجَسَدِ مُضْغَةً إِذَا صَلَحَتْ صَلَحَ الْجَسَدُ كُلُّهُ، وَإِذَا فَسَدَتْ فَسَدَ الْجَسَدُ كُلُّهُ، أَلَا وَهِيَ الْقَلْبُ", "عن النعمان بن بشير رضي الله عنهما — متفق عليه", "ابتعد عن الشبهات صيانةً لدينك، واعتنِ بإصلاح قلبك فهو أصل صلاح الأعمال كلها."], ["h94", "كَلِمَتَانِ خَفِيفَتَانِ عَلَى اللِّسَانِ، ثَقِيلَتَانِ فِي الْمِيزَانِ، حَبِيبَتَانِ إِلَى الرَّحْمَنِ: سُبْحَانَ اللَّهِ وَبِحَمْدِهِ، سُبْحَانَ اللَّهِ الْعَظِيمِ", "عن أبي هريرة رضي الله عنه — متفق عليه", "اجعل هذا الذكر القصير على لسانك في كل وقت، فهو خفيف في النطق عظيم في الأجر."], ["h95", "مَنْ قَالَ: سُبْحَانَ اللَّهِ وَبِحَمْدِهِ، فِي يَوْمٍ مِائَةَ مَرَّةٍ، حُطَّتْ خَطَايَاهُ وَإِنْ كَانَتْ مِثْلَ زَبَدِ الْبَحْرِ", "عن أبي هريرة رضي الله عنه — متفق عليه", "حافظ على مائة تسبيحة كل يوم، فهي تكفير للخطايا ولو كثرت."], ["h96", "أَحَبُّ الْكَلَامِ إِلَى اللَّهِ أَرْبَعٌ: سُبْحَانَ اللَّهِ، وَالْحَمْدُ لِلَّهِ، وَلَا إِلَهَ إِلَّا اللَّهُ، وَاللَّهُ أَكْبَرُ، لَا يَضُرُّكَ بِأَيِّهِنَّ بَدَأْتَ", "عن سمرة بن جندب رضي الله عنه — رواه مسلم", "هذه الكلمات الأربع أحب الكلام إلى الله، فاجعلها ذكرك في المواصلات وأوقات الفراغ."], ["h97", "مَنْ صَلَّى عَلَيَّ صَلَاةً صَلَّى اللَّهُ عَلَيْهِ بِهَا عَشْرًا", "عن أبي هريرة رضي الله عنه — رواه مسلم", "أكثر من الصلاة على النبي ﷺ، فكل مرة بعشر صلوات من الله عليك."], ["h98", "الدُّعَاءُ هُوَ الْعِبَادَةُ", "عن النعمان بن بشير رضي الله عنهما — رواه الترمذي وقال: حسن صحيح", "الجأ إلى الله في كل حاجة صغيرة وكبيرة، فالدعاء عبادة وقرب من الله."], ["h99", "كُنْ فِي الدُّنْيَا كَأَنَّكَ غَرِيبٌ أَوْ عَابِرُ سَبِيلٍ", "عن عبد الله بن عمر رضي الله عنهما — رواه البخاري", "لا تتعلق بالدنيا تعلقًا يشغلك عن الآخرة، واعمل لما بعد الرحيل."], ["h100", "لَيْسَ الْغِنَى عَنْ كَثْرَةِ الْعَرَضِ، وَلَكِنَّ الْغِنَى غِنَى النَّفْسِ", "عن أبي هريرة رضي الله عنه — متفق عليه", "القناعة هي الغنى الحقيقي، فارضَ بما قسم الله لك تعش مطمئنًا."], ["h101", "فِي كُلِّ كَبِدٍ رَطْبَةٍ أَجْرٌ", "عن أبي هريرة رضي الله عنه — متفق عليه", "الإحسان إلى الحيوان من أبواب الأجر، فسقيُ كلبٍ عطشانَ أو إطعامُ هرّةٍ جائعة عملٌ يُثاب عليه صاحبه."], ["h102", "دَخَلَتِ امْرَأَةٌ النَّارَ فِي هِرَّةٍ رَبَطَتْهَا، فَلَمْ تُطْعِمْهَا وَلَمْ تَدَعْهَا تَأْكُلُ مِنْ خَشَاشِ الْأَرْضِ", "عن عبد الله بن عمر رضي الله عنهما — متفق عليه", "حبس الحيوان دون إطعامه ظلمٌ عظيم، فمن ملك دابةً أو هرّةً فعليه نفقتها ورعايتها."], ["h103", "إِنَّ اللَّهَ كَتَبَ الْإِحْسَانَ عَلَى كُلِّ شَيْءٍ، فَإِذَا قَتَلْتُمْ فَأَحْسِنُوا الْقِتْلَةَ، وَإِذَا ذَبَحْتُمْ فَأَحْسِنُوا الذَّبْحَ، وَلْيُحِدَّ أَحَدُكُمْ شَفْرَتَهُ، وَلْيُرِحْ ذَبِيحَتَهُ", "عن شداد بن أوس رضي الله عنه — رواه مسلم", "الرحمة تشمل حتى لحظة الذبح، فاحرص على حدّ السكين وإراحة الذبيحة وعدم تعذيبها."], ["h104", "إِنَّ اللَّهَ رَفِيقٌ يُحِبُّ الرِّفْقَ، وَيُعْطِي عَلَى الرِّفْقِ مَا لَا يُعْطِي عَلَى الْعُنْفِ، وَمَا لَا يُعْطِي عَلَى مَا سِوَاهُ", "عن عائشة رضي الله عنها — رواه مسلم", "اجعل الرفق أسلوبك في الأمر والنهي والتربية والعمل، فنتائجه أبلغ من الشدة."], ["h105", "إِنَّ الْمُقْسِطِينَ عِنْدَ اللَّهِ عَلَى مَنَابِرَ مِنْ نُورٍ، عَنْ يَمِينِ الرَّحْمَنِ عَزَّ وَجَلَّ، وَكِلْتَا يَدَيْهِ يَمِينٌ، الَّذِينَ يَعْدِلُونَ فِي حُكْمِهِمْ وَأَهْلِيهِمْ وَمَا وَلُوا", "عن عبد الله بن عمرو رضي الله عنهما — رواه مسلم", "العدل يبدأ من بيتك ومن كل مسؤولية بين يديك، فاعدل بين أهلك وأولادك ومن تدير شؤونهم."], ["h106", "اتَّقُوا الظُّلْمَ، فَإِنَّ الظُّلْمَ ظُلُمَاتٌ يَوْمَ الْقِيَامَةِ", "عن جابر رضي الله عنه — رواه مسلم", "لا تستصغر حقًّا لأحد عندك، فرُدَّ المظالم وتحلَّل من أصحابها قبل أن يأتي يوم لا درهم فيه ولا دينار."], ["h107", "سَبْعَةٌ يُظِلُّهُمُ اللَّهُ فِي ظِلِّهِ يَوْمَ لَا ظِلَّ إِلَّا ظِلُّهُ: الْإِمَامُ الْعَادِلُ، وَشَابٌّ نَشَأَ فِي عِبَادَةِ اللَّهِ، وَرَجُلٌ قَلْبُهُ مُعَلَّقٌ فِي الْمَسَاجِدِ، وَرَجُلَانِ تَحَابَّا فِي اللَّهِ اجْتَمَعَا عَلَيْهِ وَتَفَرَّقَا عَلَيْهِ، وَرَجُلٌ طَلَبَتْهُ امْرَأَةٌ ذَاتُ مَنْصِبٍ وَجَمَالٍ فَقَالَ: إِنِّي أَخَافُ اللَّهَ، وَرَجُلٌ تَصَدَّقَ بِصَدَقَةٍ فَأَخْفَاهَا حَتَّى لَا تَعْلَمَ شِمَالُهُ مَا تُنْفِقُ يَمِينُهُ، وَرَجُلٌ ذَكَرَ اللَّهَ خَالِيًا فَفَاضَتْ عَيْنَاهُ", "عن أبي هريرة رضي الله عنه — متفق عليه", "اختر لنفسك خصلة من السبع تلتزمها، فكلها أخلاق عملية: عدل، وعفة، وإخفاء للصدقة، وخلوة بالذكر."], ["h109", "كُلُّكُمْ رَاعٍ وَكُلُّكُمْ مَسْؤُولٌ عَنْ رَعِيَّتِهِ، الْإِمَامُ رَاعٍ وَمَسْؤُولٌ عَنْ رَعِيَّتِهِ، وَالرَّجُلُ رَاعٍ فِي أَهْلِهِ وَهُوَ مَسْؤُولٌ عَنْ رَعِيَّتِهِ، وَالْمَرْأَةُ رَاعِيَةٌ فِي بَيْتِ زَوْجِهَا وَمَسْؤُولَةٌ عَنْ رَعِيَّتِهَا، وَالْخَادِمُ رَاعٍ فِي مَالِ سَيِّدِهِ وَمَسْؤُولٌ عَنْ رَعِيَّتِهِ", "عن عبد الله بن عمر رضي الله عنهما — متفق عليه", "اسأل نفسك: من هم الذين في رعايتي، وهل أديت حقهم من التوجيه والنفقة والعدل؟"], ["h110", "عُرِضَتْ عَلَيَّ أَعْمَالُ أُمَّتِي حَسَنُهَا وَسَيِّئُهَا، فَوَجَدْتُ فِي مَحَاسِنِ أَعْمَالِهَا الْأَذَى يُمَاطُ عَنِ الطَّرِيقِ", "عن أبي ذر رضي الله عنه — رواه مسلم", "إزالة حجرٍ أو قشرةٍ أو شوكةٍ من طريق الناس عملٌ يسير وأجره مدخور."], ["h111", "بَيْنَمَا رَجُلٌ يَمْشِي بِطَرِيقٍ وَجَدَ غُصْنَ شَوْكٍ عَلَى الطَّرِيقِ فَأَخَّرَهُ، فَشَكَرَ اللَّهُ لَهُ فَغَفَرَ لَهُ", "عن أبي هريرة رضي الله عنه — متفق عليه", "قد يكون سبب مغفرتك عملًا صغيرًا ينفع الناس، فلا تحتقر من المعروف شيئًا."], ["h112", "الْإِيمَانُ بِضْعٌ وَسَبْعُونَ، أَوْ بِضْعٌ وَسِتُّونَ، شُعْبَةً، فَأَفْضَلُهَا قَوْلُ لَا إِلَهَ إِلَّا اللَّهُ، وَأَدْنَاهَا إِمَاطَةُ الْأَذَى عَنِ الطَّرِيقِ، وَالْحَيَاءُ شُعْبَةٌ مِنَ الْإِيمَانِ", "عن أبي هريرة رضي الله عنه — رواه مسلم", "الإيمان عقيدة وسلوك معًا، فمن أعلى شعبه التوحيد ومن أدناها نفع الناس في طريقهم."], ["h116", "قَدْ أَفْلَحَ مَنْ أَسْلَمَ وَرُزِقَ كَفَافًا وَقَنَّعَهُ اللَّهُ بِمَا آتَاهُ", "عن عبد الله بن عمرو رضي الله عنهما — رواه مسلم", "اسأل الله الكفاف والقناعة، فهما سبب راحة القلب وبعدٌ عن الجشع."], ["h117", "انْظُرُوا إِلَى مَنْ هُوَ أَسْفَلَ مِنْكُمْ وَلَا تَنْظُرُوا إِلَى مَنْ هُوَ فَوْقَكُمْ، فَهُوَ أَجْدَرُ أَنْ لَا تَزْدَرُوا نِعْمَةَ اللَّهِ عَلَيْكُمْ", "عن أبي هريرة رضي الله عنه — رواه مسلم", "قارن نفسك بمن هو دونك في الدنيا ليزداد شكرك، وبمن هو فوقك في الطاعة ليزداد اجتهادك."], ["h118", "مَا ذِئْبَانِ جَائِعَانِ أُرْسِلَا فِي غَنَمٍ بِأَفْسَدَ لَهَا مِنْ حِرْصِ الْمَرْءِ عَلَى الْمَالِ وَالشَّرَفِ لِدِينِهِ", "عن كعب بن مالك رضي الله عنه — رواه الترمذي وقال: حسن صحيح", "الحرص على المال والجاه يأكل الدين، فاجعل الدنيا في يدك لا في قلبك."], ["h120", "يُسْتَجَابُ لِأَحَدِكُمْ مَا لَمْ يَعْجَلْ، يَقُولُ: دَعَوْتُ فَلَمْ يُسْتَجَبْ لِي", "عن أبي هريرة رضي الله عنه — متفق عليه", "لا تستعجل الإجابة ولا تيأس، فالله يجيب بما هو أصلح لك في الوقت المناسب."], ["h121", "يَنْزِلُ رَبُّنَا تَبَارَكَ وَتَعَالَى كُلَّ لَيْلَةٍ إِلَى السَّمَاءِ الدُّنْيَا حِينَ يَبْقَى ثُلُثُ اللَّيْلِ الْآخِرُ، يَقُولُ: مَنْ يَدْعُونِي فَأَسْتَجِيبَ لَهُ، مَنْ يَسْأَلُنِي فَأُعْطِيَهُ، مَنْ يَسْتَغْفِرُنِي فَأَغْفِرَ لَهُ", "عن أبي هريرة رضي الله عنه — متفق عليه", "اجعل لك نصيبًا من آخر الليل ولو ركعتين ودعاءً، فهو وقت إجابة ومغفرة."], ["h122", "دَعْوَةُ الْمَرْءِ الْمُسْلِمِ لِأَخِيهِ بِظَهْرِ الْغَيْبِ مُسْتَجَابَةٌ، عِنْدَ رَأْسِهِ مَلَكٌ مُوَكَّلٌ، كُلَّمَا دَعَا لِأَخِيهِ بِخَيْرٍ قَالَ الْمَلَكُ الْمُوَكَّلُ بِهِ: آمِينَ وَلَكَ بِمِثْلٍ", "عن أبي الدرداء رضي الله عنه — رواه مسلم", "ادعُ لإخوانك في غيبتهم، فدعاؤك لهم يعود عليك بمثله."], ["h123", "أَقْرَبُ مَا يَكُونُ الْعَبْدُ مِنْ رَبِّهِ وَهُوَ سَاجِدٌ، فَأَكْثِرُوا الدُّعَاءَ", "عن أبي هريرة رضي الله عنه — رواه مسلم", "ادعُ في سجودك بحاجاتك، فهو من مواطن القرب والإجابة."], ["h124", "اللَّهُمَّ إِنِّي أَسْأَلُكَ الْهُدَى وَالتُّقَى وَالْعَفَافَ وَالْغِنَى", "عن عبد الله بن مسعود رضي الله عنه — رواه مسلم", "دعاء جامع لخير الدين والدنيا: هداية، وتقوى، وعفة عن الحرام، وغنى عن الناس."], ["h125", "مَثَلُ الَّذِي يَذْكُرُ رَبَّهُ وَالَّذِي لَا يَذْكُرُ رَبَّهُ مَثَلُ الْحَيِّ وَالْمَيِّتِ", "عن أبي موسى الأشعري رضي الله عنه — رواه البخاري", "الذكر حياة القلب، فاجعل لك وردًا يوميًّا لا تتركه."], ["h127", "لَأَنْ أَقُولَ: سُبْحَانَ اللَّهِ، وَالْحَمْدُ لِلَّهِ، وَلَا إِلَهَ إِلَّا اللَّهُ، وَاللَّهُ أَكْبَرُ، أَحَبُّ إِلَيَّ مِمَّا طَلَعَتْ عَلَيْهِ الشَّمْسُ", "عن أبي هريرة رضي الله عنه — رواه مسلم", "الباقيات الصالحات خير من الدنيا وما فيها، فاستكثر منها."], ["h129", "مَنْ قَالَ: لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، فِي يَوْمٍ مِائَةَ مَرَّةٍ، كَانَتْ لَهُ عَدْلَ عَشْرِ رِقَابٍ، وَكُتِبَتْ لَهُ مِائَةُ حَسَنَةٍ، وَمُحِيَتْ عَنْهُ مِائَةُ سَيِّئَةٍ، وَكَانَتْ لَهُ حِرْزًا مِنَ الشَّيْطَانِ يَوْمَهُ ذَلِكَ حَتَّى يُمْسِيَ، وَلَمْ يَأْتِ أَحَدٌ بِأَفْضَلَ مِمَّا جَاءَ بِهِ إِلَّا أَحَدٌ عَمِلَ أَكْثَرَ مِنْ ذَلِكَ", "عن أبي هريرة رضي الله عنه — متفق عليه", "اقرأه في الصباح لتكون في حرز من الشيطان طوال يومك."], ["h130", "أَرَأَيْتُمْ لَوْ أَنَّ نَهَرًا بِبَابِ أَحَدِكُمْ يَغْتَسِلُ مِنْهُ كُلَّ يَوْمٍ خَمْسَ مَرَّاتٍ، هَلْ يَبْقَى مِنْ دَرَنِهِ شَيْءٌ؟ قَالُوا: لَا يَبْقَى مِنْ دَرَنِهِ شَيْءٌ، قَالَ: فَذَلِكَ مَثَلُ الصَّلَوَاتِ الْخَمْسِ، يَمْحُو اللَّهُ بِهِنَّ الْخَطَايَا", "عن أبي هريرة رضي الله عنه — متفق عليه", "حافظ على الصلوات الخمس في أوقاتها، فهي تطهير يومي للقلب من الذنوب."], ["h131", "الصَّلَوَاتُ الْخَمْسُ، وَالْجُمُعَةُ إِلَى الْجُمُعَةِ، وَرَمَضَانُ إِلَى رَمَضَانَ، مُكَفِّرَاتٌ مَا بَيْنَهُنَّ إِذَا اجْتَنَبَ الْكَبَائِرَ", "عن أبي هريرة رضي الله عنه — رواه مسلم", "اجتنب الكبائر لتنال تكفير الصغائر بهذه العبادات المتكررة."], ["h132", "أَوَّلُ مَا يُحَاسَبُ بِهِ الْعَبْدُ يَوْمَ الْقِيَامَةِ مِنْ عَمَلِهِ صَلَاتُهُ، فَإِنْ صَلَحَتْ فَقَدْ أَفْلَحَ وَأَنْجَحَ، وَإِنْ فَسَدَتْ فَقَدْ خَابَ وَخَسِرَ", "عن أبي هريرة رضي الله عنه — رواه الترمذي وقال: حسن غريب", "اجعل صلاتك أعظم همّك، فصلاحها مفتاح صلاح سائر عملك."], ["h133", "الصِّيَامُ جُنَّةٌ، فَلَا يَرْفُثْ وَلَا يَجْهَلْ، وَإِنِ امْرُؤٌ قَاتَلَهُ أَوْ شَاتَمَهُ فَلْيَقُلْ: إِنِّي صَائِمٌ، مَرَّتَيْنِ", "عن أبي هريرة رضي الله عنه — متفق عليه", "الصيام مدرسة لضبط اللسان، فإذا استفزك أحد فقل: إني صائم، وامتنع عن الرد."], ["h134", "مَنْ لَمْ يَدَعْ قَوْلَ الزُّورِ وَالْعَمَلَ بِهِ فَلَيْسَ لِلَّهِ حَاجَةٌ فِي أَنْ يَدَعَ طَعَامَهُ وَشَرَابَهُ", "عن أبي هريرة رضي الله عنه — رواه البخاري", "ثمرة الصيام تقوى الجوارح عن الكذب والأذى، لا مجرد ترك الطعام."], ["h137", "اتَّقُوا النَّارَ وَلَوْ بِشِقِّ تَمْرَةٍ", "عن عدي بن حاتم رضي الله عنه — متفق عليه", "لا تستقلّ الصدقة القليلة، فشقّ تمرة قد يكون سببًا للنجاة."], ["h138", "مَنْ تَصَدَّقَ بِعَدْلِ تَمْرَةٍ مِنْ كَسْبٍ طَيِّبٍ، وَلَا يَقْبَلُ اللَّهُ إِلَّا الطَّيِّبَ، فَإِنَّ اللَّهَ يَتَقَبَّلُهَا بِيَمِينِهِ، ثُمَّ يُرَبِّيهَا لِصَاحِبِهِ كَمَا يُرَبِّي أَحَدُكُمْ فَلُوَّهُ، حَتَّى تَكُونَ مِثْلَ الْجَبَلِ", "عن أبي هريرة رضي الله عنه — متفق عليه", "تصدق من مال حلال فقط، فالله ينمّي القليل الطيب حتى يعظم أثره."], ["h139", "خَيْرُ يَوْمٍ طَلَعَتْ عَلَيْهِ الشَّمْسُ يَوْمُ الْجُمُعَةِ: فِيهِ خُلِقَ آدَمُ، وَفِيهِ أُدْخِلَ الْجَنَّةَ، وَفِيهِ أُخْرِجَ مِنْهَا", "عن أبي هريرة رضي الله عنه — رواه مسلم", "عظّم يوم الجمعة بالتبكير والغسل والإكثار من الذكر والدعاء."], ["h140", "مَنِ اغْتَسَلَ ثُمَّ أَتَى الْجُمُعَةَ فَصَلَّى مَا قُدِّرَ لَهُ، ثُمَّ أَنْصَتَ حَتَّى يَفْرُغَ مِنْ خُطْبَتِهِ، ثُمَّ يُصَلِّي مَعَهُ، غُفِرَ لَهُ مَا بَيْنَهُ وَبَيْنَ الْجُمُعَةِ الْأُخْرَى وَفَضْلُ ثَلَاثَةِ أَيَّامٍ", "عن أبي هريرة رضي الله عنه — رواه مسلم", "استعد للجمعة بالغسل والتبكير والإنصات، فأجرها مغفرة أسبوع كامل."], ["h143", "فَاسْتَوْصُوا بِالنِّسَاءِ خَيْرًا", "عن أبي هريرة رضي الله عنه — متفق عليه", "أوصاك النبي بالنساء، فعاملهن بالرفق والتقدير والصبر على ما فيهن."], ["h145", "كَفَى بِالْمَرْءِ إِثْمًا أَنْ يَحْبِسَ عَمَّنْ يَمْلِكُ قُوتَهُ", "عن عبد الله بن عمرو رضي الله عنهما — رواه مسلم", "النفقة على الأهل والأولاد واجبة، فلا تقصّر فيها ولا تمنعها."], ["h146", "مَنْ عَالَ جَارِيَتَيْنِ حَتَّى تَبْلُغَا جَاءَ يَوْمَ الْقِيَامَةِ أَنَا وَهُوَ، وَضَمَّ أَصَابِعَهُ", "عن أنس بن مالك رضي الله عنه — رواه مسلم", "القيام على تربية البنات والإحسان إليهن طريق إلى مرافقة النبي صلى الله عليه وسلم."], ["h147", "اتَّقُوا اللَّهَ وَاعْدِلُوا بَيْنَ أَوْلَادِكُمْ", "عن النعمان بن بشير رضي الله عنهما — متفق عليه", "سوِّ بين أولادك في العطية والمعاملة حتى لا تزرع بينهم الحقد."], ["h148", "إِذَا مَاتَ ابْنُ آدَمَ انْقَطَعَ عَمَلُهُ إِلَّا مِنْ ثَلَاثَةٍ: صَدَقَةٍ جَارِيَةٍ، أَوْ عِلْمٍ يُنْتَفَعُ بِهِ، أَوْ وَلَدٍ صَالِحٍ يَدْعُو لَهُ", "عن أبي هريرة رضي الله عنه — رواه مسلم", "أحسن تربية أولادك وانشر علمًا نافعًا وابنِ صدقة جارية، فهي رصيدك بعد موتك."], ["h149", "قَالَ رَجُلٌ: يَا رَسُولَ اللَّهِ، مَنْ أَحَقُّ النَّاسِ بِحُسْنِ صَحَابَتِي؟ قَالَ: أُمُّكَ، قَالَ: ثُمَّ مَنْ؟ قَالَ: ثُمَّ أُمُّكَ، قَالَ: ثُمَّ مَنْ؟ قَالَ: ثُمَّ أُمُّكَ، قَالَ: ثُمَّ مَنْ؟ قَالَ: ثُمَّ أَبُوكَ", "عن أبي هريرة رضي الله عنه — متفق عليه", "قدّم برّ أمك أولًا ثم أبيك، بالزيارة والخدمة والكلمة الطيبة."], ["h150", "مَا أَكَلَ أَحَدٌ طَعَامًا قَطُّ خَيْرًا مِنْ أَنْ يَأْكُلَ مِنْ عَمَلِ يَدِهِ، وَإِنَّ نَبِيَّ اللَّهِ دَاوُدَ عَلَيْهِ السَّلَامُ كَانَ يَأْكُلُ مِنْ عَمَلِ يَدِهِ", "عن المقدام بن معدي كرب رضي الله عنه — رواه البخاري", "اعمل واكسب بيدك ولا تحتقر مهنة شريفة، فهي سنة الأنبياء."], ["h151", "لَأَنْ يَأْخُذَ أَحَدُكُمْ حَبْلَهُ فَيَأْتِيَ بِحُزْمَةِ الْحَطَبِ عَلَى ظَهْرِهِ فَيَبِيعَهَا، فَيَكُفَّ اللَّهُ بِهَا وَجْهَهُ، خَيْرٌ لَهُ مِنْ أَنْ يَسْأَلَ النَّاسَ، أَعْطَوْهُ أَوْ مَنَعُوهُ", "عن الزبير بن العوام رضي الله عنه — رواه البخاري", "الكسب الشاق الشريف أكرم من مدّ اليد للناس، فاحفظ ماء وجهك بالعمل."], ["h152", "رَحِمَ اللَّهُ رَجُلًا سَمْحًا إِذَا بَاعَ، وَإِذَا اشْتَرَى، وَإِذَا اقْتَضَى", "عن جابر بن عبد الله رضي الله عنهما — رواه البخاري", "كن سمحًا في بيعك وشرائك وتقاضيك للدين، فالسماحة سبب لرحمة الله."], ["h153", "الْبَيِّعَانِ بِالْخِيَارِ مَا لَمْ يَتَفَرَّقَا، فَإِنْ صَدَقَا وَبَيَّنَا بُورِكَ لَهُمَا فِي بَيْعِهِمَا، وَإِنْ كَتَمَا وَكَذَبَا مُحِقَتْ بَرَكَةُ بَيْعِهِمَا", "عن حكيم بن حزام رضي الله عنه — متفق عليه", "الصدق وبيان العيوب سبب البركة في التجارة، والكذب والكتمان يمحقانها."], ["h155", "التَّاجِرُ الصَّدُوقُ الْأَمِينُ مَعَ النَّبِيِّينَ وَالصِّدِّيقِينَ وَالشُّهَدَاءِ", "عن أبي سعيد الخدري رضي الله عنه — رواه الترمذي وقال: حسن", "الصدق والأمانة في الكسب يرفعان صاحبهما إلى منازل عالية."], ["h156", "مَنْ نَفَّسَ عَنْ مُؤْمِنٍ كُرْبَةً مِنْ كُرَبِ الدُّنْيَا نَفَّسَ اللَّهُ عَنْهُ كُرْبَةً مِنْ كُرَبِ يَوْمِ الْقِيَامَةِ، وَمَنْ يَسَّرَ عَلَى مُعْسِرٍ يَسَّرَ اللَّهُ عَلَيْهِ فِي الدُّنْيَا وَالْآخِرَةِ، وَمَنْ سَتَرَ مُسْلِمًا سَتَرَهُ اللَّهُ فِي الدُّنْيَا وَالْآخِرَةِ، وَاللَّهُ فِي عَوْنِ الْعَبْدِ مَا كَانَ الْعَبْدُ فِي عَوْنِ أَخِيهِ", "عن أبي هريرة رضي الله عنه — رواه مسلم", "اقض حوائج الناس وأمهل المعسر وستر العيوب، فجزاؤك من جنس عملك."], ["h157", "لَا يَسْتُرُ عَبْدٌ عَبْدًا فِي الدُّنْيَا إِلَّا سَتَرَهُ اللَّهُ يَوْمَ الْقِيَامَةِ", "عن أبي هريرة رضي الله عنه — رواه مسلم", "إذا رأيت زلّة لأخيك فاستره ولا تفضحه، فالله يستر على الساتر."], ["h159", "أَلَا أُخْبِرُكُمْ بِأَفْضَلَ مِنْ دَرَجَةِ الصِّيَامِ وَالصَّلَاةِ وَالصَّدَقَةِ؟ قَالُوا: بَلَى، قَالَ: إِصْلَاحُ ذَاتِ الْبَيْنِ، فَإِنَّ فَسَادَ ذَاتِ الْبَيْنِ هِيَ الْحَالِقَةُ", "عن أبي الدرداء رضي الله عنه — رواه أبو داود والترمذي", "بادر إلى الإصلاح بين المتخاصمين من أهل أو أصدقاء، فأجره فوق أجر النوافل."], ["h160", "لَيْسَ الْكَذَّابُ الَّذِي يُصْلِحُ بَيْنَ النَّاسِ، فَيَنْمِي خَيْرًا، أَوْ يَقُولُ خَيْرًا", "عن أم كلثوم بنت عقبة رضي الله عنها — متفق عليه", "يجوز قول ما فيه تلطيف لإصلاح ذات البين، فاحرص على جمع القلوب لا تفريقها."], ["h161", "تُفْتَحُ أَبْوَابُ الْجَنَّةِ يَوْمَ الِاثْنَيْنِ وَيَوْمَ الْخَمِيسِ، فَيُغْفَرُ لِكُلِّ عَبْدٍ لَا يُشْرِكُ بِاللَّهِ شَيْئًا، إِلَّا رَجُلًا كَانَتْ بَيْنَهُ وَبَيْنَ أَخِيهِ شَحْنَاءُ، فَيُقَالُ: أَنْظِرُوا هَذَيْنِ حَتَّى يَصْطَلِحَا", "عن أبي هريرة رضي الله عنه — رواه مسلم", "لا تُبقِ في قلبك خصومة، فالشحناء تحجب المغفرة حتى تصطلح."], ["h162", "إِيَّاكُمْ وَالظَّنَّ، فَإِنَّ الظَّنَّ أَكْذَبُ الْحَدِيثِ، وَلَا تَحَسَّسُوا وَلَا تَجَسَّسُوا وَلَا تَحَاسَدُوا وَلَا تَدَابَرُوا وَلَا تَبَاغَضُوا، وَكُونُوا عِبَادَ اللَّهِ إِخْوَانًا", "عن أبي هريرة رضي الله عنه — متفق عليه", "احمل أفعال الناس على أحسن المحامل، ولا تتبع عوراتهم ولا تحسدهم."], ["h163", "لَا يَمُوتَنَّ أَحَدُكُمْ إِلَّا وَهُوَ يُحْسِنُ الظَّنَّ بِاللَّهِ", "عن جابر بن عبد الله رضي الله عنهما — رواه مسلم", "أحسن الظن بالله في كل حال، وعش بين الخوف والرجاء وغلّب الرجاء عند الموت."], ["h164", "يَقُولُ اللَّهُ تَعَالَى: أَنَا عِنْدَ ظَنِّ عَبْدِي بِي، وَأَنَا مَعَهُ إِذَا ذَكَرَنِي", "عن أبي هريرة رضي الله عنه — متفق عليه", "ظنّ بربك خيرًا وأكثر من ذكره، فهو معك بعونه ولطفه."], ["h165", "لَا حَسَدَ إِلَّا فِي اثْنَتَيْنِ: رَجُلٌ آتَاهُ اللَّهُ مَالًا فَسُلِّطَ عَلَى هَلَكَتِهِ فِي الْحَقِّ، وَرَجُلٌ آتَاهُ اللَّهُ الْحِكْمَةَ فَهُوَ يَقْضِي بِهَا وَيُعَلِّمُهَا", "عن عبد الله بن مسعود رضي الله عنه — متفق عليه", "المراد الغبطة، فتمنَّ مثل ما عند غيرك من الخير في الإنفاق والعلم دون تمني زوال نعمته."], ["h168", "يَتْبَعُ الْمَيِّتَ ثَلَاثَةٌ: أَهْلُهُ وَمَالُهُ وَعَمَلُهُ، فَيَرْجِعُ اثْنَانِ وَيَبْقَى وَاحِدٌ: يَرْجِعُ أَهْلُهُ وَمَالُهُ وَيَبْقَى عَمَلُهُ", "عن أنس بن مالك رضي الله عنه — متفق عليه", "الذي يصحبك في قبرك عملك، فاستكثر من الصالحات قبل الرحيل."], ["h169", "حُفَّتِ الْجَنَّةُ بِالْمَكَارِهِ، وَحُفَّتِ النَّارُ بِالشَّهَوَاتِ", "عن أبي هريرة رضي الله عنه — رواه مسلم", "طريق الجنة فيه مجاهدة النفس وصبر على الطاعة، وطريق النار مزيّن بالشهوات، فاثبت."], ["h170", "لَنْ تَزُولَ قَدَمَا عَبْدٍ يَوْمَ الْقِيَامَةِ حَتَّى يُسْأَلَ عَنْ عُمُرِهِ فِيمَ أَفْنَاهُ، وَعَنْ عِلْمِهِ فِيمَ فَعَلَ، وَعَنْ مَالِهِ مِنْ أَيْنَ اكْتَسَبَهُ وَفِيمَ أَنْفَقَهُ، وَعَنْ جِسْمِهِ فِيمَ أَبْلَاهُ", "عن أبي برزة الأسلمي رضي الله عنه — رواه الترمذي وقال: حسن صحيح", "حاسب نفسك اليوم عن عمرك وعلمك ومالك وصحتك قبل أن تُسأل عنها غدًا."]];
window.FULL_STORIES=[{"id": "s01", "title": "قصة نوح عليه السلام", "type": "قصة قرآنية", "verse": "وَلَقَدْ أَرْسَلْنَا نُوحًا إِلَىٰ قَوْمِهِ فَلَبِثَ فِيهِمْ أَلْفَ سَنَةٍ إِلَّا خَمْسِينَ عَامًا", "source": "سورة العنكبوت 29:14", "parts": [["قوم نوح وبداية الشرك", "كان الناس بعد آدم عليه السلام على التوحيد زمنًا، ثم دبّ إليهم الانحراف شيئًا فشيئًا. وروى البخاري عن ابن عباس رضي الله عنهما أن أسماء ودّ وسواع ويغوث ويعوق ونسر كانت لرجال صالحين من قوم نوح، فلما ماتوا أوحى الشيطان إلى قومهم أن انصبوا في مجالسهم التي كانوا يجلسون فيها أنصابًا وسمّوها بأسمائهم، ففعلوا، فلم تُعبد في ذلك الجيل، حتى إذا هلك أولئك ونُسي العلم عُبدت من دون الله. وهكذا بدأ الشرك بحبٍّ مبالغ فيه للصالحين، ثم صار عبادةً صريحة للأصنام. فأرسل الله إليهم نوحًا عليه السلام، وهو أول رسول أُرسل إلى أهل الأرض كما جاء في حديث الشفاعة الصحيح. وكان نوح عليه السلام من قومه نسبًا ولغةً، يعرفونه ويعرفون صدقه، فقال لهم ما قاله كل الرسل: ﴿اعْبُدُوا اللَّهَ مَا لَكُم مِّنْ إِلَٰهٍ غَيْرُهُ﴾، وخوّفهم من عذاب يوم عظيم إن أصرّوا على ما هم عليه."], ["دعوة بلا كلل", "مكث نوح عليه السلام في قومه ألف سنة إلا خمسين عامًا كما أخبر القرآن، لا يملّ ولا يفتر. وقد حكى الله في سورة نوح صورة من دعوته حين قال نوح عليه السلام إنه دعا قومه ليلًا ونهارًا، فلم يزدهم دعاؤه إلا فرارًا. دعاهم سرًّا ودعاهم جهرًا، ونوّع الأساليب، فذكّرهم بالاستغفار، وبيّن لهم أنه سبب نزول المطر وكثرة الأموال والبنين وجريان الأنهار، ثم لفت أنظارهم إلى عظمة الله في خلق السماوات والأرض والشمس والقمر، وإلى خلقهم هم أطوارًا. ومع ذلك كانوا كلما دعاهم جعلوا أصابعهم في آذانهم، واستغشَوا ثيابهم، أي غطّوا بها وجوههم حتى لا يسمعوا ولا يروه، وأصرّوا واستكبروا استكبارًا. وقد بيّن القرآن أن مشكلتهم لم تكن قلة الدليل، بل كبرًا وعنادًا وتمسكًا بما ورثوه عن آبائهم، حتى صار الحق ثقيلًا على قلوبهم."], ["اعتراضات الملأ وردّ نوح", "لم يكتفِ كبراء القوم بالإعراض، بل أخذوا يعترضون على نوح عليه السلام وعلى من آمن معه. قالوا له: ما نراك إلا بشرًا مثلنا، يريدون أن الرسول ينبغي ألا يكون من جنس البشر. واعترضوا على أتباعه فقالوا إنهم أراذلهم، يعنون الضعفاء والفقراء، وزعموا أنه لا فضل له عليهم. فأجابهم نوح عليه السلام بهدوء وحجة: إنه على بيّنة من ربه، وإن الله آتاه رحمة من عنده خفيت عليهم، وإنه لا يسألهم على دعوته مالًا، فأجره على الله وحده. وأخبرهم أنه لن يطرد المؤمنين لأجل أهوائهم، فهم ملاقو ربهم، ومن ينصره من الله إن طردهم؟ وحين ضاقوا بالحجة قالوا له: قد جادلتنا فأكثرت جدالنا، فأتنا بما تعدنا إن كنت من الصادقين. فبيّن لهم أن العذاب بيد الله وحده، يأتي به إن شاء، وليسوا بمعجزين."], ["صناعة السفينة", "بعد زمن طويل من الصبر أوحى الله إلى نوح عليه السلام أنه لن يؤمن من قومه إلا من قد آمن، وأن عليه ألا يحزن بما كانوا يفعلون. وعندها دعا نوح عليه السلام ربه فقال ما معناه: ربّ لا تترك على الأرض من الكافرين أحدًا، إنك إن تتركهم يضلّوا عبادك ولا يلدوا إلا فاجرًا كفارًا. فاستجاب الله دعاءه، وأمره أن يصنع السفينة بأعيننا ووحينا، أي بحفظ الله وتعليمه. فأخذ نوح عليه السلام يصنعها، وكان كلما مرّ عليه جماعة من قومه سخروا منه، فيرد عليهم بثقة: إن تسخروا منا فإنا نسخر منكم، فسوف تعلمون من يأتيه عذاب يخزيه ويحلّ عليه عذاب مقيم. ولم يحدد القرآن نوع خشبها ولا مقاسها، وما ورد في ذلك من تفاصيل مروية عن بني إسرائيل لا يصح الاعتماد عليه، وإنما العبرة في طاعة الأمر والصبر على السخرية."], ["الطوفان", "جاء أمر الله، وفار التنور، وهذه علامة أخبره الله بها. فأمر الله نوحًا أن يحمل في السفينة من كل زوجين اثنين، وأهله إلا من سبق عليه القول منهم، ومن آمن، وقال القرآن: ﴿وَمَا آمَنَ مَعَهُ إِلَّا قَلِيلٌ﴾، ولم يحدد القرآن عددهم. وركب نوح عليه السلام وقال لمن معه: ﴿ارْكَبُوا فِيهَا بِسْمِ اللَّهِ مَجْرَاهَا وَمُرْسَاهَا﴾. وانفتحت أبواب السماء بماء منهمر، وفجّر الله الأرض عيونًا، فالتقى الماء على أمر قد قُدر. وجرت السفينة بهم في موج كالجبال، وكان القوم الظالمون يغرقون فلا ناصر لهم من دون الله. ويذكر القرآن أن الله حمل نوحًا ومن معه على ذات ألواح ودُسُر، وأن السفينة جرت بأعين الله، جزاءً لمن كُفر به. وبقيت أخبارها آية يتحدث بها الناس، وفي القرآن أن الله جعلها آية باقية فهل من مدّكر."], ["ابن نوح ونهاية الطوفان", "في وسط الموج رأى نوح عليه السلام ابنه في معزل عنهم، فناداه بشفقة الأب: يا بنيّ اركب معنا ولا تكن مع الكافرين. لكن الابن ظن أن الجبل ينجيه، فقال: سآوي إلى جبل يعصمني من الماء. فقال له نوح: ﴿لَا عَاصِمَ الْيَوْمَ مِنْ أَمْرِ اللَّهِ إِلَّا مَن رَّحِمَ﴾. وحال بينهما الموج فكان من المغرقين. فتألم نوح عليه السلام وناجى ربه: إن ابني من أهلي وإن وعدك الحق. فأجابه الله أنه ليس من أهله، إنه عمل غير صالح، ونهاه أن يسأل ما ليس له به علم، فاستغفر نوح وتاب. ثم قال الله: يا أرض ابلعي ماءك ويا سماء أقلعي، وغاض الماء وقُضي الأمر واستوت السفينة على الجودي، وقيل بعدًا للقوم الظالمين. ثم قيل لنوح: اهبط بسلام منا وبركات عليك وعلى أمم ممن معك. وذكر القرآن أن امرأة نوح كانت خائنة في الدين لا في العرض، فلم يغنِ عنها زواجها منه شيئًا."]], "lesson": ["الصبر على الدعوة والإصلاح ولو طال الزمن وقلّ المستجيبون.", "النسب والقرابة لا تنفع من غير إيمان وعمل صالح.", "لا يُقاس الحق بكثرة أتباعه ولا بمكانتهم الاجتماعية.", "التوكل على الله مع الأخذ بالأسباب، كما بنى نوح السفينة ثم ركبها باسم الله."], "cat": "story"}, {"id": "sr01", "title": "العرب قبل البعثة ونسب النبي ﷺ وعام الفيل", "type": "من السيرة النبوية", "verse": "أَلَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ بِأَصْحَابِ الْفِيلِ", "source": "سورة الفيل 105:1", "parts": [["جزيرة العرب قبل البعثة", "كانت جزيرة العرب قبل بعثة النبي ﷺ أرضًا واسعة يغلب عليها الصحراء، وأهلها قبائل متفرقة لا تجمعهم دولة ولا نظام واحد، وإنما يجمعهم اللسان العربي الفصيح والأنساب والعادات. وكان الناس يعيشون بين البدو الذين يتتبعون مواقع المطر والكلأ، وأهل الحضر الذين استقروا في المدن والقرى كمكة والطائف ويثرب. وكانت التجارة عصب الحياة في مكة خاصة، فلها رحلتان معروفتان ذكرهما القرآن في سورة قريش، رحلة الشتاء إلى اليمن ورحلة الصيف إلى الشام. وكان العرب يتفاخرون بالشعر والخطابة وحفظ الأنساب، ويكرمون الضيف ويحمون الجار، لكن القبلية كانت تحكم أمورهم، فكانت الحرب تقوم لأسباب يسيرة وتطول سنين، ولا يأخذ الضعيف حقه إلا بحماية قبيلته. وفي هذا الجو جاءت الرسالة لتجمع الناس على كلمة واحدة وتبني أمة من متفرقين. وكانت مكة وادٍ غير ذي زرع، لكن الله جعل فيها بيته الحرام فأمّنها وجعل الناس يقصدونها، فصار لها شأن ديني وتجاري لا يضاهيها فيه موضع آخر في الجزيرة."], ["دين العرب وعاداتهم", "بقيت في العرب بقايا من دين إبراهيم عليه السلام، فكانوا يعظمون الكعبة ويحجون إليها ويطوفون بها، ويعرفون أن لهذا الكون ربًّا خالقًا. لكن الشرك تسلل إليهم مع الزمن فاتخذوا الأصنام وسيلةً يزعمون أنها تقرّبهم إلى الله. وفي الصحيحين أن النبي ﷺ ذكر عمرو بن عامر الخزاعي وقال إنه رآه في النار يجرّ أمعاءه، وكان أول من سيّب السوائب، أي أول من أدخل عبادة الأوثان إلى العرب. وكان عندهم كذلك خير وشر، فمن أخلاقهم الكرم والشجاعة والوفاء بالعهد وإجارة المستجير، ومن أخطائهم شرب الخمر والربا والميسر وكثرة الثأر. وذكر القرآن عادة وأد البنات في قوله تعالى: ﴿وَإِذَا الْمَوْءُودَةُ سُئِلَتْ﴾. وكان في الجزيرة يهود ونصارى، ومعهم قلة من الموحدين الذين تركوا عبادة الأصنام ويسمَّون الحنفاء. فكان الناس بحاجة إلى نور جديد يردّهم إلى التوحيد الخالص. وهذا هو الحال الذي وصفه جعفر بن أبي طالب رضي الله عنه للنجاشي حين سأله عن حال قومه قبل الإسلام، كما سيأتي في موضعه من هذه السيرة."], ["نسب النبي ﷺ الشريف", "هو محمد بن عبد الله بن عبد المطلب بن هاشم بن عبد مناف بن قصي بن كلاب بن مرة بن كعب بن لؤي بن غالب بن فهر، من قريش، وهو منتهى النسب المتفق عليه إلى عدنان، وأما ما فوق عدنان فقد اختلف فيه أهل النسب، والثابت أن عدنان من ولد إسماعيل بن إبراهيم عليهما السلام. وفي صحيح مسلم أن النبي ﷺ قال: «إن الله اصطفى كنانة من ولد إسماعيل، واصطفى قريشًا من كنانة، واصطفى من قريش بني هاشم، واصطفاني من بني هاشم». وكانت قريش أهل مكة وسدنة البيت، وكانت لها الشرف والسيادة بين العرب. وكان جده قصي قد جمع قريشًا بعد تفرقها، وتولى أمور الكعبة من سقاية ورفادة وحجابة. وفي بني هاشم خاصة كانت السقاية، وقد اشتهر منهم هاشم بإطعام الحجاج، فنشأ النبي ﷺ في بيت شرف ومكانة بين قومه. وبذلك اجتمع للنبي ﷺ شرف النسب إلى جانب شرف النبوة وحسن الخلق، فلم يكن في أصله ما يُعاب عند قومه."], ["أبرهة وقصة الفيل", "كان أبرهة الحبشي نائبًا على اليمن من قبل الأحباش، فبنى كنيسةً ضخمة في صنعاء، ورغب في أن يصرف العرب عن حج الكعبة إليها. وتذكر كتب السير أن رجلًا من العرب أحدث فيها حدثًا استهانةً بها، فغضب أبرهة وأقسم أن يهدم الكعبة. فخرج بجيش كبير فيه فيل أو أكثر، وكان العرب لا يعرفون الفيلة ولا يطيقون قتال مثل هذا الجيش. فلما اقترب من مكة أخذ إبلًا لأهلها، منها إبل لعبد المطلب جدّ النبي ﷺ وكان سيد قريش. وتذكر كتب السير أن عبد المطلب كلّم أبرهة في إبله، وأن قريشًا تفرقت في الجبال خوفًا، وأن عبد المطلب تعلّق بحلقة باب الكعبة ودعا الله. وهذا الخبر في جملته مشهور عند أهل السير، أما تفاصيل ألفاظ الحوار فمحل اجتهاد الرواة، ولذلك يكفي أن نعرف أن مكة لم تكن تملك دفع هذا الجيش بقوتها. وكان الأحباش يومئذ على النصرانية، وكانت لهم دولة قوية في اليمن، فلم تكن القبائل تقدر على مواجهة جيش منظم كجيشهم."], ["عقاب الله لأصحاب الفيل", "لما تهيأ الجيش لدخول مكة وهدم البيت، تدخّلت قدرة الله. وقد خلّد القرآن الحادثة في سورة الفيل فقال تعالى: ﴿أَلَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ بِأَصْحَابِ الْفِيلِ * أَلَمْ يَجْعَلْ كَيْدَهُمْ فِي تَضْلِيلٍ * وَأَرْسَلَ عَلَيْهِمْ طَيْرًا أَبَابِيلَ * تَرْمِيهِمْ بِحِجَارَةٍ مِّن سِجِّيلٍ * فَجَعَلَهُمْ كَعَصْفٍ مَّأْكُولٍ﴾. فأرسل الله عليهم طيرًا جماعات جماعات ترميهم بحجارة من طين متحجر فأهلكتهم وتفرق من بقي منهم. وتذكر كتب السير أن الفيل الأكبر برك فلم يتحرك نحو مكة، وأن أبرهة أصابه مرض شديد وهلك في طريق العودة، وتفاصيل هذا الجزء من الروايات التاريخية لا من الصحيح. والثابت من القرآن أن الله حمى بيته الحرام بقدرته، لا بقوة قريش ولا بحيلتهم، فعظمت مكانة الحرم في نفوس العرب بعد ذلك. ومعنى أبابيل جماعات متفرقة يتبع بعضها بعضًا، والسجّيل الطين المتحجّر، والعصف ورق الزرع اليابس الذي أكلته الدواب فتفتت. وهكذا شبّه القرآن حال الجيش بعد هلاكه بورق ممزق تأكله الأنعام."], ["عام الفيل وميلاد النبي ﷺ", "اشتهر عند أهل السير أن النبي ﷺ ولد في عام الفيل، أي في السنة التي وقعت فيها هذه الحادثة، وقد نقل ذلك جماعة من أهل العلم، وكان العرب يؤرخون بها قبل أن يُعرف التاريخ الهجري. وكأن الله أراد أن يجعل مقدم النبي الخاتم مسبوقًا بآية عظيمة تعلن حرمة البيت الذي سيصير قبلة المسلمين. وفي صحيح البخاري يوم الحديبية لما بركت ناقة النبي ﷺ قال أصحابه: خلأت القصواء، فقال ﷺ: «ما خلأت القصواء وما ذاك لها بخلق، ولكن حبسها حابس الفيل»، يشير إلى أن الله هو الذي منع الفيل عن مكة قديمًا وهو الذي يمنع المسلمين الآن عن القتال في الحرم. وبهذا يظهر أن حادثة الفيل ثابتة في الوعي الإسلامي منذ البدء، وأن البيت الحرام ظل محفوظًا بحفظ الله ليكون محطّ الأنظار ومهوى القلوب. ومن أثر هذه الحادثة أن العرب ازدادوا تعظيمًا لقريش وللحرم، وأن مكة صارت أكثر أمنًا، وهو ما مهّد لظهور الرسالة من أرضها."]], "lesson": ["حفظ الله لبيته الحرام قبل البعثة آيةٌ على أن الله يدبّر لرسالته وأهلها من قبل أن تبدأ.", "أصل الشرف الحقيقي الإيمان والعمل الصالح، ومع ذلك فإن الله يختار من يشاء لحمل رسالته من أطيب الأنساب.", "الحق يحتاج إلى نور الوحي، فقد كانت العرب على مروءة وأخلاق لكنها ضلت في العقيدة وانقسمت بالقبلية.", "قوة الباطل مهما بلغت لا تقف أمام إرادة الله، وقد ردّ الله جيش أبرهة بأضعف الأسباب."], "cat": "seerah"}, {"id": "s02", "title": "قصة آسية امرأة فرعون", "type": "قصة قرآنية", "verse": "وَضَرَبَ اللَّهُ مَثَلًا لِّلَّذِينَ آمَنُوا امْرَأَتَ فِرْعَوْنَ إِذْ قَالَتْ رَبِّ ابْنِ لِي عِندَكَ بَيْتًا فِي الْجَنَّةِ وَنَجِّنِي مِن فِرْعَوْنَ وَعَمَلِهِ وَنَجِّنِي مِنَ الْقَوْمِ الظَّالِمِينَ", "source": "سورة التحريم 66:11", "parts": [["امرأة في قصر الطغيان", "كانت آسية بنت مزاحم رضي الله عنها زوجة فرعون، أعظم طغاة زمانه، الذي قال لقومه: أنا ربكم الأعلى. عاشت في قصر مليء بالمال والخدم والترف، وكل ما تتمناه نساء الدنيا من مكانة وسلطان. ولم يذكر القرآن اسمها، وإنما ذكرها بوصفها امرأة فرعون، وجاء اسمها «آسية بنت مزاحم» في السنة، كما سيأتي في الحديث. وبرغم هذا الجو الذي يقوم على الكفر والظلم، كان قلبها معلقًا بالله. وجعل الله قصتها مثلًا للذين آمنوا إلى يوم القيامة، ليعلم كل مؤمن أن البيئة الفاسدة لا تُجبر القلب على الكفر، وأن الهداية بيد الله يمنحها من يشاء حتى في أشدّ المواضع ظلمة. وهذا مثل في الثبات على التوحيد وسط أعظم أسباب الفتنة. وبهذا تبدأ حكايتها: امرأة تحمل في صدرها إيمانًا لا يراه أحد، وتعيش بين جدران لا يُذكر فيها اسم الله إلا استهزاءً، ومع ذلك لا يتغير قلبها."], ["المولود في التابوت", "حين ألقت أم موسى وليدها في اليم بأمر الله، حملته الأمواج حتى التقطه آل فرعون، وكان قدر الله أن يكون الطفل قرة عين لامرأة فرعون. فقالت لزوجها: ﴿قُرَّتُ عَيْنٍ لِّي وَلَكَ لَا تَقْتُلُوهُ﴾ عسى أن ينفعنا أو نتخذه ولدًا. وكان فرعون يقتل الأطفال الذكور من بني إسرائيل، فكان طلبها نجاةً لطفل لا يعلم أحد أنه سيكون هلاك الطغيان على يديه، وقد قال الله: وهم لا يشعرون. فأوقع الله محبة موسى عليه السلام في قلبها، وكان ذلك من تدبير الله: ﴿وَأَلْقَيْتُ عَلَيْكَ مَحَبَّةً مِّنِّي﴾. فكانت آسية سببًا لحياة نبي من أولي العزم، وهذا من رحمتها وإن لم تكن قد أعلنت إيمانها وقتئذ، وهو مما لا يُجزم به في وقت بعينه، فالقرآن لم يحدد متى آمنت. وفي ذلك درس عظيم أن الله قد يجعل أسباب النجاة في أحضان من يظنون أنهم قادرون على كل شيء، وأن ما يدبّره الله لعباده المؤمنين يفوق كل تدبير."], ["إيمان تخفيه القلوب", "نشأ موسى عليه السلام في بيتها، وكبر، ثم أرسله الله إلى فرعون وقومه، وكانت المعجزات التي جاء بها، كالعصا واليد البيضاء وإيمان السحرة، حديث مصر كلها. وقد دلّ القرآن على أنها آمنت بالله وحده وتبرأت من دين زوجها. وذكر بعض المفسرين أخبارًا في كيفية إيمانها وإظهاره لا تثبت بإسناد صحيح، فنكتفي بما صحّ وهو أنها كانت مؤمنة، ولم يحدد القرآن متى ولا كيف. وهي لم تكن تعبد الله في خلوة فقط، بل كانت تطلب النجاة من فرعون وعمله، أي من ظلمه ومن أفعاله ومن الظالمين جميعًا. وذلك دليل أنها كانت تدرك حجم الباطل الذي تعيش فيه وتتبرأ منه في قلبها وقولها. وكانت الأيام تمرّ عليها وهي ترى الباطل بعينيها كل صباح، فتزداد بالله تعلّقًا، وتعلم أن العزة لله وحده وأن كل ملك في الأرض إلى زوال."], ["دعاء آسية", "في لحظة صفاء وصدق رفعت آسية يديها إلى الله بدعاء خلّده القرآن. لم تسأل إعادة ملكها ولا انتقامًا من ظالمها، بل قالت: ﴿رَبِّ ابْنِ لِي عِندَكَ بَيْتًا فِي الْجَنَّةِ﴾. وانظر إلى حسن ترتيب الدعاء: قدّمت الجار قبل الدار، فقالت: عندك، أي في جوار الله وقربه، ثم قالت: في الجنة. ثم طلبت النجاة: ﴿وَنَجِّنِي مِن فِرْعَوْنَ وَعَمَلِهِ وَنَجِّنِي مِنَ الْقَوْمِ الظَّالِمِينَ﴾. فجمعت في دعائها بين طلب أعلى المطالب وبين الاستعاذة من أشد المخاوف. وكأنها تقول إن القصور التي تعيش فيها لا تساوي شيئًا أمام بيت واحد عند ربها. وقد قال بعض المفسرين إن الله أراها بيتها في الجنة قبل أن تموت، لكن هذا لا يثبت بنص صحيح، فنكتفي بأن الله استجاب دعاءها وجعلها مثلًا للمؤمنين. وهي بذلك تعلّمنا أن أعظم ما يطلبه المؤمن في الدعاء ليس متاع الدنيا، بل القرب من الله ورضاه، وأن الحاجة إلى النجاة من الظلم لا تتعارض مع الرضا بقضاء الله."], ["الابتلاء والثبات", "كان ثمن الإيمان في بيت فرعون غاليًا. ولم يرد في القرآن ولا في السنة الصحيحة تفصيل تعذيبها، وما يُروى من أنه ربطها وأوقعها في الشمس أو أنه وضع صخرة على صدرها هو مما ذكره بعض المفسرين عن بني إسرائيل ولم يثبت بإسناد صحيح، فلا نجزم به، ونكتفي بأن ما ثبت هو أنها بلغت الكمال في الإيمان. فقد صحّ عن النبي صلى الله عليه وسلم أنه قال: «كمل من الرجال كثير، ولم يكمل من النساء إلا مريم بنت عمران وآسية امرأة فرعون». وأخبر صلى الله عليه وسلم أن أفضل نساء أهل الجنة خديجة وفاطمة ومريم وآسية. فاجتمع لها ثناء القرآن وثناء النبي صلى الله عليه وسلم، وكفى بذلك شرفًا لامرأة صبرت على الباطل وهي في قلب سلطانه، وآثرت ما عند الله على ما عند الدنيا."], ["خاتمة قصتها", "ختم الله ذكر آسية في سورة التحريم مقرونًا بمريم بنت عمران، فجعل مثلًا للمؤمنين في الإيمان والصبر والعفة. وجاء في الحديث أن النبي صلى الله عليه وسلم خطّ أربعة خطوط في الأرض، وقال: أتدرون ما هذا؟ قالوا: الله ورسوله أعلم، فقال: «أفضل نساء أهل الجنة: خديجة بنت خويلد، وفاطمة بنت محمد، ومريم بنت عمران، وآسية بنت مزاحم امرأة فرعون». وهذا الحديث رواه أحمد وصححه جماعة من أهل العلم. وهكذا يتبين أن المرأة المؤمنة قد تبلغ بإيمانها وصبرها أعلى المنازل، وأن الحياة في أشد البيئات فسادًا لا تمنع من الفوز بالجنة إذا صدق القلب وثبت العبد. وقد جاء ذكرها في القرآن ليبقى دعاؤها حيًّا على ألسنة المؤمنين، ويتعلم منه كل مبتلى أن يطلب من ربه الجوار والنجاة معًا. فلتكن قصتها زادًا لكل مؤمن ومؤمنة يعيش بين الفتن، ولتبقَ حجة على أن الأعذار بالظروف لا تقوم أمام من أراد الله ورسوله والدار الآخرة."]], "lesson": ["الإيمان الصادق ينمو حتى في أشد البيئات فسادًا ولا يتوقف على الظروف.", "إذا ضاقت الدنيا فاطلب من الله بيتًا عنده في الجنة وأحسن الدعاء.", "الاعتماد على الأحاديث الصحيحة وترك الروايات الضعيفة في تفاصيل القصص.", "المرأة المؤمنة قد تبلغ الكمال في الإيمان والصبر وتكون قدوة للأمة كلها."], "cat": "story"}, {"id": "sr02", "title": "مولد النبي ﷺ ورضاعته عند حليمة ويتمه ووفاة أمه", "type": "من السيرة النبوية", "verse": "أَلَمْ يَجِدْكَ يَتِيمًا فَآوَىٰ", "source": "سورة الضحى 93:6", "parts": [["مولده ﷺ", "ولد النبي ﷺ في مكة في عام الفيل على الراجح عند أهل السير. وقد ثبت في صحيح مسلم أنه سُئل عن صوم الاثنين فقال: «ذاك يوم ولدت فيه، ويوم بعثت أو أنزل عليّ فيه»، فالثابت إذن أنه ولد يوم الاثنين. أما تحديد الشهر واليوم فقد اختلف فيه أهل العلم، والمشهور عند أكثر أهل السير أنه في شهر ربيع الأول، وأن الثاني عشر منه هو اليوم المشهور، وقد قيل غير ذلك، ولم يرد في الصحيح تحديد يوم بعينه من الشهر. وكانت أمه آمنة بنت وهب من بني زهرة من خيار نساء قريش نسبًا، وأبوه عبد الله بن عبد المطلب. وقد وُلد النبي ﷺ يتيمًا في الراجح، فقد مات أبوه وهو حمل في بطن أمه، وقيل مات بعد ولادته بقليل، والأول أشهر. وسمّاه جدّه عبد المطلب محمدًا، وهو اسم قليل عند العرب، وفرح به فرحًا شديدًا."], ["أبوه عبد الله وكفالة أمه", "تذكر كتب السير أن عبد الله والد النبي ﷺ خرج في تجارة إلى الشام، فعاد في طريقه ونزل بالمدينة عند أخوال أبيه من بني عدي بن النجار، فمرض بها ومات وهو شاب. فلم يجد النبي ﷺ أباه ولا رآه، وبقي في رعاية أمه آمنة وجدّه عبد المطلب. وقد أشار القرآن إلى يتمه فقال تعالى: ﴿أَلَمْ يَجِدْكَ يَتِيمًا فَآوَىٰ﴾، يمتنّ الله على نبيه بأنه آواه حين فقد أباه، فلم يتركه ضائعًا. ومن حكمة الله في ذلك أن النبي ﷺ لم يكن لأحد من الخلق عليه فضل التربية كاملًا، بل كان الله هو الذي تولى تربيته وأعدّه لرسالته. وأرضعته في أول أمره ثويبة مولاة أبي لهب أيامًا قليلة، وقد جاء ذكر ثويبة في صحيح البخاري في باب الرضاع، ثم دُفع إلى مرضعة من البادية على عادة أشراف مكة. ولم يكن لعبد الله مال كثير، فخلّف لابنه ميراثًا قليلًا، وبقي النبي ﷺ يعتمد على فضل الله ثم على من يكفله."], ["عند حليمة السعدية", "كان من عادة أهل مكة أن يدفعوا أبناءهم إلى مرضعات من البادية، لأن هواء الصحراء أصفى، ولينشأ الطفل على اللسان العربي الفصيح. فجاءت نساء من بني سعد بن بكر يلتمسن الرضعاء، وكان من بينهن حليمة بنت أبي ذؤيب السعدية، فأخذت محمدًا ﷺ وهو يتيم، وتذكر كتب السير أن ذلك لم يكن مرغوبًا فيه لأن الأب هو الذي يعطي الأجر. وتذكر كتب السير أن حليمة وزوجها لحظا في بيتهما بركةً وخيرًا مذ جاءهم، وهذه الروايات التفصيلية ليست في الصحيح، لكنها مشهورة في السير. والمعروف أن النبي ﷺ أقام في بني سعد نحو سنتين للرضاعة ثم أعيد إلى أمه، ثم طلبت حليمة أن يبقى عندها مدة أخرى فأذنت آمنة، فعاش في البادية سنوات قليلة تعلّم فيها الفصاحة ونشأ نشأة قوية ونقية."], ["شق الصدر", "ثبت في صحيح مسلم من حديث أنس بن مالك رضي الله عنه أن جبريل عليه السلام أتى النبي ﷺ وهو يلعب مع الغلمان، فأخذه فصرعه فشق عن قلبه، فاستخرج القلب ثم استخرج منه علقة، فقال: هذا حظّ الشيطان منك. ثم غسله في طست من ذهب بماء زمزم، ثم لأمه، أي ضمّ بعضه إلى بعض، وأعاده إلى مكانه. وجاء الغلمان يسعون إلى أمه، أي مرضعته، فقالوا: إن محمدًا قد قُتل، فاستقبلوه وهو منتقع اللون. قال أنس: وقد كنت أرى أثر ذلك المخيط في صدره. وهذه الحادثة تدل على أن الله هيّأ نبيه منذ صغره وطهّر قلبه من حظ الشيطان فيه. وتذكر كتب السير أن حليمة خافت عليه بعد هذه الحادثة فردّته إلى أمه، وأن عمره كان نحو أربع أو خمس سنين، وهذا من تفصيلات السير التي لا يبلغ بها الجزم. ومن عظيم هذه الحادثة أنها ثبتت بسند صحيح، وهي من أخبار الغيب التي يؤمن بها المسلمون كما أخبر بها الصادق المصدوق ﷺ."], ["العودة إلى أمه ورحلة المدينة", "عاد النبي ﷺ إلى مكة إلى أمه آمنة، وتذكر كتب السير أنها خرجت به إلى المدينة لزيارة أخوال جده عبد المطلب من بني عدي بن النجار، وزيارة قبر زوجها عبد الله، وكانت معها أم أيمن بركة الحبشية خادمتها. وأقامت هناك مدة، ثم ركبت راجعةً إلى مكة، فمرضت في الطريق في موضع يسمّى الأبواء بين مكة والمدينة، فتوفيت ودفنت هناك. وكان عمره ﷺ نحو ست سنين على ما ذكره أهل السير. وفي صحيح مسلم أن النبي ﷺ زار قبر أمه فبكى وأبكى من حوله، وقال: «استأذنت ربي أن أستغفر لها فلم يأذن لي، واستأذنته أن أزور قبرها فأذن لي، فزوروا القبور فإنها تذكّر الموت». وهذا يبيّن أن الله لم يأذن لنبيه بالاستغفار لها لأنها ماتت على الجاهلية قبل البعثة، ويبيّن كذلك وفاء النبي ﷺ وعاطفته نحو أمه. ولا يعارض ذلك رحمة الله الواسعة، فالأمر لله وحده، وعلى المسلم أن يسلّم لما ثبت عن نبيه ﷺ."], ["اليتم الكامل وثمرته", "بوفاة آمنة صار النبي ﷺ يتيم الأب والأم معًا وهو في سنٍّ صغيرة جدًّا، فعاد إلى مكة مع أم أيمن إلى جدّه عبد المطلب. وقد عاش ﷺ هذا الفقد المبكر، فكان يعرف مرارة اليتم فعلًا، ولذلك أوصى الله به في القرآن لما قال: ﴿فَأَمَّا الْيَتِيمَ فَلَا تَقْهَرْ﴾. وفي صحيح البخاري قال ﷺ: «أنا وكافل اليتيم في الجنة هكذا»، وأشار بالسبابة والوسطى وفرّج بينهما شيئًا. وهذه الوصية صادرة ممن ذاق اليتم ثم أكرمه الله بالنبوة. وقد جعل الله هذه الأعوام الأولى مدرسة صبر وتواضع، فنشأ النبي ﷺ لا يتكل على أبٍ ولا مالٍ، ويعرف قيمة الرحمة بالضعفاء، وتعلّم أن العناية الحقيقية من الله وحده، فكان في سيرته كلها رحيمًا باليتامى والمساكين. وتعلّم النبي ﷺ من هذا اليتم المبكر كيف يكون الإنسان معتمدًا على ربه، فكانت رحمته باليتامى والأرامل والضعفاء ظاهرة في خلقه وسلوكه، وجاءت تعاليم الإسلام في رعاية اليتيم وحفظ ماله وإكرامه تُذكّر بما ذاقه ﷺ في طفولته، وجعل الله لذلك أجرًا عظيمًا لمن قام به. فمن أراد القرب من النبي ﷺ فلينظر إلى اليتيم من حوله."]], "lesson": ["اليتم لا يمنع الله أن يجعل صاحبه سيد الخلق، فمن تولاه الله لم يضِع.", "الفصاحة والصحة وقوة الجسم من أسباب القيام بالدعوة، وقد أعدّ الله نبيه بنشأته في البادية.", "تطهير القلب مقدّم على كل عمل، وقد طهّر الله قلب نبيه منذ صغره ليكون مستعدًّا للوحي.", "على المسلم أن يرحم اليتيم ويكفله، فقد ذاق النبي ﷺ اليتم وجعل كافله رفيقه في الجنة."], "cat": "seerah"}, {"id": "s03", "title": "قصة إبراهيم عليه السلام", "type": "قصة قرآنية", "verse": "قُلْنَا يَا نَارُ كُونِي بَرْدًا وَسَلَامًا عَلَىٰ إِبْرَاهِيمَ", "source": "سورة الأنبياء 21:69", "parts": [["إبراهيم وأبوه", "نشأ إبراهيم عليه السلام في بيئة تعبد الأصنام، وكان أبوه آزر ممن يصنعها أو يعبدها، كما ذكر القرآن أن إبراهيم قال له: أتتخذ أصنامًا آلهة؟ إني أراك وقومك في ضلال مبين. وقد آتاه الله رشده من قبل، فكان عقله يرفض عبادة ما لا يسمع ولا يبصر ولا ينفع. وخاطب أباه بأدب وحنان، فقال: يا أبتِ لم تعبد ما لا يسمع ولا يبصر ولا يغني عنك شيئًا؟ يا أبتِ إني قد جاءني من العلم ما لم يأتك فاتبعني أهدك صراطًا سويًّا، يا أبتِ لا تعبد الشيطان. لكن الأب ردّ بقسوة: أراغب أنت عن آلهتي يا إبراهيم؟ لئن لم تنتهِ لأرجمنك واهجرني مليًّا. فقال إبراهيم عليه السلام: سلامٌ عليك، سأستغفر لك ربي. ثم تبرّأ منه لما تبيّن له أنه عدو لله. وكان مثالًا في الرحمة بالأب مع الثبات على الحق."], ["الاستدلال على التوحيد", "جاء في سورة الأنعام أن إبراهيم عليه السلام أراد أن يقيم الحجة على قومه بطريقة ذكية تقرّبهم إلى الفكرة بالتدرج. فلما جنّ عليه الليل رأى كوكبًا، فقال: هذا ربي، فلما أفل قال: لا أحب الآفلين. ثم رأى القمر بازغًا فقال: هذا ربي، فلما أفل قال: لئن لم يهدني ربي لأكونن من القوم الضالين. ثم رأى الشمس بازغة فقال: هذا ربي هذا أكبر، فلما أفلت قال: يا قوم إني بريء مما تشركون. إني وجهت وجهي للذي فطر السماوات والأرض حنيفًا وما أنا من المشركين. وهذا أسلوب مناظرة يهدم فيه كل معبود يزول، ليصل بهم إلى أن الإله الحق لا يغيب ولا يزول. وقد حاجّه قومه فخوّفوه بآلهتهم، فقال: ولا أخاف ما تشركون به إلا أن يشاء ربي شيئًا، وسع ربي كل شيء علمًا."], ["تحطيم الأصنام", "قرر إبراهيم عليه السلام أن يريهم عجز آلهتهم بنفسه. فأقسم قائلًا: وتالله لأكيدنّ أصنامكم بعد أن تولّوا مدبرين. وحين خرج القوم إلى عيدهم، دخل إلى معبدهم، فجعل الأصنام جذاذًا، أي قطعًا مكسّرة، إلا كبيرًا لهم لعلهم إليه يرجعون. فلما عادوا ورأوا ما حلّ بآلهتهم، سألوا: من فعل هذا بآلهتنا إنه لمن الظالمين؟ فقالوا: سمعنا فتى يذكرهم يقال له إبراهيم. فجاؤوا به على أعين الناس، وسألوه: أأنت فعلت هذا بآلهتنا يا إبراهيم؟ قال: بل فعله كبيرهم هذا فاسألوهم إن كانوا ينطقون. فرجعوا إلى أنفسهم وقالوا: إنكم أنتم الظالمون، ثم نكسوا على رؤوسهم: لقد علمتَ ما هؤلاء ينطقون. فقال لهم: أفتعبدون من دون الله ما لا ينفعكم شيئًا ولا يضركم؟ أفٍّ لكم ولما تعبدون من دون الله، أفلا تعقلون؟ وبهذا بيّن إبراهيم عليه السلام أن العبادة لا تكون إلا لمن يسمع ويبصر وينفع ويضر، وأن كثرة المتمسكين بالباطل لا تجعله حقًّا، وأن الحجة الصحيحة تُقام بالكلمة قبل اليد."], ["النار التي صارت بردًا", "حين عجز القوم عن الجواب لجؤوا إلى القوة، فقالوا: حرّقوه وانصروا آلهتكم إن كنتم فاعلين. وجمعوا له الحطب، وأوقدوا نارًا عظيمة، ثم ألقوه فيها. ولم يحدد القرآن كيفية إلقائه. وفي صحيح البخاري عن ابن عباس رضي الله عنهما أن آخر قول إبراهيم حين أُلقي في النار: حسبنا الله ونعم الوكيل. فجاء أمر الله: ﴿يَا نَارُ كُونِي بَرْدًا وَسَلَامًا عَلَىٰ إِبْرَاهِيمَ﴾، فلم تحرقه. وأراد القوم به كيدًا فجعلهم الله الأخسرين. ونجّاه الله وطلب منه الهجرة إلى الأرض المباركة. وما يُروى من تفاصيل كثيرة عن المنجنيق وجبريل وعرض المساعدة مما يتكرر في كتب القصص، فمنه ما لا يصح، ونكتفي بما ثبت في القرآن والبخاري. وهذه المعجزة من أعظم آيات الله، إذ أبطل بها خاصية الإحراق في النار بأمره سبحانه. وأخبر القرآن أنهم أرادوا به كيدًا، ولكن الله كفاه، وفي ذلك بيان أن حفظ الله لأوليائه يغلب كل تدبير يدبّره الظالمون لهم."], ["الهجرة والذرية", "هاجر إبراهيم عليه السلام من أرض قومه، وقال: إني مهاجر إلى ربي إنه هو العزيز الحكيم. وقال أيضًا: إني ذاهب إلى ربي سيهدين. وسأل الله ولدًا صالحًا فقال: ربّ هب لي من الصالحين، فبشّره الله بغلام حليم. وجاءت زوجته سارة وكانت عقيمًا، ثم بشّرته الملائكة بإسحاق ومن وراء إسحاق يعقوب. وبحسب ما صحّ في صحيح البخاري، جاء بهاجر وابنها إسماعيل إلى مكة وهي واد غير ذي زرع، فتركهما عند البيت وليس بها أنيس، ثم دعا ربه قائلًا: ربنا إني أسكنت من ذريتي بواد غير ذي زرع عند بيتك المحرّم ربنا ليقيموا الصلاة فاجعل أفئدة من الناس تهوي إليهم وارزقهم من الثمرات لعلهم يشكرون. فاستجاب الله دعاءه، وفجّر لهما زمزم، وجاءت قبيلة جرهم فسكنت عندهما، وصارت مكة بلدًا آمنًا. ومن هنا صارت مكة مهبط الوحي ومقصد الحجاج، وكل ذلك بدأ بدعوة صادقة من نبي توكّل على ربه وترك أهله في وادٍ لا ماء فيه ولا زرع."], ["رؤيا الذبح", "كبر إسماعيل عليه السلام وبلغ معه السعي، فرأى إبراهيم في المنام أنه يذبحه، ورؤيا الأنبياء وحي. فقال لابنه: يا بنيّ إني أرى في المنام أني أذبحك فانظر ماذا ترى. فقال الابن الصالح: يا أبتِ افعل ما تؤمر ستجدني إن شاء الله من الصابرين. فلما أسلما وتلّه للجبين، أي أضجعه على جبينه، ناداه الله: أن يا إبراهيم قد صدّقت الرؤيا إنا كذلك نجزي المحسنين، إن هذا لهو البلاء المبين. وفداه الله بذبح عظيم. وجعل الله ذلك سنة باقية في الأضاحي. وظاهر القرآن أن الذبيح هو الابن الذي بشّر به إبراهيم بعد ذكر الهجرة، وقد اختلف العلماء في تعيينه بين إسماعيل وإسحاق، والراجح عند كثير من المحققين أنه إسماعيل لأن القرآن ذكر البشارة بإسحاق بعد القصة، ولم يحدد القرآن اسمه صراحة. ثم رفع إبراهيم وابنه قواعد البيت وقالا: ربنا تقبل منا إنك أنت السميع العليم."]], "lesson": ["الدعوة تبدأ بالرحمة والأدب خاصة مع الأقارب مع التمسك بالحق.", "استعمال العقل والحجة في الدعوة أبلغ من الصدام والخصومة.", "قول حسبنا الله ونعم الوكيل عند الشدائد يفتح أبواب الفرج.", "الامتثال لأمر الله والصبر على الابتلاء يورث الفداء والفرج والذكر الحسن."], "cat": "story"}, {"id": "sr03", "title": "كفالة عبد المطلب ثم أبي طالب ورحلة الشام", "type": "من السيرة النبوية", "verse": "وَلَسَوْفَ يُعْطِيكَ رَبُّكَ فَتَرْضَىٰ", "source": "سورة الضحى 93:5", "parts": [["في كنف جده عبد المطلب", "بعد وفاة آمنة انتقلت كفالة النبي ﷺ إلى جده عبد المطلب بن هاشم، سيد قريش وكبيرها وصاحب السقاية، وكان محترمًا في قومه معظّمًا عند العرب. وتذكر كتب السير أن عبد المطلب كان يحب حفيده حبًّا شديدًا ويؤثره على أولاده، وكان له فراش في ظل الكعبة لا يجلس عليه أحد من أبنائه إجلالًا له، فكان النبي ﷺ يأتي فيجلس عليه وهو صغير، فيمنعه أعمامه فيقول جده: دعوه فإن لابني هذا شأنًا. وهذا الخبر مشهور في كتب السير، وإن لم يثبت في الصحيح بتفاصيله، لكنه يدل على عناية الجد به. وعاش النبي ﷺ في بيت عز وشرف، وقد رأى بنفسه كيف يعظّم الناس البيت الحرام ويقصدونه، فتأثر ذلك في نفسه. وهذه الأعوام القليلة عوّضته بعض ما فقده من حنان الأب، وجعلته قريبًا من سادة مكة وأحوالها. وبقي النبي ﷺ يذكر هذا الفضل لجده في نفسه، وإن كان جده على دين قومه."], ["وفاة عبد المطلب", "لم تطل أيام النبي ﷺ مع جده، فقد مات عبد المطلب وكان عمر النبي ﷺ نحو ثماني سنين على ما ذكر ابن إسحاق وغيره، وفي سنّه خلاف يسير بين أهل السير. فحزن عليه النبي ﷺ حزنًا شديدًا، وتذكر كتب السير أنه بكى عند جنازته. وبهذا فقد النبي ﷺ ثالث كافل له في سنوات قليلة، بعد أبيه وأمه. وكان عبد المطلب قد أوصى بابن ابنه إلى ابنه أبي طالب، شقيق عبد الله والد النبي ﷺ من أمه وأبيه على ما ذكر أهل النسب، فانتقلت الكفالة إليه. وتدلّ هذه الوصية على أن العرب كانوا يعظمون حقوق القرابة واليتيم، وأن الله هيّأ للنبي ﷺ من يحميه كلما فقد حاميًا. وقد وعده الله في القرآن بالعطاء الواسع فقال: ﴿وَلَسَوْفَ يُعْطِيكَ رَبُّكَ فَتَرْضَىٰ﴾، وكأنما كانت تلك السنوات الأولى تمهيدًا لعطاء أعظم بعدها. فكانت بذلك أيام جده وعمه أيام أمان ورعاية، وإن كانت العناية محدودة بإمكانات البيت وحال العرب."], ["في بيت أبي طالب", "كان أبو طالب عمّ النبي ﷺ رجلًا كريم النفس شريفًا في قومه، لكنه كان فقير المال كثير العيال، وقد قبل ابن أخيه في بيته كأحد أولاده بل أشد حبًّا. وتذكر كتب السير أن البركة كانت تحل في طعامه إذا حضر النبي ﷺ، وأنه كان يقدّمه على أولاده، ويصحبه معه حيثما ذهب. ونشأ النبي ﷺ عند عمه على العفاف والصدق والأمانة، لم يشاركه في ما كان عند الجاهليين من اللهو والعبث وعبادة الأصنام، فقد عصمه الله وحفظه. ومع هذا كله بقي أبو طالب على دين قومه حتى مات، وهو الأمر الذي سيذكره القرآن في قوله تعالى لنبيه: ﴿إِنَّكَ لَا تَهْدِي مَنْ أَحْبَبْتَ وَلَكِنَّ اللَّهَ يَهْدِي مَن يَشَاءُ﴾. فهذه المحبة القوية للنبي ﷺ لم تقترن بإسلام عمه، وهو درس عظيم في أن الهداية بيد الله وحده. وكان ﷺ يعاملهم بأحسن ما يكون، فلم يشتكِ منه عمه قط ولم يؤذِ أحدًا من أهل بيته."], ["رعي الغنم", "عمل النبي ﷺ في صغره في رعي الغنم، وهي مهنة الأنبياء، وقد ثبت ذلك في صحيح البخاري عن أبي هريرة رضي الله عنه أن النبي ﷺ قال: «ما بعث الله نبيًّا إلا رعى الغنم»، فقال أصحابه: وأنت؟ فقال: «نعم، كنت أرعاها على قراريط لأهل مكة». والقراريط جمع قيراط وهو جزء من الدينار أو الدرهم. وقد كان في الرعي تربية للنفس على الصبر وحسن الرعاية والرفق بالضعيف، وهي صفات يحتاجها من سيقود الأمة. وبهذا يظهر أن النبي ﷺ لم يكن بعيدًا عن الكسب والعمل منذ صغره، وأنه أكل من عمل يده، وقد قال ﷺ في صحيح البخاري: «ما أكل أحد طعامًا قط خيرًا من أن يأكل من عمل يده، وإن نبي الله داود عليه السلام كان يأكل من عمل يده». فالعمل عند المسلم شرف ولا عيب فيه. فكان مثالًا للأجير الأمين الذي يرعى ما استؤمن عليه، وهذا من أخلاق النبوة قبل البعثة."], ["رحلة الشام مع أبي طالب", "تذكر كتب السير أن أبا طالب خرج في تجارة إلى الشام ومعه النبي ﷺ وهو صغير، فكانت هذه أولى رحلاته إلى تلك البلاد. وتذكر كتب السير أن راهبًا في بصرى رأى علامات في الصبي، وأوصى عمه بالحذر عليه من اليهود والروم. وهذه القصة مشهورة في كتب السير وقد رواها الترمذي، لكن في تفاصيلها كلامًا لأهل العلم، ومن ذلك ذكر بعض الصحابة فيها بما لا يستقيم تاريخيًّا، فلا نعتمد منها إلا ما سبق، وهو أن الرحلة وقعت وأن عمه عاد به إلى مكة محافظًا عليه. ومن المهم أن نعلم أن هذه الرحلة لا تدل على أن النبي ﷺ تعلّم من راهب أو كتاب، فقد قال الله تعالى: ﴿وَمَا كُنتَ تَتْلُو مِن قَبْلِهِ مِن كِتَابٍ وَلَا تَخُطُّهُ بِيَمِينِكَ﴾، فكان أميًّا لا يقرأ ولا يكتب. ثم إن هذه الخبرة بالرحلات والطرق والأسواق نفعته بعد ذلك حين خرج في تجارة خديجة رضي الله عنها."], ["أثر هذه المرحلة", "كانت سنوات الصبا في كنف أبي طالب مرحلة إعداد وبناء. فقد عرف النبي ﷺ الحياة في مكة وفي طرق التجارة وفي رعاية الغنم، ورأى أحوال الناس وعاداتهم، من غير أن يتلوث بما كانوا عليه من الشرك والفحش. وقد وصف الله حال النبي ﷺ في ذلك بقوله: ﴿أَلَمْ يَجِدْكَ يَتِيمًا فَآوَىٰ * وَوَجَدَكَ عَائِلًا فَأَغْنَىٰ﴾. وكان أبو طالب قد صار حامي النبي ﷺ لسنوات طويلة بعد بعثته، ولم يتخلّ عنه لما اشتدت قريش عليه، وسيأتي ذلك في الدعوة والحصار. ومن هنا يتبين أن الله يعدّ لنبيه كل حاجة: كفيلًا في صغره، وحاميًا في دعوته، وزوجة ناصحة في وحيه. فالمؤمن إذا أحسن الظن بالله رأى كيف يرتب له الأسباب في كل مرحلة من عمره ويصنعه على عينه. وهكذا حفظ الله نبيه في أيام صباه، وكلما كبر ظهرت فيه علامات الاستعداد لأعظم رسالة في الأرض."]], "lesson": ["من فقد كافلًا هيّأ الله له غيره، فالله أرحم بعباده من أنفسهم.", "شرف العمل اليدوي عظيم، فقد رعى النبي ﷺ الغنم وأكل من كسب يده.", "القرابة والحب لا يغنيان عن الإيمان، فالهداية بيد الله وحده.", "لا يُعتمد في السيرة على كل ما اشتهر، فقد يشتهر الخبر وفي ثبوته نظر، فيُتثبت فيه."], "cat": "seerah"}, {"id": "s04", "title": "قصة يوسف عليه السلام", "type": "قصة قرآنية", "verse": "لَقَدْ كَانَ فِي يُوسُفَ وَإِخْوَتِهِ آيَاتٌ لِّلسَّائِلِينَ", "source": "سورة يوسف 12:7", "parts": [["الرؤيا وحسد الإخوة", "كان يوسف عليه السلام ابنًا ليعقوب عليه السلام، وكان له أحد عشر أخًا. وذات ليلة رأى في منامه أحد عشر كوكبًا والشمس والقمر رآهم له ساجدين، فحدّث أباه بها، فقال له يعقوب: يا بنيّ لا تقصص رؤياك على إخوتك فيكيدوا لك كيدًا، إن الشيطان للإنسان عدو مبين. وعرف يعقوب أن ابنه سيجتبيه ربه ويعلّمه من تأويل الأحاديث. وكان إخوة يوسف يرون أن أباهم يحبه أكثر منهم، فقالوا: ليوسف وأخوه أحب إلى أبينا منا ونحن عصبة، إن أبانا لفي ضلال مبين. فقال قائل منهم: اقتلوا يوسف أو اطرحوه أرضًا يخلُ لكم وجه أبيكم وتكونوا من بعده قومًا صالحين. وقال قائل منهم: لا تقتلوا يوسف وألقوه في غيابة الجبّ يلتقطه بعض السيارة إن كنتم فاعلين. فتواطؤوا على الأمر، وأقبلوا على أبيهم يطلبون إرسال يوسف معهم ليرتع ويلعب."], ["البئر والقميص", "أرسله يعقوب عليه السلام معهم بعد تردد وخوف أن يأكله الذئب، وأخذوه، وأجمعوا أن يجعلوه في غيابة الجب. وأوحى الله إلى يوسف: لتنبئنّهم بأمرهم هذا وهم لا يشعرون. وجاؤوا أباهم عشاءً يبكون، وقالوا إنهم ذهبوا يستبقون وتركوا يوسف عند متاعهم فأكله الذئب، وجاؤوا على قميصه بدم كذب. فقال يعقوب: بل سوّلت لكم أنفسكم أمرًا فصبر جميل والله المستعان على ما تصفون. وقد كان القميص سالمًا لم يمزق، فعرف يعقوب كذبهم من ذلك، وإن لم يذكر القرآن هذه الجزئية صراحة. وجاءت سيارة فأرسلوا واردهم فأدلى دلوه، قال: يا بشرى هذا غلام. وأخفوه بضاعة، وباعوه بثمن بخس دراهم معدودة وكانوا فيه من الزاهدين. وذلك أن القافلة لم ترَ فيه قيمة، والله يريد له شأنًا عظيمًا. وكان يعقوب عليه السلام يعلم أن ابنه محفوظ بعناية الله، فلم يزد على الصبر الجميل، وهو الصبر الذي لا شكوى فيه لغير الله."], ["في بيت العزيز والفتنة", "اشتراه رجل من مصر وقال لامرأته: أكرمي مثواه عسى أن ينفعنا أو نتخذه ولدًا. وبهذا مكّن الله ليوسف في الأرض وعلّمه من تأويل الأحاديث. ولما بلغ أشدّه آتاه الله حكمًا وعلمًا. وراودته التي هو في بيتها عن نفسه، وغلّقت الأبواب وقالت: هيت لك. فقال: معاذ الله إنه ربي أحسن مثواي إنه لا يفلح الظالمون. ولولا أن رأى برهان ربه لكان منها ما كان، وكان ذلك صرفًا من الله للسوء والفحشاء عنه. واستبقا الباب وقدّت قميصه من دُبُر، وألفيا سيدها لدى الباب، فاتهمته. فقال يوسف: هي راودتني عن نفسي، وشهد شاهد من أهلها أن القميص إن كان قُدّ من دبر فهو من الصادقين. فلما رأى قميصه قُدّ من دبر قال: إنه من كيدكن إن كيدكن عظيم، يوسف أعرض عن هذا واستغفري لذنبك إنك كنتِ من الخاطئين."], ["السجن وتأويل الرؤيا", "اجتمع نسوة المدينة ولمن امرأة العزيز، فأرينه ما أرين، وقطّعن أيديهن، وقلن: ما هذا بشرًا إن هذا إلا ملك كريم. فهدّدته إن لم يفعل ما تأمر ليُسجنن، فقال: ربّ السجن أحب إليّ مما يدعونني إليه وإلا تصرف عني كيدهن أصبُ إليهن وأكن من الجاهلين. فاستجاب له ربه فصرف عنه كيدهن. ثم بدا لهم من بعد ما رأوا الآيات ليسجننّه حتى حين. ودخل معه السجن فتيان، فرأى أحدهما أنه يعصر خمرًا، ورأى الآخر أنه يحمل فوق رأسه خبزًا تأكل الطير منه، فطلبا تأويلها. فدعاهما يوسف إلى التوحيد أولًا، ثم أوّل لهما رؤياهما: أما أحدكما فيسقي ربه خمرًا وأما الآخر فيصلب فتأكل الطير من رأسه. وقال للذي ظن أنه ناجٍ: اذكرني عند ربك. فأنساه الشيطان ذكر ربه فلبث في السجن بضع سنين. وهكذا أصبح السجن مدرسة لتعليم التوحيد، ودعا يوسف عليه السلام إلى ربه في أضيق الأماكن، ولم يمنعه الابتلاء من أداء رسالته."], ["رؤيا الملك والتمكين", "رأى ملك مصر في منامه سبع بقرات سمان يأكلهن سبع عجاف، وسبع سنبلات خضر وأخر يابسات. فجمع الملأ وسألهم عن تعبيرها فقالوا: أضغاث أحلام وما نحن بتأويل الأحلام بعالمين. وتذكّر الذي نجا من الفتيين يوسف بعد مدة، فأرسل إليه يسأله، فأوّل له: تزرعون سبع سنين دأبًا فما حصدتم فذروه في سنبله إلا قليلًا مما تأكلون، ثم يأتي من بعد ذلك سبع شداد يأكلن ما قدمتم لهن إلا قليلًا مما تحصنون، ثم يأتي من بعد ذلك عام فيه يغاث الناس وفيه يعصرون. فلما سمع الملك ذلك أمر بإخراجه، لكن يوسف أبى أن يخرج حتى تُبرّأ ساحته، فسأل الملك النسوة، فشهدت امرأة العزيز: الآن حصحص الحق أنا راودته عن نفسه وإنه لمن الصادقين. فقال الملك: ائتوني به أستخلصه لنفسي، فلما كلّمه قال: إنك اليوم لدينا مكين أمين. فقال يوسف: اجعلني على خزائن الأرض إني حفيظ عليم."], ["لقاء الإخوة ولمّ الشمل", "جاء إخوة يوسف من أرض كنعان يطلبون الطعام في سني القحط، فعرفهم وهم له منكرون. وأمرهم أن يأتوه بأخ لهم من أبيهم، وجعل بضاعتهم في رحالهم. وبعد مراجعات وابتلاءات، احتال في أخذ أخيه بأن جعل السقاية في رحله، فبقي معه. وحزن يعقوب عليه السلام وابيضت عيناه من الحزن، وقال: إنما أشكو بثّي وحزني إلى الله. ثم قال لأبنائه: يا بنيّ اذهبوا فتحسسوا من يوسف وأخيه ولا تيأسوا من روح الله. فلما دخلوا عليه قالوا: يا أيها العزيز مسّنا وأهلنا الضر. فعرّفهم بنفسه: أنا يوسف وهذا أخي قد منّ الله علينا. واعترفوا بخطئهم، فقال: لا تثريب عليكم اليوم يغفر الله لكم. وأمرهم أن يلقوا قميصه على وجه أبيه ليرتد بصيرًا، ثم جاء الأبوان والإخوة، ورفع أبويه على العرش وخرّوا له سجّدًا، وقال: يا أبتِ هذا تأويل رؤياي من قبل قد جعلها ربي حقًّا. وختم دعاءه: توفني مسلمًا وألحقني بالصالحين."]], "lesson": ["من صبر وعفّ عن الحرام رفعه الله ومكّن له وإن طال الابتلاء.", "العفو عند المقدرة من أخلاق الأنبياء: لا تثريب عليكم اليوم.", "أخذ الأسباب لا ينافي التوكل، فقد دبّر يوسف للقحط قبل وقوعه.", "الفرج يأتي بعد الشدة، والله يدبّر لعباده أحسن مما يخططون."], "cat": "story"}, {"id": "sr04", "title": "شباب النبي ﷺ وحلف الفضول وزواجه من خديجة", "type": "من السيرة النبوية", "verse": "وَوَجَدَكَ عَائِلًا فَأَغْنَىٰ", "source": "سورة الضحى 93:8", "parts": [["صدقه وأمانته", "نشأ النبي ﷺ في شبابه على الصدق والأمانة، حتى اشتهر بين قريش بلقب الصادق الأمين، وهو لقب ذكره أهل السير. ويدل على ذلك أن قريشًا لما اختلفت في وضع الحجر الأسود رضيت بحكمه، وأنهم كانوا يودعون عنده أماناتهم، وسيأتي بيان هذا. وفي صحيح البخاري أن النبي ﷺ لما صعد الصفا ينذر قومه قال لهم: «أرأيتكم لو أخبرتكم أن خيلًا بالوادي تريد أن تغير عليكم أكنتم مصدّقيّ؟» قالوا: ما جرّبنا عليك كذبًا. وهذه شهادة قومه له قبل الإسلام وبعده. فلم يكن في سيرته قبل البعثة ما يعيبه عندهم، وقد قال الله تعالى لهم: ﴿فَقَدْ لَبِثْتُ فِيكُمْ عُمُرًا مِّن قَبْلِهِ أَفَلَا تَعْقِلُونَ﴾، أي عشت بينكم أربعين سنة قبل الوحي وأنتم تعرفون أخلاقي. فكانت سيرته قبل النبوة حجةً عليهم. وكان قومه يعرفون ذلك فيه ويشهدون له به، وهذا من فضل الله أن جعل الناس شهودًا على خلقه قبل أن يدعوهم."], ["الفجار وحلف الفضول", "شهد النبي ﷺ في شبابه حربًا اشتعلت بين قريش وكنانة من جهة وقيس عيلان من جهة، وسميت حرب الفجار لأنها وقعت في الأشهر الحرم، وتذكر كتب السير أنه شارك فيها بإعداد النبل لأعمامه، ولم يقاتل فيها. ثم تداعى بعض أشراف قريش بعدها إلى حلف في دار عبد الله بن جدعان، أن ينصروا المظلوم في مكة من أي قبيلة كان، فسمّي حلف الفضول. وقد رُوي في مسند أحمد وغيره أن النبي ﷺ قال: «لقد شهدت في دار عبد الله بن جدعان حلفًا ما أحبّ أن لي به حُمر النعم، ولو أُدعى به في الإسلام لأجبت». وهذا يدل على أن الإسلام يقرّ كل ما فيه نصرة المظلوم وإقامة العدل، وإن كان صادرًا عن غير المسلمين، فما كان من مكارم الأخلاق فهو مقبول. وبهذا نعرف أن الأخلاق الفاضلة أساس مشترك بين الناس، وأن الإسلام لم يأتِ ليهدم المروءة بل ليتمّمها كما قال ﷺ: «إنما بعثت لأتمم صالح الأخلاق»."], ["العمل والتجارة", "كان النبي ﷺ يعمل بيده ويتكسب، فقد رعى الغنم كما ثبت في الصحيح، ثم عمل في التجارة، وكان يعرف بالأمانة فيها وعدم الغش والصدق في المعاملة. وكان مال قريش يُدار في أكثره بالتجارة، فكانت تجارته حسنة بحسب ما ذكره أهل السير، ولم يشتهر عنه ما يخلّ بالمروءة. وسمعت خديجة بنت خويلد رضي الله عنها بصدقه وأمانته، وكانت تاجرة شريفة ذات مال، تستأجر الرجال ليتجروا بمالها مقابل أجر أو شراكة. فعرضت عليه أن يخرج بمالها إلى الشام، وأن تعطيه أكثر مما كانت تعطي غيره، وأرسلت معه غلامًا لها يسمى ميسرة. وتذكر كتب السير أن رحلته كانت موفقة وأنه عاد بربح كبير، وأن ميسرة أخبر سيدته بما رأى من أمانته وحسن خلقه، فنمت في نفسها رغبة في الزواج منه. وهذا يدل على أن العمل بالتجارة والكسب الحلال من أخلاق الأنبياء ومن أسباب العفة والكرامة."], ["خديجة بنت خويلد رضي الله عنها", "كانت خديجة رضي الله عنها من أشرف نساء قريش نسبًا وأوسعهن عقلًا ومالًا، وتذكر كتب السير أنها لقّبت في الجاهلية بالطاهرة. وكانت قد تزوجت قبل النبي ﷺ ثم ترملت، ورغب فيها كثير من سادة قريش فلم تقبل. فلما رأت من النبي ﷺ ما رأت، أرسلت إليه من يخطبها له، وتذكر كتب السير أن ذلك كان عن طريق صديقة لها اسمها نفيسة. فعرض النبي ﷺ الأمر على أعمامه، وخرج معه عمه أبو طالب وحمزة رضي الله عنه وبعض كبراء بني هاشم إلى بيت خديجة، فتمّ العقد، وكان أبو طالب هو الذي خطب في الحفل. وقد وصف القرآن إغناء الله لنبيه بعد فقره بقوله: ﴿وَوَجَدَكَ عَائِلًا فَأَغْنَىٰ﴾، وكانت خديجة رضي الله عنها سببًا ظاهرًا من أسباب هذا الغنى. ولم يكن في هذا الزواج طلب مال فقط، بل كان زواج الكفاءة والمودة بين رجل عرف بالأمانة وامرأة عرفت بالفضل والعقل."], ["بيت الزوجية", "كان بيت النبي ﷺ وخديجة رضي الله عنها بيت سكينة ومودة، وقد رُزق منها ﷺ أولاده كلهم عدا إبراهيم رضي الله عنه، فولدت له القاسم وعبد الله وزينب ورقية وأم كلثوم وفاطمة رضي الله عنهن، وقد مات الأبناء الذكور صغارًا. وتذكر كتب السير أن الله امتنّ عليه بخديجة، فكانت أول من آمن به وصدّقه ونصره، وقد دلّ حديث البخاري عن عائشة رضي الله عنها على شدة محبته لها حتى بعد موتها. وتذكر كتب السير أن النبي ﷺ لم يتزوج عليها في حياتها، وكان زواجه منها هو الزواج الأول في حياته. وكانت خديجة رضي الله عنها سندًا نفسيًّا له قبل الوحي وبعده، فلما نزل عليه جبريل عليه السلام ورجع مرتجفًا، كانت أول من واساه، وهو ما سنأتي عليه في بدء الوحي. وكان لهذا الاستقرار في بيته أثر في هدوء نفسه وتفرغه للتفكر والتأمل في العبادة قبل البعثة."], ["زيد وعلي في بيت النبي ﷺ", "وتذكر كتب السير أن خديجة رضي الله عنها وهبت للنبي ﷺ غلامًا هو زيد بن حارثة رضي الله عنه، وكان قد وقع في الأسر صغيرًا فبيع في مكة، فأعتقه النبي ﷺ وتبنّاه في الجاهلية. وتذكر كتب السير أن أباه وعمّه جاءا يطلبانه، فخيّره النبي ﷺ فاختار البقاء عنده على الرجوع إلى أهله، فازداد النبي ﷺ حبًّا له. وقد بقي زيد ينتسب إلى النبي ﷺ حتى نزل قوله تعالى: ﴿ادْعُوهُمْ لِآبَائِهِمْ﴾. وكان زيد رضي الله عنه من أوائل من آمن. وكذلك نشأ علي بن أبي طالب رضي الله عنه في بيت النبي ﷺ بطلب منه، تخفيفًا عن أبي طالب وقت شدة أصابت قريشًا، على ما ذكر ابن إسحاق. فكان بيته مأوى لمن يحتاج، ومثالًا في الرحمة والإحسان قبل أن يُبعث بسنين. ولا يخفى أن هذا الإحسان في الصغر كان له أثره الطيب في حياة هذين الصحابيين، وفي مكانتهما بعد ذلك في الإسلام."]], "lesson": ["الخلق الحسن قبل الدعوة حجة للداعي، فقد شهد له قومه بالصدق والأمانة قبل أن يكون نبيًّا.", "نصرة المظلوم وإقامة العدل من مكارم الأخلاق التي يقرّها الإسلام ولو صدرت من غير المسلمين.", "الزوجة الصالحة نعمة عظيمة وعون على الخير، وقد كانت خديجة رضي الله عنها خير عون للنبي ﷺ.", "الأمانة في التجارة سبب للبركة والمكانة، وهي أساس الثقة بين الناس."], "cat": "seerah"}, {"id": "s05", "title": "قصة موسى عليه السلام: من الولادة إلى النجاة من فرعون", "type": "قصة قرآنية", "verse": "وَأَوْحَيْنَا إِلَىٰ أُمِّ مُوسَىٰ أَنْ أَرْضِعِيهِ فَإِذَا خِفْتِ عَلَيْهِ فَأَلْقِيهِ فِي الْيَمِّ وَلَا تَخَافِي وَلَا تَحْزَنِي إِنَّا رَادُّوهُ إِلَيْكِ وَجَاعِلُوهُ مِنَ الْمُرْسَلِينَ", "source": "سورة القصص 28:7", "parts": [["طغيان فرعون وميلاد موسى", "علا فرعون في أرض مصر وجعل أهلها شيعًا، يستضعف طائفة منهم، وهم بنو إسرائيل، يذبّح أبناءهم ويستحيي نساءهم، وقد أخبر الله أنه كان من المفسدين. وأراد الله أن يمنّ على هؤلاء المستضعفين ويجعلهم أئمة ويجعلهم الوارثين. وفي هذا الزمن وُلد موسى عليه السلام، وكانت أمه تخاف عليه أن يقتله جنود فرعون. فأوحى الله إليها وحي إلهام أن ترضعه، فإذا خافت عليه ألقته في اليمّ، وهو النيل، وألا تخاف ولا تحزن، فإن الله رادّه إليها وجاعله من المرسلين. فأرضعته، ثم وضعته في تابوت وألقته في الماء كما أُمرت. ولم يذكر القرآن اسم أمه ولا تفاصيل أخرى عن ولادته، وما يُروى من أسماء وقصص كثيرة في هذا الباب مأخوذ من أخبار بني إسرائيل، فلا نجزم به. ولكن الثابت أن أمًّا ألقت ولدها في الماء ثقةً بوعد ربها، وهي في أشد الخوف والرجاء."], ["في بيت فرعون", "التقط آل فرعون التابوت، ولم يعلموا أن هذا الطفل سيكون لهم عدوًّا وحزنًا، قال الله: ﴿فَالْتَقَطَهُ آلُ فِرْعَوْنَ لِيَكُونَ لَهُمْ عَدُوًّا وَحَزَنًا﴾. فقالت امرأة فرعون: قرة عين لي ولك لا تقتلوه عسى أن ينفعنا أو نتخذه ولدًا، وهم لا يشعرون. وأصبح فؤاد أم موسى فارغًا، أي خاليًا من الصبر من شدة القلق، وكادت تُظهر أمره لولا أن ربط الله على قلبها لتكون من المؤمنين. فقالت لأخت موسى: قصّيه، أي اتبعي أثره، فبصرت به عن جنب وهم لا يشعرون. وحرّم الله عليه المراضع من قبل، فلما أعيتهم الحيلة قالت أخته: هل أدلكم على أهل بيت يكفلونه لكم وهم له ناصحون؟ فردّه الله إلى أمه كي تقرّ عينها ولا تحزن، ولتعلم أن وعد الله حق. وهكذا نشأ موسى في قصر فرعون، وهو العدو الذي أراد الله أن يُهلكه على يديه، وهذا من لطف الله وتدبيره."], ["قتل القبطي والفرار", "لما بلغ موسى عليه السلام أشدّه واستوى آتاه الله حكمًا وعلمًا، وكذلك يجزي المحسنين. ودخل المدينة على حين غفلة من أهلها، فوجد فيها رجلين يقتتلان، هذا من شيعته وهذا من عدوه، فاستغاثه الذي من شيعته على الذي من عدوه، فوكزه موسى فقضى عليه، ولم يكن قصده القتل. فقال: هذا من عمل الشيطان إنه عدو مضل مبين، ثم قال: رب إني ظلمت نفسي فاغفر لي فغفر له. وأصبح في المدينة خائفًا يترقب، فإذا الذي استنصره بالأمس يستصرخه، فقال له موسى: إنك لغوي مبين. ولما أراد أن يبطش بالذي هو عدو لهما، قال: أتريد أن تقتلني كما قتلت نفسًا بالأمس؟ فانتشر خبر القتل في المدينة. فجاء رجل من أقصى المدينة يسعى، قال: يا موسى إن الملأ يأتمرون بك ليقتلوك فاخرج إني لك من الناصحين. فخرج منها خائفًا يترقب، قال: رب نجني من القوم الظالمين."], ["في مدين", "توجّه موسى عليه السلام تلقاء مدين، وقال: عسى ربي أن يهديني سواء السبيل. ولما ورد ماء مدين وجد عليه أمة من الناس يسقون، ووجد من دونهم امرأتين تذودان، أي تمنعان غنمهما عن الماء. فسألهما عن شأنهما فقالتا: لا نسقي حتى يصدر الرعاء وأبونا شيخ كبير. فسقى لهما، ثم تولّى إلى الظل، فقال: رب إني لما أنزلت إليّ من خير فقير. فجاءته إحداهما تمشي على استحياء، قالت: إن أبي يدعوك ليجزيك أجر ما سقيت لنا. فلما جاءه وقصّ عليه القصص قال: لا تخف نجوت من القوم الظالمين. قالت إحداهما: يا أبت استأجره إن خير من استأجرت القوي الأمين. فقال الشيخ: إني أريد أن أنكحك إحدى ابنتيّ هاتين على أن تأجرني ثماني حجج، فإن أتممت عشرًا فمن عندك. ولم يحدد القرآن اسم هذا الرجل الصالح، ومن قال إنه شعيب فهو اجتهاد لا نص فيه. وصحّ في البخاري عن ابن عباس أن موسى قضى أكمل الأجلين وأطيبهما، أي عشر سنين."], ["النار والوادي المقدس", "قضى موسى الأجل وسار بأهله، فآنس من جانب الطور نارًا، فقال لأهله: امكثوا إني آنست نارًا لعلي آتيكم منها بخبر أو جذوة من النار لعلكم تصطلون. فلما أتاها نودي من شاطئ الوادي الأيمن في البقعة المباركة من الشجرة: أن يا موسى إني أنا الله رب العالمين. وقيل له: فاخلع نعليك إنك بالواد المقدس طوى. وأوحى الله إليه: وأنا اخترتك فاستمع لما يوحى، إنني أنا الله لا إله إلا أنا فاعبدني وأقم الصلاة لذكري. ثم سأله: وما تلك بيمينك يا موسى؟ قال: هي عصاي أتوكأ عليها وأهشّ بها على غنمي ولي فيها مآرب أخرى. فأمره أن يلقيها فإذا هي حية تسعى، ثم أمره بأخذها ولا يخاف. وأمره أن يضع يده في جيبه فتخرج بيضاء من غير سوء. ثم قال: اذهب إلى فرعون إنه طغى. فقال موسى: رب اشرح لي صدري ويسّر لي أمري، واحلل عقدة من لساني يفقهوا قولي، واجعل لي وزيرًا من أهلي هارون أخي. فأجاب الله سؤله."], ["المواجهة والسحرة", "ذهب موسى وأخوه هارون عليهما السلام إلى فرعون، وقال الله لهما: فقولا له قولًا لينًا لعله يتذكر أو يخشى. فبلّغاه الرسالة، فقال فرعون: وما رب العالمين؟ قال موسى: رب السماوات والأرض وما بينهما إن كنتم موقنين. فتحدّاه فرعون وأراه موسى العصا واليد، فقال فرعون: إن هذا لساحر عليم، وجمع السحرة ليوم الزينة. فألقوا حبالهم وعصيّهم، وقالوا: بعزة فرعون إنا لنحن الغالبون. فأوجس في نفسه خيفة موسى، فقال الله: لا تخف إنك أنت الأعلى، وألقِ ما في يمينك تلقف ما صنعوا. فألقى عصاه فإذا هي تلقف ما يأفكون. فألقي السحرة ساجدين، قالوا: آمنا برب هارون وموسى. فهدّدهم فرعون أن يقطّع أيديهم وأرجلهم من خلاف ويصلّبهم، فقالوا: لا ضير إنا إلى ربنا منقلبون. وآمن رجل من آل فرعون يكتم إيمانه، وقال: أتقتلون رجلًا أن يقول ربي الله وقد جاءكم بالبينات من ربكم؟"], ["الخروج وانفلاق البحر", "أوحى الله إلى موسى أن يسري بعباده ليلًا، فخرج ببني إسرائيل، وأتبعهم فرعون بجنوده بُكرةً. فلما تراءى الجمعان قال أصحاب موسى: إنا لمدركون. قال: كلا إن معي ربي سيهدين. فأوحى الله إليه أن اضرب بعصاك البحر، فانفلق فكان كل فرق كالطود العظيم. وأزلف الله الآخرين، أي قرّبهم، وأنجى موسى ومن معه أجمعين، ثم أغرق الآخرين. ولما دخل فرعون وجنوده في الطريق اليابس، أمر الله البحر فأطبق عليهم. فلما أدركه الغرق قال: آمنت أنه لا إله إلا الذي آمنت به بنو إسرائيل وأنا من المسلمين. فقيل له: آلآن وقد عصيت قبل وكنت من المفسدين؟ فاليوم ننجيك ببدنك لتكون لمن خلفك آية. وصحّ في البخاري أن النبي صلى الله عليه وسلم قدم المدينة فوجد اليهود يصومون يوم عاشوراء، فسألهم، فقالوا: هذا يوم عظيم أنجى الله فيه موسى وقومه، فقال: «نحن أحق بموسى منكم»، فصامه وأمر بصيامه. وبذلك انتهى طغيان فرعون."]], "lesson": ["وعد الله حق، فمن توكل عليه كفاه حتى حين لا يرى بابًا للنجاة.", "الدعوة تبدأ بالقول اللين حتى مع أعتى الطغاة.", "الأمانة والقوة صفتان تجتمعان في خير من يُستأجر ويُعتمد عليه.", "التوبة السريعة والاستغفار بعد الخطأ، والصبر على الابتلاء حتى يأتي الفرج."], "cat": "story"}, {"id": "sr05", "title": "بناء الكعبة وتحكيم النبي ﷺ في الحجر الأسود", "type": "من السيرة النبوية", "verse": "وَإِنَّكَ لَعَلَىٰ خُلُقٍ عَظِيمٍ", "source": "سورة القلم 68:4", "parts": [["الكعبة قبل التجديد", "الكعبة أول بيت وضع للناس للعبادة، قال تعالى: ﴿إِنَّ أَوَّلَ بَيْتٍ وُضِعَ لِلنَّاسِ لَلَّذِي بِبَكَّةَ مُبَارَكًا وَهُدًى لِّلْعَالَمِينَ﴾، وقد رفع قواعدها إبراهيم وإسماعيل عليهما السلام كما أخبر القرآن. وبعد قرون كانت الكعبة في عهد النبي ﷺ بناءً متواضعًا من حجارة رصف بعضها فوق بعض بلا طين، ارتفاعه قليل وليس له سقف. وتذكر كتب السير أن السيول كانت تنحدر من الجبال إلى مكة فتضرّ بها، وأن حريقًا أصاب الكعبة فضعف جدارها. فرأت قريش أن تعيد بناءها، وكانوا يعظمون البيت ويخشون أن يصيبهم شر إن مسّوه بسوء، فتهيّبوا هدمه، فبدأ الوليد بن المغيرة بالهدم وهو يدعو الله ألا يريد إلا الإصلاح، فلما رأوا أنه لم يصبه شيء تبعوه. وكان النبي ﷺ شابًّا في نحو الخامسة والثلاثين على ما ذكر ابن إسحاق، أي قبل البعثة بنحو خمس سنين. وكان فعل ذلك إجلالًا للبيت وحرصًا على سلامة بنائه، وهذا مما بقي في نفوس الناس من تعظيم الحرم."], ["جمع المال والبناء", "اتفقت قريش على ألا يدخل في بناء البيت إلا مال طيب لا ربا فيه ولا ظلم ولا مهر بغيّ. وهذا ثابت في الحديث، ففي الصحيحين أن النبي ﷺ قال لعائشة رضي الله عنها: «ألم تري أن قومك لما بنوا الكعبة اقتصروا عن قواعد إبراهيم»، وفي رواية أن النفقة الحلال قصّرت بهم، فأخرجوا الحِجْر من البيت. وتذكر كتب السير أن سفينة لرجل رومي تحطمت على ساحل جدة، فاشترت قريش خشبها لتسقيف الكعبة، وأن نجّارًا رومياً يسمى باقوم ساعدهم. وقسّموا العمل بين القبائل، لكل قبيلة جانب. وفي صحيح البخاري عن جابر رضي الله عنه أن النبي ﷺ والعباس رضي الله عنه كانا ينقلان الحجارة، فقال العباس للنبي ﷺ: اجعل إزارك على رقبتك يقيك من الحجارة، ففعل فخرّ إلى الأرض وطمحت عيناه إلى السماء، ثم قال: «إزاري إزاري»، فشدّ عليه إزاره. فصان الله نبيه عن كشف العورة قبل النبوة."], ["الاختلاف في الحجر الأسود", "لما بلغ البناء موضع الحجر الأسود، وهو الحجر الذي أنزله الله من الجنة على ما جاء في بعض الأحاديث، وكان إبراهيم عليه السلام قد وضعه عند ركن الكعبة، تنازعت قبائل قريش أيها يكون لها شرف وضعه. وكل قبيلة أرادت أن تنفرد بهذا الشرف. فاشتد الجدال واحتدم، حتى كاد القتال أن يقع في الحرم، وتذكر كتب السير أن بعض القبائل تحالفت وأعدّت للقتال، وبقي النزاع أيامًا. وفي هذا المشهد يظهر أن قريشًا كانت تعظّم الكعبة، لكنها كانت أسيرة للعصبية القبلية، حتى تكاد تفسد على نفسها ما بنته بيدها. وقد وصف القرآن ذلك بقوله: ﴿الْحَمِيَّةَ حَمِيَّةَ الْجَاهِلِيَّةِ﴾، وجاء الإسلام فنهى عن العصبية وأمر باجتماع الكلمة. وكان لا بد من حل ينقذ مكة من حرب لا فائدة منها، وهو ما حصل بعد ذلك. وكان كل قبيلة تدّعي أنها الأحق، ولم يكن في الجزيرة سلطة تفصل بين المتنازعين إلا الأعراف والحكماء، فلذلك كان تعيين الحكَم أمرًا مهمًّا في تلك الأيام."], ["الحكَم الذي ارتضوه", "تذكر كتب السير أن أبا أمية بن المغيرة، وكان أكبر قريش سنًّا، اقترح أن يحكّموا بينهم أول من يدخل من باب المسجد، فاتفقوا على ذلك. وكان أول من دخل النبي ﷺ، فلما رأوه قالوا: هذا الأمين رضينا، هذا محمد. وهذا الخبر رواه الإمام أحمد في مسنده وغيره من أهل الحديث، وقد قبله أهل العلم وذكره ابن كثير في السيرة. وفي قبولهم له ما يدل على ما ثبت له في قلوبهم من الصدق والأمانة، فلم يكن في قريش من يُحتكم إليه في مثل هذا غير من يثقون به كلهم. وقد جعل الله هذا الأمر حدثًا يشهد لنبيه قبل بعثته، حتى إن من عاداه بعد البعثة كان يعرف أنه ما كذب قط. فكانت هذه الحادثة أحد المواقف التي أظهرت للناس شخصية النبي ﷺ ومكانته. ولو كان لهم فيه ريبة ما ارتضوه، لكنه كان عندهم ثقة بلا نزاع، وفي ذلك درس للدعاة أن الثقة تُكتسب بالسيرة قبل الكلام."], ["الحل الحكيم", "ثم أمر النبي ﷺ بثوب، فبسطه على الأرض، ووضع الحجر الأسود فيه بيده الشريفة، ثم قال: لتأخذ كل قبيلة بطرف من أطراف الثوب، ثم ارفعوه جميعًا. وهذا الحل مذكور في كتب السير ومسند أحمد، وهو حل بسيط عبقري أرضى الجميع، فلم تنفرد قبيلة بالشرف، وإنما اشتركت كل القبائل في رفعه. فلما بلغوا موضعه أخذه النبي ﷺ بيده ووضعه في مكانه، ثم بنوا عليه. وبهذه الحكمة حُقنت الدماء وانتهت الأزمة، وكان عمره نحو خمس وثلاثين سنة على قول أهل السير. وقد ظهر في هذا الموقف عقل النبي ﷺ ورجاحة رأيه وقدرته على الجمع بين الأطراف المتنازعة، وهي صفات ستظهر لاحقًا في إدارته للدعوة والدولة. وقد قال الله تعالى فيه: ﴿وَإِنَّكَ لَعَلَىٰ خُلُقٍ عَظِيمٍ﴾. ولم يكن في فعله ﷺ ما يخالف الشرع، فقد وضع الحجر في الثوب ولم يمسّ الأمر بسوء، وهو مثال على حسن إدارة الخلاف بأقل الخسائر الممكنة. ولو قام أحد بوضعه بيده لانفرد بالفضل، ولو تُرك الأمر لتنازع القوم لوقع الشر."], ["نتيجة البناء وما بقي من الكعبة", "انتهى بناء قريش للكعبة، وقصّروا عن قواعد إبراهيم عليه السلام فبقي الحِجْر خارج البيت، وجعلوا لها بابًا مرتفعًا ليدخلوا من يشاؤون ويمنعوا من يشاؤون. وفي الصحيحين أن النبي ﷺ قال لعائشة رضي الله عنها: «لولا أن قومك حديثو عهد بجاهلية لأمرت بالبيت فهُدم فأدخلت فيه ما أُخرج منه، وألزقته بالأرض، وجعلت له بابين، بابًا شرقيًّا وبابًا غربيًّا»، وفي رواية: «لولا حداثة عهدهم بكفر». فترك النبي ﷺ ذلك مراعاةً لحال الناس حتى لا يفتتنوا، وهذا يدل على أن الحكمة في الدعوة تقتضي مراعاة قلوب الناس وعدم الإقدام على ما قد يؤدي إلى فتنة. وقد بقي بناء قريش حتى جاء عبد الله بن الزبير رضي الله عنهما فبناه على ما أراد النبي ﷺ، ثم أعاده الحجاج إلى بناء قريش كما ذكر أهل العلم. وهذا الفقه النبوي مأخوذ منه قاعدة جليلة هي أن المصلحة الراجحة تقدَّم أحيانًا على ما هو أفضل في ذاته."]], "lesson": ["الأمانة والصدق قبل النبوة جعلا قريشًا كلها ترضى بحكمه، فالسمعة الطيبة رأس مال الداعية.", "الحكمة في الخلاف أن نجمع بين المختلفين بحل يرضي الجميع، لا أن ننتصر لطرف.", "العصبية القبلية تفسد ما بُني بجهد كبير، والإسلام جاء ليقضي عليها بالأخوة.", "مراعاة حال الناس وحداثة عهدهم بالدين من حكمة الدعوة، حتى لو كان الأمر المتروك فاضلًا."], "cat": "seerah"}, {"id": "s06", "title": "قصة موسى والخضر عليهما السلام", "type": "قصة قرآنية", "verse": "قَالَ إِنَّكَ لَن تَسْتَطِيعَ مَعِيَ صَبْرًا", "source": "سورة الكهف 18:67", "parts": [["سبب الرحلة", "جاء في صحيح البخاري عن أبيّ بن كعب رضي الله عنه عن النبي صلى الله عليه وسلم أن موسى عليه السلام قام خطيبًا في بني إسرائيل، فسُئل: أيّ الناس أعلم؟ فقال: أنا. فعتب الله عليه إذ لم يردّ العلم إليه، وأوحى إليه أن لي عبدًا بمجمع البحرين هو أعلم منك. فقال موسى: يا رب كيف لي به؟ فقيل له: تأخذ حوتًا فتجعله في مكتل، فحيث فقدت الحوت فهو ثَمّ. فانطلق ومعه فتاه يوشع بن نون، وحملا حوتًا في مكتل، وقال موسى لفتاه: لا أبرح حتى أبلغ مجمع البحرين أو أمضي حقبًا. ولم يحدد القرآن موضع مجمع البحرين، والأقوال فيه اجتهادات لا دليل عليها. وفي ذلك درس عظيم: أن العالم مهما بلغ علمه ينبغي أن يتواضع ويرجع العلم إلى الله، وأن طلب العلم يقتضي السفر والتعب وعدم الاستعجال، فقد قال موسى عليه السلام ما قال وهو نبي كريم."], ["فقد الحوت ولقاء العبد الصالح", "سار موسى وفتاه حتى بلغا مجمع البحرين، فنسيا حوتهما. وجاء في الحديث أن الحوت دبّت فيه الحياة بإذن الله وسلك سبيله في البحر سربًا، وأن الله أمسك عن الحوت جريان الماء فصار مثل الطاق، أي كالنفق. ثم تجاوزا وأصاب موسى التعب، فقال لفتاه: آتنا غداءنا لقد لقينا من سفرنا هذا نصبًا. فقال الفتى: أرأيت إذ أوينا إلى الصخرة فإني نسيت الحوت وما أنسانيه إلا الشيطان أن أذكره واتخذ سبيله في البحر عجبًا. قال موسى: ذلك ما كنا نبغ، فارتدّا على آثارهما قصصًا. فوجدا عند الصخرة عبدًا من عباد الله، قال الله فيه: ﴿آتَيْنَاهُ رَحْمَةً مِّنْ عِندِنَا وَعَلَّمْنَاهُ مِن لَّدُنَّا عِلْمًا﴾. وسُمّي الخضر، كما في البخاري، لأنه جلس على فروة بيضاء فإذا هي تهتز من خلفه خضراء. ولم يذكر القرآن اسمه، واختلف العلماء هل هو نبي أم وليّ، والأرجح عند كثيرين أنه نبي لقوله: وما فعلته عن أمري."], ["الشرط والتحذير", "قال موسى عليه السلام للخضر بأدب العالم المتعلّم: هل أتّبعك على أن تعلمني مما عُلّمت رشدًا؟ فأجابه الخضر: إنك لن تستطيع معي صبرًا، وكيف تصبر على ما لم تحط به خبرًا؟ وهذه الكلمة تنبئ بأن ما سيراه موسى سيبدو في ظاهره منكرًا، وإن كان في حقيقته حكمة وعلمًا لدنيًّا. قال موسى: ستجدني إن شاء الله صابرًا ولا أعصي لك أمرًا. فقال الخضر: فإن اتبعتني فلا تسألني عن شيء حتى أحدث لك منه ذكرًا. فانطلقا يمشيان على ساحل البحر، ولم يحدد القرآن زمن هذه الرحلة ولا مدتها. وقد وافق موسى على الشرط، لكن النفس البشرية تضيق بما تراه ظاهرًا من الخطأ. وفي هذا يتبين أن طالب العلم لا بد أن يعلم أن لكل فعل علّة قد تخفى، وأن العجلة في الحكم على الأمور قبل معرفة أسبابها تضيع الحكمة."], ["السفينة والغلام", "ركبا في سفينة، فخرقها الخضر. فاعترض موسى: أخرقتها لتغرق أهلها؟ لقد جئت شيئًا إمرًا. قال الخضر: ألم أقل إنك لن تستطيع معي صبرًا؟ قال موسى: لا تؤاخذني بما نسيت ولا ترهقني من أمري عسرًا. وفي الحديث الصحيح أنه جاء عصفور فوقع على حرف السفينة فنقر في البحر نقرة، فقال الخضر: ما نقص علمي وعلمك من علم الله إلا مثل ما نقص هذا العصفور من هذا البحر. ثم انطلقا حتى لقيا غلامًا فقتله الخضر. فقال موسى: أقتلت نفسًا زكية بغير نفس؟ لقد جئت شيئًا نكرًا. قال: ألم أقل لك إنك لن تستطيع معي صبرًا؟ قال موسى: إن سألتك عن شيء بعدها فلا تصاحبني قد بلغت من لدني عذرًا. ولم يحدد القرآن اسم الغلام ولا عمره. والمعروف أن ما فعله الخضر جاء بوحي من الله، فلا يجوز لأحد أن يقتدي به في ذلك."], ["الجدار والقرية", "ثم انطلقا حتى إذا أتيا أهل قرية استطعما أهلها، فأبوا أن يضيّفوهما. فوجدا فيها جدارًا يريد أن ينقضّ فأقامه الخضر. فقال موسى: لو شئت لاتخذت عليه أجرًا. فهنا انتهت الصحبة، قال الخضر: هذا فراق بيني وبينك سأنبئك بتأويل ما لم تستطع عليه صبرًا. وفي ذلك درس أن القرية التي لم تُكرم الضيف أُقيم لها الجدار بلا ثمن، لأن وراء الجدار حكمة أرادها الله. ولم يحدد القرآن اسم القرية ولا مكانها، وقيل غير ذلك مما لا دليل عليه. وفي صحيح البخاري قال النبي صلى الله عليه وسلم: «يرحم الله موسى لوددنا لو أنه صبر حتى يقصّ علينا من أمرهما». وهذا يدل على أن في القصة علمًا كثيرًا لم نعلمه، وأن موسى عليه السلام كان شديد الحرص على طلب الحق، لكنه عجل لأنه رأى ما ظاهره الظلم ولم يكن يعلم الباطن."], ["تأويل ما لم يستطع عليه صبرًا", "بيّن الخضر الحكمة. أما السفينة فكانت لمساكين يعملون في البحر، فأردت أن أعيبها، وكان وراءهم ملك يأخذ كل سفينة غصبًا. وأما الغلام فكان أبواه مؤمنين، فخشينا أن يرهقهما طغيانًا وكفرًا، فأردنا أن يبدلهما ربهما خيرًا منه زكاة وأقرب رحمًا. وأما الجدار فكان لغلامين يتيمين في المدينة، وكان تحته كنز لهما، وكان أبوهما صالحًا، فأراد ربك أن يبلغا أشدهما ويستخرجا كنزهما رحمةً من ربك. ولم يحدد القرآن نوع الكنز، وقيل إنه مال أو علم مكتوب، ولا دليل صحيحًا على التعيين. ثم قال الخضر: وما فعلته عن أمري ذلك تأويل ما لم تسطع عليه صبرًا. وفي هذا بيان عظيم أن الله يدبّر لعباده بما فيه خيرهم، وإن كان ظاهره الابتلاء، وأن علم البشر مهما عظم قليل بجانب علم الله، وأن الرضا بالقضاء يورث الطمأنينة، وأن حسن الظن بالله من أعظم أسباب الراحة."]], "lesson": ["التواضع في طلب العلم، فمهما بلغ المرء فوق كل ذي علم عليم.", "لا تحكم على الأمور بظواهرها، فقد تخفى الحكمة وراء ما نكره.", "الصبر والتأني وعدم العجلة من أسباب نيل العلم والفهم.", "الإيمان بقدر الله وحسن الظن به في الابتلاءات، فهو يختار لعبده الخير."], "cat": "story"}, {"id": "sr06", "title": "غار حراء وبدء الوحي", "type": "من السيرة النبوية", "verse": "اقْرَأْ بِاسْمِ رَبِّكَ الَّذِي خَلَقَ", "source": "سورة العلق 96:1", "parts": [["الخلوة في غار حراء", "لما قارب النبي ﷺ الأربعين من عمره حُبّبت إليه العزلة، فكان يخرج إلى غار في جبل حراء قرب مكة، يتعبد فيه الليالي ذوات العدد. وقد روت أمنا عائشة رضي الله عنها في صحيح البخاري أن أول ما بُدئ به رسول الله ﷺ من الوحي الرؤيا الصالحة في النوم، فكان لا يرى رؤيا إلا جاءت مثل فلق الصبح. ثم حُبّب إليه الخلاء، فكان يخلو بغار حراء فيتحنّث فيه، وهو التعبد، الليالي ذوات العدد قبل أن ينزع إلى أهله، ويتزود لذلك، ثم يرجع إلى خديجة فيتزود لمثلها. ولم يكن قد جاءه الوحي بالشريعة، لكنه كان يتعبد على ما بقي عنده من دين إبراهيم عليه السلام، متأملًا في ملكوت الله بعيدًا عن صخب مكة وأوثانها. وكانت هذه العزلة إعدادًا لقلبه ليستقبل أعظم حدث في تاريخ البشرية. وكان ذلك الخروج إلى الغار تهيئةً ربّانية لقلبه، وبعدًا عن ضجيج الحياة ليستعدّ لاستقبال الوحي."], ["مجيء الملك", "قالت عائشة رضي الله عنها: حتى جاءه الحق وهو في غار حراء، فجاءه الملك فقال: اقرأ، قال: «ما أنا بقارئ». قال: «فأخذني فغطّني حتى بلغ مني الجهد، ثم أرسلني فقال: اقرأ، قلت: ما أنا بقارئ، فأخذني فغطّني الثانية حتى بلغ مني الجهد، ثم أرسلني فقال: اقرأ، فقلت: ما أنا بقارئ، فأخذني فغطّني الثالثة ثم أرسلني فقال: ﴿اقْرَأْ بِاسْمِ رَبِّكَ الَّذِي خَلَقَ * خَلَقَ الْإِنسَانَ مِنْ عَلَقٍ * اقْرَأْ وَرَبُّكَ الْأَكْرَمُ﴾». وهذه الواقعة رواها البخاري ومسلم. وفيها أن جبريل عليه السلام هو الملك الذي جاء بالوحي، وأن أول ما نزل من القرآن هذه الآيات الأولى من سورة العلق على الصحيح. وبهذه الآيات بدأت الرسالة، وبدأ معها أمر القراءة والعلم، وهو أمر لافت في أمة عرفت بالأمية. وقد كان ذلك في شهر رمضان، فقد قال تعالى: ﴿شَهْرُ رَمَضَانَ الَّذِي أُنزِلَ فِيهِ الْقُرْآنُ﴾. وفي قوله «ما أنا بقارئ» دليل على أنه ﷺ كان أميًّا لا يقرأ ولا يكتب، وهذا من دلائل صدقه."], ["العودة إلى خديجة", "رجع النبي ﷺ بها ترجف بوادره، أي يرتعد لحمه من الخوف والرهبة، حتى دخل على خديجة بنت خويلد رضي الله عنها فقال: «زمّلوني زمّلوني»، فزمّلوه حتى ذهب عنه الروع. فقال لخديجة وأخبرها الخبر: «لقد خشيت على نفسي». فقالت خديجة: كلّا والله ما يخزيك الله أبدًا، إنك لتصل الرحم، وتحمل الكَلّ، وتكسب المعدوم، وتقري الضيف، وتعين على نوائب الحق. هكذا جاء في الصحيحين. وفي هذا الكلام دليل على فقه خديجة رضي الله عنها وحكمتها، فقد استدلت بأخلاق النبي ﷺ على أن الله لن يخذله. والمعنى أن من كانت هذه صفاته لا يسلّط الله عليه الشيطان ولا يضيّعه. فكانت أول من واساه وثبّته وصدّقه، وأعطته من العقل والسكينة ما خفّف عنه هول الموقف. ومعنى «تكسب المعدوم» أنها تعطي الفقير ما لا يجده عند غيره، ومعنى «تحمل الكل» أنها تعين الضعيف الذي لا يقوى على أمره، وكلها من أخلاق النبي ﷺ قبل الوحي ومن شواهد حسن سيرته."], ["ورقة بن نوفل", "ثم انطلقت به خديجة رضي الله عنها إلى ابن عمها ورقة بن نوفل بن أسد بن عبد العزى، وكان قد تنصّر في الجاهلية، وكان يكتب الكتاب العبراني فيكتب من الإنجيل بالعبرانية ما شاء الله أن يكتب، وكان شيخًا كبيرًا قد عمي. فقالت له خديجة: يا ابن عمّ اسمع من ابن أخيك. فسأله ورقة عما رأى فأخبره النبي ﷺ، فقال ورقة: هذا الناموس الذي نزّل الله على موسى، يا ليتني فيها جذعًا، ليتني أكون حيًّا إذ يخرجك قومك. فقال رسول الله ﷺ: «أو مخرجيّ هم؟» قال: نعم، لم يأتِ رجل قط بمثل ما جئت به إلا عودي، وإن يدركني يومك أنصرك نصرًا مؤزَّرًا. ثم لم ينشب ورقة أن توفي، وفتر الوحي. والناموس هو جبريل عليه السلام، صاحب السر الذي يختص بالوحي. وفي قول ورقة دليل على أن أهل الكتاب كانوا ينتظرون نبيًّا في آخر الزمان، وأن المصلحين يلقون عداوة قومهم في كل زمن."], ["فترة الوحي ونزول المدثر", "وبعد هذه الواقعة فتر الوحي مدة لم يُحدَّد قدرها بدقة في الصحيح، وكان النبي ﷺ يحزن لانقطاعه حتى كان يهمّ بالتردي من رؤوس الجبال، كما ورد في رواية البخاري من كلام الزهري، وهي زيادة في سندها كلام. ثم روى الشيخان عن جابر رضي الله عنه أن النبي ﷺ قال وهو يحدّث عن فترة الوحي: «بينا أنا أمشي إذ سمعت صوتًا من السماء، فرفعت بصري فإذا الملك الذي جاءني بحراء جالس على كرسي بين السماء والأرض، فجُئثت منه رعبًا فرجعت فقلت: زمّلوني زمّلوني». فأنزل الله تعالى: ﴿يَا أَيُّهَا الْمُدَّثِّرُ * قُمْ فَأَنذِرْ * وَرَبَّكَ فَكَبِّرْ * وَثِيَابَكَ فَطَهِّرْ * وَالرُّجْزَ فَاهْجُرْ﴾. ثم حمي الوحي وتتابع. فصار هذا هو الأمر بالدعوة والتبليغ بعد أن كان النبي ﷺ قد نُبّئ بـ﴿اقْرَأْ﴾. وقد دلّت هذه القصة على أن الوحي كان يأتي متدرجًا، فبدأ بالقراءة والعلم ثم جاء الأمر بالإنذار والتبليغ، وكل ذلك بحكمة الله."], ["دلالات الحادثة", "في بدء الوحي دروس عظيمة، منها أن النبوة اصطفاء من الله لا يُكتسب بالتمنّي ولا بالرياضة، فقد جاء النبي ﷺ الوحي وهو لا يتوقعه ولا يطلبه. ومنها أن الرسالة بدأت بالعلم والقراءة، وهي بداية تؤكد مكانة العلم في الإسلام. ومنها أن النبي ﷺ بشر خاف وارتجف، فلم يدّعِ لنفسه شيئًا من الألوهية، وكان هذا من صدقه. ومنها فضل الزوجة العاقلة الناصحة في تثبيت زوجها عند الشدائد. ومنها أن أخلاق الإنسان وأعماله الصالحة سبب لثقة الله به وحفظه له. وبهذا الحدث بدأ تاريخ جديد للبشرية، ونزل القرآن الذي سيغيّر الأرض، وبدأ النبي ﷺ دعوته على بصيرة. وكان عمره ﷺ أربعين سنة على المشهور عند أهل العلم، وهو سنّ اكتمال العقل والنضج. ويؤخذ منها أيضًا أن من أراد حمل الرسالة فلا بد له من بناء نفسه بالصبر والأخلاق والتأمل قبل المواجهة. وقد كان في كل ما جرى لطف من الله ورعاية خاصة لنبيه ﷺ."]], "lesson": ["أول ما نزل من الوحي أمر بالقراءة والعلم باسم الله، فالإسلام دين علم وعبادة.", "الزوجة الصالحة تثبّت زوجها وتشدّ أزره، وقد كانت خديجة رضي الله عنها مثالًا في ذلك.", "حسن الخلق والإحسان للناس سبب لحفظ الله وإكرامه في الشدائد.", "النبوة اصطفاء من الله، والنبي ﷺ بشر يخاف ويطمئن، ولكن الله يثبّته."], "cat": "seerah"}, {"id": "s07", "title": "قصة أيوب عليه السلام", "type": "قصة قرآنية", "verse": "وَأَيُّوبَ إِذْ نَادَىٰ رَبَّهُ أَنِّي مَسَّنِيَ الضُّرُّ وَأَنتَ أَرْحَمُ الرَّاحِمِينَ", "source": "سورة الأنبياء 21:83", "parts": [["عبد صالح وبلاء عظيم", "أيوب عليه السلام نبي كريم ذكره الله في القرآن مع الأنبياء، في سورتي الأنبياء وص. وقد أثنى الله عليه ثناءً عظيمًا فقال: ﴿إِنَّا وَجَدْنَاهُ صَابِرًا نِّعْمَ الْعَبْدُ إِنَّهُ أَوَّابٌ﴾، أي كثير الرجوع إلى الله. ولم يذكر القرآن نسبه ولا موطنه ولا زمانه، وما قيل في ذلك فمن أخبار أهل الكتاب أو اجتهادات المفسرين، ولا يثبت منه شيء بنص صحيح. وأخبر القرآن أن الله ابتلاه ببلاء شديد في جسده، فنادى ربه: أني مسني الضر وأنت أرحم الراحمين. ولم يبيّن القرآن نوع المرض ولا مدته. وفي كتب القصص روايات كثيرة مفصّلة عن مرضه وعن ذهاب ماله وأولاده وهجران الناس له، لكنها ليست في القرآن، ولم يصح في ذلك نص عن النبي صلى الله عليه وسلم، فنتجنب الجزم بها. والذي نتيقنه أنه ابتُلي ابتلاءً شديدًا فصبر، وأن ذلك الصبر كان سبب ثناء الله عليه."], ["أدب الدعاء", "من أبلغ ما في قصة أيوب عليه السلام أدب دعائه. لم يقل: ارفع عني البلاء، ولم يطلب شفاءً صريحًا، بل عرض حاجته وقال: أني مسني الضر وأنت أرحم الراحمين. فكأنه يعرض حاله على الرحيم الذي لا يحتاج إلى تفصيل ولا إلحاح. وجاء في سورة ص قوله: ﴿وَاذْكُرْ عَبْدَنَا أَيُّوبَ إِذْ نَادَىٰ رَبَّهُ أَنِّي مَسَّنِيَ الشَّيْطَانُ بِنُصْبٍ وَعَذَابٍ﴾. وقد فسّر العلماء النصب والعذاب بما أصابه من مرض وألم. وأما نسبة المسّ إلى الشيطان فقد قال بعضهم إن الشيطان وسوس له في شدة مرضه، فتأدّب أيوب عليه السلام فنسب المسّ إلى الشيطان ولم ينسب المصيبة إلى الله، والله أعلم بالمراد. وهذا يعلّمنا أن الشكوى إلى الله ليست منافية للصبر، وأن الأنبياء أنفسهم يرفعون حاجاتهم إلى ربهم بتواضع وخضوع، فالدعاء عبادة، والتضرع إليه سبحانه سبب لرحمته."], ["الاستجابة والشفاء", "استجاب الله لأيوب عليه السلام، فقال: ﴿ارْكُضْ بِرِجْلِكَ هَٰذَا مُغْتَسَلٌ بَارِدٌ وَشَرَابٌ﴾. فضرب برجله الأرض فنبع الماء، فاغتسل منه وشرب، فبرئ من دائه بإذن الله. ولم يحدد القرآن موضع العين. وقال الله: فكشفنا ما به من ضر وآتيناه أهله ومثلهم معهم رحمة من عندنا وذكرى للعابدين. وقد اختلف المفسرون في معنى إيتاء الأهل ومثلهم، فقيل أنه رُدّ إليه أهله الذين فقدهم وزِيد عليهم مثلهم، وقيل بغير ذلك، ولا يثبت تعيين في السنة الصحيحة. وثبت في صحيح البخاري عن أبي هريرة رضي الله عنه عن النبي صلى الله عليه وسلم أن أيوب عليه السلام بينما هو يغتسل عريانًا خرّ عليه رِجل جراد من ذهب، فجعل يحثي في ثوبه، فناداه ربه: يا أيوب ألم أكن أغنيتك عما ترى؟ قال: بلى يا رب ولكن لا غنى لي عن بركتك. فكان شكره وحرصه على بركة الله."], ["الضغث والقسم", "ذكر الله في سورة ص أن أيوب عليه السلام حلف على أمر، فلما شفاه الله أراد الله أن يبرّ بيمينه من غير أن يُلحق الأذى الشديد بمن حلف عليه. فقال: ﴿وَخُذْ بِيَدِكَ ضِغْثًا فَاضْرِب بِّهِ وَلَا تَحْنَثْ﴾. والضغث هو حزمة من الأعواد الرقيقة، فضرب بها دفعة واحدة، فبرّ بقسمه ولم يؤذِ. وقد ذكر المفسرون أن الحلف كان على زوجته، وأنه حلف أن يضربها عددًا من الضربات، وقيل في سبب القسم أقوال متعددة، ولكن لا يثبت في سبب القسم ولا في عدد الضربات دليل صحيح، فنقول: ولم يحدد القرآن ذلك. وفي هذا تعليم أن الشريعة تأتي بالمخارج واليسر، وأن من حلف ثم رأى الخير في غيره جاز له التحلل، وأن الله إذا أراد الخير لعبده فتح له بابًا من الرحمة، وأنه سبحانه لا يضيع من صبر وأناب."], ["ثناء الله على أيوب", "بعد أن شفاه الله أثنى عليه بقوله: ﴿إِنَّا وَجَدْنَاهُ صَابِرًا نِّعْمَ الْعَبْدُ إِنَّهُ أَوَّابٌ﴾. وكل ثناء من الله فيه منزلة عظيمة، فقد جمع أيوب عليه السلام بين الصبر والعبودية والإنابة. وقد جعل الله قصته ذكرى للعابدين، أي عبرة ودرسًا لكل من يُبتلى في دنياه ويطلب الفرج من ربه. والمؤمن في حال البلاء يُجرى عليه أجره إن صبر ورضي، كما قال النبي صلى الله عليه وسلم: «عجبًا لأمر المؤمن إن أمره كله له خير، وليس ذلك لأحد إلا للمؤمن؛ إن أصابته سرّاء شكر فكان خيرًا له، وإن أصابته ضرّاء صبر فكان خيرًا له». وهذا الحديث رواه مسلم في صحيحه، وهو يبيّن أن حال المؤمن كله خير إذا صبر وشكر. فمن تأمل قصة أيوب عليه السلام علم أن الابتلاء ليس عقوبة في كل حال، بل قد يكون رفعة للدرجات وتكفيرًا للسيئات واختبارًا للصبر."], ["خلاصة القصة وما يُستفاد منها", "هذه هي القصة كما وردت في القرآن والسنة الصحيحة، وهي قصة قصيرة في حروفها عظيمة في معانيها. ابتُلي نبي كريم فصبر، ودعا ربه بأدب، فاستجاب الله له وشفاه، وأكرمه وأعاد إليه أهله، وجعله مثالًا يُحتذى به. وقد أنكر العلماء ما نُسب إلى أيوب عليه السلام من أمور لا تليق بمقام النبوة، كأن يقال إنه كان مرضه منفّرًا حتى تركه الناس، أو أنه تضجّر أو اعترض، فالقرآن يصفه بأنه صابر، وأنه نعم العبد. ولم يرد في القرآن تحديد لسنوات مرضه، وما رُوي عن ثمانية عشر عامًا أو غيرها لا يصحّ نسبته إلى النبي صلى الله عليه وسلم، وقد استغربه أهل العلم. ويكفينا أنها كانت مدة طالت على صاحبها، فلم ينقطع أمله بالله، ولم يمنعه ضعف جسده عن ذكر ربه. وفي هذا طمأنينة لكل مبتلى أن بعد العسر يسرًا."]], "lesson": ["الصبر على البلاء من أعظم مقامات العبودية وسبب لثناء الله على عبده.", "اعرض حاجتك على الله بأدب وتذلل، فهو أرحم الراحمين.", "لا تيأس من رحمة الله مهما طال البلاء، فالفرج قريب.", "الشكر على النعمة والتعلق ببركة الله لا بالمال وحده."], "cat": "story"}, {"id": "sr07", "title": "الدعوة السرية وأوائل المسلمين", "type": "من السيرة النبوية", "verse": "يَا أَيُّهَا الْمُدَّثِّرُ قُمْ فَأَنذِرْ", "source": "سورة المدثر 74:1-2", "parts": [["بدء الدعوة في الخفاء", "بعد أن نزل الأمر بالإنذار في سورة المدثر، بدأ النبي ﷺ دعوته، لكنه لم يجهر بها في أول الأمر، بل بدأ بمن يثق بهم من أهله وأصدقائه، فكانت دعوة خفية في البيوت وفي الأماكن البعيدة عن أعين قريش. وقد استمرت هذه المرحلة نحو ثلاث سنين على ما ذكر ابن إسحاق وجمع من أهل السير، وهي مدة لم تثبت في حديث صحيح بتحديد دقيق. وكان في ذلك حكمة بالغة، فإن قريشًا كانت قوية متعصبة لدين آبائها، والمسلمون قلة، فاقتضى الأمر أن يبني النبي ﷺ جماعة مؤمنة صلبة قبل أن يواجه قومه. وتكوّن في هذه المرحلة النواة الأولى التي ستتحمل الأذى وتحمل الدعوة لاحقًا. وقد كان من حكمة الله أن تُبنى هذه الجماعة على العقيدة الراسخة والأخلاق العالية قبل أن تُبتلى. فكانت مكة بعد ذلك ومحيطها ميدانًا لهذه الدعوة، وما كانت لتبدأ إلا في وقتها الذي قدّره الله."], ["أول من آمن", "كانت خديجة بنت خويلد رضي الله عنها أول من آمن به وصدّقه من الناس، وقد اتفق أهل العلم على أنها أول المسلمين. ثم آمن علي بن أبي طالب رضي الله عنه، وكان صبيًّا صغيرًا في بيت النبي ﷺ، وآمن زيد بن حارثة رضي الله عنه مولى النبي ﷺ، وأبو بكر الصديق رضي الله عنه. وقد اختلف أهل العلم في أيهم أول من أسلم من الرجال والصبيان والموالي، وجمع بعضهم بأن أول من أسلم من النساء خديجة، ومن الصبيان علي، ومن الموالي زيد، ومن الرجال الأحرار أبو بكر رضي الله عنهم أجمعين. وكان أبو بكر رضي الله عنه تاجرًا محبوبًا في قومه، معروفًا بحسن الخلق، فصار يدعو من يثق به إلى الإسلام. وتذكر كتب السير أنه أسلم على يديه عدد من كبار الصحابة، منهم عثمان بن عفان والزبير بن العوام وعبد الرحمن بن عوف وسعد بن أبي وقاص وطلحة بن عبيد الله رضي الله عنهم."], ["من المستضعفين والموالي", "وآمن مع هؤلاء كثير من الضعفاء والموالي، منهم بلال بن رباح وعمار بن ياسر وأبوه ياسر وأمه سمية، وصهيب بن سنان وخباب بن الأرت والمقداد بن عمرو رضي الله عنهم. وفي صحيح البخاري عن عمار رضي الله عنه قال: رأيت رسول الله ﷺ وما معه إلا خمسة أعبد وامرأتان وأبو بكر. وكان إيمان هؤلاء دليلًا على أن الإسلام يخاطب الإنسان بلا نظر إلى جاهه أو ماله، وأن العقيدة الصحيحة تجمع الحر والعبد على أخوة واحدة. وكانت هذه الفئة هي التي ستتحمل أشد الأذى، فقد كانت بلا حماية قبلية. ومن الحديث الذي يدل على قلة العدد وثبات الإيمان ما رواه البخاري عن سعد بن أبي وقاص رضي الله عنه أنه قال: «لقد رأيتني وأنا ثلث الإسلام»، فهكذا كان الأمر في بدايته. فكان هؤلاء الأوائل بذور الأمة التي ستحمل الرسالة إلى العالم."], ["العبادة والتعلّم", "كان المسلمون يتعلمون القرآن وأحكام الدين من النبي ﷺ في السر، وكان بعضهم يصلّي في الشعاب بعيدًا عن أعين قريش. وتذكر كتب السير أن النبي ﷺ كان يصلي هو وأصحابه ركعتين بالغداة وركعتين بالعشي قبل فرض الصلوات الخمس ليلة الإسراء، وهذا ما ذكره ابن إسحاق وغيره. وتذكر كتب السير كذلك أن النبي ﷺ اتخذ دار الأرقم بن أبي الأرقم المخزومي رضي الله عنه عند الصفا مكانًا يجتمع فيه بأصحابه ويعلمهم، لأنها كانت بعيدة عن أنظار قريش نسبيًّا. وكانت هذه الدار مدرسة أولى للمسلمين، يتلقون فيها القرآن ويتزكون به، ويتعلمون الصبر والثبات. وقد قال الله تعالى في أمر هذه الأمة: ﴿وَاصْبِرْ نَفْسَكَ مَعَ الَّذِينَ يَدْعُونَ رَبَّهُمْ بِالْغَدَاةِ وَالْعَشِيِّ﴾، وهي آية مكية تناسب هذا الحال. وكانت هذه الجلسات قصيرة لكنها عميقة الأثر، فقد صنعت أخلاقهم وثبتت عقيدتهم قبل المحن. ولم تكن الحاجة إلى المكان وحده، بل إلى القلوب المؤمنة التي تتلقى وتعمل."], ["أمثلة من إسلامهم", "وفي صحيح مسلم قصة عمرو بن عبسة السلمي رضي الله عنه، وقد كان في الجاهلية يرى أن الناس على ضلالة وأنهم ليسوا على شيء، فسمع برجل بمكة يخبر أخبارًا، فقدم عليه فوجده مستخفيًا جرآء عليه قومه، فسأله: ما أنت؟ قال: «نبي»، قال: وما نبي؟ قال: «أرسلني الله»، قال: وبأي شيء أرسلك؟ قال: «أرسلني بصلة الأرحام وكسر الأوثان وأن يوحَّد الله لا يشرك به شيء». قال: فمن معك على هذا؟ قال: «حرّ وعبد»، يعني أبا بكر وبلالًا. وهذا يبين أن الإسلام وصل في السرّ إلى من كان يبحث عن الحق من خارج مكة، وأن النبي ﷺ كان يعلنه لمن يسأله. فكانت الدعوة السرية لا تعني الانقطاع عن الناس، بل اختيار من يأتي منهم عن رغبة ومعرفة. وفي ذلك دليل على أن الحق يجد أهله وإن كان خفيًّا، وأن الله يسوق إليه من يريد هدايته من أطراف الأرض."], ["حكمة المرحلة السرية", "في هذه المرحلة تظهر حكمة الدعوة، فلم يعجل النبي ﷺ بالمواجهة وهو يعلم أن القوة المادية غير متكافئة، وإنما اختار بناء الأفراد على الإيمان قبل المواجهة. فكان كل مسلم يتربى على القرآن، ويتعلم الصبر والإخلاص، ويؤمن أن الله ناصر دينه. ومع الوقت صار لهذا الجمع القليل أثر كبير، فصار كل منهم داعيةً في محيطه. وقد ثبت أن النبي ﷺ لم يكتم الدعوة خوفًا، بل مراعاةً للمصلحة، فلما أمره الله بالجهر جهر بلا تردد. وقد ظهرت ثمرة هذه المرحلة في الثبات العجيب الذي أظهره المسلمون بعد ذلك تحت التعذيب والحصار. وفي الإسلام أن الدعوة تتنوع أساليبها بحسب الأحوال، فيبدأ الداعية بالأقرب فالأقرب، ويبني الأساس قبل البناء. وبهذا نفهم أن السرية كانت وسيلة لا غاية، وأنها لا تتعارض مع الإخلاص والجرأة في الحق عند اللزوم. وكما بنى النبي ﷺ جماعته على الصبر، علّمنا أن نقدّر الظرف قبل الإقدام. فمن عرف مصلحة دعوته عرف متى يسكت ومتى يتكلم، فلا إفراط ولا تفريط."]], "lesson": ["البناء الهادئ للأفراد على الإيمان قبل المواجهة من حكمة الدعوة.", "الإسلام لا يفرّق بين حرّ وعبد وغني وفقير، فالتقوى هي الميزان.", "السبق إلى الإيمان فضل عظيم، وقد كان أبو بكر وخديجة وعلي وزيد رضي الله عنهم من الأوائل.", "القرآن هو المدرسة الأولى التي تخرّج الرجال، وبه ثبّت الله المؤمنين في أشد أيامهم."], "cat": "seerah"}, {"id": "s08", "title": "قصة يونس عليه السلام", "type": "قصة قرآنية", "verse": "فَنَادَىٰ فِي الظُّلُمَاتِ أَن لَّا إِلَٰهَ إِلَّا أَنتَ سُبْحَانَكَ إِنِّي كُنتُ مِنَ الظَّالِمِينَ", "source": "سورة الأنبياء 21:87", "parts": [["رسالة إلى مئة ألف أو يزيدون", "يونس عليه السلام نبي كريم، وهو يونس بن متّى كما جاء في الحديث الصحيح. أرسله الله إلى قوم كثيرين، قال الله تعالى: ﴿وَأَرْسَلْنَاهُ إِلَىٰ مِائَةِ أَلْفٍ أَوْ يَزِيدُونَ﴾. ولم يسمِّ القرآن قومه ولا مدينتهم، وقيل إنهم أهل نينوى في العراق، والله أعلم. دعاهم إلى عبادة الله وحده وترك ما هم عليه من الشرك، فاستمر في دعوتهم مدةً، ولم يحدد القرآن مدتها، لكنهم لم يستجيبوا وأعرضوا. فضاق صدره بهم وبإصرارهم، وظن أن الأمر لا فائدة منه. وقد أخبر النبي صلى الله عليه وسلم في البخاري أنه قال: «لا ينبغي لعبد أن يقول أنا خير من يونس بن متّى». وهذا تنبيه إلى منزلة يونس عليه السلام وأنه من الأنبياء الكرام الذين لا يُنقص من شأنهم ما ورد في قصتهم من عتاب. وفي هذه البداية عبرة أن الدعوة قد تُقابَل بالإعراض زمنًا طويلًا، وأن على الداعي أن يصبر ولا يتعجل ثمرة عمله."], ["الخروج مغاضبًا", "ذكر القرآن أن يونس عليه السلام ذهب مغاضبًا: ﴿وَذَا النُّونِ إِذ ذَّهَبَ مُغَاضِبًا فَظَنَّ أَن لَّن نَّقْدِرَ عَلَيْهِ﴾. والنون هو الحوت. وقد فسّر العلماء الغضب بأنه غضب على قومه لإصرارهم على الكفر، لا غضب على ربه، وفسّروا قوله: فظن أن لن نقدر عليه، أي ظن أن لن نضيّق عليه، فالقدر هنا بمعنى التضييق، لا نفي قدرة الله، فحاشاه عليه السلام. وكان خروجه قبل أن يأذن الله له بالخروج من بين قومه، فاستحقّ العتاب. وقيل إنه وعدهم بالعذاب ثم خرج قبل أن يأتيهم، وهذا من أقوال المفسرين ولا يثبت فيه نص صحيح. فخرج يونس عليه السلام إلى البحر، وركب سفينةً مملوءة. وكان الأنبياء رغم عصمتهم في التبليغ بشرًا يتألمون ويغضبون، ويؤدّبهم الله بما يرفع درجاتهم. وفي ذلك تعليم لأهل الدعوة أن الصبر على الناس عبادة، وأن اليأس منهم قبل إذن الله لا يليق."], ["القرعة والحوت", "ركب يونس عليه السلام السفينة المشحونة، وهي المملوءة بالركاب والأمتعة. وجاء في القرآن: ﴿فَسَاهَمَ فَكَانَ مِنَ الْمُدْحَضِينَ﴾، أي أُجريت قرعة فكان من المغلوبين. ولم يفصّل القرآن لماذا كانت القرعة، وما يُروى في ذلك من تفاصيل عن هياج البحر وثقل السفينة فمن أخبار المفسرين، ولا يثبت بنص صحيح. فالتقمه الحوت، قال الله: ﴿فَالْتَقَمَهُ الْحُوتُ وَهُوَ مُلِيمٌ﴾، أي والحال أنه مستحق للّوم. ولم يحدد القرآن نوع الحوت، ولا المدة التي بقيها في بطنه. وما قيل من ثلاثة أيام أو أربعين أو غيرها فلا يصح فيه دليل. ولم يمت يونس عليه السلام، بل حفظه الله في بطن الحوت، وكان في ظلمات ثلاث، هي ظلمة الليل وظلمة البحر وظلمة بطن الحوت، وهذا قول كثير من المفسرين. وكانت تلك الظلمات سبب إنابته، وهي لحظة عظيمة يتعلم منها كل عبد أنه لا ملجأ من الله إلا إليه."], ["دعوة ذي النون", "في هذه الظلمات الثلاث رفع يونس عليه السلام صوته بالدعاء: ﴿لَّا إِلَٰهَ إِلَّا أَنتَ سُبْحَانَكَ إِنِّي كُنتُ مِنَ الظَّالِمِينَ﴾. وفي هذا الدعاء ثلاثة أركان عظيمة: التوحيد في قوله: لا إله إلا أنت، والتنزيه في قوله: سبحانك، والاعتراف بالذنب في قوله: إني كنت من الظالمين. وهكذا يكون دعاء المضطر، يبدأ بتعظيم الله، ثم يعترف بالتقصير. وقد جاء في الحديث الصحيح الذي رواه الترمذي عن سعد بن أبي وقاص رضي الله عنه أن النبي صلى الله عليه وسلم قال: «دعوة ذي النون إذ دعا وهو في بطن الحوت: لا إله إلا أنت سبحانك إني كنت من الظالمين، فإنه لم يدعُ بها رجل مسلم في شيء قط إلا استجاب الله له». ثم قال الله: فاستجبنا له ونجيناه من الغم وكذلك ننجي المؤمنين. وقال تعالى أيضًا: فلولا أنه كان من المسبحين للبث في بطنه إلى يوم يبعثون، فكان تسبيحه سبب نجاته."], ["النجاة والشجرة", "استجاب الله لدعاء يونس عليه السلام، فنبذه الحوت بالعراء وهو سقيم. والعراء هو الأرض الخالية من الشجر والبناء، وكان يونس عليه السلام ضعيفًا هزيلًا من أثر ما أصابه. ثم قال الله: ﴿وَأَنبَتْنَا عَلَيْهِ شَجَرَةً مِّن يَقْطِينٍ﴾. واليقطين كل شجر لا يقوم على ساق، كالقرع، فتظلّل بأوراقها وأكل من ثمرها وتهيّأ جسده. ولم يحدد القرآن موضع العراء، ولا ما أكل من اليقطين على وجه التحديد. وهذا من لطف الله ورحمته بعبده الذي أنابه إليه. وقد قال الله فيه: ﴿فَاجْتَبَاهُ رَبُّهُ فَجَعَلَهُ مِنَ الصَّالِحِينَ﴾، فرجعت له المنزلة والرفعة بعد العتاب. ثم أمر الله نبيه محمدًا صلى الله عليه وسلم ألا يكون مثل صاحب الحوت: ﴿وَلَا تَكُن كَصَاحِبِ الْحُوتِ إِذْ نَادَىٰ وَهُوَ مَكْظُومٌ﴾، أي مملوء غمًّا. والمعنى أن يصبر ولا يستعجل ولا يضيق صدره بقومه."], ["قومه والعودة", "وأخبر القرآن عن قوم يونس عليه السلام: ﴿فَآمَنُوا فَمَتَّعْنَاهُمْ إِلَىٰ حِينٍ﴾، فتبيّن أنهم آمنوا جميعًا. وأخبر الله في سورة يونس أنه لم تكن قرية آمنت فنفعها إيمانها إلا قوم يونس، لما آمنوا كشفنا عنهم عذاب الخزي في الحياة الدنيا ومتعناهم إلى حين. وهذه خصوصية لقوم يونس، إذ نفعهم إيمانهم عند معاينة العذاب، بينما لا ينفع الإيمان عند حضور الموت أو رؤية العذاب لغيرهم، كما حدث لفرعون. ولم يفصّل القرآن كيفية إيمانهم، وما يُروى من أنهم خرجوا إلى فلاة وفرّقوا بين الأمهات والأولاد ودعوا الله فهو من أخبار المفسرين التي لا تثبت. ولم يحدد القرآن متى رجع إليهم يونس عليه السلام، ولكن إيمانهم كان ثمرة دعوته الطويلة. وفي هذا أن رحمة الله تسبق غضبه، وأن باب التوبة مفتوح ما لم يغرغر العبد، وأن الدعوة تثمر ولو بعد حين."]], "lesson": ["الصبر على الناس وعدم اليأس من هدايتهم ولو طال إعراضهم.", "اعترف بتقصيرك لله وتب إليه، فدعوة يونس مفتاح لكل كرب.", "التسبيح والذكر في الرخاء يكونان سببًا للنجاة في الشدة.", "باب التوبة مفتوح، ورحمة الله وسعت كل شيء."], "cat": "story"}, {"id": "sr08", "title": "الجهر بالدعوة وأذى قريش", "type": "من السيرة النبوية", "verse": "وَأَنذِرْ عَشِيرَتَكَ الْأَقْرَبِينَ", "source": "سورة الشعراء 26:214", "parts": [["الأمر بالجهر", "بعد نحو ثلاث سنين من الدعوة الخفية نزل الأمر بإعلان الدعوة وإنذار القوم جهرة، فقال الله تعالى: ﴿وَأَنذِرْ عَشِيرَتَكَ الْأَقْرَبِينَ﴾، وقال سبحانه: ﴿فَاصْدَعْ بِمَا تُؤْمَرُ وَأَعْرِضْ عَنِ الْمُشْرِكِينَ﴾. وهذا أمر صريح من الله بأن يرفع النبي ﷺ صوته بالحق ولا يخشى أحدًا. وكان في هذا الأمر تحول كبير في مسيرة الدعوة، فقد انتقلت من الأسرار إلى المواجهة العلنية، ومن العناية بالأفراد إلى مخاطبة المجتمع كله. وكان النبي ﷺ يعلم أن قريشًا ستغضب وتؤذي، لكنه امتثل لأمر ربه بلا تردد. وبدأ بعشيرته الأقربين من بني هاشم وبني المطلب ثم قريش كلها، ثم الناس أجمعين، كما قال تعالى في سورة سبأ: ﴿وَمَا أَرْسَلْنَاكَ إِلَّا كَافَّةً لِّلنَّاسِ بَشِيرًا وَنَذِيرًا﴾. وقد بدأت قريش حينئذ تدرك خطر هذه الدعوة، فبدأ ما كان خافتًا يتحول إلى حديث المجالس والأسواق والبيوت كلها."], ["على جبل الصفا", "روى البخاري ومسلم عن ابن عباس رضي الله عنهما قال: لما نزلت ﴿وَأَنذِرْ عَشِيرَتَكَ الْأَقْرَبِينَ﴾ صعد النبي ﷺ الصفا فجعل ينادي: «يا بني فهر، يا بني عدي»، لبطون قريش، حتى اجتمعوا، فجعل الرجل إذا لم يستطع أن يخرج أرسل رسولًا لينظر ما هو. فجاء أبو لهب وقريش. فقال: «أرأيتكم لو أخبرتكم أن خيلًا بالوادي تريد أن تغير عليكم أكنتم مصدّقيّ؟» قالوا: نعم، ما جرّبنا عليك إلا صدقًا. قال: «فإني نذير لكم بين يدي عذاب شديد». فقال أبو لهب: تبًّا لك سائر اليوم، ألهذا جمعتنا؟ فنزلت: ﴿تَبَّتْ يَدَا أَبِي لَهَبٍ وَتَبَّ﴾. وهكذا كان أول موقف علني من قريش هو التكذيب والسخرية، وكان أبو لهب عمّ النبي ﷺ أول من جاهره بالعداوة. وكان في وقوع هذا الحدث في صميم مكة تحدٍّ علني لما اعتاد عليه القوم، فاشتد عليهم."], ["اتهامات قريش", "لم يجد المشركون ما يطعنون به في النبي ﷺ من جهة أخلاقه، فلجؤوا إلى الاتهامات المتناقضة، فقالوا ساحر وشاعر وكاهن ومجنون، وقد حكى القرآن ذلك فقال تعالى: ﴿وَقَالَ الْكَافِرُونَ هَٰذَا سَاحِرٌ كَذَّابٌ﴾. وتناقض هذه الأوصاف يدل على أنهم لم يجدوا حجة. وجاؤوا إلى أبي طالب مرارًا يطلبون منه أن يكفّ ابن أخيه أو يسلّمه، فرفض أن يخذله. وتذكر كتب السير أنهم عرضوا عليه مالًا وملكًا ونساءً على أن يترك دعوته، فرفض ﷺ، وفي أسانيد هذه الروايات مقال، لكن موقفه الثابت من الدعوة لا يُشك فيه. ولما عجزوا عن الحجة لجؤوا إلى السخرية والاستهزاء، ثم إلى الإيذاء الجسدي، وهي سنّة المبطلين في كل زمان، يضيقون على أهل الحق إذا لم تنفعهم الحجة. وقد سلّى الله نبيه بقوله: ﴿وَلَقَدِ اسْتُهْزِئَ بِرُسُلٍ مِّن قَبْلِكَ﴾. فكان ردّهم على الحجة بالتهديد والأذى، وهذا شأن من لا يجد برهانًا. ولم يكن النبي ﷺ يرد إلا بالحجة والصبر، يتلو عليهم القرآن في مجالسهم وأسواقهم وفي مواسم الحج، ويدعوهم بالحسنى."], ["الأذى الذي لحق النبي ﷺ", "وقد تعرض النبي ﷺ لأنواع من الأذى، ومن ذلك ما رواه البخاري ومسلم عن عبد الله بن مسعود رضي الله عنه أن النبي ﷺ كان يصلي عند الكعبة وجمع من قريش جلوس، فقال بعضهم: أيكم يجيء بسلا جزور بني فلان فيضعه على ظهر محمد إذا سجد؟ فانبعث أشقاهم فجاء به، فلما سجد النبي ﷺ وضعه بين كتفيه، وثبت النبي ﷺ ساجدًا، وضحكوا حتى مال بعضهم على بعض. فجاءت فاطمة رضي الله عنها وهي جويرية فطرحته عنه، وأقبلت عليهم تسبّهم، فلما قضى صلاته دعا عليهم، وذكر أبا جهل وعتبة وشيبة والوليد بن عتبة وأمية بن خلف وعقبة بن أبي معيط. قال ابن مسعود: فوالله لقد رأيتهم صرعى يوم بدر. وبهذا أثبت الله صدق دعوته، وأن ما أخبر به وقع كما أخبر. فهذه كلها مواقف أظهرت فيها قريش حقدها، وثبت فيها النبي ﷺ ثبات الأنبياء من قبله، حتى قال له ربه: ﴿فَاصْبِرْ كَمَا صَبَرَ أُولُو الْعَزْمِ مِنَ الرُّسُلِ﴾."], ["أبو بكر يدافع", "وفي صحيح البخاري عن عروة بن الزبير قال: سألت ابن عمرو بن العاص عن أشد ما صنع المشركون برسول الله ﷺ، قال: بينا رسول الله ﷺ يصلي بفناء الكعبة إذ أقبل عقبة بن أبي معيط فوضع ثوبه في عنقه فخنقه خنقًا شديدًا، فأقبل أبو بكر حتى أخذ بمنكبه ودفعه عن النبي ﷺ وقال: ﴿أَتَقْتُلُونَ رَجُلًا أَن يَقُولَ رَبِّيَ اللَّهُ وَقَدْ جَاءَكُمْ بِالْبَيِّنَاتِ مِن رَّبِّكُمْ﴾. وهذا الموقف يظهر صدق أبي بكر رضي الله عنه وشجاعته ودفاعه عن النبي ﷺ حين كان الأمر خطرًا. ويدل كذلك على أن الله يقيّض لدينه من ينصره في أصعب المواقف، وأن المؤمنين كانوا يدافعون عن رسولهم بأرواحهم قبل أن تكون للمسلمين دولة أو قوة. وكان هذا من دلائل صدق أبي بكر رضي الله عنه وشدة محبته لنبيه ﷺ، وسيبقى ذكره في الصحيح ما بقيت الدنيا. وهو دليل على أن الرجال تُعرف عند الشدائد."], ["تعذيب المستضعفين", "وأما المستضعفون ممن آمن ولا حماية لهم، فقد نالهم من الأذى أشد مما نال غيرهم، فعُذّب بلال بن رباح رضي الله عنه تحت الرمضاء، وتذكر كتب السير أن سيده أمية بن خلف كان يضع على صدره الحجر العظيم ليتركه الإسلام فكان يقول: أحدٌ أحد. وقد اشتراه أبو بكر رضي الله عنه وأعتقه، وفي صحيح البخاري قول عمر رضي الله عنه: أبو بكر سيّدنا وأعتق سيّدنا، يعني بلالًا. وعُذّب عمار وأبوه ياسر وأمه سمية رضي الله عنهم، وتذكر كتب السير أن سمية رضي الله عنها كانت أول شهيدة في الإسلام، قتلها أبو جهل، وقد روى أحمد وابن ماجه عن ابن مسعود أن أول من أظهر إسلامه سبعة: رسول الله ﷺ وأبو بكر وعمار وأمه سمية وصهيب وبلال والمقداد. وكان النبي ﷺ يمرّ بهم ويقول لهم ما معناه: صبرًا آل ياسر، فإن موعدكم الجنة، وهو مشهور في السير."], ["الثبات والبشارة", "وقد شكا الصحابة ما يلقونه، فروى البخاري عن خباب بن الأرت رضي الله عنه قال: شكونا إلى رسول الله ﷺ وهو متوسد بردة له في ظل الكعبة، قلنا: ألا تستنصر لنا؟ ألا تدعو الله لنا؟ فقال: «كان الرجل فيمن قبلكم يُحفر له في الأرض فيُجعل فيه، فيُجاء بالمنشار فيوضع على رأسه فيُشقّ باثنتين، وما يصدّه ذلك عن دينه، ويمشَّط بأمشاط الحديد ما دون لحمه من عظم أو عصب، وما يصدّه ذلك عن دينه، والله ليتمّنّ هذا الأمر حتى يسير الراكب من صنعاء إلى حضرموت لا يخاف إلا الله أو الذئب على غنمه، ولكنكم تستعجلون». فهكذا ثبّت النبي ﷺ أصحابه بالبشارة بالنصر، وبيّن أن الابتلاء سنة الله في أهل الإيمان. وبقي أبو طالب يحمي النبي ﷺ، فلم تقدر قريش أن تصل إليه بما تريد. وكان هذا الوعد من النبي ﷺ يتحقق بعد ذلك على مرّ السنين، فاتسع الإسلام حتى بلغ الشرق والغرب."]], "lesson": ["الدعوة تبدأ بالإنذار والصدق ولو قوبلت بالسخرية والعداء.", "الأذى في سبيل الحق سنة الأنبياء، والعاقبة للمتقين.", "الإيمان لا يعرف الفوارق الاجتماعية، وقد صبر الضعفاء مثل بلال وآل ياسر وثبتوا.", "البشارة بالنصر تقوّي الصابرين، فالله متم أمره مهما استعجل الناس."], "cat": "seerah"}, {"id": "s09", "title": "قصة أصحاب الكهف", "type": "قصة قرآنية", "verse": "إِذْ أَوَى الْفِتْيَةُ إِلَى الْكَهْفِ فَقَالُوا رَبَّنَا آتِنَا مِن لَّدُنكَ رَحْمَةً وَهَيِّئْ لَنَا مِنْ أَمْرِنَا رَشَدًا", "source": "سورة الكهف 18:10", "parts": [["فتية آمنوا بربهم", "ذكر الله في سورة الكهف قصة فتية آمنوا بربهم في زمنٍ شاع فيه الشرك وعبادة غير الله، وقال سبحانه: ﴿إِنَّهُمْ فِتْيَةٌ آمَنُوا بِرَبِّهِمْ وَزِدْنَاهُمْ هُدًى﴾. ولم يحدد القرآن أسماءهم ولا مدينتهم ولا اسم الملك الذي كان في زمنهم، وكل ما يُروى من تسمية البلد أو أسماء الفتية أو اسم الكلب فهو من أخبار المفسرين ولا يثبت بدليل صحيح. والذي أخبرنا به القرآن أنهم كانوا شبابًا، وأن الله ربط على قلوبهم حين قاموا فقالوا: ربنا رب السماوات والأرض لن ندعو من دونه إلهًا لقد قلنا إذًا شططًا. أي لو دعونا غير الله لكان قولنا بعيدًا عن الحق. ثم قالوا: هؤلاء قومنا اتخذوا من دونه آلهة لولا يأتون عليهم بسلطان بيّن، فمن أظلم ممن افترى على الله كذبًا؟ فالقصة تبدأ بإيمان قلبٍ شابٍّ صادق، وصدعٍ بالحق أمام قومٍ مشركين، وتُبيّن أن الشباب إذا صدقوا مع الله زادهم الله هدى."], ["اللجوء إلى الكهف", "لما رأى الفتية أنهم لا يستطيعون إعلان إيمانهم بين قومهم، ويخشون الفتنة في دينهم، قال بعضهم لبعض: ﴿وَإِذِ اعْتَزَلْتُمُوهُمْ وَمَا يَعْبُدُونَ إِلَّا اللَّهَ فَأْوُوا إِلَى الْكَهْفِ يَنشُرْ لَكُمْ رَبُّكُم مِّن رَّحْمَتِهِ وَيُهَيِّئْ لَكُم مِّنْ أَمْرِكُم مِّرْفَقًا﴾. فتركوا بلدهم وما فيه من أهل ومال وراحة، وفرّوا بدينهم إلى كهف في جبل. ولم يحدد القرآن موضع الكهف. وحين دخلوا الكهف رفعوا أيديهم بالدعاء الذي ورد في الآية: ربنا آتنا من لدنك رحمة وهيئ لنا من أمرنا رشدًا. فاستجاب الله دعاءهم أحسن استجابة، وفتح لهم بابًا للرحمة لم يخطر لهم على بال. وهنا درس أن المؤمن إذا ضاقت به الأرض في دينه، فعليه أن يأخذ بالأسباب كالهجرة والاعتزال إذا خشي الفتنة، ثم يتوكل على الله ويدعوه أن يهيئ له من أمره رشدًا، فالله لا يخذل من فرّ إليه بدينه."], ["نوم ثلاثمئة سنة", "ثم أخبر الله أنه ضرب على آذانهم في الكهف سنين عددًا، أي أنامهم نومًا عميقًا لا تُوقظهم فيه الأصوات. ووصف القرآن حال الكهف ووضعهم فيه وصفًا بديعًا: ﴿وَتَرَى الشَّمْسَ إِذَا طَلَعَت تَّزَاوَرُ عَن كَهْفِهِمْ ذَاتَ الْيَمِينِ وَإِذَا غَرَبَت تَّقْرِضُهُمْ ذَاتَ الشِّمَالِ وَهُمْ فِي فَجْوَةٍ مِّنْهُ﴾. فكانت الشمس تميل عنهم عند الطلوع والغروب فلا تؤذيهم، وهم في متسع من الكهف. وقال أيضًا: ونقلّبهم ذات اليمين وذات الشمال وكلبهم باسط ذراعيه بالوصيد، أي أن الله كان يقلّبهم في نومهم فلا تأكل الأرض أجسادهم، وكلبهم عند باب الكهف. وأخبر أن من رآهم لوليّت منهم فرارًا ولملئ منهم رعبًا. وبيّن أنهم لبثوا في كهفهم ثلاثمئة سنين وازدادوا تسعًا، لكنه أمر بتفويض العلم له فقال: ﴿قُلِ اللَّهُ أَعْلَمُ بِمَا لَبِثُوا﴾، والمراد أن الله أعلم بالمدة على الحقيقة."], ["الاستيقاظ والبعث", "ثم بعثهم الله من نومهم ليتساءلوا بينهم. قال قائل منهم: كم لبثتم؟ قالوا: لبثنا يومًا أو بعض يوم. قالوا: ربكم أعلم بما لبثتم. فقرروا أن يرسلوا أحدهم بنقودهم إلى المدينة ليشتري طعامًا، وأوصوه: فلينظر أيها أزكى طعامًا فليأتكم برزق منه وليتلطف ولا يشعرن بكم أحدًا، إنهم إن يظهروا عليكم يرجموكم أو يعيدوكم في ملتهم ولن تفلحوا إذًا أبدًا. وهذه الوصية تدل على أنهم ظنوا أن الخطر ما زال قائمًا. فخرج أحدهم إلى المدينة، فلما رأى أهلها عملته القديمة وهيئته ثارت لديهم الشبهات، وانكشف أمرهم. وأخبر الله أنه أعثر عليهم الناس ليعلموا أن وعد الله حق وأن الساعة لا ريب فيها. ولم يذكر القرآن تفاصيل ما دار مع أهل المدينة، وما ورد في ذلك من روايات فمن أخبار المفسرين وأهل الكتاب، فلا نثبته."], ["الخلاف في عددهم وما بُني عليهم", "بعد أن توفّى الله الفتية أو عاد بهم إلى نومهم، اختلف الناس فيهم: فقال بعضهم: ابنوا عليهم بنيانًا ربهم أعلم بهم. وقال الذين غلبوا على أمرهم: لنتخذن عليهم مسجدًا. وقد استدل بعض العلماء بهذه الآية على جواز بناء المساجد على القبور، لكن السنة الصحيحة جاءت بالنهي عن ذلك، فقد قال النبي صلى الله عليه وسلم: «لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد»، رواه البخاري ومسلم. فما حكاه القرآن عن الذين غلبوا فهو حكاية لا إقرار. وفي أمر عددهم قال الله: سيقولون ثلاثة رابعهم كلبهم ويقولون خمسة سادسهم كلبهم رجمًا بالغيب، ويقولون سبعة وثامنهم كلبهم، قل ربي أعلم بعدتهم ما يعلمهم إلا قليل، فلا تمار فيهم إلا مراءً ظاهرًا ولا تستفتِ فيهم منهم أحدًا. فالقرآن لم يحدد عددهم، وفيه توجيه إلى ألا ننشغل بما لا ينفع."], ["دروس السورة وفضلها", "قصة أصحاب الكهف إحدى أربع قصص في سورة الكهف: قصة أصحاب الكهف وفيها فتنة الدين، وقصة صاحب الجنتين وفيها فتنة المال، وقصة موسى والخضر وفيها فتنة العلم، وقصة ذي القرنين وفيها فتنة السلطان. وقد جاء في الحديث الصحيح أن من حفظ عشر آيات من أول سورة الكهف عُصم من الدجال، رواه مسلم. وجاء أن من قرأ سورة الكهف يوم الجمعة أضاء له من النور ما بين الجمعتين، وهو حديث صححه بعض أهل العلم. وجاء في أثناء السورة تأديب للنبي صلى الله عليه وسلم: ﴿وَلَا تَقُولَنَّ لِشَيْءٍ إِنِّي فَاعِلٌ ذَٰلِكَ غَدًا إِلَّا أَن يَشَاءَ اللَّهُ﴾. وسبب نزول السورة بحسب ما رواه ابن إسحاق أن قريشًا سألت النبي صلى الله عليه وسلم عن الفتية وذي القرنين والروح بإيعاز من اليهود، وهي رواية فيها ضعف في إسنادها، فنقول: وقيل. وهكذا تعلّمنا القصة أن الله يحفظ أولياءه، وأن البعث حق."]], "lesson": ["الثبات على الدين والهجرة بالدين عند خوف الفتنة من أعظم القربات.", "الشباب المؤمن الصادق قدوة عظيمة وزادهم الله هدى.", "الدعاء والتوكل على الله يفتحان أبواب الرحمة من حيث لا نحتسب.", "قصة النوم الطويل دليل على قدرة الله على البعث بعد الموت."], "cat": "story"}, {"id": "sr09", "title": "الهجرة الأولى إلى الحبشة والنجاشي", "type": "من السيرة النبوية", "verse": "وَمَن يَتَّقِ اللَّهَ يَجْعَل لَّهُ مَخْرَجًا", "source": "سورة الطلاق 65:2", "parts": [["لماذا الحبشة؟", "لما اشتد أذى قريش على المسلمين، وكان النبي ﷺ لا يستطيع أن يحميهم جميعًا، أذن لهم بالهجرة إلى أرض الحبشة، وكانت يومئذ تحت حكم ملك نصراني يسمّى النجاشي، واسمه أصحمة بن أبجر على ما ذكر أهل السير. وروى ابن إسحاق أن النبي ﷺ قال لأصحابه: لو خرجتم إلى أرض الحبشة، فإن بها ملكًا لا يُظلم عنده أحد، وهي أرض صدق، حتى يجعل الله لكم فرجًا مما أنتم فيه. وكانت الحبشة قريبة بالبحر من الحجاز، ولقريش علاقة تجارية بها، ولم يكن للنجاشي مصلحة في معاداة المسلمين. وكانت هذه الهجرة في السنة الخامسة من البعثة على المشهور، وهي أول هجرة في الإسلام، وفيها دليل على أن الفرار بالدين من مواضع الفتنة مشروع، وأن للمسلم أن يطلب الأمن في الأرض ما دام عاجزًا عن إقامة دينه. وقد كان اختيار الحبشة بتوجيه من النبي ﷺ نفسه، فلم يكن عن اجتهاد من الصحابة وحدهم."], ["الهجرة الأولى والثانية", "تذكر كتب السير أن أول من خرج مجموعة صغيرة من الرجال والنساء، منهم عثمان بن عفان رضي الله عنه ومعه زوجته رقية بنت رسول الله ﷺ، وقد أُثر عن النبي ﷺ أنه قال عنهما: «صحبهما الله، إن عثمان لأول من هاجر بأهله بعد لوط»، وهذا في كتب السير وقد اختلفت أسانيده. ثم تتابع المسلمون في الخروج، وكان من أبرزهم جعفر بن أبي طالب رضي الله عنه، فتكوّنت جماعة كبيرة أقامت في الحبشة. وتذكر كتب السير أن هذه كانت الهجرة الثانية، وقد شارك فيها عبد الله بن مسعود رضي الله عنه، فقد روى البخاري عنه أنه قال: كنا نسلّم على النبي ﷺ وهو يصلي فيردّ علينا، فلما رجعنا من عند النجاشي سلّمنا عليه فلم يرد علينا، وقال: «إن في الصلاة شغلًا». فهذا يدلّ على أن ابن مسعود كان من المهاجرين إلى الحبشة. وقد بقي ابن مسعود وغيره في الحبشة ثم عادوا إلى المدينة بعد الهجرة الكبرى."], ["وفد قريش إلى النجاشي", "استاءت قريش من أمان المسلمين في الحبشة، فأرسلت وفدًا إلى النجاشي برئاسة عمرو بن العاص وعبد الله بن أبي ربيعة، ومعهما هدايا لأساقفته وللنجاشي، ليطلبوا منه تسليم المسلمين. وهذه القصة رواها الإمام أحمد في مسنده عن أم سلمة رضي الله عنها، وذكرها ابن إسحاق في السيرة، وقد حسّنها كثير من أهل العلم. فأتى الوفد بطارقة النجاشي فأعطوهم الهدايا، وطلبوا منهم أن يشيروا على الملك بتسليم المسلمين، ثم عرضوا على النجاشي طلبهم، وقالوا إن هؤلاء سفهاء خرجوا عن دين قومهم ولم يدخلوا في دينه. فأراد النجاشي أن يسمع من المسلمين قبل أن يقرّر شيئًا، وكان في ذلك عدل منه، فلم يحكم قبل أن يسمع الطرفين. فاستدعى المسلمين وسألهم عن دينهم. وكان رسولا قريش يظنان أن الهدايا تكفي لإقناع الملك، فلم يدريا أن العدل أغلى من الهدايا. وقد أعدّا خطتهما بدقة، فكلّما قدّما الهدايا للبطارقة طلبا منهم ألا يتكلموا إلا بكلمة واحدة. ومع ذلك أراد الملك أن يسمع المسلمين بنفسه."], ["كلمة جعفر رضي الله عنه", "وتحدّث باسم المسلمين جعفر بن أبي طالب رضي الله عنه، وكان خطيبًا. وفي رواية أم سلمة رضي الله عنها عند أحمد أنه قال، بمعناه: كنا قومًا أهل جاهلية، نعبد الأصنام ونأكل الميتة ونأتي الفواحش ونقطع الأرحام ونسيء الجوار ويأكل القوي منا الضعيف، فكنا على ذلك حتى بعث الله إلينا رسولًا نعرف نسبه وصدقه وأمانته وعفافه، فدعانا إلى الله لنوحّده ونعبده ونخلع ما كنا نعبد من الحجارة والأوثان، وأمرنا بصدق الحديث وأداء الأمانة وصلة الرحم وحسن الجوار والكفّ عن المحارم والدماء، ونهانا عن الفواحش وقول الزور وأكل مال اليتيم وقذف المحصنة، وأمرنا بالصلاة والزكاة والصيام. فصدّقناه وآمنّا به. وهذه الكلمة من أجمل ما قيل في تلخيص الإسلام وبيان الفرق بين الجاهلية والرسالة. وكان جعفر رضي الله عنه حكيمًا في عرضه، فلم يهاجم دين النجاشي بل بيّن حقيقة الإسلام، وذكر ما فيه من خلق وعدل، فصار كلامه حجة لا تُرد. وقد قيل إن هذه الكلمة تُدرَّس إلى اليوم لما فيها من وضوح العرض وصدق الحال."], ["سورة مريم والنجاشي", "فلما سمع النجاشي هذا سأل جعفرًا: هل معك مما جاء به عن الله من شيء؟ فقال جعفر: نعم، فقرأ عليه صدرًا من سورة مريم. وفي رواية أم سلمة رضي الله عنها عند أحمد أن النجاشي بكى حتى اخضلّت لحيته، وبكى أساقفته حتى بلّوا مصاحفهم حين سمعوا ما تُلي عليهم. ثم قال النجاشي: إن هذا والذي جاء به موسى ليخرج من مشكاة واحدة. ثم قال لرسولي قريش: انطلقا فوالله لا أسلّمهم إليكم. وفي اليوم التالي حاول عمرو بن العاص أن يكيد للمسلمين فقال إنهم يقولون في عيسى ابن مريم قولًا عظيمًا، فسألهم النجاشي، فأجاب جعفر رضي الله عنه: نقول فيه الذي جاءنا به نبيّنا، هو عبد الله ورسوله وروحه وكلمته ألقاها إلى مريم العذراء البتول. فأخذ النجاشي عودًا من الأرض وقال: ما عدا عيسى ابن مريم ما قلتَ قدر هذا العود. فردّ هدايا قريش وأقام المسلمون في الحبشة آمنين."], ["إسلام النجاشي وصلاة النبي ﷺ عليه", "وقد ثبت في الصحيحين عن أبي هريرة رضي الله عنه أن النبي ﷺ نعى النجاشي في اليوم الذي مات فيه، وخرج بالناس إلى المصلى فصفّ بهم وكبّر عليه أربع تكبيرات، وقال: «استغفروا لأخيكم». وفي رواية قال: «مات اليوم رجل صالح من الحبش». وهذا يدل على إسلام النجاشي وحسن إيمانه. وتذكر كتب السير أن النبي ﷺ كان يراسله بعد الهجرة إلى المدينة، وأنه زوّج النبي ﷺ أم حبيبة بنت أبي سفيان رضي الله عنها وكانت من مهاجرات الحبشة. وتذكر كتب السير أن الله ردّ على قريش كيدها، وأن الدعوة وجدت لها مأوى آمنًا خارج مكة، وأن بعض المهاجرين عادوا إلى مكة بعد أن بلغهم أن قريشًا سجدت مع النبي ﷺ عندما قرأ سورة النجم، وهو أمر ثابت في الصحيح من حيث السجود، وكانت الأحوال في مكة لا تزال صعبة. وتذكر كتب السير أن الأحباش بعدها ظلوا يذكرون ما حصل لهم مع المسلمين."], ["دروس الهجرة إلى الحبشة", "في هذه الهجرة دروس كبيرة، منها أن النبي ﷺ كان حريصًا على حماية أصحابه ولو بتركهم بلدهم وهم أحبّ الأرض إليهم، فالدين أغلى من الوطن والمال. ومنها أن المسلمين اختاروا حاكمًا عادلًا يعيشون في كنفه ولو كان على غير دينهم، فكان العدل مقصدًا شرعيًّا. ومنها أن الخطاب الهادئ المؤدّب والصدق في العرض أبلغ أثرًا من المجادلة والتهويل. ومنها أن الله يجعل للمتقين مخرجًا كما قال تعالى: ﴿وَمَن يَتَّقِ اللَّهَ يَجْعَل لَّهُ مَخْرَجًا﴾. ومنها كذلك أن قريشًا كانت تعتمد على المال والمكر، فهزمها الصدق والحق. وهذه الهجرة كانت مقدمة للهجرة الكبرى إلى المدينة، وفيها تعلّم المسلمون كيف يتصرفون في بلد غريب، وكيف يقدّمون الإسلام بحسن الخلق ومنطق الحق. فمن حمل الإسلام بخلق وصدق فتح القلوب قبل الأبواب. وقد ظل جعفر رضي الله عنه وأصحابه في الحبشة حتى عادوا إلى النبي ﷺ وهو بخيبر، كما جاء في الصحيح، فأفرحه قدومهم فرحًا عظيمًا."]], "lesson": ["حماية الدين مقدّمة على الوطن والمال، وللمسلم أن يهاجر عند الفتنة.", "العدل مقصد عظيم، وقد كان عدل النجاشي سببًا في حماية المسلمين.", "الصدق وحسن العرض أبلغ من الجدال، وقد أبكى القرآن النجاشي وأساقفته.", "من يتق الله يجعل له مخرجًا، وهو سبحانه ينصر دينه بمن يشاء."], "cat": "seerah"}, {"id": "s10", "title": "قصة مريم وميلاد عيسى عليهما السلام", "type": "قصة قرآنية", "verse": "وَاذْكُرْ فِي الْكِتَابِ مَرْيَمَ إِذِ انتَبَذَتْ مِنْ أَهْلِهَا مَكَانًا شَرْقِيًّا", "source": "سورة مريم 19:16", "parts": [["نذر امرأة عمران", "بدأت قصة مريم عليها السلام من قبل ولادتها. فقد نذرت امرأة عمران ما في بطنها لله خالصًا، فقالت: ﴿رَبِّ إِنِّي نَذَرْتُ لَكَ مَا فِي بَطْنِي مُحَرَّرًا فَتَقَبَّلْ مِنِّي﴾، أي خالصًا لعبادتك وخدمة بيتك. فلما وضعتها قالت: رب إني وضعتها أنثى والله أعلم بما وضعت وليس الذكر كالأنثى وإني سميتها مريم وإني أعيذها بك وذريتها من الشيطان الرجيم. فاستجاب الله دعاءها، وتقبلها ربها بقبول حسن وأنبتها نباتًا حسنًا. وثبت في الصحيح أن النبي صلى الله عليه وسلم قال: «ما من مولود يولد إلا والشيطان يمسّه حين يولد، فيستهلّ صارخًا من مسّ الشيطان إياه، إلا مريم وابنها»، رواه البخاري ومسلم. ولم يذكر القرآن اسم امرأة عمران، وما يُروى في اسمها وفي تفاصيل أخرى مما لا يثبت. وكانت مريم من بيت صالح، فنشأت في طاعة الله وعبادته."], ["كفالة زكريا والمحراب", "ولما وُلدت مريم تنافس الناس في كفالتها، فكفلها زكريا عليه السلام، وهو نبي كريم، كما قال الله: ﴿وَكَفَّلَهَا زَكَرِيَّا﴾. وكانت في المحراب، أي في مكان العبادة، منقطعة إلى الله. وكان زكريا كلما دخل عليها المحراب وجد عندها رزقًا. فقال: يا مريم أنّى لك هذا؟ قالت: هو من عند الله إن الله يرزق من يشاء بغير حساب. ولم يحدد القرآن نوع الرزق، وقيل إنه فاكهة الصيف في الشتاء وفاكهة الشتاء في الصيف، وهو قول لبعض المفسرين، ولا يثبت بنص صحيح. وهذه الكرامة من الله لمريم عليها السلام تدل على صلاحها وصدق عبادتها. وعندها دعا زكريا ربه أن يهب له ذرية طيبة، فاستجاب الله دعاءه ورزقه يحيى. وقال الله في مريم: وصدّقت بكلمات ربها وكتبه وكانت من القانتين. وقالت لها الملائكة: يا مريم إن الله اصطفاك وطهّرك واصطفاك على نساء العالمين، يا مريم اقنتي لربك واسجدي واركعي مع الراكعين."], ["البشارة", "وفي يوم من الأيام انفردت مريم عليها السلام من أهلها في مكان شرقي، واتخذت من دونهم حجابًا. فأرسل الله إليها روحه، وهو جبريل عليه السلام، فتمثل لها بشرًا سويًّا. فخافت وقالت: إني أعوذ بالرحمن منك إن كنت تقيًّا. فقال: إنما أنا رسول ربك لأهب لك غلامًا زكيًّا. قالت: أنّى يكون لي غلام ولم يمسسني بشر ولم أك بغيًّا؟ قال: كذلك قال ربك هو عليّ هيّن، ولنجعله آية للناس ورحمة منّا وكان أمرًا مقضيًّا. وقد بشّرتها الملائكة كذلك بقولهم في سورة آل عمران: إن الله يبشّرك بكلمة منه اسمه المسيح عيسى ابن مريم وجيهًا في الدنيا والآخرة ومن المقرّبين، ويكلّم الناس في المهد وكهلًا ومن الصالحين. فلم يكن ميلاد عيسى عليه السلام من أب، بل بكلمة من الله: كن فيكون. وهذا بيان لقدرة الله الكاملة التي لا يعجزها شيء، وقد قال سبحانه: إن مثل عيسى عند الله كمثل آدم خلقه من تراب ثم قال له كن فيكون."], ["المخاض والنخلة", "حملت مريم عليها السلام بعيسى عليه السلام بنفخ من روح الله، فانتبذت به مكانًا قصيًّا، أي ابتعدت إلى مكان بعيد عن أهلها. ولم يحدد القرآن اسم المكان، وما قيل إنه بيت لحم فهو من أخبار المفسرين وأهل الكتاب. فأجاءها المخاض إلى جذع النخلة، أي ألجأها ألم الولادة إلى جذع نخلة تستند إليه. قالت وهي في شدة الألم والخوف من كلام الناس: ﴿يَا لَيْتَنِي مِتُّ قَبْلَ هَٰذَا وَكُنتُ نَسْيًا مَّنسِيًّا﴾. فناداها من تحتها، قيل جبريل عليه السلام وقيل عيسى عليه السلام، وقد اختلف المفسرون: ألا تحزني قد جعل ربك تحتك سريًّا، وهزّي إليك بجذع النخلة تساقط عليك رطبًا جنيًّا، فكلي واشربي وقرّي عينًا. ولم يحدد القرآن وقت ولادته من العام. ثم أوصيت: فإما ترين من البشر أحدًا فقولي إني نذرت للرحمن صومًا فلن أكلم اليوم إنسيًّا. ففي هذا اللطف الإلهي تسلية لقلب أم في أشد حالات الضعف."], ["عودة مريم ونطق الطفل", "أتت مريم عليها السلام قومها تحمله، فلما رأوها قالوا: يا مريم لقد جئت شيئًا فريًّا، يا أخت هارون ما كان أبوك امرأ سوء وما كانت أمك بغيًّا. وفي صحيح مسلم أن المغيرة بن شعبة رضي الله عنه سأله أهل نجران عن قوله: يا أخت هارون، فرجع إلى النبي صلى الله عليه وسلم فقال: «إنهم كانوا يسمّون بأنبيائهم والصالحين قبلهم»، أي أنها من نسل الصالحين وعلى طريقتهم. فلم تردّ عليهم بالكلام، بل أشارت إلى الطفل. فقالوا: كيف نكلم من كان في المهد صبيًّا؟ فأنطقه الله وهو رضيع، فقال: ﴿إِنِّي عَبْدُ اللَّهِ آتَانِيَ الْكِتَابَ وَجَعَلَنِي نَبِيًّا﴾، وجعلني مباركًا أين ما كنت، وأوصاني بالصلاة والزكاة ما دمت حيًّا، وبرًّا بوالدتي ولم يجعلني جبارًا شقيًّا، والسلام عليّ يوم ولدت ويوم أموت ويوم أُبعث حيًّا. فكان أول ما نطق به أنه عبد الله، تبرئةً لأمه وردًّا على من ادّعى ألوهيته."], ["رسالة عيسى عليه السلام ومعجزاته", "كبر عيسى عليه السلام وأرسله الله إلى بني إسرائيل، وأيّده بالمعجزات، فقال لهم: ﴿أَنِّي قَدْ جِئْتُكُم بِآيَةٍ مِّن رَّبِّكُمْ﴾، أني أخلق لكم من الطين كهيئة الطير فأنفخ فيه فيكون طيرًا بإذن الله، وأُبرئ الأكمه والأبرص وأحيي الموتى بإذن الله، وأُنبّئكم بما تأكلون وما تدّخرون في بيوتكم. وكل ذلك بإذن الله، لا بقدرة ذاتية فيه. وأتاه الله الإنجيل، وجاء مصدّقًا لما بين يديه من التوراة، ومحلًّا لبعض ما حُرّم عليهم. فآمن به الحواريون، وقالوا: نحن أنصار الله آمنا بالله واشهد بأنا مسلمون. وطلبوا منه أن ينزل الله عليهم مائدة من السماء، فأنزلها الله عليهم وحذّرهم من الكفر بعدها. ولم يحدد القرآن عدد الحواريين ولا ما كان على المائدة، وما ورد في ذلك من أخبار فغير ثابت. وقد أنكر عيسى عليه السلام أن يكون قال للناس اتخذوني وأمي إلهين، وقال: ما قلت لهم إلا ما أمرتني به أن اعبدوا الله ربي وربكم."], ["رفعه إلى الله وخاتمة القصة", "أراد بنو إسرائيل قتل عيسى عليه السلام، لكن الله نجّاه. قال تعالى: ﴿وَمَا قَتَلُوهُ وَمَا صَلَبُوهُ وَلَٰكِن شُبِّهَ لَهُمْ﴾، وقال: بل رفعه الله إليه وكان الله عزيزًا حكيمًا. فهو حيّ مرفوع إلى السماء بإذن الله. ولم يحدد القرآن كيفية الشبه ولا من الذي شُبّه به، وما رُوي في ذلك فمن اجتهاد المفسرين وأخبار أهل الكتاب. وثبت في الصحيحين عن أبي هريرة رضي الله عنه أن النبي صلى الله عليه وسلم قال: «والذي نفسي بيده ليوشكن أن ينزل فيكم ابن مريم حكمًا عدلًا، فيكسر الصليب ويقتل الخنزير ويضع الجزية». فينزل في آخر الزمان تابعًا لشريعة محمد صلى الله عليه وسلم. وأما مريم عليها السلام فقد قال فيها النبي صلى الله عليه وسلم: «كمل من الرجال كثير، ولم يكمل من النساء إلا مريم بنت عمران وآسية امرأة فرعون»، وذكرها القرآن بالصدّيقة. وبذلك تبقى مريم قدوة للعفة والعبادة، وعيسى عليه السلام عبدًا لله ورسوله وكلمته ألقاها إلى مريم وروحًا منه."]], "lesson": ["الإخلاص لله في النذر والعمل والدعاء، وطلب الذرية الصالحة.", "العفة والحياء والطاعة تحفظ المرأة وتُعلي قدرها عند الله.", "من توكل على الله جعل له من كل ضيق مخرجًا ومن كل هم فرجًا.", "عيسى عليه السلام عبد الله ورسوله، خلقه الله بقدرته كما خلق آدم."], "cat": "story"}, {"id": "sr10", "title": "إسلام حمزة وعمر رضي الله عنهما", "type": "من السيرة النبوية", "verse": "فَمَن يُرِدِ اللَّهُ أَن يَهْدِيَهُ يَشْرَحْ صَدْرَهُ لِلْإِسْلَامِ", "source": "سورة الأنعام 6:125", "parts": [["أسد الله حمزة بن عبد المطلب", "كان حمزة بن عبد المطلب رضي الله عنه عمّ النبي ﷺ وأخاه من الرضاعة، وكان من أشدّ فتيان قريش وأعزّهم، يحب الصيد والقنص. وقد أسلم في السنة السادسة من البعثة على ما ذكر أهل السير. وتذكر كتب السير أن أبا جهل آذى النبي ﷺ عند الصفا وسبّه ونال منه، وكان النبي ﷺ ساكتًا لا يكلمه، وكانت مولاة لعبد الله بن جدعان تسمع ذلك. فلما عاد حمزة من صيده أخبرته، فغضب غضبًا شديدًا وانطلق إلى أبي جهل وهو في نادي قومه فضربه بقوسه، ثم أعلن إسلامه. وهذا الخبر مشهور في كتب السير، وإن لم يكن في الصحيح بتفاصيله. وتذكر كتب السير أنه دخل في الإسلام في أول الأمر أنفةً وحميّةً ثم شرح الله صدره للإيمان. ومنذ ذلك الحين لُقّب بأسد الله وأسد رسوله ﷺ. وكان هذا الحادث مما رُوي أن فيه فرحة للمسلمين لاجتماع شملهم بعد افتراق."], ["أثر إسلام حمزة", "كان لإسلام حمزة رضي الله عنه أثر كبير في نفوس قريش، فقد علموا أن النبي ﷺ صار له من يمنعه بقوة. وتذكر كتب السير أن قريشًا خفّفت بعض ما كانت تتعرض به للنبي ﷺ لما أسلم حمزة، لأنها خافت من بطشه وعزته. وكان ذلك عزًّا للمسلمين وسببًا في اطمئنانهم بعض الشيء. واستمر حمزة رضي الله عنه يدافع عن الإسلام ويجاهد، وشهد بدرًا وأبلى فيها بلاءً حسنًا، ثم استشهد في أحد، قتله وحشي رضي الله عنه، وقد أسلم بعد ذلك. وقد رُوي في سيرته أن النبي ﷺ سمّاه سيد الشهداء، وذلك في المستدرك وغيره. وكان النبي ﷺ حزينًا عليه حزنًا شديدًا. وفي هذا بيان أن العزة بالإسلام لا بالجاه، فحمزة رضي الله عنه قد دخل الإسلام قويًّا فجعل الله قوته في نصرة الدين. وفي هذا ما يدل على أن المسلم قد يكون عاملًا مؤثرًا في أي مكان قاصيًا كان أو قريبًا."], ["عمر بن الخطاب قبل الإسلام", "وأما عمر بن الخطاب رضي الله عنه فكان من أشد الناس على المسلمين قبل إسلامه، رجلًا قويًّا مهيبًا من بني عدي، يحمل في نفسه غيرة على دين قومه. وكان النبي ﷺ يرجو إسلامه، وقد رُوي في الترمذي عن ابن عمر رضي الله عنهما أن النبي ﷺ قال: «اللهم أعزّ الإسلام بأحبّ هذين الرجلين إليك: بعمر بن الخطاب أو بأبي جهل بن هشام»، قال: فكان أحبهما إلى الله عمر بن الخطاب، وهو حديث حسّنه جمع من أهل العلم. وكان إسلام عمر بعد هجرة الحبشة على ما ذكر أهل السير، وكان في السنة السادسة من البعثة تقريبًا. ولم يكن النبي ﷺ يطلب العزة لدينه بالقوة وحدها، لكنه كان يدعو الله أن ييسّر له من ينصره، فاستجاب الله دعاءه. وفي اشتهاره بين المسلمين ما يدل على عظم أثره في نفوسهم، وإن كان بين العلماء كلام في أسانيد بعض تفاصيله."], ["قصة إسلامه", "تذكر كتب السير أن عمر رضي الله عنه خرج متقلدًا سيفه يريد قتل النبي ﷺ، فلقيه رجل فأخبره أن أخته فاطمة وزوجها سعيد بن زيد قد أسلما، فذهب إليهما، فوجد عندهما خبّاب بن الأرت رضي الله عنه يعلّمهما القرآن، فضرب أخته وزوجها، ثم رقّ قلبه لما رأى منها من الثبات، وطلب أن يقرأ الصحيفة، فقرأ صدرًا من سورة طه، فتأثر بها وطلب الدخول على النبي ﷺ. وهذه القصة مشهورة في السير، لكن أهل العلم تكلموا في أسانيدها، ولذلك لا نجزم بتفاصيلها، والمتفق عليه أن عمر أسلم بعد أن رأى من آيات القرآن وصدق النبي ﷺ ما شرح صدره. وهكذا تتحول القلوب الشديدة إذا أراد الله هدايتها، فعمر الذي خرج غاضبًا يريد الأذى دخل الإسلام ونصرته. وفي هذه النتيجة ما يدل على أن الله يحرس دينه ويكتب النصر لأهل الحق متى صدقوا. فكل ما جرى كان بقدر الله وحكمته."], ["أثر إسلام عمر", "كان لإسلام عمر رضي الله عنه أثر عظيم في عزة المسلمين، حتى قال عبد الله بن مسعود رضي الله عنه كما في صحيح البخاري: ما زلنا أعزّة منذ أسلم عمر. وتذكر كتب السير أن المسلمين خرجوا بعد إسلامه إلى الكعبة وصلّوا عندها علانية بعد أن كانوا يخفون عبادتهم. وفي صحيح البخاري عن ابن عمر رضي الله عنهما أن عمر لما أسلم اجتمع الناس عند داره وقالوا: صبأ عمر، فجاء العاص بن وائل السهمي فقال: أنا له جار، فتفرّق الناس. وفي هذا بيان ما كان للجوار من مكانة عند العرب، وأن عمر رضي الله عنه كان قد صار هدفًا للتعرّض لولا حماية هذا الجار. وبهذا كان إسلام عمر رضي الله عنه من أسباب ظهور الإسلام في مكة بعد أن كان خافتًا. وتذكر كتب السير أنه كان له أثر في حياة عمر بن الخطاب كلها، إذ كان يشهد المشاهد كلها مع النبي ﷺ ويقف على مكانة هذا المقام الكبير."], ["العلاقة بين الحدثين", "جاء إسلام حمزة ثم عمر رضي الله عنهما في وقت اشتد فيه البلاء على المسلمين، فكان رحمة من الله وتخفيفًا، وإن لم يوقف الأذى. وهذا يدل على أن النصر يأتي من حيث لا يحتسب المؤمن، فالقوم الذين كانوا يخافون من أن يقتلهم بعض المسلمين ويتعذّبون في الأرض، صار بينهم رجلان من أعزّ رجال قريش. وقد قال الله تعالى: ﴿فَمَن يُرِدِ اللَّهُ أَن يَهْدِيَهُ يَشْرَحْ صَدْرَهُ لِلْإِسْلَامِ﴾، فشرح الله صدر حمزة وعمر ولم يكن ذلك بحيلة بشر. وسيأتي بعد هذين الإسلامين فصل المقاطعة والحصار، فتبيّن أن اشتداد الابتلاء لا يعني ضعف الدعوة، بل قد يكون مقدمة لاتساعها. وبقي الصحابيان الجليلان عزًّا للإسلام وجنديين من جنوده، حتى لقيا ربهما شهيدين، فحمزة في أحد وعمر في المحراب. وهذا الصنف من الحماية هو الذي كان يُعرف بالجوار، ولولاه ما أمكن لكثير من أصحاب الدعوة أن يمشوا في الطرقات."], ["دروس من الحدثين", "في إسلام هذين الصحابيين دروس كثيرة، منها أن الهداية فضل من الله، فهو يهدي من يشاء ولو كان من أشد الناس عداوة، فلا ييأس الداعية من أحد. ومنها أن الإسلام يغيّر الطباع إلى الخير، فشدّة عمر صارت قوةً في الحق، وغضب حمزة صار نصرة للنبي ﷺ. ومنها أن الدعاء سلاح المؤمن، فقد دعا النبي ﷺ بعزة الإسلام فاستجاب الله. ومنها أن القوة المادية مطلوبة إذا صُرفت في سبيل الخير، وقد قال النبي ﷺ: «المؤمن القوي خير وأحب إلى الله من المؤمن الضعيف وفي كل خير»، رواه مسلم. ومنها أن العزة لا تكون بالتخلي عن الدين، بل بالتمسك به، فمنذ أسلم هذان الرجلان كان للمسلمين وجود ظاهر في مكة، ولم يعودوا يصلّون في الخفاء. وبهذا مضت الدعوة نحو مرحلتها التالية بثبات. وبهذا ننتهي من فصول العزة والمنعة في الدعوة المكية، ويبقى الدرس أن الله ناصر عباده المؤمنين مهما تعاظمت المحن."]], "lesson": ["لا ييأس الداعية من هداية أحد، فقد هدى الله أشد الناس عداوة ثم جعلهم ركائز الدين.", "الدعاء بعزة الإسلام سلاح المؤمن، وقد استجاب الله لنبيه ﷺ في عمر رضي الله عنه.", "القوة النافعة هي التي تُوظَّف في الحق ونصرة المظلوم.", "الابتلاء المتصل قد يكون مقدمة للفرج، وقد يأتي النصر من حيث لا يحتسب المؤمن."], "cat": "seerah"}, {"id": "s11", "title": "قصة ذي القرنين", "type": "قصة قرآنية", "verse": "قَالَ هَٰذَا رَحْمَةٌ مِّن رَّبِّي ۖ فَإِذَا جَاءَ وَعْدُ رَبِّي جَعَلَهُ دَكَّاءَ ۖ وَكَانَ وَعْدُ رَبِّي حَقًّا", "source": "سورة الكهف 18:98", "parts": [["من هو ذو القرنين؟", "جاء ذكر ذي القرنين في سورة الكهف، حيث قال الله تعالى لنبيه صلى الله عليه وسلم: ﴿وَيَسْأَلُونَكَ عَن ذِي الْقَرْنَيْنِ قُلْ سَأَتْلُو عَلَيْكُم مِّنْهُ ذِكْرًا﴾. ولم يحدد القرآن اسمه ولا زمانه ولا بلاده، وللعلماء في تعيينه أقوال متعددة، فقيل هو الإسكندر المقدوني، وقد استبعد ذلك كثير من المحققين، ورجّح ابن كثير أنه رجل صالح مؤمن سبق الإسكندر بزمن طويل، وقيل غير ذلك. وسبب تسميته بذي القرنين مختلف فيه أيضًا، فقيل لأنه بلغ قرني الشمس أي مشرقها ومغربها، وقيل لغير ذلك، ولا يثبت في ذلك نص صحيح. والمقصود من القصة العبرة لا تحديد الشخص. وقد وصفه الله بقوله: إنا مكنا له في الأرض وآتيناه من كل شيء سببًا، أي أعطاه الله أسباب الملك والقوة والعلم والتمكين، فاتبع سببًا، أي سلك طريقًا من الأسباب التي أتاحها الله له. فهو ملك صالح، جمع بين السلطان والإيمان."], ["رحلة المغرب والعدل", "سار ذو القرنين في الأرض حتى إذا بلغ مغرب الشمس وجدها تغرب في عين حمئة، أي في بحر أو ماء يخالطه طين أسود فيما بدا له بحسب رؤيته. ووجد عندها قومًا، فخيّره الله: يا ذا القرنين إما أن تعذب وإما أن تتخذ فيهم حسنًا. فأجاب بميزان العدل: ﴿أَمَّا مَن ظَلَمَ فَسَوْفَ نُعَذِّبُهُ ثُمَّ يُرَدُّ إِلَىٰ رَبِّهِ فَيُعَذِّبُهُ عَذَابًا نُّكْرًا﴾، وأما من آمن وعمل صالحًا فله جزاء الحسنى وسنقول له من أمرنا يسرًا. فبيّن أنه لن يتجاوز حدود الله، وأنه سيعاقب الظالم وسيكرم المؤمن، وأن الأمر كله لله. ولم يحدد القرآن اسم هؤلاء القوم ولا مكانهم. وفي ذلك درس في سياسة الحاكم العادل، إذ لا يتعامل مع الناس بالهوى بل بميزان الإيمان والعمل. وهذا هو الحكم الصالح الذي يجمع الرحمة والحزم، فيعاقب المسيء بقدر إساءته ويحسن إلى المحسن، ويذكّر الناس بأنهم راجعون إلى الله."], ["رحلة المشرق", "ثم أتبع سببًا آخر، فسار حتى إذا بلغ مطلع الشمس وجدها تطلع على قوم لم يجعل الله لهم من دونها سترًا. وفسّر المفسرون ذلك بأنهم قوم لا بناء لهم ولا ملابس تقيهم من حر الشمس، وقيل غير ذلك، والمهم أنهم قوم بدائيون في العيش. ثم قال الله: ﴿كَذَٰلِكَ وَقَدْ أَحَطْنَا بِمَا لَدَيْهِ خُبْرًا﴾، أي أن الله محيط بعلم ما عند ذي القرنين من القوة والعلم والجنود. ولم يذكر القرآن ما فعله معهم ولا ما جرى بينهم. ولم يتحدد في القرآن مكان هؤلاء القوم ولا عصرهم. وقد دلّت الآية على أن الله سبحانه لا يخفى عليه شيء من أمر عباده، وأن المُلك إنما هو بيده يؤتيه من يشاء. وهذه الرحلات الواسعة لذي القرنين من المغرب إلى المشرق تدل على اتساع نفوذه وعلى أنه كان يجمع بين الإيمان والعدالة والحركة في سبيل الإصلاح، لا في سبيل التسلط والاستعلاء."], ["القوم الذين لا يكادون يفقهون قولًا", "ثم أتبع سببًا ثالثًا، فسار حتى إذا بلغ بين السدّين وجد من دونهما قومًا لا يكادون يفقهون قولًا. والسدّان جبلان عظيمان، ولم يحدد القرآن موضعهما، واختلفت أقوال المفسرين والمؤرخين في تعيينه، ولا يثبت منها قول صحيح. فشكا إليه هؤلاء القوم ما يعانونه فقالوا: ﴿يَا ذَا الْقَرْنَيْنِ إِنَّ يَأْجُوجَ وَمَأْجُوجَ مُفْسِدُونَ فِي الْأَرْضِ فَهَلْ نَجْعَلُ لَكَ خَرْجًا عَلَىٰ أَن تَجْعَلَ بَيْنَنَا وَبَيْنَهُمْ سَدًّا﴾. أي: نعطيك أجرًا على أن تبني بيننا وبينهم حاجزًا. ويأجوج ومأجوج أمتان من بني آدم، كما جاء في الصحيح أن الله يقول لآدم يوم القيامة: يا آدم، فيقول: لبيك وسعديك، فيقول: أخرج بعث النار، قال: وما بعث النار؟ قال: من كل ألف تسعمائة وتسعة وتسعين، وأن منكم رجلًا ومن يأجوج ومأجوج ألفًا. وهكذا كانت حاجة هؤلاء إلى من ينصرهم دافعًا لعمل ذي القرنين العظيم."], ["بناء السد", "فأجاب ذو القرنين بتواضع وإيمان: ﴿مَا مَكَّنِّي فِيهِ رَبِّي خَيْرٌ فَأَعِينُونِي بِقُوَّةٍ أَجْعَلْ بَيْنَكُمْ وَبَيْنَهُمْ رَدْمًا﴾. فرفض الأجر وطلب منهم أن يعينوه بالجهد والعمل. ثم قال: آتوني زبر الحديد، أي قطع الحديد الكبيرة، فجاؤوه بها، فوضعها بين الجبلين حتى ساوى بين الصدفين، أي سوّى بين جانبي الجبلين. ثم قال: انفخوا، فنفخوا حتى جعله نارًا. ثم قال: آتوني أُفرغ عليه قطرًا، وهو النحاس المذاب. فسكبه على الحديد المحمّى فالتصق وتماسك، فما استطاعوا أن يظهروه أي يتسلقوه، وما استطاعوا له نقبًا. ولم يحدد القرآن موضع السد ولا ارتفاعه ولا عرضه، وما تتناقله الكتب من تفاصيل فمن اجتهاد أصحابها. والمهم أن ذا القرنين جمع بين التواضع والإتقان والعمل بالأسباب، فاستعان بقوتهم ولم يكلفهم ما لا يطيقون، وصنع بينهم وبين الفساد حاجزًا متينًا، ثم نسب الفضل كله لله."], ["الوعد الحق", "قال ذو القرنين بعد أن أتم بناء السد: ﴿هَٰذَا رَحْمَةٌ مِّن رَّبِّي فَإِذَا جَاءَ وَعْدُ رَبِّي جَعَلَهُ دَكَّاءَ وَكَانَ وَعْدُ رَبِّي حَقًّا﴾. فلم يتعظّم بما فعل، ولم يُرجع الفضل إلى نفسه، بل ردّه إلى الله وذكّر بيوم تنهدم فيه الأرض. وأخبر القرآن بخروج يأجوج ومأجوج في آخر الزمان: حتى إذا فُتحت يأجوج ومأجوج وهم من كل حدب ينسلون. وقد جاء في الصحيحين عن زينب بنت جحش رضي الله عنها أن النبي صلى الله عليه وسلم قال: «ويل للعرب من شرّ قد اقترب، فتح اليوم من ردم يأجوج ومأجوج مثل هذه»، وحلّق بإصبعه الإبهام والتي تليها. وهذا يدلّ على قرب اقتراب الساعة وعلى عظم الفتن في آخر الزمان. ويُستفاد من القصة أن العمل الصالح والمُلك الراشد يجتمعان في عبد مؤمن، وأن أعظم الأعمال أن ينفع الناس ويدفع عنهم الشر، وأن كل بناء يزول إذا جاء وعد الله، وأن الأعمال تُقاس بإخلاصها."]], "lesson": ["التمكين نعمة من الله تُشكر بالعدل والإحسان وليس بالاستكبار.", "العمل بالأسباب من الإيمان، وطلب العون من الناس بالجهد لا بالمال.", "التواضع بعد الإنجاز بنسبة الفضل لله: هذا رحمة من ربي.", "كل بناء في الدنيا زائل، والوعد الحق للآخرة."], "cat": "story"}, {"id": "sr11", "title": "المقاطعة في شعب أبي طالب", "type": "من السيرة النبوية", "verse": "إِنَّ مَعَ الْعُسْرِ يُسْرًا", "source": "سورة الشرح 94:6", "parts": [["أسباب المقاطعة", "لما رأت قريش أن الإسلام يشق طريقه رغم الأذى، وأن النجاشي أحسن استقبال المهاجرين إلى الحبشة، وأن حمزة وعمر رضي الله عنهما قد دخلا في دين الله، اشتد غيظها وضاقت حيلها. فحاولت أولًا أن تساوم أبا طالب، عمّ النبي ﷺ وحاميه، فطلبت منه أن يكفّ ابن أخيه أو يسلّمه إليها، فرفض أن يخذله. فلما لم تنفع المساومة قرر زعماؤها أن يضيّقوا على بني هاشم وبني المطلب حتى يتخلّوا عن النبي ﷺ. وكان هؤلاء قد وقفوا معه حميّةً وقرابةً، فمنهم من آمن ومنهم من بقي على دين قومه، لكنهم جميعًا أبوا أن يسلموه. وكان ذلك في أوائل العام السابع من البعثة على المشهور، وقيل غير ذلك. وبهذا انتقلت قريش من الأذى الفردي لأفراد المؤمنين إلى أسلوب جديد هو العزل الاقتصادي والاجتماعي لقبيلة كاملة."], ["الصحيفة الظالمة", "اجتمعت قريش وتعاهدت على ألا يتزوجوا من بني هاشم وبني المطلب ولا يزوّجوهم، وألا يبيعوهم شيئًا ولا يشتروا منهم، وألا يخالطوهم حتى يسلّموا إليهم محمدًا ﷺ ليقتلوه. وكتبوا بذلك صحيفةً وعلّقوها في جوف الكعبة تأكيدًا للعهد وتهيبًا له. وقد ثبت في الصحيحين أن النبي ﷺ قال: «نحن نازلون غدًا بخيف بني كنانة حيث تقاسموا على الكفر». وبيّن الزهري، كما في صحيح البخاري، أن ذلك أن قريشًا وكنانة تحالفت على بني هاشم وبني المطلب ألا يناكحوهم ولا يبايعوهم حتى يسلّموا إليهم النبي ﷺ. وهكذا صار الميثاق الذي أرادوه حصارًا شاملًا لا يُباع فيه الطعام ولا يقع فيه نكاح ولا مخالطة، والغاية إجبار جماعة كاملة على تسليم رجل واحد، وهو أبعد ما يكون عن مروءة العرب التي يتفاخرون بها."], ["الدخول في الشِّعب", "انحاز بنو هاشم وبنو المطلب إلى شِعب أبي طالب، وهو موضع بين جبال مكة كان لبني هاشم، ودخل معهم النبي ﷺ ومن آمن من أقاربه، ولم يخرج عن جماعتهم إلا أبو لهب، فإنه فارقهم وظاهر قريشًا عليهم. ومكثوا على هذه الحال نحو ثلاث سنين على المشهور، وقيل سنتان. وتذكر كتب السيرة أن أبا طالب كان شديد الحرص على النبي ﷺ، فإذا نام الناس أمره أن يبيت في فراشه ليراه من أراد به سوءًا، ثم يحوّله إلى مكان آخر ليلًا حتى لا يؤخذ على غرّة. وكانت خديجة رضي الله عنها مع زوجها في ذلك الحصار، وقد كانت من أعظم من واساه ونصره بنفسها ومالها قبل ذلك وبعده، فصبرت معه على الجوع والعزلة بعد ما عاشت في رغد وسعة."], ["الجوع والصبر", "اشتدّ البلاء في الشِّعب حتى بلغ الجوع بأهله مبلغًا شديدًا، وتذكر كتب السيرة أن أصوات صبيانهم كانت تُسمع من وراء الشِّعب من شدة الجوع. وكان الطعام لا يصل إليهم إلا خفيةً في الغالب، وخرجوا في أوقات من الأشهر الحرم يلتمسون ما يحتاجون إليه، وقريش تتربص بهم. وتروي كتب السيرة أن حكيم بن حزام، وكان ابن أخي خديجة رضي الله عنها وقتها على دين قومه، حمل شيئًا من القمح إلى عمته، فاعترضه أبو جهل ليمنعه، فتدخل رجل من قريش هو أبو البختري بن هشام فخلّى سبيله. وفي هذه الأيام لم يتوقف النبي ﷺ عن الدعوة، فكان يعرض الإسلام على الوافدين في مواسم الحج، ويثبّت أصحابه، فلم يقطع الحصار عنه الرسالة ولم يضعف إيمان أصحابه."], ["نقض الصحيفة", "لم يكن في قريش من أهل الرحم والمروءة إلا من ضاق صدره بهذا الظلم. وتذكر كتب السيرة أن هشام بن عمرو، وكان يصل بني هاشم سرًّا بالطعام، سعى في نقض الصحيفة، فكلّم زهير بن أبي أمية والمطعم بن عدي وأبا البختري وزمعة بن الأسود، فاتفقوا على إنهاء المقاطعة. وقام زهير عند الكعبة فاستنكر أن يأكل أهل مكة ويلبسوا وبنو هاشم محبوسون، وأعلن أنه لن يرضى حتى تُمزّق الصحيفة الظالمة. واعترض أبو جهل، لكن الجمع أسكته. وتروي كتب السيرة أن الصحيفة وُجدت وقد أكلت الأرضةُ ما فيها من ظلم وقطيعة وبقي فيها اسم الله، وأن أبا طالب كان قد أخبر قريشًا بذلك عن ابن أخيه ﷺ، وفي سند هذه الرواية مقال، فيُقتصر على ما اتفق عليه أهل السير من أن المقاطعة انتهت بجهد هؤلاء الرجال الأشراف."], ["نهاية الحصار ودلالته", "خرج المحاصَرون من الشِّعب وقد أنهكهم الجوع، لكنهم خرجوا أقوى عزيمةً مما دخلوا، فقد ثبتوا على الحق ثلاث سنين تقريبًا لم يتراجع فيها النبي ﷺ ولم يتخلَّ عنه قومه من بني هاشم وبني المطلب. ولم تكف قريش عن الإيذاء بعد ذلك، بل ازدادت شدتها بعد وفاة أبي طالب وخديجة رضي الله عنها بقليل. وفي هذه الحادثة يظهر أن الله يربّي أهل الحق بالشدائد ليكونوا أهلًا لحمل الرسالة، وأن الظلم مهما اتسع يزول بأسباب لا يتوقعها الظالمون، فقد ذكر القرآن وعد الله بأن مع العسر يسرًا. وكانت تلك السنوات الثلاث مدرسة صبر خرّجت جيلًا سيحمل الإسلام إلى المدينة ثم إلى الدنيا كلها بعد ذلك."]], "lesson": ["الثبات على الحق عند اشتداد الحصار والجوع، وعدم تسليم المبدأ مهما اشتد الضغط.", "نصرة الأقارب والجماعة لصاحب الحق من المروءة، وقد يكون الأخذ بالقرابة سببًا في دفع الشر.", "الظلم لا يدوم، وقد يقيّض الله لنقضه رجالًا من حيث لا يحتسب الظالمون.", "الدعوة لا تتوقف بالمحنة، فقد كان النبي ﷺ يعرض الإسلام على الوافدين وهو في أشد الحصار."], "cat": "seerah"}, {"id": "s12", "title": "قصة سليمان عليه السلام: النملة والهدهد وبلقيس", "type": "قصة قرآنية", "verse": "حَتَّىٰ إِذَا أَتَوْا عَلَىٰ وَادِ النَّمْلِ قَالَتْ نَمْلَةٌ يَا أَيُّهَا النَّمْلُ ادْخُلُوا مَسَاكِنَكُمْ لَا يَحْطِمَنَّكُمْ سُلَيْمَانُ وَجُنُودُهُ وَهُمْ لَا يَشْعُرُونَ", "source": "سورة النمل 27:18", "parts": [["ملك سليمان وعلمه", "ورث سليمان عليه السلام أباه داود في النبوة والملك، قال الله تعالى: وورث سليمان داود، وقال: يا أيها الناس علّمنا منطق الطير وأوتينا من كل شيء إن هذا لهو الفضل المبين. ومعنى منطق الطير أن الله علّمه فهم أصواتها ومقاصدها. وحُشر له جنوده من الجن والإنس والطير فهم يُوزعون، أي يُمنعون من التفرق حتى يجتمعوا. وسخّر الله له الريح، غدوّها شهر ورواحها شهر، وأسال له عين القطر أي النحاس، وسخّر له من الجن من يعمل بين يديه بإذن ربه. وقد دعا ربه بقوله: ﴿رَبِّ اغْفِرْ لِي وَهَبْ لِي مُلْكًا لَّا يَنبَغِي لِأَحَدٍ مِّن بَعْدِي﴾، فاستجاب الله له. ورغم هذا الملك العظيم لم يتكبّر، بل كان شاكرًا متواضعًا لله، وكان إذا رأى فضل ربه قال: هذا من فضل ربي ليبلوني أأشكر أم أكفر. فكان مثالًا لحاكم اجتمع له الملك والشكر والعلم والحكمة."], ["وادي النمل", "بينما كان سليمان عليه السلام يسير في جنده، حتى إذا أتوا على وادي النمل، قالت نملة: ﴿يَا أَيُّهَا النَّمْلُ ادْخُلُوا مَسَاكِنَكُمْ لَا يَحْطِمَنَّكُمْ سُلَيْمَانُ وَجُنُودُهُ وَهُمْ لَا يَشْعُرُونَ﴾. فسمع سليمان عليه السلام قولها، وفهمه بما علّمه الله، فتبسّم ضاحكًا من قولها. ولم يحدد القرآن موضع هذا الوادي، وما قيل إنه بالشام أو بالطائف أو غير ذلك فلا دليل عليه. ثم لم يلهِه ملكه عن شكر ربه، فقال: ﴿رَبِّ أَوْزِعْنِي أَنْ أَشْكُرَ نِعْمَتَكَ الَّتِي أَنْعَمْتَ عَلَيَّ وَعَلَىٰ وَالِدَيَّ وَأَنْ أَعْمَلَ صَالِحًا تَرْضَاهُ وَأَدْخِلْنِي بِرَحْمَتِكَ فِي عِبَادِكَ الصَّالِحِينَ﴾. ولم يذكر القرآن اسم النملة، وقيل غير ذلك مما لا يثبت. ونلحظ في ذلك دقة النظام عند هذا المخلوق الصغير، وحرص النملة على قومها، وأدب النبي الكريم الذي لم يستكبر ولم يحتقر هذا المخلوق، بل شكر الله وطلب العون على الشكر."], ["غياب الهدهد", "تفقّد سليمان عليه السلام الطير، فقال: ما لي لا أرى الهدهد أم كان من الغائبين؟ لأعذبنّه عذابًا شديدًا أو لأذبحنّه أو ليأتيني بسلطان مبين. وفي هذا ما يدل على حزمه ومتابعته لأمور مملكته ودقته في سياسة جنده. ولم يحدد القرآن نوع العذاب الذي هدّد به، ولكنه اشترط أن يأتيه بعذر واضح. فمكث الهدهد غير بعيد، فجاء فقال: أحطتُ بما لم تحط به وجئتك من سبأ بنبأ يقين. إني وجدت امرأة تملكهم وأوتيت من كل شيء ولها عرش عظيم، وجدتها وقومها يسجدون للشمس من دون الله وزيّن لهم الشيطان أعمالهم فصدّهم عن السبيل فهم لا يهتدون. ألّا يسجدوا لله الذي يخرج الخبء في السماوات والأرض ويعلم ما تخفون وما تعلنون، الله لا إله إلا هو رب العرش العظيم. فكان همّ الهدهد التوحيد، وغضب لحق الله. وهذا درس أن للمخلوق الصغير أثرًا كبيرًا إذا صدقت نيته."], ["كتاب سليمان", "لم يتعجل سليمان عليه السلام في تصديق الخبر، بل قال: سننظر أصدقتَ أم كنت من الكاذبين. وكتب كتابًا وأعطاه الهدهد: اذهب بكتابي هذا فألقه إليهم ثم تولَّ عنهم فانظر ماذا يرجعون. فألقاه إلى ملكة سبأ، فجمعت الملأ وقالت: يا أيها الملأ إني أُلقي إليّ كتاب كريم، إنه من سليمان وإنه بسم الله الرحمن الرحيم، ألّا تعلوا عليّ وأتوني مسلمين. ثم استشارت قومها: ما كنت قاطعة أمرًا حتى تشهدون. فقالوا: نحن أولو قوة وأولو بأس شديد والأمر إليك فانظري ماذا تأمرين. قالت: إن الملوك إذا دخلوا قرية أفسدوها وجعلوا أعزّة أهلها أذلة وكذلك يفعلون، وإني مرسلة إليهم بهدية فناظرة بم يرجع المرسلون. وفي ذلك دلالة على فطنتها وحكمتها وتأنّيها، ولم يسمّها القرآن بلقيس، بل قال: امرأة تملكهم، وتسميتها بلقيس مشهورة في كتب التفسير ولم ترد في القرآن."], ["الهدية والعرش", "جاء رسل الملكة إلى سليمان عليه السلام بالهدية، فقال: ﴿أَتُمِدُّونَنِ بِمَالٍ فَمَا آتَانِيَ اللَّهُ خَيْرٌ مِّمَّا آتَاكُم بَلْ أَنتُم بِهَدِيَّتِكُمْ تَفْرَحُونَ﴾. ثم قال لرسولها: ارجع إليهم فلنأتينّهم بجنود لا قبل لهم بها ولنخرجنّهم منها أذلة وهم صاغرون. فعلمت أن سليمان ليس طالب مال، بل صاحب دعوة. ثم قال لحاشيته: أيّكم يأتيني بعرشها قبل أن يأتوني مسلمين؟ قال عفريت من الجن: أنا آتيك به قبل أن تقوم من مقامك وإني عليه لقوي أمين. قال الذي عنده علم من الكتاب: أنا آتيك به قبل أن يرتد إليك طرفك. فلما رآه مستقرًّا عنده قال: ﴿هَٰذَا مِن فَضْلِ رَبِّي لِيَبْلُوَنِي أَأَشْكُرُ أَمْ أَكْفُرُ﴾. ولم يحدد القرآن اسم الذي عنده علم من الكتاب، وقيل إنه آصف بن برخيا، وقيل غير ذلك، ولا يثبت فيه حديث صحيح. فنسب النجاح إلى فضل الله، ولم يأخذه الغرور."], ["إسلام الملكة", "أمر سليمان عليه السلام أن يُغيَّر عرشها ليختبر فطنتها: نكّروا لها عرشها ننظر أتهتدي أم تكون من الذين لا يهتدون. فلما جاءت قيل لها: أهكذا عرشك؟ قالت: كأنه هو. فلم تنكر ولم تؤكد، وهذا من ذكائها. وقال سليمان: وأوتينا العلم من قبلها وكنا مسلمين. وصدّها ما كانت تعبد من دون الله، إنها كانت من قوم كافرين. ثم قيل لها: ادخلي الصرح، فلما رأته حسبته لجّة وكشفت عن ساقيها، قال: إنه صرح ممرّد من قوارير. وعندها ظهر لها عظم ما أوتي سليمان من آيات الله وأن ملكه من عند الله، فقالت: ﴿رَبِّ إِنِّي ظَلَمْتُ نَفْسِي وَأَسْلَمْتُ مَعَ سُلَيْمَانَ لِلَّهِ رَبِّ الْعَالَمِينَ﴾. ولم يذكر القرآن ما فعلته بعد إسلامها، وما يُروى أنه تزوجها فمن الأخبار التي لا يصح فيها شيء عن النبي صلى الله عليه وسلم. ثم جاء النص على أن الإيمان بالله يكون بالعلم والرؤية والتفكر، لا بالقوة والإكراه."], ["درس المشيئة ووفاة سليمان", "ثبت في صحيح البخاري عن أبي هريرة رضي الله عنه عن النبي صلى الله عليه وسلم أن سليمان عليه السلام قال: لأطوفنّ الليلة على مائة امرأة، تلد كل واحدة غلامًا يقاتل في سبيل الله، فقال له الملك: قل إن شاء الله، فلم يقل، فلم تحمل منهن إلا امرأة جاءت بشق رجل. فقال النبي صلى الله عليه وسلم: «لو قال إن شاء الله لم يحنث وكان دركًا لحاجته». وهذا درس أن العبد يقول إن شاء الله ويوكل الأمر إلى الله. أما وفاته فقد قال الله: ﴿فَلَمَّا قَضَيْنَا عَلَيْهِ الْمَوْتَ مَا دَلَّهُمْ عَلَىٰ مَوْتِهِ إِلَّا دَابَّةُ الْأَرْضِ تَأْكُلُ مِنسَأَتَهُ﴾. والمنسأة هي العصا، وكان متكئًا عليها، فلما سقط تبيّنت الجن أن لو كانوا يعلمون الغيب ما لبثوا في العذاب المهين. وفي هذا بيان أن الجن لا يعلمون الغيب. وهكذا ختمت حياة نبي أوتي ملكًا عظيمًا فمات كما يموت البشر، والملك لله وحده."]], "lesson": ["الشكر على النعمة سبيل دوام الملك والفضل، فالنعمة تزيد بالشكر.", "التثبت من الأخبار قبل الحكم عليها، كما قال سليمان للهدهد: سننظر أصدقت.", "لا تحتقر صغيرًا، فقد ينفع الله بمخلوق ضعيف وبكلمة صادقة.", "قل: إن شاء الله، فالأمر كله لله والتوفيق منه."], "cat": "story"}, {"id": "sr12", "title": "عام الحزن", "type": "من السيرة النبوية", "verse": "مَا وَدَّعَكَ رَبُّكَ وَمَا قَلَىٰ", "source": "سورة الضحى 93:3", "parts": [["بعد الحصار", "خرج النبي ﷺ ومن معه من الشِّعب بعد سنوات من الجوع والعزلة، فلم تكد تهدأ نفوسهم حتى جاءت أحزان جديدة. ففي العام العاشر من البعثة، أي قبل الهجرة بنحو ثلاث سنين على المشهور، توفي عمّه أبو طالب، ثم توفيت زوجته خديجة رضي الله عنها بعده بوقت قصير، وتختلف الروايات في المدة بينهما فقيل ثلاثة أيام وقيل أكثر من ذلك. وبهذا فقد النبي ﷺ سندين عظيمين في وقت واحد: سندًا من الخارج يحميه بين قومه بمكانته، وسندًا من الداخل يسكن إليه ويثبّته. وقد سمّى أهل السير هذه السنة عام الحزن، وهذه التسمية من عبارات السير وليست حديثًا مرفوعًا، لكنها تصف بدقة وقع الفقد على قلب النبي ﷺ وأصحابه."], ["وفاة أبي طالب", "كان أبو طالب أعظم الناس حمايةً للنبي ﷺ منذ صغره، دافع عنه ولم يسلّمه لقريش، لكنه ظل على دين قومه. وفي الصحيحين من حديث سعيد بن المسيب عن أبيه أنه لما حضرت أبا طالب الوفاة جاءه النبي ﷺ وعنده أبو جهل وعبد الله بن أبي أمية، فقال النبي ﷺ: «أي عمّ، قل: لا إله إلا الله، كلمةً أحاجّ لك بها عند الله». فقال له الرجلان: أترغب عن ملة عبد المطلب؟ فلم يزالا يكلمانه حتى كان آخر ما قال إنه على ملة عبد المطلب. فقال النبي ﷺ: «لأستغفرنّ لك ما لم أُنْهَ عنك»، فنزل قوله تعالى: ﴿مَا كَانَ لِلنَّبِيِّ وَالَّذِينَ آمَنُوا أَن يَسْتَغْفِرُوا لِلْمُشْرِكِينَ﴾، ونزل في أبي طالب قوله: ﴿إِنَّكَ لَا تَهْدِي مَنْ أَحْبَبْتَ وَلَكِنَّ اللَّهَ يَهْدِي مَن يَشَاءُ﴾."], ["أثر موقف أبي طالب", "وفي الصحيحين أيضًا أن العباس رضي الله عنه سأل النبي ﷺ: هل نفعتَ أبا طالب بشيء فإنه كان يحوطك ويغضب لك؟ فقال: «نعم، هو في ضحضاح من النار، ولولا أنا لكان في الدرك الأسفل من النار». وفي رواية أخرى أنه قال: «لعله تنفعه شفاعتي يوم القيامة، فيُجعل في ضحضاح من النار يبلغ كعبيه يغلي منه دماغه». وفي هذا بيان أن نصرة أبي طالب كانت نصرة قرابة وحميّة لا نصرة إيمان، وأن الهداية بيد الله، وأن هذا لا يمنع أن يُكافأ المحسن على إحسانه بما يشاء الله. أما أثر موته في الدعوة فقد كان كبيرًا، إذ زالت الحماية التي كانت تردع سفهاء قريش، فتجرّؤوا على النبي ﷺ بما لم يتجرؤوا عليه في حياته."], ["وفاة خديجة رضي الله عنها", "كانت خديجة رضي الله عنها أول من آمن به وصدّقه، ولما نزل عليه الوحي أول مرة ورجع يرتجف، قالت له: «كلا، والله ما يخزيك الله أبدًا، إنك لتصل الرحم، وتحمل الكَلَّ، وتكسب المعدوم، وتقري الضيف، وتعين على نوائب الحق»، كما في الصحيحين. وبذلت مالها في سبيل الدعوة، وصبرت معه في الشِّعب، وولدت له أولاده جميعًا عدا إبراهيم رضي الله عنه. وروى البخاري عن أبي هريرة رضي الله عنه أن جبريل عليه السلام قال للنبي ﷺ: «هذه خديجة قد أتتك بإناء فيه إدام أو طعام أو شراب، فإذا أتتك فاقرأ عليها السلام من ربها ومني، وبشّرها ببيت في الجنة من قصب لا صخب فيه ولا نصب». فهي أم المؤمنين الأولى وسيدة نساء زمانها في الوفاء."], ["وفاء النبي ﷺ لها", "ظل النبي ﷺ يذكر خديجة رضي الله عنها بعد موتها بأحسن الذكر. قالت عائشة رضي الله عنها: ما غِرتُ على أحد من نساء النبي ﷺ ما غرتُ على خديجة، وما رأيتها، ولكن كان النبي ﷺ يكثر ذكرها، وربما ذبح الشاة ثم يقطّعها أعضاءً ثم يبعثها في صدائق خديجة، رواه البخاري. وفي الصحيحين أنه كان إذا قيل له في ذلك قال: «إنها كانت وكانت، وكان لي منها ولد»، وفي رواية أخرى أنه قال: «إني قد رُزقتُ حبّها». وهذا الوفاء يعلّم أن الحبّ الصادق لا ينتهي بالموت، وأن الفضل يُحفظ لأهله حتى بعد رحيلهم، وأن بيت النبوة لم يكن بيتًا بلا مشاعر، بل كان بيتًا يعرف قدر الصبر والتضحية ويكرم أهلهما."], ["اشتداد الأذى", "بعد موت أبي طالب اشتد أذى قريش، وتروي كتب السيرة عن ابن إسحاق أن النبي ﷺ قال: «ما نالت قريش مني شيئًا أكرهه حتى مات أبو طالب». وتذكر كتب السيرة أن بعض سفهاء قريش ألقى على رأسه ترابًا، فدخل بيته والتراب على رأسه، فقامت إحدى بناته تغسله وهي تبكي، وهو يقول لها: «لا تبكي يا بنية، فإن الله مانع أباك». وهذه الرواية في كتب السير وليست في الصحيح، لكن معناها يتفق مع ثبات النبي ﷺ ويقينه بنصر الله. ولم يكن أمامه إلا أن يبحث عن مكان جديد للدعوة خارج مكة، فاتجه إلى الطائف، ثم إلى القبائل في مواسم الحج، حتى فتح الله له باب الأنصار في المدينة."], ["التسلية والثبات", "لم يترك الله نبيه في حزنه، فكانت السور المكية تثبّته وتبشّره، وفيها قوله تعالى في سورة الضحى: ﴿مَا وَدَّعَكَ رَبُّكَ وَمَا قَلَىٰ﴾، تطمينًا له أن الله لم يتركه ولم يبغضه. وتذكر كتب السيرة أنه تزوّج بعد خديجة رضي الله عنها سودة بنت زمعة رضي الله عنها، فكانت تدبّر بيته وتربّي بناته، وخطب عائشة رضي الله عنها وهما بمكة، وعقد نكاحهما قبل الهجرة، كما في صحيح البخاري، ودخل بها في المدينة. وبهذا امتلأ بيته من جديد بمن يعينه على مواصلة الطريق. وهكذا مرّ عام الحزن وفي ظاهره خسارة شديدة، لكنه كان تمهيدًا لمرحلة جديدة انتهت بالإسراء والمعراج ثم بالهجرة، وبذلك صدق قوله تعالى إن مع العسر يسرًا."]], "lesson": ["الهداية بيد الله وحده، فلا ينفع النسب والقرابة من غير إيمان، حتى لو كان القريب نبيًّا.", "الوفاء للمحسنين وذكرهم بالخير بعد موتهم من أخلاق النبوة.", "الشدائد الكبرى قد تكون مقدمة لتمكين الله ونصره، فبعد عام الحزن جاء الإسراء ثم الهجرة.", "المؤمن يجد في كتاب الله وذكره سلوانه وثباته إذا فقد من يأنس بهم."], "cat": "seerah"}, {"id": "s13", "title": "قصة صالح عليه السلام وناقة الله", "type": "قصة قرآنية", "verse": "قَالَ هَٰذِهِ نَاقَةٌ لَّهَا شِرْبٌ وَلَكُمْ شِرْبُ يَوْمٍ مَّعْلُومٍ", "source": "سورة الشعراء 26:155", "parts": [["ثمود بعد عاد", "ثمود قوم جاؤوا بعد عاد، وقد ذكّرهم نبيهم صالح عليه السلام بهذه النعمة فقال لهم ما معناه: واذكروا إذ جعلكم خلفاء من بعد عاد وبوّأكم في الأرض. وكانوا يسكنون الحِجر، وهي ديارهم بين الحجاز والشام، وقد أعطاهم الله قوة ونعمة، فكانوا يتخذون من سهول الأرض قصورًا وينحتون من الجبال بيوتًا. ولم يحدد القرآن تاريخهم بالسنين ولا عدد أفرادهم. وكان الشرك قد فشا فيهم، فعبدوا من دون الله آلهة لا تنفع ولا تضر، وأفسدوا في الأرض. فأرسل الله إليهم أخاهم صالحًا عليه السلام، وهو منهم نسبًا، يعرفون صدقه وأمانته وخلقه. فقال لهم ما قاله الرسل قبله: ﴿يَا قَوْمِ اعْبُدُوا اللَّهَ مَا لَكُم مِّنْ إِلَٰهٍ غَيْرُهُ﴾. وبيّن لهم أن الله هو الذي أنشأهم من الأرض واستعمرهم فيها، فعليهم أن يستغفروه ثم يتوبوا إليه، فإن ربه قريب مجيب. وبهذا بدأت دعوته: رسول من قومه يدعوهم إلى ربٍّ أنعم عليهم بكل ما يتمتعون به."], ["التذكير بالنعم والتحذير من الفساد", "لم يكتفِ صالح عليه السلام بالأمر بالتوحيد، بل ذكّر قومه بنعم الله عليهم وخوّفهم من زوالها. فقال لهم ما معناه: أتُتركون فيما هاهنا آمنين، في جنات وعيون، وزروع ونخل طلعها هضيم؟ وتنحتون من الجبال بيوتًا فارهين؟ أي أتظنون أن هذه النعم باقية لكم أبدًا وأنتم على الشرك والظلم؟ ثم أمرهم أن يتقوا الله ويطيعوه، ونهاهم عن طاعة المسرفين الذين يفسدون في الأرض ولا يصلحون. وأعلن لهم أنه لا يطلب منهم على دعوته مالًا ولا جاهًا، فقال: ﴿وَمَا أَسْأَلُكُمْ عَلَيْهِ مِنْ أَجْرٍ إِنْ أَجْرِيَ إِلَّا عَلَىٰ رَبِّ الْعَالَمِينَ﴾. وهذه سنة الأنبياء جميعًا، يبلّغون الحق خالصًا لوجه الله، لا يطمعون في دنيا الناس. وكان في كلامه رفق ومحبة، فهو يناديهم: يا قوم، ويحرص على نجاتهم كما يحرص الأخ على إخوته، غير أن القلوب التي أغلقها الكبر لم تلن لموعظته ولا لحجته."], ["إنكار الملأ وانقسام القوم", "قابل القوم دعوة صالح عليه السلام بالتكذيب والاستخفاف. فقالوا له: قد كنت فينا مرجوًّا قبل هذا، أي كنا نؤمل فيك الخير والعقل قبل أن تدعونا إلى ترك ما كان يعبد آباؤنا، وإننا لفي شك مما تدعونا إليه مريب. وقالوا أيضًا: إنما أنت من المسحَّرين، أي ممن سُحروا فاختل عقلهم، وما أنت إلا بشر مثلنا فأتِ بآية إن كنت من الصادقين. فأجابهم بأنه على بيّنة من ربه، وأن الله آتاه منه رحمة، وسألهم: فمن ينصرني من الله إن عصيته؟ وانقسم قومه فريقين يختصمون: فريق آمن واستضعفه الكبراء، وفريق استكبر. وقد حكى القرآن حوارًا بينهم، حين قال الملأ المستكبرون للمستضعفين الذين آمنوا: أتعلمون أن صالحًا مرسل من ربه؟ قالوا: إنا بما أرسل به مؤمنون. قال الذين استكبروا: إنا بالذي آمنتم به كافرون. فتبيّن أن الإيمان يوزن بالقلوب لا بالمنازل، وأن أتباع الحق في كل زمان كثيرًا ما يكونون من الضعفاء."], ["الناقة آية من الله", "طلب القوم آية يصدّقون بها، فأعطاهم الله ناقة جعلها آية مبصرة، وأضافها إليه تشريفًا فقال: ﴿نَاقَةُ اللَّهِ﴾. وقال لهم صالح عليه السلام: هذه ناقة الله لكم آية، فذروها تأكل في أرض الله ولا تمسّوها بسوء فيأخذكم عذاب أليم. وبيّن لهم أن لها شِرب ماء يومًا ولهم شِرب يوم معلوم، فنظّم لهم قسمة الماء بينهم وبينها. ولم يحدد القرآن كيف ظهرت الناقة، ويُروى أنها خرجت من صخرة بعد أن سألوه ذلك، وهذا مما ذكره بعض المفسرين ولا يثبت بنص صحيح، فنكتفي بأنها آية من الله. وتذكّرهم القرآن بأنها فتنة لهم: إنا مرسلو الناقة فتنةً لهم، فارتقبهم واصطبر. وقد جعل الله هذه المعجزة اختبارًا لهم، فمن احترم آية ربه نجا، ومن اعتدى عليها عرّض نفسه للهلاك. وكانوا يرون الآية كل يوم، ومع ذلك لم يرجعوا عن عنادهم، فبقي الحق أمام أعينهم ولم تسلم له قلوبهم."], ["عقر الناقة", "ضاق الكبراء بالناقة وبالمقاسمة في الماء، وبالدعوة التي تهدد جاههم، فأقدموا على الجريمة. قال الله تعالى: ﴿فَكَذَّبُوهُ فَعَقَرُوهَا﴾. وفي سورة القمر أنهم نادوا صاحبهم فتعاطى فعقر، أي تناول السيف فقتلها. وفي سورة الشمس: إذ انبعث أشقاها. وروى البخاري ومسلم عن عبد الله بن زمعة رضي الله عنه أن النبي صلى الله عليه وسلم ذكر الذي عقر الناقة فقال: انتدب لها رجل ذو عزّ ومنعة في قومه. ونُسب الفعل إلى القوم جميعًا لأنهم رضوا به وأقرّوه. ولم يحدد القرآن اسم الفاعل، وما يُروى من أسماء وتفاصيل فمن أخبار المفسرين. وحين وقعت الجريمة قالوا مستهزئين: يا صالح ائتنا بما تعدنا إن كنت من المرسلين. فقال لهم صالح عليه السلام: تمتعوا في داركم ثلاثة أيام، ذلك وعد غير مكذوب. وهكذا أمهلهم الله مدة قصيرة لعلهم يتوبون، لكنهم لم يعودوا إلى ربهم."], ["مؤامرة التسعة والهلاك", "وفي سورة النمل أن في المدينة تسعة رهط يفسدون في الأرض ولا يصلحون. وقد تقاسموا بالله لنبيّتنّه وأهله، أي لنباغتنّه ليلًا ثم لنقولنّ لوليّه: ما شهدنا مهلك أهله وإنا لصادقون. قال الله: ومكروا مكرًا ومكرنا مكرًا وهم لا يشعرون. فانظر كيف كان عاقبة مكرهم أنّا دمّرناهم وقومهم أجمعين. ثم جاء الموعد، فأخذتهم الرجفة، وأخذتهم الصيحة، فأصبحوا في دارهم جاثمين، كأن لم يغنوا فيها. وأخبر القرآن أن الله نجّى صالحًا والذين آمنوا معه برحمة منه ومن خزي ذلك اليوم. وأما صالح عليه السلام فتولّى عنهم وقال: يا قوم لقد أبلغتكم رسالة ربي ونصحت لكم ولكن لا تحبون الناصحين. ولم يحدد القرآن عدد من نجا مع صالح. والقصة تدل على أن الله يمهل ولا يهمل، وأن كثرة القوة وحصانة البيوت المنحوتة في الجبال لا ترد أمر الله إذا جاء."], ["الحِجر عبرة للمارّين", "بقيت ديار ثمود شاهدة على ما حلّ بهم، وقد مرّ بها النبي صلى الله عليه وسلم وهو في طريقه إلى تبوك. وروى البخاري عن ابن عمر رضي الله عنهما أن النبي صلى الله عليه وسلم لما مرّ بالحِجر قال: «لا تدخلوا مساكن الذين ظلموا أنفسهم إلا أن تكونوا باكين، حذرًا أن يصيبكم مثل ما أصابهم». ثم قنّع رأسه وأسرع السير حتى جاوز الوادي. وفي هذا تعليم للأمة أن تمرّ بآثار المعذَّبين مرور الخائف المعتبر لا مرور السائح اللاهي. ثم إن القرآن ذكر قصة صالح في مواضع متعددة ليبقى الاعتبار حاضرًا في القلوب: في الأعراف وهود والشعراء والنمل والقمر والشمس وغيرها. ومنه نعلم أن النعمة قد تكون ابتلاءً، وأن احترام شعائر الله وحرماته علامة الإيمان، وأن العاقبة للمتقين وإن طال الإمهال. فمن أصلح علاقته بربه نجا في الدنيا والآخرة، ومن عاند وكابر لم تنفعه قصوره ولا جباله."]], "lesson": ["النعمة تحتاج إلى شكر وطاعة، وإلا زالت بالكفر والظلم.", "الحق لا يُعرف بقوة أصحابه ولا بكثرتهم، فقد آمن مع صالح الضعفاء وكفر الكبراء.", "الاعتداء على حرمات الله وآياته جريمة عظيمة، ورضا القوم بالجريمة مشاركة فيها.", "نمرّ بآثار الظالمين مرور المعتبر الخائف ونسأل الله العافية."], "cat": "story"}, {"id": "sr13", "title": "رحلة الطائف", "type": "من السيرة النبوية", "verse": "فَاصْبِرْ كَمَا صَبَرَ أُولُو الْعَزْمِ مِنَ الرُّسُلِ", "source": "سورة الأحقاف 46:35", "parts": [["لماذا الطائف؟", "بعد أن مات أبو طالب وخديجة رضي الله عنها، واشتد أذى قريش، فكّر النبي ﷺ في البحث عن نصير من خارج مكة، فاتجه إلى الطائف، وهي بلدة ذات بساتين في الجبال تسكنها قبيلة ثقيف، وكانت لهم صلة قرابة بقريش وصلات تجارية. وكان ذلك على المشهور في شوال من السنة العاشرة للبعثة، وتذكر كتب السيرة أنه خرج ماشيًا على قدميه ومعه مولاه زيد بن حارثة رضي الله عنه. ولم يكن يطلب بذلك قتالًا ولا مُلكًا، بل رجا أن يؤمن به أهل الطائف أو أن يمنعوه حتى يبلّغ رسالة ربه. وكان ذلك أول خروج له من مكة لأجل الدعوة بعد أن ضاقت عليه، وهو يعلم أن الطريق شاق وأن العاقبة بيد الله."], ["لقاء سادة ثقيف", "ذكر ابن إسحاق أن النبي ﷺ عمد إلى ثلاثة إخوة من سادة ثقيف، فجلس إليهم، ودعاهم إلى الله وإلى نصرته على من خالفه من قومه، فردّوا عليه ردًّا قبيحًا، وتهكموا عليه، ولم يقبلوا منه شيئًا. فلما يئس من خيرهم قام عنهم وقد طلب منهم أن يكتموا عنه خبر مجيئه حتى لا تشمت به قريش، فلم يفعلوا. وبهذا نرى أن النبي ﷺ حاول أن يخفي أمره ليخفف على نفسه، فلم يجد من القوم حتى هذا. وكانت خيبة النبي ﷺ كبيرة، فقد خرج ينتظر نصرة فعاد ببلاء. غير أنه لم يُصرّح بحقد عليهم ولا دعا عليهم بالهلاك، بل ظل يتمنى لهم الهداية، كما ستبيّن الرواية الصحيحة بعد قليل."], ["الإيذاء ورمي الحجارة", "تذكر كتب السيرة أن أهل الطائف لما أيسوا من إسكاته أغروا به سفهاءهم وعبيدهم، فتجمعوا يسبّونه ويصيحون به، وألجؤوه إلى حائط، أي بستان، ورموه بالحجارة، وزيد بن حارثة رضي الله عنه يقيه بنفسه حتى شُجّ رأسه. وهذا المعنى مأخوذ من ابن إسحاق وغيره ولم يرد في الصحيحين بهذا التفصيل. أما الصحيح فهو قول النبي ﷺ لعائشة رضي الله عنها فيما سيأتي، إذ عدّ ما لقيه يوم العقبة، يعني الطائف، أشد ما لقي من قومه. وهكذا كان الجزاء على الدعوة الصادقة شتمًا ورجمًا من أهل بلد لم يعرف منه إلا الخير، ومع ذلك لم ينتقم لنفسه ولم يلعنهم، بل فوّض أمره إلى الله."], ["قرن الثعالب وملك الجبال", "في الصحيحين عن عائشة رضي الله عنها أنها قالت للنبي ﷺ: هل أتى عليك يوم كان أشد من يوم أحد؟ قال: «لقد لقيتُ من قومك ما لقيت، وكان أشد ما لقيت منهم يوم العقبة، إذ عرضتُ نفسي على ابن عبد ياليل بن عبد كلال فلم يجبني إلى ما أردت، فانطلقتُ وأنا مهموم على وجهي، فلم أستفق إلا وأنا بقرن الثعالب، فرفعتُ رأسي فإذا أنا بسحابة قد أظلّتني، فنظرتُ فإذا فيها جبريل فناداني فقال: إن الله قد سمع قول قومك لك وما ردّوا عليك، وقد بعث إليك ملك الجبال لتأمره بما شئت فيهم». وقرن الثعالب مكان قريب من مكة يسمى اليوم قرن المنازل، وفيه ميقات أهل نجد."], ["جواب النبي ﷺ ورحمته", "ثم قال النبي ﷺ في الحديث نفسه: «فناداني ملك الجبال فسلّم عليّ، ثم قال: يا محمد، إن الله قد سمع قول قومك لك، وأنا ملك الجبال، وقد بعثني ربك إليك لتأمرني بأمرك، فما شئت؟ إن شئتَ أطبقتُ عليهم الأخشبين». والأخشبان جبلا مكة. «فقال النبي ﷺ: بل أرجو أن يخرج الله من أصلابهم من يعبد الله وحده لا يشرك به شيئًا». فهذه رحمة النبي ﷺ بمن آذاه وهو قادر على الانتقام بأمر الله، اختار أن يصبر وأن يرجو لهم الخير. وقد صدق رجاؤه، فأسلم من ثقيف بعد ذلك خلق كثير، وعاد وفدهم بعد سنين وهم مسلمون، وفيهم من رزقه الله النصر والفضل في الإسلام."], ["عَدّاس وجنّ نخلة", "وتذكر كتب السيرة أن النبي ﷺ استراح في بستان لابني ربيعة، فأرسلا إليه غلامهما عدّاسًا بقطف عنب، وهو نصراني من أهل نينوى، فلما أكل النبي ﷺ قال: «بسم الله»، فتعجب عدّاس من ذلك وسأله عن دينه، وتذكر الرواية أنه أقبل يقبّل يديه ورجليه، وهو خبر في السير لم يثبت في الصحيح. ثم عاد النبي ﷺ إلى مكة، ونزل في نخلة على المشهور، وقام يصلّي الفجر فاستمع إليه نفر من الجن، كما روى البخاري عن ابن عباس رضي الله عنهما أن النبي ﷺ كان في طائفة من أصحابه عامدين إلى سوق عكاظ فاستمع إليه الجن وهو يقرأ في صلاة الفجر، فنزل قوله تعالى: ﴿قُلْ أُوحِيَ إِلَيَّ أَنَّهُ اسْتَمَعَ نَفَرٌ مِّنَ الْجِنِّ﴾. وقيل إن هذا كان في عودته من الطائف وقيل في وقت آخر."], ["الدخول في جوار المطعم", "وصل النبي ﷺ إلى مكة وهو لا يأمن على نفسه من قريش بعد أن فقد حماية أبي طالب، فأرسل إلى رجال من قريش يطلب جوارهم، فرفضوا حتى أجاره المطعم بن عدي، فدخل في حمايته، وأمر ابنه وأهله فتسلحوا وحرسوا الكعبة حتى طاف النبي ﷺ وصلى، كما تذكر كتب السير. وقد حفظ النبي ﷺ له هذا الجميل، فقال يوم بدر، كما في صحيح البخاري عن جبير بن مطعم رضي الله عنه: «لو كان المطعم بن عدي حيًّا، ثم كلّمني في هؤلاء النَّتنى لتركتُهم له». وهكذا رجع النبي ﷺ من الطائف مكسور الخاطر في الظاهر، لكنه عاد بيقين أكبر، وبعد قليل أكرمه الله بالإسراء والمعراج."]], "lesson": ["الرحمة بالمخالفين والصبر على أذاهم، فقد اختار النبي ﷺ رجاء هدايتهم على الانتقام منهم.", "يتحمل الداعية بنفسه ثمن الدعوة، ولا ينتظر نصرًا عاجلًا ولا يحكم بالفشل على الطريق.", "إكرام من أحسن إلينا ولو كان على غير ديننا، فقد حفظ النبي ﷺ جميل المطعم بن عدي.", "الله يفتح بعد الضيق باب الفرج، وكثيرًا ما تكون أشد اللحظات قبل أعظم الكرامات."], "cat": "seerah"}, {"id": "s14", "title": "قصة هود عليه السلام وقوم عاد", "type": "قصة قرآنية", "verse": "وَأَمَّا عَادٌ فَأُهْلِكُوا بِرِيحٍ صَرْصَرٍ عَاتِيَةٍ", "source": "سورة الحاقة 69:6", "parts": [["قوم عاد وقوتهم", "عاد قوم جعلهم الله خلفاء من بعد قوم نوح عليه السلام، وزادهم في الخلق بسطة، أي قوة في أجسامهم وبنيانهم. وقد ذكر القرآن مكانهم بقوله: إذ أنذر قومه بالأحقاف، والأحقاف جمع حِقف، وهي الرمال المرتفعة، وقيل إنها في جنوب الجزيرة العربية. وأعطاهم الله أنعامًا وبنين وجنات وعيون. وكانوا أصحاب عمران وحضارة، فقال لهم نبيهم ما معناه: أتبنون بكل ريع آية تعبثون؟ وتتخذون مصانع لعلكم تخلدون؟ وذكر القرآن أنهم أصحاب إرم ذات العماد، التي لم يُخلق مثلها في البلاد. ولم يحدد القرآن موضع إرم بدقة، وما يُروى عن مدينة مخبأة من ذهب وفضة فمن أخبار القصاصين التي لا تثبت. والمقصود من ذكر قوتهم أن الله حذّر مما آل إليه أمرهم، فما أغنت عنهم القوة ولا العمران حين كفروا بنعمة ربهم وجحدوا آياته وعصوا رسله."], ["دعوة هود عليه السلام", "أرسل الله إلى عاد أخاهم هودًا عليه السلام، فقال لهم: ﴿يَا قَوْمِ اعْبُدُوا اللَّهَ مَا لَكُم مِّنْ إِلَٰهٍ غَيْرُهُ﴾. وكان من قومه نسبًا ولسانًا، فعرفوا خلقه وصدقه. ودعاهم إلى تقوى الله، وبيّن لهم أنه لا يطلب أجرًا على دعوته، إن أجره إلا على الذي فطره. ثم رغّبهم في الاستغفار والتوبة، فقال لهم ما معناه: استغفروا ربكم ثم توبوا إليه يرسل السماء عليكم مدرارًا ويزدكم قوة إلى قوتكم ولا تتولّوا مجرمين. فربط بين الإيمان والاستغفار وبين الرزق والقوة، وبيّن أن طاعة الله لا تنقص من دنياهم شيئًا بل تزيدها. وذكّرهم بأن الله استخلفهم بعد قوم نوح ورأوا ما حلّ بمن قبلهم. وكان خطابه لينًا ناصحًا، فهو يقول لهم: يا قوم، ويدعوهم بأحب الألفاظ إليهم. غير أن الغالبية من القوم لم يستجيبوا، وبقيت دعوته حجة عليهم أمام الله."], ["ردّ القوم وجواب هود", "ردّ الملأ الذين كفروا من قومه بالتكذيب والتجهيل، فقالوا: إنا لنراك في سفاهة وإنا لنظنك من الكاذبين. فأجابهم بخلق النبي الحليم: يا قوم ليس بي سفاهة ولكني رسول من ربّ العالمين، أبلّغكم رسالات ربي وأنا لكم ناصح أمين. وقالوا له: أجئتنا لنعبد الله وحده ونذر ما كان يعبد آباؤنا؟ فأتنا بما تعدنا إن كنت من الصادقين. وقالوا أيضًا: ما جئتنا ببيّنة وما نحن بتاركي آلهتنا عن قولك وما نحن لك بمؤمنين، إن نقول إلا اعتراك بعض آلهتنا بسوء. فرد عليهم هود عليه السلام بثقة المتوكل على الله: إني أشهد الله واشهدوا أني بريء مما تشركون من دونه، فكيدوني جميعًا ثم لا تنظرون، إني توكلت على الله ربي وربكم، ما من دابة إلا هو آخذ بناصيتها، إن ربي على صراط مستقيم. وفي هذا الموقف يظهر ثبات النبي وحده أمام قوم أقوياء لا يخاف تهديدهم، لأن قلبه معلّق بربه."], ["تذكير بالنعم واتباع الجبابرة", "وكرّر هود عليه السلام عليهم ذكر نعم الله، فقال ما معناه: واتقوا الذي أمدكم بما تعلمون، أمدكم بأنعام وبنين وجنات وعيون، إني أخاف عليكم عذاب يوم عظيم. فلم يزدهم ذلك إلا عنادًا، وقالوا: سواء علينا أوعظت أم لم تكن من الواعظين، إن هذا إلا خُلُق الأولين وما نحن بمعذَّبين. فأصروا على تقليد من سبقهم، وأعرضوا عن النظر في الدليل. وقد لخّص القرآن حالهم بقوله: ﴿وَتِلْكَ عَادٌ جَحَدُوا بِآيَاتِ رَبِّهِمْ وَعَصَوْا رُسُلَهُ وَاتَّبَعُوا أَمْرَ كُلِّ جَبَّارٍ عَنِيدٍ﴾. وفي ذلك أن أسباب هلاكهم ثلاثة: جحود الآيات، ومعصية الرسل، واتباع أمر كل جبار عنيد. وقال لهم هود إنه قد وقع عليهم من ربهم رجس وغضب، وسألهم: أتجادلونني في أسماء سميتموها أنتم وآباؤكم ما نزّل الله بها من سلطان؟ فانتظروا إني معكم من المنتظرين. ولم يحدد القرآن مدة دعوته فيهم."], ["العارض الذي ظنوه مطرًا", "جاء أمر الله، وبدأت علامة العذاب بما ظنوه رحمة، قال الله تعالى: ﴿فَلَمَّا رَأَوْهُ عَارِضًا مُّسْتَقْبِلَ أَوْدِيَتِهِمْ قَالُوا هَٰذَا عَارِضٌ مُّمْطِرُنَا﴾. والعارض هو السحاب الذي يعترض في الأفق. فاستبشروا بالمطر بعد جفاف، فجاءهم الرد: بل هو ما استعجلتم به، ريح فيها عذاب أليم، تدمّر كل شيء بأمر ربها. وفي الصحيحين عن عائشة رضي الله عنها أن النبي صلى الله عليه وسلم كان إذا رأى مخيلة في السماء أقبل وأدبر ودخل وخرج وتغيّر وجهه، فإذا أمطرت سُرّي عنه. فسألته عن ذلك فقال: «ما أدري لعله كما قال قوم: فلما رأوه عارضًا مستقبل أوديتهم قالوا هذا عارض ممطرنا». وهذا يعلّمنا أن نخاف من مكر الله حتى حين نرى ما نحب، وأن نسأل الله خير ما في الغمام وخير ما يأتي به ونعوذ به من شره، وأن الأمور بعواقبها لا بمظاهرها."], ["الريح الصرصر ونجاة المؤمنين", "سلّط الله على عاد ريحًا صرصرًا عاتية، فسّرها المفسرون بأنها شديدة البرودة أو شديدة الصوت، وعاتية أي عتت على خزّانها فلم يضبطوها. قال الله: ﴿سَخَّرَهَا عَلَيْهِمْ سَبْعَ لَيَالٍ وَثَمَانِيَةَ أَيَّامٍ حُسُومًا فَتَرَى الْقَوْمَ فِيهَا صَرْعَىٰ كَأَنَّهُمْ أَعْجَازُ نَخْلٍ خَاوِيَةٍ﴾. فهدمت قوتهم، وصاروا كجذوع النخل المقتلعة، حتى أصبحوا لا يُرى إلا مساكنهم، كذلك نجزي القوم المجرمين. أما هود عليه السلام فقد نجّاه الله والذين آمنوا معه برحمة منه ونجّاهم من عذاب غليظ. ولم يحدد القرآن عدد من آمن معه. وختم الله القصة بقوله: ألا إن عادًا كفروا ربهم ألا بعدًا لعاد قوم هود. فمن اغتر بقوته أو بنائه أو ماله دون الله هلك، ومن لجأ إلى الله فهو في حفظه، فالقوة الحقيقية في الإيمان لا في الأجساد ولا في البناء، والعاقبة للمتقين وإن طال البلاء."]], "lesson": ["القوة والعمران لا يغنيان عن الإيمان، ومن اغتر بنعمة الله جاءه الهلاك من حيث لا يحتسب.", "الاستغفار والتوبة سبب لزيادة الرزق والقوة بإذن الله.", "التوكل على الله يُثبّت الداعي ولو كان وحده في مواجهة الجميع.", "تقليد الآباء وطاعة الجبابرة بغير دليل طريق إلى الهلاك، والواجب اتباع الحجة."], "cat": "story"}, {"id": "sr14", "title": "الإسراء والمعراج", "type": "من السيرة النبوية", "verse": "سُبْحَانَ الَّذِي أَسْرَىٰ بِعَبْدِهِ لَيْلًا مِّنَ الْمَسْجِدِ الْحَرَامِ إِلَى الْمَسْجِدِ الْأَقْصَى الَّذِي بَارَكْنَا حَوْلَهُ لِنُرِيَهُ مِنْ آيَاتِنَا إِنَّهُ هُوَ السَّمِيعُ الْبَصِيرُ", "source": "سورة الإسراء 17:1", "parts": [["زمن الحادثة وحكمتها", "جاءت رحلة الإسراء والمعراج بعد سنوات الشدة، وبعد وفاة أبي طالب وخديجة رضي الله عنها ورحلة الطائف، قبل الهجرة بمدة. وتختلف الروايات في وقتها اختلافًا كبيرًا، فقيل قبل الهجرة بسنة، وقيل بأكثر، وقيل غير ذلك، والمتفق عليه أنها كانت بمكة قبل الهجرة. وقد جعلها الله إكرامًا لنبيه ﷺ بعد ما لقي من الأذى، وتثبيتًا له، وإظهارًا لمكانته عند ربه، وتهيئةً له لمرحلة جديدة. والإسراء هو الرحلة من المكان الحرام إلى المسجد الأقصى، والمعراج هو الصعود إلى السماوات. وقد ذكر القرآن الإسراء في أول سورة الإسراء، وأشار إلى المعراج في سورة النجم. وعامة أهل السنة على أن ذلك كان بجسده وروحه ﷺ يقظةً لا مناما."], ["الإسراء إلى بيت المقدس", "روى البخاري ومسلم أن النبي ﷺ كان في مكة، فأتاه جبريل عليه السلام، وفي رواية أنه كان نائمًا في الحِجر قريبًا من البيت، فشقّ صدره، فاستخرج قلبه فغسله بماء زمزم، ثم جاء بطست من ذهب مملوء حكمة وإيمانًا فأفرغه في صدره. ثم أُتي بالبراق، وهو دابة بيضاء فوق الحمار ودون البغل، يضع حافره عند منتهى بصره. فركبه حتى أتى بيت المقدس، فربطه بالحلقة التي يربط بها الأنبياء، ثم دخل المسجد فصلّى فيه ركعتين، وفي حديث أبي هريرة رضي الله عنه عند مسلم أنه أَمّ الأنبياء في الصلاة، فكانت إمامته لهم دليلًا على أن رسالته خاتمة الرسالات وأنه سيد المرسلين."], ["اللبن والخمر والعروج", "وفي الصحيحين أن جبريل عليه السلام أتى النبي ﷺ بإناءين، أحدهما فيه لبن والآخر فيه خمر، فاختار النبي ﷺ اللبن، فقال له جبريل: «هُديتَ الفطرة، أما إنك لو أخذتَ الخمر غوتْ أمتك». ثم عرج به جبريل إلى السماء الدنيا، فاستفتح، فقيل: من هذا؟ قال: جبريل. قيل: ومن معك؟ قال: محمد. قيل: وقد أُرسل إليه؟ قال: نعم. ففُتح لهما. وفي كل سماء كان يلقى نبيًّا، فلقي في الأولى آدم عليه السلام، وفي الثانية يحيى وعيسى عليهما السلام، وفي الثالثة يوسف، وفي الرابعة إدريس، وفي الخامسة هارون، وفي السادسة موسى، وفي السابعة إبراهيم عليهم السلام، وهو مسند ظهره إلى البيت المعمور. وكلهم رحّبوا به ودعوا له بخير."], ["سدرة المنتهى", "ثم رُفع إلى سدرة المنتهى، فإذا نبقها مثل قلال هجر وورقها مثل آذان الفيلة، كما في حديث الصحيحين، وغشيها من أمر الله ما غشي حتى تغيّرت فما أحد من خلق الله يستطيع أن ينعتها من حسنها. وقد أشار القرآن إلى ذلك في سورة النجم بقوله: ﴿وَلَقَدْ رَآهُ نَزْلَةً أُخْرَىٰ * عِندَ سِدْرَةِ الْمُنتَهَىٰ * عِندَهَا جَنَّةُ الْمَأْوَىٰ﴾، وقال تعالى: ﴿لَقَدْ رَأَىٰ مِنْ آيَاتِ رَبِّهِ الْكُبْرَىٰ﴾. وقد اختلف الصحابة هل رأى النبي ﷺ ربه؟ فأنكرت عائشة رضي الله عنها ذلك، وقال ابن عباس رضي الله عنهما إنه رآه بفؤاده، وجاء في صحيح مسلم أنه ﷺ قال: «نورٌ أنّى أراه». وفي هذا المشهد أوحى الله إلى عبده ما أوحى."], ["فرض الصلاة", "وكان أعظم ما أُعطيه ﷺ في هذه الليلة الصلاة. ففي الصحيحين أن الله فرض عليه خمسين صلاة في اليوم والليلة، فنزل فمرّ بموسى عليه السلام، فسأله: بم أمرك ربك؟ فأخبره، فقال: ارجع إلى ربك فاسأله التخفيف، فإن أمتك لا تطيق ذلك، وإني قد بلوت بني إسرائيل وخبرتهم. فرجع النبي ﷺ فخفف الله عنه، ولم يزل يتردد بين ربه وموسى عليه السلام حتى جعلها خمس صلوات في اليوم والليلة، فقال الله تعالى: «هي خمس وهي خمسون، لا يُبدَّل القول لديّ». وفي صحيح مسلم أنه أُعطي كذلك خواتيم سورة البقرة، وغُفر لمن لم يشرك بالله شيئًا من أمته المقحمات، أي الكبائر الموجبات. فالصلاة هبة أُعطيت في الملأ الأعلى."], ["صباح مكة وتكذيب قريش", "أصبح النبي ﷺ في مكة، فأخبر قومه بما رأى، فكذّبوه واستهزؤوا به، وارتدّ بعض ضعاف الإيمان كما تذكر كتب السير، وسارعوا إلى أبي بكر رضي الله عنه يخبرونه ليستنكر، فصدّق النبي ﷺ دون تردد، وتذكر كتب السيرة أنه لقّب بسبب ذلك بالصدّيق. وطلبت قريش من النبي ﷺ أن يصف لهم بيت المقدس، وكانوا قد رأوه، وهو لم يره قبل ذلك. فروى مسلم عن أبي هريرة رضي الله عنه أن النبي ﷺ قال: «فكُربتُ كربًا ما كُربتُ مثله قط، فرفعه الله لي أنظر إليه، ما يسألوني عن شيء إلا أنبأتهم به». فوصفه لهم وصفًا دقيقًا فلم يجدوا ما يردّونه به، لكنهم أصرّوا على العناد."], ["الدروس والمعاني", "مثّلت هذه الليلة ربطًا بين المسجد الحرام والمسجد الأقصى، وهو ما يجعل لبيت المقدس مكانة خاصة عند المسلمين، فقد كان أولى القبلتين وثالث المسجدين اللذين تُشدّ إليهما الرحال. وكانت المعراج فرصة لرؤية آيات الله في الملأ الأعلى ولقاء الأنبياء وقبول الأمة وفرض الصلاة، فالصلاة لم تفرض في الأرض بوحي يأتي إلى الغار بل فرضت في السماء، وفي ذلك تنبيه إلى منزلتها. ومن دلالاتها أيضًا أن الله لا يترك عبده المبتلى بل يكرمه بعد الصبر، وأن وحدة الأنبياء ورسالتهم واحدة وأن الإسلام دين الأنبياء جميعًا. وقد أخبر الله في أول الآية بقوله ﴿سُبْحَانَ﴾ أن هذه معجزة لا تخضع لموازين البشر وقدرتهم."]], "lesson": ["الصلاة فُرضت في الملأ الأعلى، وهذا يدل على عظم منزلتها وأنها صلة العبد بربه.", "الله يعوّض عبده الصابر بعد الشدة بما يُنسيه ما لقي من أذى.", "بيت المقدس له مكانة في الإسلام، وارتباط المسجد الأقصى بالمسجد الحرام ثابت بالقرآن.", "التصديق بخبر الوحي دون تردد من علامات كمال الإيمان، كما فعل أبو بكر رضي الله عنه."], "cat": "seerah"}, {"id": "s15", "title": "قصة صاحب الجنتين", "type": "قصة قرآنية", "verse": "وَاضْرِبْ لَهُم مَّثَلًا رَّجُلَيْنِ جَعَلْنَا لِأَحَدِهِمَا جَنَّتَيْنِ مِنْ أَعْنَابٍ وَحَفَفْنَاهُمَا بِنَخْلٍ وَجَعَلْنَا بَيْنَهُمَا زَرْعًا", "source": "سورة الكهف 18:32", "parts": [["مثل يضربه الله", "جاءت هذه القصة في سورة الكهف مثلًا يضربه الله للناس، وهي إحدى القصص الأربع في السورة، ومعها قصة أصحاب الكهف وموسى والخضر وذي القرنين. وتأتي بعد أمر الله لنبيه صلى الله عليه وسلم أن يصبر نفسه مع الذين يدعون ربهم بالغداة والعشي يريدون وجهه، ولا يعدو عينيه عنهم يريد زينة الحياة الدنيا. فالمثل هنا يبيّن حال من افتتن بمتاع الدنيا وأنساه ربه. وقد جعل الله لأحد الرجلين جنتين من أعناب، وأحاطهما بالنخل، وجعل بينهما زرعًا. ولم يسمِّ القرآن الرجلين ولا ذكر بلدهما ولا زمانهما، وقيل إنهما أخوان، ولا يثبت ذلك بنص صحيح. وهذا الإبهام مقصود، لأن العبرة في النموذج الذي يتكرر في كل عصر: رجل أنعم الله عليه، فغرّه ماله، وآخر مؤمن فقير لا يغترّ بالدنيا ولا يحقد على غنيّها."], ["الجنتان وحال صاحبهما", "وصف القرآن الجنتين وصفًا بديعًا: ﴿كِلْتَا الْجَنَّتَيْنِ آتَتْ أُكُلَهَا وَلَمْ تَظْلِم مِّنْهُ شَيْئًا وَفَجَّرْنَا خِلَالَهُمَا نَهَرًا﴾. أي أن كل جنة تعطي ثمرها كاملًا غير ناقص، وأن النهر يجري بينهما فلا يحتاج صاحبهما إلى ما يحتاج إليه الناس من انتظار المطر. وكان لصاحبهما ثمر، أي أنواع من المال والمكاسب غير الثمار. فاجتمع له الأمن والرزق والثروة. وكان بإمكان هذه النعم أن تجعله شاكرًا متواضعًا، لكنها جعلته مغرورًا. فقال لصاحبه، وهو يحاوره في حديث بينهما: ﴿أَنَا أَكْثَرُ مِنكَ مَالًا وَأَعَزُّ نَفَرًا﴾. أي أكثر خدمًا وأعوانًا وأولادًا. فانظر كيف جعل المال والجاه ميزانًا للقيمة، وكأن من كثر ماله فهو الأعلى عند الله والناس، وهذا أصل الخطأ الذي وقع فيه كثير من المتكبرين في كل زمان، إذ يقيسون الناس بما يملكون لا بما يحملون من إيمان وخلق."], ["ظالم لنفسه", "ثم دخل جنته وهو ظالم لنفسه، فقال ما حكاه القرآن: ﴿مَا أَظُنُّ أَن تَبِيدَ هَٰذِهِ أَبَدًا﴾. فاعتقد أن نعمته لا تزول، وأنكر البعث بقوله: وما أظن الساعة قائمة. ثم زاد في اغتراره فقال: ولئن رُددت إلى ربي لأجدنّ خيرًا منها منقلبًا. أي إن كان هناك بعث فسيكون لي هناك أفضل مما هنا، لأن الله أكرمني في الدنيا. وهذا فهم منحرف، يظن فيه أن النعمة في الدنيا دليل على الرضا الإلهي دائمًا، وقد بيّن القرآن في مواضع أخرى أن الله يعطي الدنيا لمن يحب ولمن لا يحب. وتجتمع في كلامه ثلاث خطايا: ظنّه أن الدنيا لا تزول، وإنكاره قيام الساعة، وتألّيه على الله في الآخرة. ولم يسجد شكرًا ولم يقل كلمة حمد لله، فخلت جنته من ذكر ربه، وكان ظلمه لنفسه أنه نسب النعمة إلى نفسه وجهله بمن وهبها له."], ["نصيحة الصاحب المؤمن", "أجابه صاحبه المؤمن وهو يحاوره، ولم يردّ عليه بغضب ولا حسد، بل بإنكار الحق للتوحيد: ﴿أَكَفَرْتَ بِالَّذِي خَلَقَكَ مِن تُرَابٍ ثُمَّ مِن نُّطْفَةٍ ثُمَّ سَوَّاكَ رَجُلًا﴾. فذكّره بأصله الأول، وأن من خلقه من العدم قادر على إعادته. ثم أعلن عقيدته: لكنّا هو الله ربي ولا أشرك بربي أحدًا. وأرشده إلى ما كان ينبغي أن يقوله عند دخول جنته: ﴿وَلَوْلَا إِذْ دَخَلْتَ جَنَّتَكَ قُلْتَ مَا شَاءَ اللَّهُ لَا قُوَّةَ إِلَّا بِاللَّهِ﴾. ثم لم يتعالَ بفقره، بل قال: إن ترنِ أنا أقل منك مالًا وولدًا، فعسى ربي أن يؤتين خيرًا من جنتك. وحذّره من أن يرسل الله على جنته حسبانًا من السماء، فتصبح صعيدًا زلقًا، أو يصبح ماؤها غورًا، فلن يستطيع له طلبًا. وبهذا جمع بين التذكير بالله والتحذير من زوال النعمة وبين التواضع والرجاء في فضل الله."], ["زوال الجنتين", "ثم وقع ما حذّر منه الصاحب المؤمن، قال الله تعالى: ﴿وَأُحِيطَ بِثَمَرِهِ فَأَصْبَحَ يُقَلِّبُ كَفَّيْهِ عَلَىٰ مَا أَنفَقَ فِيهَا وَهِيَ خَاوِيَةٌ عَلَىٰ عُرُوشِهَا﴾. فأصبح يقلّب كفيه حسرةً على ما أنفقه فيها، وقد سقطت الأعناب على عيدانها التي كانت تحملها. ولم يحدد القرآن كيف جاء الهلاك، هل كان بصاعقة أو ريح أو غيره، ولم يحدد زمنه. وإنما قال: أُحيط بثمره، أي أحاط به الهلاك فلم يبقَ منه شيء. ثم ذكر القرآن ما قاله الرجل عندها: يا ليتني لم أشرك بربي أحدًا. فعرف متأخرًا أن ماله كان رزقًا من الله وأن الاعتماد عليه شرك خفي. ولم يخبر القرآن هل كان قوله توبة صادقة أم ندمًا لا يغني. ثم قال الله: ولم تكن له فئة ينصرونه من دون الله وما كان منتصرًا، فلا المال ولا الأعوان ردّوا عنه أمر الله."], ["العبرة ومثل الدنيا", "ختم الله القصة بقوله: ﴿هُنَالِكَ الْوَلَايَةُ لِلَّهِ الْحَقِّ هُوَ خَيْرٌ ثَوَابًا وَخَيْرٌ عُقْبًا﴾. أي أن النصرة والحكم في النهاية لله وحده، وأن ثوابه لمن آمن به خير الثواب، وعاقبة أمر من أطاعه خير العواقب. ثم أتبعها بمثل الحياة الدنيا فقال: كماء أنزلناه من السماء فاختلط به نبات الأرض فأصبح هشيمًا تذروه الرياح، وكان الله على كل شيء مقتدرًا. ثم قال: المال والبنون زينة الحياة الدنيا والباقيات الصالحات خير عند ربك ثوابًا وخير أملًا. فلا ينبغي أن نقيس الإنسان بماله وولده، فالمال زينة تزول والعمل الصالح هو الذي يبقى. وكان النبي صلى الله عليه وسلم يعلّم أن قول لا حول ولا قوة إلا بالله كنز من كنوز الجنة، كما في الصحيحين. فمن قالها عند رؤية نعمة نسب الفضل لله وحفظ قلبه من الغرور وحفظ نعمته بإذن الله."]], "lesson": ["المال والجاه ليسا ميزانًا لقيمة الإنسان ولا دليلًا على رضا الله عنه.", "قل عند رؤية النعمة ما شاء الله لا قوة إلا بالله، لتنسب الفضل لله وتأمن الغرور.", "الدنيا زائلة كالنبات الهشيم، والباقيات الصالحات هي الخير الباقي.", "الناصح المؤمن يجمع بين الحزم في الحق والتواضع وعدم الاستعلاء بفقره أو علمه."], "cat": "story"}, {"id": "sr15", "title": "بيعتا العقبة الأولى والثانية", "type": "من السيرة النبوية", "verse": "إِنَّ الَّذِينَ يُبَايِعُونَكَ إِنَّمَا يُبَايِعُونَ اللَّهَ يَدُ اللَّهِ فَوْقَ أَيْدِيهِمْ", "source": "سورة الفتح 48:10", "parts": [["عرض النفس على القبائل", "لما اشتد أذى قريش بعد وفاة أبي طالب، جعل النبي ﷺ يعرض نفسه على القبائل في مواسم الحج وفي الأسواق. روى أحمد وأبو داود من حديث جابر رضي الله عنه أن النبي ﷺ مكث عشر سنين يتبع الناس في منازلهم في المواسم بمجنّة وعكاظ وفي منازلهم بمنى يقول: «من يؤويني؟ من ينصرني حتى أبلّغ رسالة ربي وله الجنة؟»، حتى إن الرجل ليرحل من اليمن أو من مضر فيأتيه قومه فيقولون: احذر غلام قريش لا يفتنك. وفي رواية: «ألا رجل يحملني إلى قومه، فإن قريشًا قد منعوني أن أبلّغ كلام ربي». وهكذا لم يكن النبي ﷺ يترك فرصةً إلا ويستثمرها، وكان الله يهيّئ له مع ذلك أرضًا جديدة لدعوته."], ["الخزرج وبداية الطريق", "كان الأوس والخزرج يسكنون يثرب وهم عرب، وقد وقعت بينهم حروب طويلة، آخرها يوم بُعاث الذي أشارت إليه عائشة رضي الله عنها في صحيح البخاري بقولها: «كان يوم بُعاث يومًا قدّمه الله لرسوله ﷺ، فقدم رسول الله ﷺ وقد افترق ملؤهم وقُتلت سَرَواتهم وجُرّحوا». وكانوا يسمعون من جيرانهم اليهود أن نبيًّا سيُبعث قد أظل زمانه. فلما التقى النبي ﷺ في موسم الحج بنفر من الخزرج، وتذكر كتب السيرة أنهم ستة، عرض عليهم الإسلام وتلا عليهم القرآن، فأجابوه وقال بعضهم لبعض إنه النبي الذي توعدكم به اليهود فلا يسبقنكم إليه. فآمنوا وعادوا إلى المدينة يدعون قومهم، وتواعدوا أن يلقوه في الموسم القادم."], ["بيعة العقبة الأولى", "وفي الموسم التالي جاء اثنا عشر رجلًا من أهل المدينة، فلقوا النبي ﷺ عند العقبة بمنى، كما في صحيح البخاري عن عبادة بن الصامت رضي الله عنه: «كنتُ فيمن حضر العقبة الأولى، وكنا اثني عشر رجلًا، فبايعنا رسول الله ﷺ على بيعة النساء، وذلك قبل أن يُفرض الحرب، على أن لا نشرك بالله شيئًا، ولا نسرق، ولا نزني، ولا نقتل أولادنا، ولا نأتي ببهتان نفتريه بين أيدينا وأرجلنا، ولا نعصيه في معروف». وقال لهم النبي ﷺ: «فإن وفيتم فلكم الجنة، وإن غشيتم من ذلك شيئًا فأخذتم بحدّه في الدنيا فهو كفارة له، وإن ستركم الله فأمركم إلى الله، إن شاء عذّبكم وإن شاء غفر لكم». وسُمّيت بيعة النساء لأنها خلت من القتال."], ["مصعب بن عمير في المدينة", "أرسل النبي ﷺ مع هؤلاء مصعب بن عمير رضي الله عنه ليعلّمهم القرآن والدين ويدعو إلى الإسلام. وثبت في صحيح البخاري عن البراء بن عازب رضي الله عنه: «أول من قدم علينا من أصحاب النبي ﷺ مصعب بن عمير وابن أم مكتوم، فجعلا يقرئاننا القرآن». وتروي كتب السيرة أن مصعبًا نزل على أسعد بن زرارة رضي الله عنه، وبفضل حسن بيانه أسلم سعد بن معاذ وأسيد بن حضير رضي الله عنهما، وهما من سادة الأوس، فدخل بإسلامهما أكثر قومهما. فانتشر الإسلام في دور الأنصار حتى لم يبق بيت إلا وفيه ذكر لرسول الله ﷺ. وهكذا كان الداعية الواحد المستعد سببًا في تهيئة المدينة لاستقبال الهجرة."], ["بيعة العقبة الثانية", "وفي موسم الحج من العام الثالث عشر للبعثة قدم المدينة جمع كبير من المسلمين مع حجاج قومهم المشركين، ومنهم نحو سبعين رجلًا وامرأتان على ما اشتهر في كتب السيرة. وفي حديث كعب بن مالك رضي الله عنه عند أحمد أنهم تواعدوا مع النبي ﷺ على العقبة في أوسط أيام التشريق، فتسللوا إليه ليلًا بعد أن مضى ثلث الليل أو أكثر، يتسللون خفية من قومهم المشركين. وحضر العباس عم النبي ﷺ، وكان يومئذ على دين قومه، وتكلم يوثّق لابن أخيه، فطلب من القوم أن يتأكدوا من قدرتهم على حمايته، فلا يدعوه إلا إن كانوا مانعيه، وتروي كتب السيرة أنه فعل ذلك حرصًا على سلامته."], ["نص البيعة", "روى أحمد عن جابر رضي الله عنه أنه حضر العقبة وأنهم قالوا: يا رسول الله، علام نبايعك؟ قال: «تبايعوني على السمع والطاعة في النشاط والكسل، والنفقة في العسر واليسر، وعلى الأمر بالمعروف والنهي عن المنكر، وأن تقولوا في الله لا تأخذكم فيه لومة لائم، وعلى أن تنصروني فتمنعوني إذا قدمتُ عليكم مما تمنعون منه أنفسكم وأزواجكم وأبناءكم، ولكم الجنة». وتروي كتب السيرة أن البراء بن معرور رضي الله عنه كان أول من ضرب على يد النبي ﷺ، وأنه قال إنهم أهل الحرب وأهل الحلقة، أي السلاح، ورثوها كابرًا عن كابر. فبايع القوم، وكانت هذه البيعة أساس قيام الدولة الإسلامية الأولى."], ["النقباء وما بعد البيعة", "وطلب النبي ﷺ منهم اثني عشر نقيبًا يكونون كفلاء على قومهم، تسعة من الخزرج وثلاثة من الأوس على ما ذكره ابن إسحاق، ليكونوا مسؤولين عن أقوامهم. وتروي كتب السيرة أن الشيطان صرخ من رأس العقبة فكشف أمرهم، فاستأذن بعضهم النبي ﷺ أن يميلوا على أهل منى بالسيوف، فقال: «لم نؤمر بذلك». وبلغ الخبر قريشًا، فلحقوا بالقوم وأدركوا سعد بن عبادة رضي الله عنه وآذوه، ثم خلّصه المطعم بن عدي، وكانت الهجرة بعد ذلك بأشهر. فانطلق المسلمون من مكة إلى المدينة أرسالًا، وهكذا كانت البيعتان أرضية الهجرة وأساس الدولة، وجعلت من أهل المدينة أنصارًا للدين."]], "lesson": ["الدعوة تحتاج إلى مثابرة وبحث عن البيئة المهيّأة للحق، فالله لا يضيع جهد الداعي.", "أهمية العلم والتعليم في بناء المجتمع المسلم، فبمصعب رضي الله عنه تهيّأت المدينة.", "البيعة التزام شرعي بالطاعة والنصرة والتضحية، وأساسها الإيمان بالله والثقة بوعده.", "الحكمة والكتمان في الأمور الكبرى حفظًا للدعوة وأهلها، مع التوكل على الله."], "cat": "seerah"}, {"id": "s16", "title": "قصة لقمان ووصاياه لابنه", "type": "قصة قرآنية", "verse": "وَلَقَدْ آتَيْنَا لُقْمَانَ الْحِكْمَةَ أَنِ اشْكُرْ لِلَّهِ", "source": "سورة لقمان 31:12", "parts": [["لقمان والحكمة", "لقمان رجل صالح آتاه الله الحكمة، وسُمّيت سورة في القرآن باسمه، وهي السورة الحادية والثلاثون. قال الله تعالى: ﴿وَلَقَدْ آتَيْنَا لُقْمَانَ الْحِكْمَةَ أَنِ اشْكُرْ لِلَّهِ وَمَن يَشْكُرْ فَإِنَّمَا يَشْكُرُ لِنَفْسِهِ وَمَن كَفَرَ فَإِنَّ اللَّهَ غَنِيٌّ حَمِيدٌ﴾. والحكمة هي إصابة الحق قولًا وعملًا، وفهم الدين والعقل السليم، وتنزيل الأمور منازلها. وقد ربط القرآن الحكمة بالشكر، فكأن أول علامات الحكمة أن يعرف العبد نعمة الله فيشكره. ولم يحدد القرآن نسبه ولا بلده ولا زمانه، وقيل إنه كان عبدًا حبشيًّا، وقيل غير ذلك، ولا يثبت شيء من هذا بدليل صحيح. واختلف العلماء هل كان نبيًّا أم عبدًا صالحًا حكيمًا، والأكثر على أنه لم يكن نبيًّا، والقرآن لم يصفه بالنبوة. وبهذا تعلمنا الآية أن الحكمة فضل يؤتيه الله من يشاء، وأن قيمة الإنسان بما آتاه الله من فقه وخلق لا بنسبه ولا بمنزلته بين الناس."], ["الوصية الأولى: التوحيد", "ذكر القرآن أن لقمان قال لابنه وهو يعظه، ولم يحدد القرآن اسم الابن: ﴿يَا بُنَيَّ لَا تُشْرِكْ بِاللَّهِ إِنَّ الشِّرْكَ لَظُلْمٌ عَظِيمٌ﴾. وبدأ بالتوحيد لأنه أصل الدين وأعظم ما يجب أن يتعلمه الولد. وناداه بقوله: يا بنيّ، بصيغة التصغير التي تدل على الشفقة والمحبة. وفي الصحيحين عن عبد الله بن مسعود رضي الله عنه قال: لما نزلت ﴿الَّذِينَ آمَنُوا وَلَمْ يَلْبِسُوا إِيمَانَهُمْ بِظُلْمٍ﴾ شقّ ذلك على أصحاب النبي صلى الله عليه وسلم، وقالوا: أيّنا لا يظلم نفسه؟ فقال رسول الله صلى الله عليه وسلم: «ليس هو كما تظنون، إنما هو كما قال لقمان لابنه: يا بنيّ لا تشرك بالله إن الشرك لظلم عظيم». فتبيّن أن الظلم المراد هو الشرك، وأن أعظم ظلم يقع من الإنسان أن يجعل لله شريكًا وهو الذي خلقه ورزقه."], ["ووصية الله بالوالدين", "وفي أثناء وصايا لقمان جاء كلام الله تعالى: ﴿وَوَصَّيْنَا الْإِنسَانَ بِوَالِدَيْهِ حَمَلَتْهُ أُمُّهُ وَهْنًا عَلَىٰ وَهْنٍ وَفِصَالُهُ فِي عَامَيْنِ أَنِ اشْكُرْ لِي وَلِوَالِدَيْكَ إِلَيَّ الْمَصِيرُ﴾. وهذه الآيات اعتراض بين الوصايا عند أكثر المفسرين، وهي من كلام الله لا من كلام لقمان. وفيها أن شكر الله مقرون بشكر الوالدين، وأن للأم من الجهد والتعب ما يستحق الوفاء. ثم قال: وإن جاهداك على أن تشرك بي ما ليس لك به علم فلا تطعهما، وصاحبهما في الدنيا معروفًا واتبع سبيل من أناب إليّ. فلا طاعة لمخلوق في معصية الخالق، ومع ذلك يبقى الإحسان إليهما في الدنيا. وقد روى مسلم أن هذه الآية نزلت في سعد بن أبي وقاص رضي الله عنه، حين حلفت أمه ألا تأكل ولا تشرب حتى يكفر بمحمد صلى الله عليه وسلم، فأبى سعد وبقي بارًّا بها في غير المعصية."], ["مراقبة الله", "ثم رجع لقمان إلى وعظ ابنه، وقال له: ﴿يَا بُنَيَّ إِنَّهَا إِن تَكُ مِثْقَالَ حَبَّةٍ مِّنْ خَرْدَلٍ فَتَكُن فِي صَخْرَةٍ أَوْ فِي السَّمَاوَاتِ أَوْ فِي الْأَرْضِ يَأْتِ بِهَا اللَّهُ إِنَّ اللَّهَ لَطِيفٌ خَبِيرٌ﴾. والضمير في إنها يعود إلى الخطيئة أو الحسنة أو الفعلة، أي أن أي عمل مهما صغر، ولو كان وزن حبة الخردل، وكان مخبوءًا في صخرة صماء أو في السماوات أو في الأرض، فإن الله يعلمه ويأتي به يوم الحساب. ووصف الله باللطيف، أي الذي يعلم دقائق الأمور وخفاياها، وبالخبير، أي العالم ببواطنها. وفي هذه الوصية تربية للضمير، فمن علم أن ربه يراه في كل مكان استحى أن يعصيه في الخلوة، وراقبه في سرّه كما يراقبه في علنه. وهذا أصل الإحسان الذي بيّنه النبي صلى الله عليه وسلم بأن تعبد الله كأنك تراه، فإن لم تكن تراه فإنه يراك."], ["الصلاة والأمر بالمعروف والصبر", "ثم انتقل لقمان إلى العبادة والعمل الصالح، فقال: ﴿يَا بُنَيَّ أَقِمِ الصَّلَاةَ وَأْمُرْ بِالْمَعْرُوفِ وَانْهَ عَنِ الْمُنكَرِ وَاصْبِرْ عَلَىٰ مَا أَصَابَكَ إِنَّ ذَٰلِكَ مِنْ عَزْمِ الْأُمُورِ﴾. فبدأ بإقامة الصلاة لأنها صلة العبد بربه، ثم ربط الصلاة بالإصلاح فأمره بأن يدعو إلى الخير وينهى عن الشر. ولأن من قام بذلك سيلقى أذى من الناس، أمره بالصبر على ما أصابه. وسمّى ذلك من عزم الأمور، أي من الأمور التي يعزم عليها أهل الهمة العالية. وفي هذا بيان أن المسلم لا يكتفي بصلاح نفسه، بل يسعى إلى إصلاح مجتمعه بالحكمة واللين، وأن الطريق إلى ذلك لا يخلو من الأذى، وأن الزاد فيه الصبر. وجاءت هذه الأمور مرتبة ترتيبًا حكيمًا: عبادة تقوّي القلب، ثم دعوة تنفع الناس، ثم صبر يحمي صاحبه من اليأس ويثبته على الطريق."], ["الأدب مع الناس", "وختم لقمان وصاياه بآداب التعامل مع الخلق، فقال: ﴿وَلَا تُصَعِّرْ خَدَّكَ لِلنَّاسِ وَلَا تَمْشِ فِي الْأَرْضِ مَرَحًا إِنَّ اللَّهَ لَا يُحِبُّ كُلَّ مُخْتَالٍ فَخُورٍ﴾. والتصعير هو أن يميل الإنسان بوجهه عن الناس تكبرًا وإعراضًا. والمرح هو الخيلاء والتبختر. ثم قال: ﴿وَاقْصِدْ فِي مَشْيِكَ وَاغْضُضْ مِن صَوْتِكَ إِنَّ أَنكَرَ الْأَصْوَاتِ لَصَوْتُ الْحَمِيرِ﴾. أي توسّط في مشيك فلا تسرع إسراعًا يذهب بالوقار ولا تتباطأ تباطؤ المتماوتين، واخفض صوتك فلا ترفعه بلا حاجة، فإن أقبح الأصوات صوت الحمير. وهذه آداب في المشي والكلام تعكس تواضع القلب. فالإيمان يظهر في الحركة والصوت كما يظهر في العبادة. وهكذا جمعت وصايا لقمان بين العقيدة والعبادة والأخلاق، فكانت منهجًا كاملًا للتربية، وبقيت كلماته حيّة في القرآن يتلوها المسلمون ويربّون عليها أبناءهم، فمن أراد أن يربّي ولده فليبدأ بما بدأ به لقمان: توحيد لله، ثم مراقبة له، ثم عبادة وصبر، ثم أدب جميل مع خلقه."]], "lesson": ["الحكمة تبدأ بالشكر لله، والتوحيد أعظم وصية يوصي بها الأب ابنه.", "الوعظ بالرفق والشفقة، كما ناداه لقمان: يا بنيّ.", "مراقبة الله في السر والعلن تحفظ العبد من المعصية ولو في الخلوة.", "الإيمان يظهر في الأخلاق: تواضع في المشي وهدوء في الصوت وحسن مع الناس."], "cat": "story"}, {"id": "sr16", "title": "الهجرة إلى المدينة: الغار والطريق", "type": "من السيرة النبوية", "verse": "إِذْ يَقُولُ لِصَاحِبِهِ لَا تَحْزَنْ إِنَّ اللَّهَ مَعَنَا", "source": "سورة التوبة 9:40", "parts": [["هجرة الصحابة وتآمر قريش", "بعد بيعة العقبة الثانية أذن النبي ﷺ لأصحابه بالهجرة إلى المدينة، فخرجوا أرسالًا يتخفّى كثير منهم، وهاجر أبو سلمة وعمر وعياش وغيرهم رضي الله عنهم، وبقي النبي ﷺ في مكة ينتظر إذن الله، ومعه أبو بكر وعلي رضي الله عنهما. فلما رأت قريش أن المسلمين صاروا لهم دارًا ومنعة، خافت أن يلحق النبي ﷺ بهم، فاجتمعوا في دار الندوة يتشاورون في أمره، وقد حكى القرآن ذلك فقال: ﴿وَإِذْ يَمْكُرُ بِكَ الَّذِينَ كَفَرُوا لِيُثْبِتُوكَ أَوْ يَقْتُلُوكَ أَوْ يُخْرِجُوكَ وَيَمْكُرُونَ وَيَمْكُرُ اللَّهُ وَاللَّهُ خَيْرُ الْمَاكِرِينَ﴾. وتذكر كتب السيرة أنهم اتفقوا على أن يؤخذ من كل قبيلة شاب قوي ليضربوه ضربة رجل واحد فيتفرق دمه في القبائل."], ["ليلة الهجرة", "أخبر الله نبيه بتدبيرهم وأذن له بالهجرة. وتذكر كتب السيرة أن النبي ﷺ أمر عليًّا رضي الله عنه أن ينام في فراشه، ويؤدّي الأمانات التي كانت عنده للناس، ثم يلحق به، وأن القوم اجتمعوا على بابه يتربصون، فخرج ﷺ عليهم وأخذ حفنة من تراب فذرّها على رؤوسهم وهو يتلو أوائل سورة يس، فلم يروه. وفي حديث عائشة رضي الله عنها عند البخاري أن النبي ﷺ كان يأتي بيت أبي بكر طرفي النهار بكرةً وعشية، فلما أُذن له بالهجرة أتاهم في ساعة لم يكن يأتيهم فيها، وهي وقت الظهيرة، متقنّعًا. فقال أبو بكر: فداء له أبي وأمي، ما جاء به في هذه الساعة إلا أمر."], ["بيت أبي بكر والتجهيز", "روت عائشة رضي الله عنها في البخاري أن النبي ﷺ قال لأبي بكر: «أخرِجْ من عندك»، فقال: إنما هم أهلك بأبي أنت يا رسول الله. فقال: «فإني قد أُذن لي في الخروج». قال أبو بكر: الصحبة يا رسول الله؟ قال: «الصحبة». قالت عائشة: فوالله ما شعرتُ قطّ قبل ذلك اليوم أن أحدًا يبكي من الفرح، حتى رأيتُ أبا بكر يبكي يومئذ. وكان أبو بكر قد أعدّ راحلتين، واستأجر رجلًا من بني الدِّيل هو عبد الله بن أُريقط، وكان مشركًا لكنه خبير بالطريق، فدفع إليه الراحلتين. وصنعت أسماء بنت أبي بكر رضي الله عنهما سفرة لهما، فلم تجد ما تربطها به، فشقّت نطاقها فربطت به، فسُميت ذات النطاقين."], ["في غار ثور", "خرج النبي ﷺ وأبو بكر رضي الله عنه من خوخة، أي باب صغير، في ظهر بيت أبي بكر، فلحقا بغار في جبل ثور جنوب مكة، فمكثا فيه ثلاث ليال. وكان عبد الله بن أبي بكر رضي الله عنهما يبيت عندهما، وهو شاب فطن، فيصبح مع قريش بمكة كبائت، فلا يسمع أمرًا يُكتاد به إلا وعاه، حتى يأتيهما بخبر ذلك حين يختلط الظلام. وكان عامر بن فهيرة مولى أبي بكر يرعى غنمه عليهما فيريحها عليهما حين تذهب ساعة من العشاء، فيبيتان في رِسْلهما، أي لبنهما. وفي ذلك دقة التخطيط وأخذ بالأسباب، من إخفاء الأثر وتأمين الأخبار والغذاء، قبل التوكل على الله."], ["الله ثالثهما", "وفي الصحيحين عن أبي بكر رضي الله عنه قال: قلتُ للنبي ﷺ وأنا في الغار: لو أن أحدهم نظر تحت قدميه لأبصرنا. فقال: «ما ظنك يا أبا بكر باثنين الله ثالثهما». وقد خلّد القرآن هذا الموقف في قوله تعالى: ﴿إِلَّا تَنصُرُوهُ فَقَدْ نَصَرَهُ اللَّهُ إِذْ أَخْرَجَهُ الَّذِينَ كَفَرُوا ثَانِيَ اثْنَيْنِ إِذْ هُمَا فِي الْغَارِ إِذْ يَقُولُ لِصَاحِبِهِ لَا تَحْزَنْ إِنَّ اللَّهَ مَعَنَا فَأَنزَلَ اللَّهُ سَكِينَتَهُ عَلَيْهِ﴾. فكان خوف أبي بكر رضي الله عنه على النبي ﷺ لا على نفسه، وكان جواب النبي ﷺ دليلًا على يقينه بربه. أما قريش فجعلت لمن يأتي بهما ديةً كاملة، وطلبتهما في كل مكان، ووقفت على باب الغار ولم تدخله."], ["الطريق وسراقة", "ثم انطلق النبي ﷺ وأبو بكر وعامر بن فهيرة والدليل ابن أريقط في طريق الساحل، وفي حديث عائشة عند البخاري أنهم ساروا ليلتهم ويومهم حتى قام قائم الظهيرة. وأدركهم سراقة بن مالك رضي الله عنه، وكان يومئذ مشركًا يطلب الجائزة، فلما دنا منهم عثرت به فرسه، ثم ساخت يدا فرسه في الأرض، فعلم أن الأمر من الله، فنادى بطلب الأمان وسأل أن يكتب له كتاب أمان، فأمر النبي ﷺ عامر بن فهيرة فكتب له في رقعة. ثم رجع سراقة يصرف الطالبين، ولم يخبر أحدًا بما رأى. وقد أسلم بعد ذلك. وهكذا انقلب الطالب حاميًا للنبي ﷺ، بتدبير الله ولطفه، من حيث لا يحتسب."], ["قباء ودخول المدينة", "كان أهل المدينة يخرجون كل غداة إلى الحرّة ينتظرون النبي ﷺ حتى تردهم حرارة الظهيرة، ففي يوم وقف رجل من اليهود على أُطم من آطامهم لأمر ما، فرأى رسول الله ﷺ وأصحابه مبيّضين يزول بهم السراب، فصرخ بأعلى صوته: يا معاشر العرب، هذا جدّكم الذي تنتظرون! كما في صحيح البخاري. فنزل النبي ﷺ بقباء على بني عمرو بن عوف يوم الاثنين من شهر ربيع الأول، وتختلف الروايات في اليوم من الشهر، فالمشهور الثاني عشر، فمكث فيهم بضع عشرة ليلة وأسّس مسجد قباء، وهو الذي أُسّس على التقوى. ثم ركب بعد ذلك إلى المدينة، وتنافس أهلها في نزوله عليهم، فقال: «دعوها فإنها مأمورة»، حتى بركت ناقته عند موضع المسجد."]], "lesson": ["الأخذ بالأسباب كاملًا ثم التوكل على الله، فقد خطّط النبي ﷺ للهجرة بدقة ثم قال لصاحبه إن الله معنا.", "الصحبة الصادقة والتضحية في سبيل الحق، كما كان أبو بكر وأهله رضي الله عنهم.", "معية الله لأوليائه تغني عن كثرة الأعوان، فالله ثالث الاثنين.", "الله يسخّر القلوب لمن شاء، حتى قلوب من جاؤوا لقتال النبي ﷺ فانقلبوا حماةً له."], "cat": "seerah"}, {"id": "sr17", "title": "بناء المسجد النبوي والمؤاخاة ووثيقة المدينة", "type": "من السيرة النبوية", "verse": "إِنَّمَا الْمُؤْمِنُونَ إِخْوَةٌ", "source": "سورة الحجرات 49:10", "parts": [["اختيار الموضع", "بعد أن نزل النبي ﷺ في المدينة وبركت ناقته، سأل عن لمن هذا المِربَد، وهو موضع تجفيف التمر، فعلم أنه لغلامين يتيمين من الأنصار في حجر أسعد بن زرارة رضي الله عنه، فساومهما به ليتخذه مسجدًا، فقالا: بل نهبه لك يا رسول الله، فأبى أن يقبله هبةً حتى ابتاعه منهما بثمن، كما في صحيح البخاري. وتروي كتب السيرة أنهما سهل وسهيل ابنا عمرو. وقبل ذلك نزل في بيت أبي أيوب الأنصاري رضي الله عنه، فقد جاء في الصحيح أن أبا أيوب قال: هذه داري وهذا بابي، فنزل عنده حتى بُني المسجد والمساكن."], ["بناء المسجد", "في الصحيحين أن في موضع المسجد قبورًا للمشركين، وكانت فيه خِرَب ونخل، فأمر النبي ﷺ بالقبور فنُبشت، وبالخرب فسُوّيت، وبالنخل فقُطع، فصفّوا النخل قبلة للمسجد. وجعلوا عضادتيه حجارة، وكان الصحابة ينقلون الحجارة وهم يرتجزون، والنبي ﷺ معهم ينقل اللبن ويقول: «اللهم لا خير إلا خير الآخرة، فانصر الأنصار والمهاجرة». وقال ابن عمر رضي الله عنهما: كان المسجد على عهد رسول الله ﷺ مبنيًّا باللبن وسقفه الجريد وعمده خشب النخل، كما في البخاري. وكان عمار بن ياسر رضي الله عنه يحمل لبنتين لبنتين، فقال النبي ﷺ: «ويح عمار تقتله الفئة الباغية»، رواه البخاري. وكان البناء متواضعًا لكن أثره عظيم في تاريخ الإسلام."], ["وظائف المسجد", "لم يكن المسجد النبوي مكانًا للصلاة وحدها، بل كان دار العبادة والعلم والقضاء والشورى واستقبال الوفود، وفيه موضع يأوي إليه فقراء المهاجرين الذين لا مأوى لهم، وهم أهل الصُّفّة كما جاء في الصحيح. وفي هذه الفترة شُرع الأذان بعد مشاورة الصحابة في كيفية جمعهم للصلاة، فقال النبي ﷺ لبلال رضي الله عنه: «يا بلال قم فناد بالصلاة»، كما في الصحيحين من حديث ابن عمر رضي الله عنهما. وهكذا صار المسجد مركز المجتمع المسلم الجديد، يجتمع فيه الغني والفقير والحاكم والمحكوم تحت سقف واحد، وتتشكل فيه روح الأخوة والمساواة قبل أن تُكتب لها القوانين."], ["حاجة المجتمع الجديد", "كان المهاجرون قد تركوا في مكة أموالهم وديارهم وأهلهم، وجاؤوا المدينة بلا مال في الغالب، وكان الأنصار أهل أرض ونخل لكنهم لا يعرفون كيف يستقبلون هذه الأعداد الكبيرة. فكان لا بد من رابطة تجمعهم وتحل المشكلة المعيشية والاجتماعية بحكمة. وفي هذا المعنى نزل قوله تعالى في وصف الأنصار: ﴿وَالَّذِينَ تَبَوَّءُوا الدَّارَ وَالْإِيمَانَ مِن قَبْلِهِمْ يُحِبُّونَ مَنْ هَاجَرَ إِلَيْهِمْ وَلَا يَجِدُونَ فِي صُدُورِهِمْ حَاجَةً مِّمَّا أُوتُوا وَيُؤْثِرُونَ عَلَىٰ أَنفُسِهِمْ وَلَوْ كَانَ بِهِمْ خَصَاصَةٌ﴾. وكانت المؤاخاة إجابة عملية لهذا الواقع، تقوم على الإيمان لا على النسب ولا على المال."], ["المؤاخاة بين المهاجرين والأنصار", "آخى النبي ﷺ بين المهاجرين والأنصار، وقال أنس رضي الله عنه: «حالف رسول الله ﷺ بين المهاجرين والأنصار في دارنا»، كما في الصحيحين. وروى البخاري أن عبد الرحمن بن عوف رضي الله عنه لما قدم المدينة آخى النبي ﷺ بينه وبين سعد بن الربيع رضي الله عنه، فقال سعد: إني أكثر الأنصار مالًا، فأقسم لك نصف مالي، وانظر أي زوجتيّ هويتَ نزلتُ لك عنها. فقال عبد الرحمن: بارك الله لك في أهلك ومالك، دلّوني على السوق. فذهب فاشترى وباع حتى أصاب شيئًا من الأقط والسمن. وقال الأنصار للنبي ﷺ: اقسم بيننا وبين إخواننا النخيل، فقال: «لا»، فقالوا: فتكفونا المؤنة ونشرككم في الثمرة؟ قالوا: سمعنا وأطعنا."], ["وثيقة المدينة", "كتب النبي ﷺ وثيقة تنظّم العلاقات بين سكان المدينة، رواها ابن إسحاق وابن هشام وأبو عبيد في كتاب الأموال، وتكلّم أهل العلم في بعض ألفاظها وأسانيدها، وتختلف الروايات في وقت كتابتها، ويحتج بمعانيها المتفقة مع الصحيح. ومن مضمونها أن المسلمين أمة واحدة من دون الناس، وأن لليهود دينهم وللمسلمين دينهم، وأن بينهم النصر على من حارب أهل الوثيقة، وأن المدينة حرم آمن لأهلها، وأن مرجع الخلاف إلى الله ورسوله. وقد ثبت في الصحيحين من صحيفة علي رضي الله عنه قوله ﷺ: «المدينة حرم ما بين عير إلى ثور»، وفيه «ذمة المسلمين واحدة يسعى بها أدناهم»، وهو يتفق مع روح هذه الوثيقة."], ["ثمار البناء", "بهذه الأعمال الثلاثة قامت الدولة الأولى في الإسلام على ثلاث ركائز: مسجد يجمع القلوب على الله، وأخوّة تجمع الناس على الإيمان فتنزع الفقر والعصبية، ووثيقة تنظّم العيش المشترك مع غير المسلمين وتحفظ الحقوق. ولم تكن المدينة بعد ذلك مثالية خالية من الاضطراب، فقد تربص بها المنافقون وبعض اليهود وقريش، لكنها كانت أساسًا متينًا استطاع المسلمون أن يواجهوا به غزوات الأحزاب وغيرها. وعرفت الدنيا بعد ذلك أن الإسلام ليس شعائر معزولة بل دين يبني مجتمعًا متكاملًا يقوم على العبادة والعدل والتكافل والعمل والعيش الآمن مع المخالف."]], "lesson": ["البدء ببناء المسجد دليل على أن العبادة والتعليم والاجتماع أساس المجتمع المسلم.", "الأخوة في الله تتجاوز المصالح، والإيثار قيمة تبني الأمم، كما فعل الأنصار.", "الكسب الحلال والعمل كرامة، فلم يقبل عبد الرحمن بن عوف رضي الله عنه أن يعيش عالة وسأل عن السوق.", "العدل في العيش مع المخالفين وتنظيم الحقوق بوثيقة معلنة من مقاصد الإسلام."], "cat": "seerah"}, {"id": "sr18", "title": "غزوة بدر الكبرى", "type": "من السيرة النبوية", "verse": "وَلَقَدْ نَصَرَكُمُ اللَّهُ بِبَدْرٍ وَأَنتُمْ أَذِلَّةٌ فَاتَّقُوا اللَّهَ لَعَلَّكُمْ تَشْكُرُونَ", "source": "سورة آل عمران 3:123", "parts": [["سبب الخروج", "كانت قريش قد صادرت أموال المهاجرين في مكة وأخرجتهم من ديارهم، فكان من حقهم أن يطلبوا حقهم في أموال قريش. وفي رمضان من السنة الثانية للهجرة سمع النبي ﷺ بقافلة تجارية كبيرة لقريش قادمة من الشام يقودها أبو سفيان، فخرج لاعتراضها، ولم يكن في نيته القتال المنظّم، ولذلك لم يستنفر كل من يستطيع، وقال: «هذه عير قريش فيها أموالهم، فاخرجوا إليها لعل الله يُنفّلكموها». وقد أشار القرآن إلى ذلك فقال: ﴿وَإِذْ يَعِدُكُمُ اللَّهُ إِحْدَى الطَّائِفَتَيْنِ أَنَّهَا لَكُمْ وَتَوَدُّونَ أَنَّ غَيْرَ ذَاتِ الشَّوْكَةِ تَكُونُ لَكُمْ﴾، أي أنهم أحبوا القافلة غير المسلحة، وأراد الله لهم لقاء الجيش."], ["تغيّر المسار", "علم أبو سفيان بخروج النبي ﷺ فغيّر طريقه إلى ساحل البحر ونجا بالقافلة، وأرسل إلى مكة يستنفر قريشًا لحماية أموالها، فخرجت قريش بجيش كبير مفاخرةً، وكانوا نحو ألف على ما ثبت في صحيح مسلم من حديث عمر رضي الله عنه. ولما بلغ أبا سفيان نجاة القافلة طلب منهم العودة، فأبى أبو جهل وقال: لا نرجع حتى نرد بدرًا. وكان المسلمون نحو ثلاثمائة وبضعة عشر رجلًا، وقد روى البخاري عن البراء رضي الله عنه: «كنا نتحدث أن أصحاب بدر على عدة أصحاب طالوت، الذين جاوزوا معه النهر، ولم يجاوز معه إلا مؤمن، بضعة عشر وثلاثمائة». وكان معهم قلة من الخيل والإبل، فكانوا يتعاقبون على البعير."], ["المشاورة", "استشار النبي ﷺ أصحابه لما بلغه خروج قريش، وكان يريد معرفة رأي الأنصار، إذ كانت بيعتهم في العقبة على حمايته داخل المدينة. فقام أبو بكر وعمر رضي الله عنهما فقالا وأحسنا. ثم قام المقداد بن الأسود رضي الله عنه فقال كما في صحيح البخاري: «يا رسول الله، امضِ لما أراك الله فنحن معك، والله لا نقول لك كما قالت بنو إسرائيل لموسى: ﴿اذْهَبْ أَنتَ وَرَبُّكَ فَقَاتِلَا إِنَّا هَاهُنَا قَاعِدُونَ﴾، ولكن امضِ ونحن معك، ونقاتل عن يمينك وعن شمالك وبين يديك ومن خلفك». وتذكر كتب السيرة أن سعد بن معاذ رضي الله عنه تكلم باسم الأنصار فأعلن أنهم لا يتخلفون عنه، وأنهم لو خاض بهم البحر لخاضوه معه. فسرّ النبي ﷺ بقولهم ونشطه ذلك."], ["الليلة السابقة للمعركة", "نزل المسلمون عند أدنى ماء من بدر، وتذكر كتب السيرة أن الحباب بن المنذر رضي الله عنه أشار على النبي ﷺ بالنزول عند أقرب ماء إلى قريش وتغوير الآبار خلفه وبناء حوض، فقبل النبي ﷺ رأيه. وقد ذكر الله نعمته في تلك الليلة بقوله: ﴿إِذْ يُغَشِّيكُمُ النُّعَاسَ أَمَنَةً مِّنْهُ وَيُنَزِّلُ عَلَيْكُم مِّنَ السَّمَاءِ مَاءً لِّيُطَهِّرَكُم بِهِ﴾، فنام المسلمون وأنزل الله مطرًا ثبّت الرمل تحت أقدامهم وطهّرهم. وبات النبي ﷺ يصلي ويدعو، وكان على يقين بأن النصر من عند الله، فأراهم مصارع القوم، وقال هذا مصرع فلان وهذا مصرع فلان، فما تعدّى أحد منهم موضعه، كما في صحيح مسلم."], ["الدعاء والمبارزة", "روى مسلم عن عمر رضي الله عنه أن النبي ﷺ لما نظر إلى المشركين وهم ألف وأصحابه ثلاثمائة وتسعة عشر رجلًا، استقبل القبلة ثم مدّ يديه فجعل يهتف بربه: «اللهم أنجز لي ما وعدتني، اللهم آتِ ما وعدتني، اللهم إن تهلك هذه العصابة من أهل الإسلام لا تُعبد في الأرض». فما زال كذلك حتى سقط رداؤه عن منكبيه، فأتاه أبو بكر فأخذ رداءه وقال: يا نبي الله كفاك مناشدتك ربك، فإنه سينجز لك ما وعدك. فأنزل الله: ﴿إِذْ تَسْتَغِيثُونَ رَبَّكُمْ فَاسْتَجَابَ لَكُمْ أَنِّي مُمِدُّكُم بِأَلْفٍ مِّنَ الْمَلَائِكَةِ مُرْدِفِينَ﴾. ثم بدأت المعركة بمبارزة، فبرز ثلاثة من قريش هم عتبة وشيبة والوليد، فخرج لهم حمزة وعلي وعبيدة بن الحارث رضي الله عنهم."], ["المعركة والملائكة", "اشتد القتال وثبت المسلمون على أمر ربهم، وأمدهم الله بالملائكة كما نص القرآن، وروى مسلم عن ابن عباس رضي الله عنهما أن رجلًا من المسلمين كان يشتد في أثر رجل من المشركين أمامه، إذ سمع ضربة بالسوط فوقه وصوت الفارس يقول: أقدمْ حيزوم، فنظر إلى المشرك فإذا هو قد خرّ مستلقيًا. وقُتل أبو جهل، فعدا عليه غلامان من الأنصار هما معاذ بن عمرو بن الجموح ومعاذ بن عفراء رضي الله عنهما، ثم أجهز عليه عبد الله بن مسعود رضي الله عنه، كما في الصحيحين. وقتل بلال رضي الله عنه أمية بن خلف الذي كان يعذبه في مكة. وانهزم جيش قريش وقد قُتل منهم سبعون وأُسر سبعون، كما في صحيح البخاري عن البراء، واستشهد من المسلمين أربعة عشر على المشهور."], ["الأسرى والنتائج", "بعد المعركة وقف النبي ﷺ على القَليب، وهي البئر التي أُلقي فيها قتلى قريش، وخاطبهم بأسمائهم: «هل وجدتم ما وعدكم ربكم حقًّا؟ فإني وجدتُ ما وعدني ربي حقًّا». فقال عمر رضي الله عنه: كيف تكلم أجسادًا لا أرواح لها؟ فقال: «ما أنتم بأسمع لما أقول منهم»، كما في الصحيحين. واستشار النبي ﷺ أبا بكر وعمر في الأسرى، فأشار أبو بكر بالفداء، وأشار عمر بالقتل، فمال النبي ﷺ إلى رأي أبي بكر، ثم نزل قوله تعالى: ﴿مَا كَانَ لِنَبِيٍّ أَن يَكُونَ لَهُ أَسْرَىٰ حَتَّىٰ يُثْخِنَ فِي الْأَرْضِ﴾، كما في صحيح مسلم. وقد سمّى الله هذا اليوم يوم الفرقان، لأنه فرّق بين الحق والباطل، وأرسى قوة المسلمين في الجزيرة العربية."]], "lesson": ["النصر من عند الله وحده، والأخذ بالأسباب لا يغني عن الدعاء والاستغاثة به.", "الشورى والاستماع لرأي الأتباع من أخلاق القيادة الراشدة، كما استشار النبي ﷺ أصحابه.", "القلة المؤمنة بالله تغلب الكثرة إذا صدقت وصبرت وأعدّت ما استطاعت.", "العدل والرحمة في التعامل مع الأسرى، وضرورة الموازنة بين المصلحة والرحمة."], "cat": "seerah"}, {"id": "sr19", "title": "غزوة أحد", "type": "من السيرة النبوية", "verse": "وَلَا تَهِنُوا وَلَا تَحْزَنُوا وَأَنتُمُ الْأَعْلَوْنَ إِن كُنتُم مُّؤْمِنِينَ", "source": "سورة آل عمران 3:139", "parts": [["الاستعداد للثأر", "بعد هزيمة قريش في بدر امتلأت قلوبهم غيظًا، وقرروا الأخذ بالثأر، فجمع أبو سفيان العدة، وخرجت قريش في شوال من السنة الثالثة للهجرة بجيش كبير على المشهور نحو ثلاثة آلاف، ومعهم نساء يحرّضن على القتال. فنزلوا قرب المدينة عند جبل أحد. وكان النبي ﷺ قد رأى رؤيا تعبّر عن المصير القريب، وتروي كتب السيرة أنه رأى بقرًا تُذبح وثلمة في سيفه، وأنه أوّلها بقتل بعض أصحابه، فاستشار أصحابه هل يبقون في المدينة أم يخرجون لقتال المشركين. فرأى هو البقاء في المدينة، لكن كثيرًا من الصحابة، ولا سيما الشباب الذين فاتهم بدر، أحبوا الخروج، فنزل عند رأيهم."], ["الخروج وانسحاب المنافقين", "دخل النبي ﷺ بيته ولبس لأمته، فلما رأى الصحابة أنهم أكرهوه ندموا وقالوا: اصنع ما شئت، فقال: «ما ينبغي لنبي إذا لبس لأمته أن يضعها حتى يقاتل»، كما رواه أحمد وصححه الحاكم. فخرج في نحو ألف، وتذكر كتب السيرة أن عبد الله بن أبي بن سلول رجع بنحو ثلث الجيش، بحجة أن النبي ﷺ لم يأخذ برأيه، فبقي نحو سبعمائة. وقد أشار القرآن إلى هذا الموقف فقال: ﴿وَلِيَعْلَمَ الَّذِينَ نَافَقُوا﴾، وبيّن الله أن الطائفتين من المؤمنين همّتا أن تفشلا لولا أن الله وليهما. فمضى النبي ﷺ بمن بقي، وصفّ أصحابه تحت جبل أحد يجعلون ظهورهم إليه، وهو يعدّهم للقتال."], ["الرماة على الجبل", "أمر النبي ﷺ خمسين من الرماة أن يقفوا على الجبل خلف جيش المسلمين، وجعل عليهم عبد الله بن جبير رضي الله عنه، كما في صحيح البخاري عن البراء بن عازب رضي الله عنه، وقال لهم: «إن رأيتمونا تخطّفنا الطير فلا تبرحوا مكانكم هذا حتى أرسل إليكم، وإن رأيتمونا هزمنا القوم وأوطأناهم فلا تبرحوا حتى أرسل إليكم». وكان الغرض من ذلك حماية ظهر المسلمين من خيّالة قريش، وعلى رأسهم خالد بن الوليد، وكان يومئذ على دين قومه. ولما بدأت المعركة ثبت المسلمون وأبلوا بلاءً حسنًا، وقاتل أبو دجانة بسيف النبي ﷺ وعليٌّ وحمزة وغيرهما، حتى انكشف المشركون وفرّوا، وانتشر المسلمون يجمعون الغنائم."], ["نزول الرماة وانقلاب المعركة", "روى البخاري أن البراء رضي الله عنه قال: فلما لقينا المشركين هربوا حتى رأيتُ النساء يشتددن في الجبل، يرفعن عن سوقهن قد بدت خلاخلهن. فأخذوا يقولون: الغنيمة الغنيمة. فقال عبد الله بن جبير: عهد إليّ النبي ﷺ ألا تبرحوا. فأبى أكثرهم، فنزلوا، فلما أبوا صُرفت وجوههم، فأصيب سبعون قتيلًا. ورأى خالد بن الوليد الثغرة، فالتفّ بخيله من وراء الجبل وقتل من بقي من الرماة، وانقضّ على المسلمين من الخلف. وقد نزل في هذا قوله تعالى: ﴿وَلَقَدْ صَدَقَكُمُ اللَّهُ وَعْدَهُ إِذْ تَحُسُّونَهُم بِإِذْنِهِ حَتَّىٰ إِذَا فَشِلْتُمْ وَتَنَازَعْتُمْ فِي الْأَمْرِ وَعَصَيْتُم مِّن بَعْدِ مَا أَرَاكُم مَّا تُحِبُّونَ﴾. فانقلب النصر ابتلاءً."], ["جراح النبي ﷺ وثبات الصحابة", "اشتد القتال على النبي ﷺ، وفي الصحيحين من حديث سهل بن سعد رضي الله عنه: «جُرح وجه النبي ﷺ، وكُسرت رباعيته، وهُشمت البيضة على رأسه، وكانت فاطمة بنت رسول الله ﷺ تغسل الدم وعلي بن أبي طالب يسكب عليها بالمجن، فلما رأت فاطمة أن الماء لا يزيد الدم إلا كثرة أخذت قطعة حصير فأحرقتها حتى صارت رمادًا ثم ألصقته بالجرح فاستمسك الدم». وحمى طلحة بن عبيد الله رضي الله عنه النبي ﷺ بجسده، قال قيس: رأيتُ يد طلحة شلاء وقى بها النبي ﷺ يوم أحد، رواه البخاري. واستشهد مصعب بن عمير رضي الله عنه، وأنس بن النضر رضي الله عنه قال: «واهًا لريح الجنة، أجده دون أحد»، فقاتل حتى قُتل، ووُجد فيه بضع وثمانون ضربة وطعنة ورمية."], ["شائعة مقتل النبي ﷺ", "وأشاع المشركون أن النبي ﷺ قد قُتل، فاضطرب كثير من المسلمين وتفرّقوا، وتروي كتب السيرة أن كعب بن مالك رضي الله عنه رأى النبي ﷺ فعرفه من عينيه تزهران تحت المغفر، فنادى بأعلى صوته: يا معشر المسلمين، أبشروا، هذا رسول الله ﷺ. فاجتمع إليه نفر منهم. ونزل القرآن يعالج هذا الأمر فقال: ﴿وَمَا مُحَمَّدٌ إِلَّا رَسُولٌ قَدْ خَلَتْ مِن قَبْلِهِ الرُّسُلُ أَفَإِيْن مَّاتَ أَوْ قُتِلَ انقَلَبْتُمْ عَلَىٰ أَعْقَابِكُمْ﴾. وقُتل حمزة رضي الله عنه، قتله وحشي بن حرب بحربة، كما في صحيح البخاري، وأسلم وحشي بعد ذلك. وتذكر كتب السيرة أن هندًا زوج أبي سفيان مثّلت به، وحزن النبي ﷺ لذلك حزنًا شديدًا."], ["النتائج والدروس", "وفي آخر النهار نادى أبو سفيان: أفي القوم محمد؟ فنهاهم النبي ﷺ عن الجواب، ثم قال: اعلُ هبل. فقال النبي ﷺ لأصحابه: «ألا تجيبونه؟» فقالوا: ما نقول؟ قال: «قولوا: الله أعلى وأجل». فقال أبو سفيان: لنا العزّى ولا عزّى لكم. فقال: «ألا تجيبونه؟ قولوا: الله مولانا ولا مولى لكم». وقال أبو سفيان: يوم بيوم بدر والحرب سجال، كما في صحيح البخاري. ودفن الشهداء، وكان يجمع بين الرجلين في قبر ويقول: «أيهم أكثر أخذًا للقرآن؟». وفي اليوم التالي خرج النبي ﷺ بمن بقي لمطاردة قريش إلى حمراء الأسد، فقالوا: ﴿حَسْبُنَا اللَّهُ وَنِعْمَ الْوَكِيلُ﴾، فألقى الله الرعب في قلوب المشركين فرجعوا. وقال النبي ﷺ: «أحد جبل يحبنا ونحبه»."]], "lesson": ["طاعة القائد في الأمور العسكرية والتنظيمية سبب النصر، ومخالفة الأمر سبب الهزيمة ولو كانت لدنيا يسيرة.", "الابتلاء بعد النصر تمحيص للمؤمنين وتمييز لهم عن المنافقين.", "الصحابة بشر يخطئون، ورباطة جأشهم وعودتهم بعد الخطأ مثال في الثبات والتوبة.", "النبي ﷺ يتعلم أصحابه الثقة بالله وعدم اليأس، فخرج في اليوم التالي بمن جُرح لمطاردة العدو."], "cat": "seerah"}, {"id": "sr20", "title": "غزوة الخندق (الأحزاب) وبنو قريظة", "type": "من السيرة النبوية", "verse": "يَا أَيُّهَا الَّذِينَ آمَنُوا اذْكُرُوا نِعْمَةَ اللَّهِ عَلَيْكُمْ إِذْ جَاءَتْكُمْ جُنُودٌ فَأَرْسَلْنَا عَلَيْهِمْ رِيحًا وَجُنُودًا لَّمْ تَرَوْهَا", "source": "سورة الأحزاب 33:9", "parts": [["تحزّب الأحزاب", "بعد إجلاء بني النضير عن المدينة خرج زعماؤهم، ومنهم حُيي بن أخطب، إلى مكة، فحرّضوا قريشًا على قتال النبي ﷺ ووعدوهم بالنصرة، ثم ذهبوا إلى غطفان وغيرهم، كما تذكر كتب السيرة. فاجتمعت قريش وغطفان ومن تبعهم، وتختلف الروايات في تاريخ الغزوة، فالمشهور أنها في شوال من السنة الخامسة للهجرة، وقيل في الرابعة. وبلغ عدد الأحزاب نحو عشرة آلاف على المشهور، والمسلمون نحو ثلاثة آلاف. وقد سمّى القرآن هذه الجموع الأحزاب، وسمّيت الغزوة الخندق بسبب الخندق الذي حُفر لحماية المدينة. ولم يكن للمسلمين طاقة بمواجهة هذه الجموع في الميدان المفتوح، فاحتاجوا إلى تدبير يمنع القتال المباشر."], ["فكرة الخندق", "استشار النبي ﷺ أصحابه، فأشار عليه سلمان الفارسي رضي الله عنه بحفر خندق حول المدينة، وهي طريقة معروفة عند الفرس لم يعهدها العرب، كما تذكر كتب السيرة، فأخذ النبي ﷺ برأيه. وكانت المدينة محاطة من جوانب عدة بالنخيل والبيوت المتلاصقة والحرّات، فكان الجانب الشمالي المفتوح هو المنفذ المحتمل للعدو، فحُفر الخندق فيه. وقد قسم النبي ﷺ العمل بين الصحابة وشارك بنفسه. وفي هذا درس في الاستفادة من الخبرة أيًّا كان مصدرها ما دامت لا تخالف الشرع، فسلمان رضي الله عنه لم يكن من العرب لكنه كان صاحب رأي نافع، وقد كان المسلمون يحبونه وينسبونه إلى آل البيت لفضله."], ["مشقة الحفر وآيات النبوة", "روى البخاري عن البراء رضي الله عنه أن النبي ﷺ كان ينقل التراب يوم الخندق حتى وارى التراب شعر صدره، وكان يرتجز برجز ابن رواحة: «اللهم لولا أنت ما اهتدينا». وروى عن أنس رضي الله عنه أنهم كانوا يقولون: «نحن الذين بايعوا محمدًا على الجهاد ما بقينا أبدًا»، فيجيبهم النبي ﷺ: «اللهم لا عيش إلا عيش الآخرة فأكرم الأنصار والمهاجرة». وفي حديث جابر رضي الله عنه في البخاري أنهم عرضت لهم كُدية، أي صخرة شديدة، فقالوا: هذه كدية عرضت في الخندق، فقام النبي ﷺ وبطنه معصوب بحجر من الجوع، فأخذ المعول فضرب فعاد كثيبًا أهيل، أي رملًا متفتتًا. وكانوا مكثوا ثلاثة أيام لا يذوقون ذواقًا."], ["طعام جابر", "وفي الحديث نفسه أن جابرًا رضي الله عنه لما رأى بالنبي ﷺ الخمص ذهب إلى امرأته فذبح عناقًا وطحنت شيئًا من الشعير، ثم جاء النبي ﷺ فسارّه: لقد ذبحنا بهيمة لنا وطحنت صاع شعير، فتعال أنت ونفر معك. فصاح النبي ﷺ: «يا أهل الخندق، إن جابرًا قد صنع سُورًا فحيّ هلا بكم»، وكانوا نحو ألف. فقال النبي ﷺ لجابر: «لا تنزلنّ برمتكم ولا تخبزنّ عجينكم حتى أجيء». فبصق في العجين وبارك، وفي البرمة وبارك، ثم قال: «ادعُ خابزة فلتخبز معك، واقدحي من برمتكم ولا تنزلوها». قال جابر: فأقسم بالله لقد أكلوا حتى تركوه وانحرفوا، وإن برمتنا لتغطّ كما هي. وهذا من دلائل النبوة وبركته ﷺ."], ["الحصار والابتلاء", "وصل الأحزاب فوجدوا الخندق، فقالوا: إن هذه لمكيدة ما كانت العرب تكيدها. وتذكر كتب السيرة أن نفرًا منهم، منهم عمرو بن عبد ودّ، اقتحموا موضعًا ضيقًا فبارزهم علي رضي الله عنه فقتل عمرًا. وطال الحصار وشُغل المسلمون بالقتال حتى فاتتهم صلاة العصر، ففي الصحيحين عن عليّ رضي الله عنه أن النبي ﷺ قال يوم الخندق: «ملأ الله بيوتهم وقبورهم نارًا، كما شغلونا عن الصلاة الوسطى حتى غابت الشمس». وصوّر القرآن المحنة بقوله: ﴿إِذْ جَاءُوكُم مِّن فَوْقِكُمْ وَمِنْ أَسْفَلَ مِنكُمْ وَإِذْ زَاغَتِ الْأَبْصَارُ وَبَلَغَتِ الْقُلُوبُ الْحَنَاجِرَ وَتَظُنُّونَ بِاللَّهِ الظُّنُونَا﴾، وقال المنافقون: ﴿مَّا وَعَدَنَا اللَّهُ وَرَسُولُهُ إِلَّا غُرُورًا﴾."], ["نقض بني قريظة وخذلان الأحزاب", "وكان بنو قريظة اليهود قد عاهدوا النبي ﷺ، فجاءهم حيي بن أخطب يحرضهم على نقض العهد، فنقضوه، وتذكر كتب السيرة أن النبي ﷺ أرسل من يستوثق فعلم صدق الخبر، وبذلك صارت المدينة مهددة من الداخل والخارج. وتروي كتب السيرة أن نعيم بن مسعود رضي الله عنه، وكان قد أسلم ولم يعلم قومه بإسلامه، أوقع الخلاف بين قريش وغطفان وقريظة. ثم أرسل الله على الأحزاب ريحًا باردة شديدة في ليلة شاتية، فأطفأت نيرانهم واقتلعت خيامهم، وفي صحيح مسلم أن حذيفة بن اليمان رضي الله عنه أرسله النبي ﷺ ليأتيه بخبر القوم، فرأى الريح تفعل بهم ما تفعل، ثم رجع أبو سفيان وارتحل الأحزاب. وقد دعا النبي ﷺ يومئذ: «اللهم منزل الكتاب، سريع الحساب، اهزم الأحزاب»."], ["بنو قريظة", "وفي الصحيحين أن النبي ﷺ قال بعد انصراف الأحزاب: «الآن نغزوهم ولا يغزوننا»، ثم رجع إلى المدينة، فوضع السلاح واغتسل، فأتاه جبريل عليه السلام وقال: وضعتَ السلاح؟ والله ما وضعناه، فاخرج إليهم. فأمر النبي ﷺ أصحابه ألا يصلين أحد العصر إلا في بني قريظة، فاختلفوا في فهم الأمر ولم يعنّف أحدًا منهم. وحاصرهم نحو شهر، ثم نزلوا على حكم سعد بن معاذ رضي الله عنه، وكان من حلفائهم القدامى، فقال النبي ﷺ: «قوموا إلى سيدكم». فحكم أن تُقتل المقاتلة وتُسبى الذرية والنساء وتقسم الأموال، فقال النبي ﷺ: «لقد حكمتَ فيهم بحكم الله»، كما في الصحيحين. وكان ذلك جزاء الخيانة العظمى زمن الحرب، وتختلف الروايات في عدد من قُتل منهم. وتوفي سعد رضي الله عنه متأثرًا بجرحه، وقال النبي ﷺ: «اهتزّ عرش الرحمن لموت سعد بن معاذ»."]], "lesson": ["الأخذ بالأسباب والتخطيط الجماعي والاستفادة من خبرة الآخرين، فالخندق فكرة جاءت من سلمان رضي الله عنه.", "القائد يشارك أتباعه في الشدة، فقد حفر النبي ﷺ معهم وربط الحجر على بطنه من الجوع.", "الخيانة في وقت الحرب جريمة عظيمة لها حكم خاص، والعهود يجب الوفاء بها.", "النصر الحقيقي من عند الله، فهو الذي أرسل الريح والجنود وهزم الأحزاب وحده."], "cat": "seerah"}, {"id": "sr21", "title": "صلح الحديبية وبيعة الرضوان", "type": "من السيرة النبوية", "verse": "لَقَدْ رَضِيَ اللَّهُ عَنِ الْمُؤْمِنِينَ إِذْ يُبَايِعُونَكَ تَحْتَ الشَّجَرَةِ", "source": "سورة الفتح 48:18", "parts": [["الخروج إلى مكة معتمرًا", "في شهر ذي القعدة من السنة السادسة للهجرة خرج النبي ﷺ من المدينة يريد العمرة، ومعه جمع من أصحابه رضي الله عنهم لا يحملون إلا سلاح المسافر، وساقوا معهم الهدي ليعلم الناس أنهم جاؤوا زائرين معظّمين للبيت لا محاربين. وقد جاء في صحيح البخاري عن جابر رضي الله عنه أنهم كانوا ألفًا وأربعمائة، وجاء في روايات أخرى أنهم كانوا ألفًا وخمسمائة، وتختلف الروايات في عددهم. وأحرموا من ذي الحليفة، وقلّد النبي ﷺ الهدي وأشعره. وكان أهل المدينة قد اشتاقوا إلى البيت الحرام بعد ست سنين من الفراق، وفيهم المهاجرون الذين أُخرجوا من ديارهم. وبعث النبي ﷺ عينًا له من خزاعة يأتيه بخبر قريش، فلما بلغ موضعًا قريبًا من عسفان جاءه الخبر بأن قريشًا جمعت الجموع وخرجت لتصدّه عن البيت، وأن خالد بن الوليد، وكان يومئذ على كفره، في خيل لهم بالمقدمة قرب كراع الغميم."], ["ناقة تبرك وطريق جديد", "أراد النبي ﷺ أن يتجنب القتال، فسأل عن رجل يدلّه على طريق غير الطريق التي فيها خيل قريش، فسلك بهم طريقًا وعرة بين الشِّعاب حتى خرجوا منها إلى أرض سهلة. ورأى خالد غبار الجيش، فأسرع راجعًا إلى قريش ينذرهم. ثم لما بلغ النبي ﷺ الثنية التي تهبط على الحديبية بركت ناقته القصواء، فقال الناس: خلأت القصواء، أي حرنت. فقال النبي ﷺ: «ما خلأت القصواء، وما ذاك لها بخُلُق، ولكن حبسها حابس الفيل»، كما في صحيح البخاري. ثم قال: «والذي نفسي بيده لا يسألوني خطة يعظّمون فيها حرمات الله إلا أعطيتهم إياها». فهو ﷺ يعلن أنه مستعد لقبول كل ما فيه تعظيم حرمة الحرم وحقن الدماء، حتى لو كان في ظاهره تنازل. ثم نزل بأقصى الحديبية، وهي موضع قريب من مكة بعضه في الحل وبعضه في الحرم، وكان فيها بئر قليلة الماء، فجاء الله لهم منها بما كفاهم كما جاء في صحيح البخاري."], ["الرسل بين الطرفين", "جاء بُدَيل بن ورقاء الخزاعي في نفر من قومه، فأخبرهم النبي ﷺ أنه لم يأتِ لقتال، وأن الحرب أضرّت بقريش، وأنه يعرض عليهم مدّة يتركونه فيها وسائر الناس. فرجع بُدَيل إلى قريش ينقل ما سمع. ثم بعثت قريش عروة بن مسعود الثقفي، فجلس إلى النبي ﷺ يكلمه، وجعل يتفرّس في أصحابه. وروى البخاري في حديث المسور بن مخرمة ومروان أنه رأى كيف كانوا لا يتوضأ النبي ﷺ إلا ابتدروا وضوءه، وإذا تكلم خفضوا أصواتهم عنده، وما يحدّون إليه النظر تعظيمًا له. فرجع إلى قريش وقال: يا معشر قريش، إني قد جئت كسرى في ملكه وقيصر في ملكه والنجاشي في ملكه، وإني والله ما رأيت ملكًا في قوم قط مثل محمد في أصحابه. وهذا الموقف يبيّن أن حب الصحابة رضي الله عنهم لنبيهم ﷺ كان حبًّا صادقًا عميقًا، شهد له به أحد ألدّ خصومه."], ["عثمان رضي الله عنه وبيعة الرضوان", "أراد النبي ﷺ أن يبعث إلى قريش من يبلّغهم مقصده، فدعا عمر رضي الله عنه، فاعتذر بأنه ليس بمكة من بني عدي من يحميه، ودلّ على عثمان بن عفان رضي الله عنه لعزّة قومه فيها، فأرسله النبي ﷺ. وأقام عثمان رضي الله عنه في مكة مدة، وشاع بين المسلمين أنه قُتل. فدعا النبي ﷺ أصحابه إلى البيعة تحت الشجرة، وقال: «لا نبرح حتى نناجز القوم». فبايعوه على ألا يفرّوا. وفي صحيح البخاري أنه ﷺ أخذ بيده وقال: «هذه عن عثمان»، فجعل يده عن يد عثمان بيعةً له. ونزل في أهل هذه البيعة قوله تعالى: ﴿لَقَدْ رَضِيَ اللَّهُ عَنِ الْمُؤْمِنِينَ إِذْ يُبَايِعُونَكَ تَحْتَ الشَّجَرَةِ فَعَلِمَ مَا فِي قُلُوبِهِمْ فَأَنزَلَ السَّكِينَةَ عَلَيْهِمْ﴾. وثبت في صحيح مسلم أن النبي ﷺ قال: «لا يدخل النار إن شاء الله من أصحاب الشجرة أحدٌ ممن بايع تحتها». ثم تبيّن أن خبر قتل عثمان رضي الله عنه لا أصل له، فعاد سالمًا."], ["نصّ الصلح وشروطه", "جاء سهيل بن عمرو من قريش للتفاوض، فلما رآه النبي ﷺ قال: «قد سهل لكم من أمركم». وتم الاتفاق على شروط ثبتت في صحيح البخاري: هدنة عشر سنين، وأن من أتى محمدًا ﷺ من قريش بغير إذن وليّه ردّه إليهم، ومن جاء قريشًا من أصحابه لم يردّوه، وأن يرجع النبي ﷺ هذا العام ويعود في العام القادم فيقيم ثلاثة أيام، وأن من أحب أن يدخل في عهد النبي ﷺ دخل ومن أحب أن يدخل في عهد قريش دخل. فدخلت خزاعة في عهده وبنو بكر في عهد قريش. وحين أمر عليًّا رضي الله عنه بالكتابة، قال: «اكتب: بسم الله الرحمن الرحيم»، فاعترض سهيل وطلب «باسمك اللهم»، فقبل النبي ﷺ. ثم كتب «هذا ما قاضى عليه محمد رسول الله»، فاعترض سهيل وقال: لو شهدنا أنك رسول الله ما قاتلناك. فأمر النبي ﷺ بمحو العبارة، فأبى علي رضي الله عنه، فمحاها النبي ﷺ بيده، وقبل أن يكتب «محمد بن عبد الله»."], ["غضب الصحابة وحكمة النبي ﷺ", "كانت الشروط ثقيلة على نفوس الصحابة رضي الله عنهم، فقد رجعوا من غير عمرة، وقُبل رد المسلم الفارّ بدينه إلى المشركين. وجاء في البخاري أن عمر رضي الله عنه أتى النبي ﷺ فقال: ألسنا على الحق؟ قال: «بلى». قال: فلِمَ نعطي الدنية في ديننا؟ فقال النبي ﷺ: «إني رسول الله ولستُ أعصيه، وهو ناصري». ثم أتى أبا بكر رضي الله عنه بمثل ذلك، فقال له أبو بكر: إنه لرسول الله، وليس يعصي ربه، وهو ناصره، فاستمسك بغرزه. وقد اعترف عمر رضي الله عنه بعد ذلك بأنه عمل لذلك أعمالًا، يعني من الصدقة والصوم والصلاة والعتق، خوفًا من كلامه يومئذ. ثم جاء أبو جندل بن سهيل رضي الله عنه يرسف في قيوده مسلمًا، فاستنكر المسلمون ردّه، فرُدّ إلى أبيه، ومعه الوعد من النبي ﷺ بأن الله جاعل له فرجًا ومخرجًا."], ["النحر والحلق وثمرات الصلح", "لما فرغ النبي ﷺ من كتاب الصلح قال لأصحابه: «قوموا فانحروا ثم احلقوا»، فما قام منهم رجل حتى قالها ثلاث مرات، لشدة ما أصابهم من الحزن. فدخل على أم سلمة رضي الله عنها وذكر لها ذلك، فأشارت عليه أن يخرج فلا يكلّم أحدًا منهم حتى ينحر هديه ويدعو حالقه فيحلق. ففعل، فلما رأوه قاموا ينحرون ويحلق بعضهم بعضًا، كما في صحيح البخاري. وفي طريق العودة نزلت سورة الفتح: ﴿إِنَّا فَتَحْنَا لَكَ فَتْحًا مُّبِينًا﴾، فقال عمر رضي الله عنه: أَوَفتحٌ هو يا رسول الله؟ قال: «نعم». وبعد أن استقرت الهدنة دخل الناس في الإسلام بكثرة لما أمنوا واختلطوا، حتى قال أهل العلم إن الصلح كان مقدمة الفتح الأكبر. وأما أبو بصير رضي الله عنه فقد جاء مسلمًا فرُدّ، فهرب واجتمع إليه المسلمون الفارّون في موضع على طريق قريش، فأخذوا يضيّقون عليهم، فطلبت قريش نفسها من النبي ﷺ إلغاء هذا الشرط. وعاد النبي ﷺ إلى المدينة، وقد تبيّنت عاقبة الصلح."]], "lesson": ["الحكمة قد تقتضي قبول ما تكرهه النفس إذا كان فيه تعظيم لحرمات الله وحقن للدماء ومصلحة بعيدة المدى.", "طاعة النبي ﷺ والرضا بقضاء الله من أعظم صور الإيمان، وقد رضي الله عن أهل بيعة الشجرة.", "استشارة الأهل مشروعة، ورأي أم سلمة رضي الله عنها فتح باب الحل في لحظة شديدة.", "ما يبدو ضياعًا قد يكون فتحًا، فقد سمّى الله صلح الحديبية فتحًا مبينًا."], "cat": "seerah"}, {"id": "sr22", "title": "خيبر ورسائل النبي ﷺ إلى الملوك وعمرة القضاء", "type": "من السيرة النبوية", "verse": "لَتَدْخُلُنَّ الْمَسْجِدَ الْحَرَامَ إِن شَاءَ اللَّهُ آمِنِينَ", "source": "سورة الفتح 48:27", "parts": [["السير إلى خيبر", "بعد أن رجع النبي ﷺ من الحديبية أقام في المدينة نحو شهر، ثم خرج إلى خيبر في المحرم من السنة السابعة على المشهور. وخيبر واحة كبيرة شمال المدينة فيها حصون كثيرة لليهود، وكانت مركز تحريض عليه، وقد كان لها أثر في تحريض الأحزاب على المدينة قبل ذلك. وخرج معه من شهد الحديبية رضي الله عنهم، ووعدهم الله في سورة الفتح بمغانم كثيرة يأخذونها. فلما بلغ خيبر وصلها ليلًا، ولم يُغِر حتى يصبح، فلما أصبح خرج أهلها بمكاتلهم ومساحيهم، فلما رأوا الجيش قالوا: محمد والخميس. فقال النبي ﷺ: «الله أكبر، خربت خيبر، إنا إذا نزلنا بساحة قوم فساء صباح المنذَرين»، كما في صحيح البخاري. ثم حاصر المسلمون حصونها واحدًا بعد واحد، وتصدّى لهم المقاتلون فيها بشدة، وفتح الله عليهم الحصون الواحد تلو الآخر."], ["راية علي رضي الله عنه", "أمضى المسلمون أيامًا في حصار حصون خيبر دون أن يفتحوا أقواها. ففي الصحيحين من حديث سهل بن سعد رضي الله عنه أن النبي ﷺ قال يوم خيبر: «لأعطينّ هذه الراية غدًا رجلًا يفتح الله على يديه، يحب الله ورسوله ويحبه الله ورسوله». فبات الناس يدوكون ليلتهم أيهم يعطاها، فلما أصبحوا غدوا كلهم يرجو أن يعطاها. فقال: «أين علي بن أبي طالب؟» فقيل: هو يشتكي عينيه. فأرسلوا إليه فجيء به، فبصق النبي ﷺ في عينيه ودعا له، فبرأ كأن لم يكن به وجع، فأعطاه الراية. وقال له: «انفُذْ على رِسلك حتى تنزل بساحتهم، ثم ادعهم إلى الإسلام، وأخبرهم بما يجب عليهم من حق الله فيه، فوالله لأن يهدي الله بك رجلًا واحدًا خير لك من حُمر النعم». وفتح الله على يديه الحصن، وفي هذا فضيلة ظاهرة لعلي رضي الله عنه، ودرس في أن الغاية هداية الناس لا غلبتهم."], ["الأرض والشاة المسمومة", "لما فُتحت الحصون وسلّم أهل خيبر طلبوا من النبي ﷺ أن يتركهم يعملون في الأرض ولهم نصف ما يخرج منها، فأقرّهم على ذلك ما شاء الله، كما في الصحيحين، ثم أخرجهم عمر رضي الله عنه من خيبر بعد ذلك في خلافته. وفي هذه الغزوة وقعت حادثة الشاة المسمومة، فقد ثبت في صحيح البخاري عن أبي هريرة رضي الله عنه أن امرأة يهودية أهدت إلى النبي ﷺ شاة فيها سمّ، فلما قدمت أُخبر النبي ﷺ بأمرها وسُئلت عن فعلها، فقالت: أردت أن أقتلك. فقال: «ما كان الله ليسلّطك على ذاك». ولم يعاقبها النبي ﷺ في تلك الحال، وتختلف الروايات في مصيرها بعد ذلك، فقيل عفا عنها وقيل قُتلت قصاصًا لما مات بعض الصحابة من أكلها. وكان النبي ﷺ يجد أثر ذلك السمّ في مرضه الأخير. وكان فيمن سُبي من خيبر صفية بنت حيي رضي الله عنها، فأعتقها النبي ﷺ وتزوجها."], ["رسائل النبي ﷺ إلى الملوك", "بعد الحديبية اطمأن النبي ﷺ إلى الهدنة، فاتجه إلى دعوة الملوك المحيطين بالجزيرة إلى الإسلام. وفي صحيح البخاري أنه لما أراد أن يكتب إلى الروم قيل له إنهم لا يقرؤون كتابًا إلا مختومًا، فاتخذ خاتمًا من فضة نقشه «محمد رسول الله». فأرسل الكتب مع رسل من أصحابه، فبعث دحية بن خليفة الكلبي رضي الله عنه إلى عظيم بصرى ليوصله إلى هرقل، وبعث غيره إلى كسرى فارس وإلى النجاشي ملك الحبشة وإلى المقوقس صاحب مصر وإلى غيرهم. وأخبر أنس رضي الله عنه في صحيح مسلم أن النبي ﷺ كتب إلى كسرى وقيصر والنجاشي وإلى كل جبار يدعوهم إلى الله تعالى. وكان في ذلك إعلان صريح بأن الإسلام رسالة عامة للعالم، لا لقوم بعينهم ولا لأرض بعينها، وأن النبي ﷺ يخاطب الدول الكبرى بأدب وحزم دون خوف ولا تردد."], ["كتابه إلى هرقل وجواب الملوك", "روى البخاري نص كتاب النبي ﷺ إلى هرقل: «بسم الله الرحمن الرحيم، من محمد عبد الله ورسوله إلى هرقل عظيم الروم، سلام على من اتبع الهدى، أما بعد، فإني أدعوك بدعاية الإسلام، أسلم تسلم، يؤتك الله أجرك مرتين، فإن توليت فإن عليك إثم الأريسيين». ثم ختمه بقوله تعالى: ﴿يَا أَهْلَ الْكِتَابِ تَعَالَوْا إِلَىٰ كَلِمَةٍ سَوَاءٍ بَيْنَنَا وَبَيْنَكُمْ﴾ الآية. وكان أبو سفيان بالشام تاجرًا وقتها، فاستدعاه هرقل وسأله عن النبي ﷺ أسئلة، ثم أقرّ بصدق ما سمع. وأما كسرى فقد مزّق كتاب النبي ﷺ، فقال النبي ﷺ: «مزّق الله ملكه»، كما في صحيح البخاري عن ابن عباس رضي الله عنهما. وأما المقوقس فردّ ردًّا رقيقًا وأهدى إلى النبي ﷺ هدايا، ولم يُعرف أنه أسلم. وتختلف الروايات في مواقف بعض الملوك وفي تفاصيل أخبار رسلهم، وأصحّ ما ثبت هو ما في الصحيحين."], ["النجاشي وأثر الرسائل", "كان النجاشي أصحمة ملك الحبشة قد أحسن استقبال المهاجرين الأوائل، وجاء في صحيح مسلم أن النبي ﷺ كتب إلى النجاشي ضمن من كتب إليهم. وتواترت الأخبار الصحيحة بإسلام النجاشي رضي الله عنه، فلما مات صلى عليه النبي ﷺ صلاة الغائب، وأخبر الصحابة بموته في اليوم الذي مات فيه، كما في الصحيحين عن أبي هريرة رضي الله عنه. وأما هرقل فقد ظهرت عليه علامات التصديق، لكنه خاف على ملكه، فبقي على دينه. وبهذا ظهر أن الرسائل لم تذهب سدًى، بل وصلت الدعوة إلى القصور ثم إلى الشعوب، وتهيأ المناخ لما سيأتي من فتوح بعد وفاة النبي ﷺ. وكان للصلح مع قريش أثر مباشر في ذلك، فإنه لما أمن جانب مكة تفرّغ النبي ﷺ لمخاطبة العالم، وهكذا كان صلح الحديبية بابًا لخير أوسع مما ظنه الناس يوم عقد."], ["عمرة القضاء", "في ذي القعدة من السنة السابعة خرج النبي ﷺ ومعه المسلمون لأداء العمرة التي صُدّوا عنها في العام الماضي، وفاءً بما اتفقوا عليه في صلح الحديبية. وفي هذا قال تعالى: ﴿لَتَدْخُلُنَّ الْمَسْجِدَ الْحَرَامَ إِن شَاءَ اللَّهُ آمِنِينَ﴾. وخرجت قريش من مكة إلى رؤوس الجبال، كما ذكر أهل السير، لتتجنب رؤية دخول المسلمين، فدخل النبي ﷺ والمسلمون، وطافوا بالبيت وسعوا بين الصفا والمروة، وأقاموا ثلاثة أيام كما اشترط الاتفاق. وعن ابن عمر رضي الله عنهما في البخاري أن النبي ﷺ اعتمر أربع عمر، إحداها في ذي القعدة، وقد سُميت عمرة القضاء لأنه قاضى قريشًا عليها، وقيل لأنها قضاء عن عمرة الحديبية. وتزوج في هذه الفترة ميمونة بنت الحارث رضي الله عنها، وتختلف الروايات هل كان محرمًا عند عقد النكاح أم حلالًا. وبعد انقضاء الأيام الثلاثة غادر مكة وفاءً بالعهد، فكان ذلك درسًا في أن الوفاء بالعهود من أخلاق هذا الدين."]], "lesson": ["الدعوة إلى الله تتجاوز الحدود، وقد خاطب النبي ﷺ الملوك برسائل واضحة مهذبة تجمع بين الحق والأدب.", "الله ينصر عباده بأسباب يحبونها وأخرى يكرهونها، فقد فتح خيبر بعد أن غُلب أهلها على أمرهم، وبقي النبي ﷺ على ثقة بربه.", "الوفاء بالعهد قيمة ثابتة، فقد غادر النبي ﷺ مكة بعد الأيام الثلاثة حسب الاتفاق.", "التوكل على الله لا ينافي الأخذ بالأسباب، فقد اتخذ النبي ﷺ خاتمًا ليُقبل كتابه عند الملوك."], "cat": "seerah"}, {"id": "sr23", "title": "غزوة مؤتة", "type": "من السيرة النبوية", "verse": "إِنَّ اللَّهَ اشْتَرَىٰ مِنَ الْمُؤْمِنِينَ أَنفُسَهُمْ وَأَمْوَالَهُم بِأَنَّ لَهُمُ الْجَنَّةَ", "source": "سورة التوبة 9:111", "parts": [["سبب الغزوة", "في جمادى الأولى من السنة الثامنة للهجرة بعث النبي ﷺ جيشًا إلى أطراف الشام عند موضع يقال له مؤتة، في أرض البلقاء شرق الأردن. وذكر أهل السير، ومنهم ابن إسحاق وابن كثير، أن سبب البعث أن النبي ﷺ أرسل الحارث بن عمير الأزدي رضي الله عنه بكتاب إلى حاكم بصرى، فاعترضه شرحبيل بن عمرو الغساني فقتله، وكان قتل الرسل من أعظم الجرائم عند الناس جميعًا. وكان القتل في أرض تابعة لنفوذ الروم، والغساسنة عرب نصارى حلفاء لهم. فجهّز النبي ﷺ جيشًا كبيرًا بحسب حال المسلمين يومئذ، فذكر أهل السير أنهم ثلاثة آلاف مقاتل. وكان هذا أكبر جيش جهزه النبي ﷺ خارج الجزيرة العربية إلى ذلك الوقت، وهو أول لقاء للمسلمين مع الروم وأتباعهم. وخرج الصحابة رضي الله عنهم يودّعهم النبي ﷺ إلى ثنية الوداع، ويوصيهم بالصبر والإحسان."], ["الأمراء الثلاثة", "ثبت في صحيح البخاري عن عبد الله بن عمر رضي الله عنهما أن النبي ﷺ أمّر على جيش مؤتة زيد بن حارثة رضي الله عنه، وقال: «إن قُتل زيد فجعفر، وإن قُتل جعفر فعبد الله بن رواحة». وكان زيد مولى النبي ﷺ الذي تبنّاه قبل الإسلام، وهو الصحابي الوحيد الذي سُمي في القرآن باسمه. وكان جعفر بن أبي طالب رضي الله عنه ابن عمّ النبي ﷺ وقد هاجر إلى الحبشة ثم عاد إلى المدينة قبل هذه الغزوة. وكان ابن رواحة رضي الله عنه شاعر الأنصار وأحد النقباء ليلة العقبة. وهذا التدرّج في القيادة يدل على أن النبي ﷺ أدرك خطر المهمة، فأوصى بتسلسل الأمراء حتى لا يختلّ الجيش إذا سقط قائده. وأوصاهم أن يدعوا الناس أولًا إلى الإسلام، وألا يقتلوا امرأة ولا صبيًّا ولا شيخًا فانيًا ولا راهبًا في صومعته، وألا يقطعوا شجرة ولا يهدموا بناءً، كما ورد في وصاياه لجيوشه."], ["اللقاء عند مؤتة", "سار الجيش حتى نزل بمعان من أرض الشام، فبلغهم أن الروم قد جمعت لهم جموعًا عظيمة، وتختلف الروايات في عددها اختلافًا كبيرًا، لكنها كانت أضعاف جيش المسلمين. فتشاوروا في أن يكتبوا إلى النبي ﷺ يخبرونه بكثرة العدو، لينتظروا مددًا أو أمرًا جديدًا. فشجّعهم عبد الله بن رواحة رضي الله عنه وقال: يا قوم، والله إن التي تكرهون للتي خرجتم تطلبون، الشهادة، وما نقاتل الناس بعدد ولا قوة ولا كثرة، ما نقاتلهم إلا بهذا الدين الذي أكرمنا الله به. فقالوا: قد والله صدق ابن رواحة. وهذا النقل من كتب السير، ومعناه يوافق ما ثبت من حال الصحابة رضي الله عنهم. ثم مضوا حتى لقيهم العدو عند مؤتة، فاصطفّ الفريقان، وبدأ القتال، وهو قتال عنيف غير متكافئ في العدد."], ["استشهاد القادة", "أخذ زيد بن حارثة رضي الله عنه الراية وقاتل بها حتى قُتل. ثم أخذها جعفر رضي الله عنه فقاتل قتالًا شديدًا، وقُطعت يداه كما ذكر أهل السير. وروى البخاري عن ابن عمر رضي الله عنهما أنه قال: كنت فيهم في تلك الغزوة، فالتمسنا جعفر بن أبي طالب فوجدناه في القتلى، ووجدنا ما في جسده بضعًا وتسعين من طعنة ورمية. وكان ابن عمر رضي الله عنهما إذا سلّم على ابن جعفر قال: السلام عليك يا ابن ذي الجناحين. ثم أخذ الراية عبد الله بن رواحة رضي الله عنه فتقدّم فقاتل حتى قُتل. وأقام الله لنبيّه ﷺ دليلًا من دلائل النبوة، فقد نعى القادة الثلاثة إلى الناس وهو في المدينة قبل أن يأتي خبرهم. قال أنس رضي الله عنه في البخاري: إن النبي ﷺ نعى زيدًا وجعفرًا وابن رواحة قبل أن يأتيهم خبرهم، فقال: «أخذ الراية زيد فأصيب، ثم أخذ جعفر فأصيب، ثم أخذ ابن رواحة فأصيب»، وعيناه تذرفان."], ["سيف الله خالد بن الوليد", "بعد استشهاد الأمراء الثلاثة اختار المسلمون خالد بن الوليد رضي الله عنه قائدًا، وكان قد أسلم قبل أشهر. وقال النبي ﷺ في الحديث الذي رواه البخاري: «ثم أخذ الراية سيف من سيوف الله حتى فتح الله عليهم». وروى البخاري عن خالد رضي الله عنه أنه قال: لقد دُقّ في يدي يوم مؤتة تسعة أسياف، فما بقي في يدي إلا صفيحة يمانية. فقاتل قتالًا قويًّا، ثم أحسن الانسحاب بالجيش حتى حفظه من الفناء. وتختلف الروايات في نتيجة المعركة، فبعض أهل السير ذكر أنه كان انسحابًا بحكمة، وذكر ابن كثير والحافظ ابن حجر رحمهما الله أن الأقرب أن خالدًا رضي الله عنه حاول المناورة حتى تفرّق العدو عن المسلمين وانصرف كل فريق. وتقرّر في هذا الموقف أن حفظ الجيش وأرواح المسلمين مقصد معتبر في الحرب، وأن حسن القيادة قد يصنع من موقف صعب نجاةً."], ["العودة وأثر الغزوة", "عاد المسلمون إلى المدينة، وقد استقبلهم بعض الناس بالتعيير على ما رأوه تراجعًا، لكن النبي ﷺ كان يعلم ما جرى وما فيه من حكمة. وحزن النبي ﷺ على جعفر وزيد وابن رواحة رضي الله عنهم حزنًا شديدًا. ولما جاء خبر جعفر أمر النبي ﷺ أن يُصنع لآل جعفر طعام، وقال: «اصنعوا لآل جعفر طعامًا، فقد أتاهم ما يشغلهم»، رواه أبو داود والترمذي وغيرهما بإسناد حسن. وفي هذا تعليم للمسلمين أن يُكرَم أهل الميت بالطعام في أول أيام مصيبتهم. وكان لمؤتة أثر في هيبة المسلمين عند قبائل العرب القريبة من الشام، فقد رأوا أن المسلمين يواجهون الروم ولا يخشونهم، وتهيّأ ذلك لغزوة تبوك. كما كانت أول معركة استشهد فيها هذا العدد من كبار الصحابة، فكانت مدرسة في التضحية والثبات عند القتال."]], "lesson": ["الإيمان يدفع صاحبه إلى الإقدام حين يرى الشهادة غاية، ولا يجعل العدد وحده ميزان الحسم.", "تنظيم القيادة بتسلسل أمراء يحفظ الصف عند فقد القائد، وهذا من حكمة النبي ﷺ.", "حفظ النفوس مقصد شرعي، وقد يكون حسن الانسحاب أفضل من الإصرار على فناء الجيش.", "مواساة أهل الميت بالطعام والعون من السنة، فهي أحق ما يقدَّم لأهل المصاب."], "cat": "seerah"}, {"id": "sr24", "title": "فتح مكة", "type": "من السيرة النبوية", "verse": "إِذَا جَاءَ نَصْرُ اللَّهِ وَالْفَتْحُ", "source": "سورة النصر 110:1", "parts": [["نقض قريش للعهد", "كان صلح الحديبية قد جعل خزاعة في عهد النبي ﷺ وبني بكر في عهد قريش. وفي السنة الثامنة اعتدى بنو بكر على خزاعة ليلًا قرب مكة، وأعانتهم قريش بالسلاح، وبعض رجالها شارك سرًّا في القتال. فخرج عمرو بن سالم الخزاعي إلى المدينة يستنصر النبي ﷺ ويذكّره بالحلف، كما ذكر ابن إسحاق وابن كثير. وقال له النبي ﷺ: «نُصرتَ يا عمرو بن سالم». وخافت قريش من عاقبة ما صنعت، فأرسلت أبا سفيان إلى المدينة ليجدد العهد ويزيد في مدته، فلم يجد عند النبي ﷺ جوابًا مقبولًا، فرجع خائبًا. وهكذا بعد نحو سنتين من الصلح انتقضت الهدنة بفعل قريش لا بفعل المسلمين، وصار للنبي ﷺ حق ظاهر في السير إلى مكة. وكان يعلم أن البيت الحرام يجب أن يعود إلى التوحيد، وأن يُحقن الدم فيه ما أمكن."], ["الإعداد السري وحاطب", "أمر النبي ﷺ أصحابه بالتجهّز دون أن يخبرهم بوجهته، ودعا الله أن يأخذ العيون والأخبار عن قريش حتى يبغتها في بلدها. وفي صحيح البخاري قصة حاطب بن أبي بلتعة رضي الله عنه، فقد كتب إلى قريش كتابًا يخبرهم بمسير النبي ﷺ، وأرسله مع امرأة. فأوحى الله إلى نبيه ﷺ بذلك، فبعث عليًّا والزبير والمقداد رضي الله عنهم، فأدركوا المرأة في روضة خاخ وأخذوا الكتاب. فسأل النبي ﷺ حاطبًا: «ما حملك على ما صنعت؟» فقال: ما بي إلا أن أكون مؤمنًا بالله ورسوله، ولكني أردت أن تكون لي عند القوم يد يدفع الله بها عن أهلي ومالي. فقال النبي ﷺ: «صدق»، فقال عمر رضي الله عنه: دعني أضرب عنقه. فقال النبي ﷺ: «إنه شهد بدرًا، وما يدريك لعل الله اطلع على أهل بدر فقال اعملوا ما شئتم فقد غفرت لكم». ونزل في ذلك صدر سورة الممتحنة."], ["الجيش في مرّ الظهران", "خرج النبي ﷺ من المدينة في العاشر من رمضان على المشهور، في عشرة آلاف من الصحابة رضي الله عنهم، كما جاء في صحيح البخاري عن ابن عباس رضي الله عنهما، ولحقت به قبائل أخرى في الطريق. وكان النبي ﷺ وأصحابه صائمين، فلما بلغ الكديد أفطر. فلما نزلوا مرّ الظهران، وهو موضع قريب من مكة، أوقد الجيش نيرانًا كثيرة، وكانت قريش لا تدري ما يجري. وخرج أبو سفيان وبعض رجالها يستطلعون، فلقيهم العباس رضي الله عنه، وكان قد لحق بالنبي ﷺ، فأخذ أبا سفيان إلى النبي ﷺ. وتروي كتب السيرة أنه أسلم تلك الليلة، فقال النبي ﷺ: «من دخل دار أبي سفيان فهو آمن، ومن أغلق عليه بابه فهو آمن، ومن دخل المسجد فهو آمن»، وقد ثبت معناه في صحيح مسلم. وفي هذا استمالة لقلب رجل يحب الشرف، ورفق بأهل مكة يقلل القتال."], ["دخول مكة", "دخل النبي ﷺ مكة يوم الفتح من أعلاها، وكانت راية المسلمين على أطرافها، وأمر القادة ألا يقاتلوا إلا من قاتلهم. وجاء في صحيح البخاري عن أنس رضي الله عنه أن النبي ﷺ دخل مكة يوم الفتح وعلى رأسه المغفر، فلما نزعه جاءه رجل فقال: ابن خطل متعلق بأستار الكعبة، فقال: «اقتلوه». وفي حديث آخر عن أنس رضي الله عنه أنه دخل مكة وذقنه على رحله متخشعًا، أي مطأطئًا رأسه تواضعًا لله حين رأى نعمة الفتح. وروى البخاري عن عبد الله بن مغفل رضي الله عنه أنه كان يقرأ سورة الفتح على راحلته. فقد دخل فاتحًا لكن في صورة العبد الشاكر، لا الجبّار المنتصر. ولم يقع قتال يُذكر إلا في ناحية واحدة، حين صدّ بعض المشركين جيش خالد بن الوليد رضي الله عنه، فقتلوا نفرًا من المسلمين، وقُتل من المشركين عدد، ثم انتهت المقاومة."], ["تطهير الكعبة", "دخل النبي ﷺ المسجد الحرام وطاف بالبيت على راحلته، وحول الكعبة ثلاثمائة وستون صنمًا، فجعل يطعنها بعود في يده ويقول: ﴿جَاءَ الْحَقُّ وَزَهَقَ الْبَاطِلُ إِنَّ الْبَاطِلَ كَانَ زَهُوقًا﴾، فتسقط الأصنام، كما في الصحيحين عن ابن مسعود رضي الله عنه. وأمر النبي ﷺ بالتصاوير التي في الكعبة فمُحيت. ثم أخذ مفتاح الكعبة من عثمان بن طلحة رضي الله عنه، ودخل البيت ومعه أسامة وبلال رضي الله عنهما، وأغلق الباب، وصلى ركعتين، كما في صحيح البخاري عن ابن عمر رضي الله عنهما. ثم خرج، فأعاد المفتاح إلى عثمان بن طلحة، وأخبره أنه لمن يحمل مفتاح البيت. وأمر بلالًا فأذّن فوق ظهر الكعبة، فارتفع صوت التوحيد في المكان الذي كان ممتلئًا بالأصنام. وكان هذا الأذان أبلغ إعلان بأن الدين الحق قد قام في أطهر بقاع الأرض."], ["العفو العام", "وقف النبي ﷺ على باب الكعبة، وخاطب أهل مكة، وكان فيهم من آذاه وأخرجه وحاربه سنين. فقال: «لا إله إلا الله وحده لا شريك له، صدق وعده، ونصر عبده، وهزم الأحزاب وحده». ثم تروي كتب السيرة أنه قال لهم: «ما تقولون أني فاعل بكم؟» قالوا: خيرًا، أخ كريم وابن أخ كريم، فقال: «اذهبوا فأنتم الطلقاء»، وهذه الرواية في كتب السير، وفي إسنادها مقال، لكن معناها ثابت في السنة العملية، فقد عفا ﷺ عن كثير ممن حاربوه. وأمّن صفوان بن أمية وعكرمة بن أبي جهل رضي الله عنهما بعد أن فرّا، فعادا وأسلما. وأمر النبي ﷺ بقتل نفر قليل ممن أجرموا إجرامًا خاصًّا، كابن خطل الذي ارتد وقتل مسلمًا وكان يهجو النبي ﷺ. وفي صحيح البخاري أنه أقام بمكة تسعة عشر يومًا يقصر الصلاة. وقال في خطبته: «لا هجرة بعد الفتح، ولكن جهاد ونية». وبذلك دانت مكة للإسلام بعد عقدين من الصراع."]], "lesson": ["النصر الحقيقي يُقابل بالتواضع والشكر لا بالكبر، وقد دخل النبي ﷺ مكة مطأطئ الرأس خاشعًا.", "العفو عند القدرة من أعلى الأخلاق، وقد صفح النبي ﷺ عن أعدائه الذين آذوه عشرين عامًا.", "التخطيط والكتمان من أسباب النصر، مع التوكل على الله ودعائه.", "الله يطهر بيته من الشرك ويقيم التوحيد، وإن طال أمد الباطل فإنه زاهق."], "cat": "seerah"}, {"id": "sr25", "title": "غزوة حنين وحصار الطائف", "type": "من السيرة النبوية", "verse": "ثُمَّ أَنزَلَ اللَّهُ سَكِينَتَهُ عَلَىٰ رَسُولِهِ وَعَلَى الْمُؤْمِنِينَ", "source": "سورة التوبة 9:26", "parts": [["تجمّع هوازن وثقيف", "بعد فتح مكة بنحو أسبوعين علم النبي ﷺ أن قبيلتي هوازن وثقيف قد جمعتا جموعًا كثيرة لقتاله، وكانتا من أقوى قبائل العرب وأمهرها في الرمي. وقاد هذا التجمع مالك بن عوف النصري، وكان شابًا مقدامًا، فأمر أن تُخرج النساء والأموال والمواشي مع الجيش ليستميت الرجال في الدفاع عنها. وتروي كتب السيرة أن دريد بن الصمة، وهو شيخ مجرّب، اعترض على هذه الخطة لكن مالكًا أصرّ عليها. فسار النبي ﷺ إليهم في شوال من السنة الثامنة للهجرة. وكان معه عشرة آلاف من الذين شهدوا الفتح، وانضم إليهم نحو ألفين من أهل مكة الذين أسلموا حديثًا، وهكذا بلغ الجيش اثني عشر ألفًا في الروايات المشهورة. واستعار النبي ﷺ دروعًا ومالًا من صفوان بن أمية على أن يردّه، وهو ما ورد في كتب السنة والسيرة. وخرج جيش المسلمين أكبر عددًا وعُدّة من أي وقت مضى."], ["الكثرة والهزيمة الأولى", "في وادي حنين، قبل الفجر، كان جيش هوازن قد كمن في شعاب الوادي ومضايقه. فلما انحدر المسلمون في الغبش، انهالت عليهم السهام من كل جانب، فاضطربت صفوفهم وفرّ كثير منهم. وقد ذكر القرآن هذا الدرس بقوله تعالى: ﴿لَقَدْ نَصَرَكُمُ اللَّهُ فِي مَوَاطِنَ كَثِيرَةٍ وَيَوْمَ حُنَيْنٍ إِذْ أَعْجَبَتْكُمْ كَثْرَتُكُمْ فَلَمْ تُغْنِ عَنكُمْ شَيْئًا وَضَاقَتْ عَلَيْكُمُ الْأَرْضُ بِمَا رَحُبَتْ ثُمَّ وَلَّيْتُم مُّدْبِرِينَ﴾. وكان بعض الذين خرجوا معهم قد قالوا: لن نُغلب اليوم من قلّة، فعلّمهم الله أن النصر من عنده لا بالعدد. وهكذا كان العُجب بالكثرة سببًا في الابتلاء، لكنه ابتلاء قصير سرعان ما انجلى بفضل الله. وهذه الآية تنبّه كل جيل إلى أن الأخذ بالأسباب مطلوب، وأن الاعتماد على الله لا على الأسباب وحدها هو الأصل."], ["ثبات النبي ﷺ", "وسط الفوضى ثبت النبي ﷺ على بغلته البيضاء، وثبت معه نفر قليل من أصحابه، منهم العباس وأبو سفيان بن الحارث وعلي وأبو بكر وعمر وغيرهم رضي الله عنهم. وفي الصحيحين من حديث البراء بن عازب رضي الله عنه أنه سمع النبي ﷺ يقول وهو يمضي نحو العدو: «أنا النبي لا كذب، أنا ابن عبد المطلب». قال البراء: كنا والله إذا احمرّ البأس نتّقي به، وإن الشجاع منا للذي يحاذي به، يعني النبي ﷺ. ثم نادى العباس رضي الله عنه، وكان جهير الصوت، بأمر النبي ﷺ: يا أصحاب السمرة، يا أصحاب سورة البقرة، فأقبلوا يقولون: لبيك لبيك، كما في صحيح مسلم. وأخذ النبي ﷺ حفنة من تراب فرمى بها وجوههم وقال: «شاهت الوجوه»، فما بقي منهم أحد إلا امتلأت عيناه ترابًا، كما ثبت في مسلم. فتحوّل الموقف، وأنزل الله سكينته على رسوله وعلى المؤمنين وأنزل جنودًا لم يروها."], ["النصر والغنائم", "عاد المسلمون إلى القتال بعد أن سمعوا نداء النبي ﷺ، وهُزمت هوازن وثقيف، وفرّ قائدهم مالك بن عوف إلى الطائف، وتحصنت ثقيف بحصونها. وغنم المسلمون غنائم كثيرة من الإبل والغنم، وتركت هوازن سبيًا من النساء والأطفال في الوادي. وتختلف الروايات في أعداد الغنائم والسبي، فلا يُجزم بعدد منها. وأمر النبي ﷺ بجمع الغنائم عند الجِعرانة، وهي موضع قرب مكة، وأخّر قسمتها ليأتيه وفد هوازن لعلهم يسلمون. ثم قصد الطائف على رأس جيشه لحصار من لجأ إليها. وبين الحدثين ظهرت سورة الأنفال وبيّنت قسمة الغنائم، فهو الله الذي يملك أمر التشريع. وكان في هذه الأيام اختبار حقيقي لإيمان المسلمين الجدد، فإن الذين أسلموا بعد الفتح كانوا يرون النصر بعد كل ابتلاء، وتعلّم الجميع كيف أن الثبات في الشدة دليل الإيمان."], ["حصار الطائف", "ذهب النبي ﷺ إلى الطائف، وكانت حصونها منيعة، فحاصرها المسلمون، وتختلف الروايات في مدة الحصار فقيل بضع عشرة ليلة وقيل غير ذلك. واستخدم المسلمون المنجنيق، كما ذكر أهل السير. وأمر النبي ﷺ بقطع بعض كروم ثقيف إغاظةً لهم وإضعافًا، ثم تركه حين سألوه بالله والرحم، كما تروي كتب السيرة. ورمى أهل الحصن بالنبال، فأصيب نفر من المسلمين. وأعلن النبي ﷺ أن من خرج إليه من عبيدهم فهو حر، فخرج بعضهم. ولما لم يظهر أن الحصار سيثمر قريبًا، استشار النبي ﷺ أصحابه، وروى البخاري عن عبد الله بن عمر رضي الله عنهما أنه قال: لما حاصر النبي ﷺ الطائف فلم ينل منهم شيئًا قال: «إنا قافلون غدًا إن شاء الله»، فثقل ذلك على المسلمين وقالوا: نذهب ولا نفتحه؟ فقال: «اغدوا على القتال»، فغدوا فأصابهم جراح، فقال: «إنا قافلون غدًا»، فأعجبهم ذلك، فضحك النبي ﷺ."], ["دعاؤه لثقيف وقسمة الغنائم", "لما انصرف النبي ﷺ عن الطائف طلب منه بعض أصحابه أن يدعو على ثقيف، فقال: «اللهم اهدِ ثقيفًا وأتِ بهم»، رواه الترمذي وحسّنه. وبعد قليل جاء وفد ثقيف مسلمين، كما سيأتي في عام الوفود. ثم أقبل وفد هوازن إلى الجِعرانة مسلمين، يطلبون ردّ السبي والأموال. فخيّرهم النبي ﷺ بين السبي والمال، فاختاروا السبي، فاستطاب النبي ﷺ نفوس أصحابه حتى ردّوا السبي، كما في صحيح البخاري. ثم قسّم النبي ﷺ الغنائم، فأعطى حديثي العهد بالإسلام عطاءً كثيرًا استمالةً لقلوبهم، فوجد بعض الأنصار في أنفسهم. فجمعهم النبي ﷺ وقال: «أفلا ترضون أن يذهب الناس بالشاة والبعير وتذهبون برسول الله إلى رحالكم؟» فبكوا حتى أخضلوا لحاهم وقالوا: رضينا برسول الله قسمًا وحظًّا، كما في الصحيحين. وبعد ذلك اعتمر النبي ﷺ من الجعرانة وعاد إلى المدينة."]], "lesson": ["العجب بالكثرة والقوة سبب للهزيمة، والنصر من عند الله وحده.", "ثبات القائد في الشدة يعيد الجيش إلى صفه، وقد ثبت النبي ﷺ ونادى أصحابه.", "الرفق بالمخالفين وطلب الهداية لهم من أخلاق النبي ﷺ، فقد دعا لثقيف بالهداية.", "محبة النبي ﷺ أعظم من متاع الدنيا، كما أدرك الأنصار رضي الله عنهم حين قارنوا بين الغنائم ورسول الله ﷺ."], "cat": "seerah"}, {"id": "sr26", "title": "غزوة تبوك وعام الوفود", "type": "من السيرة النبوية", "verse": "انفِرُوا خِفَافًا وَثِقَالًا وَجَاهِدُوا بِأَمْوَالِكُمْ وَأَنفُسِكُمْ فِي سَبِيلِ اللَّهِ", "source": "سورة التوبة 9:41", "parts": [["الخروج في العسرة", "في رجب من السنة التاسعة للهجرة أراد النبي ﷺ غزو الروم في أطراف الشام، وكان الوقت صيفًا شديد الحر، والثمار قد أينعت في المدينة، والناس في قلة ومشقة. وعلى خلاف عادته في إخفاء وجهته، أعلن النبي ﷺ وجهته لبعدها وكثرة عدوّها، ليتأهب الناس. فسُمّي الجيش جيش العسرة. وأنزل الله في ذلك آيات من سورة التوبة تعاتب المتثاقلين: ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا مَا لَكُمْ إِذَا قِيلَ لَكُمُ انفِرُوا فِي سَبِيلِ اللَّهِ اثَّاقَلْتُمْ إِلَى الْأَرْضِ﴾. وكان المنافقون يثبّطون الناس ويقولون: لا تنفروا في الحر. فنزل قوله تعالى: ﴿قُلْ نَارُ جَهَنَّمَ أَشَدُّ حَرًّا لَّوْ كَانُوا يَفْقَهُونَ﴾. وكان الخروج أكبر حشد جمعه النبي ﷺ، وتختلف الروايات في عدده، والمشهور أنهم نحو ثلاثين ألفًا."], ["بذل الصحابة رضي الله عنهم", "حثّ النبي ﷺ على الإنفاق في هذه الغزوة، فتسابق الصحابة رضي الله عنهم. فجاء عثمان بن عفان رضي الله عنه بجيش العسرة وجهّزه بمال كثير، فقال النبي ﷺ: «ما ضرّ عثمان ما عمل بعد اليوم»، رواه الترمذي وحسّنه. وجاء عمر رضي الله عنه بنصف ماله، وقال: اليوم أسبق أبا بكر إن سبقته. وجاء أبو بكر رضي الله عنه بماله كله، فسأله النبي ﷺ: «ما أبقيت لأهلك؟» قال: أبقيت لهم الله ورسوله، فقال عمر: لا أسبقه إلى شيء أبدًا. رواه أبو داود والترمذي وحسّنه الألباني وغيره. وتصدّق عبد الرحمن بن عوف رضي الله عنه بمال كثير، وجاء النساء بحليّهن، وجاء فقراء يتصدقون بالقليل. فاستهزأ المنافقون بهم، فنزل في ذلك قوله تعالى: ﴿الَّذِينَ يَلْمِزُونَ الْمُطَّوِّعِينَ مِنَ الْمُؤْمِنِينَ فِي الصَّدَقَاتِ﴾. وكان البكّاؤون من الفقراء يأتون النبي ﷺ يطلبون حملانًا فلا يجدها، فيرجعون وأعينهم تفيض من الدمع حزنًا، كما في سورة التوبة."], ["الطريق إلى تبوك", "استخلف النبي ﷺ على المدينة محمد بن مسلمة وقيل غيره، وتختلف الروايات في اسمه. وترك عليًّا رضي الله عنه في أهله، فقال المنافقون: ما خلّفه إلا استثقالًا له، فلحق علي بالنبي ﷺ وأخبره، فقال له: «أما ترضى أن تكون مني بمنزلة هارون من موسى إلا أنه لا نبي بعدي»، كما في الصحيحين. وسار الجيش في طريق صحراوية شاقة، وبلغهم العطش والجوع حتى نحروا بعض الإبل ليشربوا من ما في كروشها، كما ذكر أهل السير. وفي صحيح مسلم أن النبي ﷺ قال لهم قبل بلوغ تبوك: «إنكم ستأتون غدًا إن شاء الله عين تبوك، فلا تمسّوا من مائها شيئًا حتى آتي». ثم وصل ونزل تبوك، فلم يلقَ جيشًا للروم، فقد انسحبت جموعهم أو تفرقت. وأقام فيها أيامًا، وبلغ الدعوة إلى المنطقة."], ["الصلح مع أهل الحدود", "لم يقع قتال في تبوك، لكنّ أثرها كان سياسيًّا كبيرًا. فقد أقام النبي ﷺ أيامًا بتبوك، وجاءه يوحنا بن رؤبة صاحب أيلة فصالحه على الجزية، وأهدى له بغلة بيضاء، كما في صحيح البخاري عن أبي حميد الساعدي رضي الله عنه. وجاءه أهل جرباء وأذرح فصالحهم، ثم بعث خالد بن الوليد رضي الله عنه إلى أُكَيدر دومة الجندل، فأُسر وجيء به، ثم صالح على الجزية، كما ذكر أهل السير. وكانت هذه الصلحات أمانًا للقوافل على طريق الشام، وتثبيتًا للحدود الشمالية، وفتحًا لباب انتشار الإسلام بين العرب النصارى. ثم رجع النبي ﷺ إلى المدينة. وفي رجوعه قال: «إن بالمدينة أقوامًا ما سرتم مسيرًا ولا قطعتم واديًا إلا كانوا معكم، حبسهم العذر»، كما في صحيح البخاري عن أنس رضي الله عنه."], ["الثلاثة الذين خُلّفوا", "قعد عن الغزوة قوم من المنافقين اعتذروا بأعذار كاذبة، فقبل النبي ﷺ علانيتهم ووكل سرائرهم إلى الله. أما الثلاثة: كعب بن مالك ومرارة بن الربيع وهلال بن أمية رضي الله عنهم، فقد تخلفوا من غير عذر، وصدقوا النبي ﷺ حين سألهم. فأمر النبي ﷺ المسلمين بمقاطعتهم، فاعتزلهم الناس خمسين ليلة، حتى ضاقت عليهم الأرض بما رحبت. ويروي كعب رضي الله عنه في الصحيحين أن ملك غسان أرسل إليه كتابًا يدعوه إلى اللحاق به، فقال: وهذا أيضًا من البلاء، فسجّر به التنور. ثم أنزل الله توبتهم: ﴿وَعَلَى الثَّلَاثَةِ الَّذِينَ خُلِّفُوا حَتَّىٰ إِذَا ضَاقَتْ عَلَيْهِمُ الْأَرْضُ بِمَا رَحُبَتْ﴾. فبشّرهم المسلمون، وقال كعب إن الصدق نجّاه، فقد أمر الله المؤمنين: ﴿اتَّقُوا اللَّهَ وَكُونُوا مَعَ الصَّادِقِينَ﴾. ونزل كذلك ما يتعلق بمسجد الضرار الذي بناه المنافقون، فأمر النبي ﷺ بهدمه."], ["عام الوفود", "كانت السنة التاسعة تُعرف عند أهل السير بعام الوفود، فقد تتابعت وفود العرب على المدينة تعلن الإسلام وتبايع النبي ﷺ بعد أن رأت الفتح وحنينًا وتبوك. فجاء وفد ثقيف في رمضان ومعهم عروة، ثم أسلم أهل الطائف، وجاء وفد بني تميم وعبد القيس وغيرهم، وجاءه وفود من اليمن. وأرسل النبي ﷺ معاذ بن جبل وأبا موسى الأشعري رضي الله عنهما إلى اليمن معلمين ودعاة، وأوصى معاذًا في الصحيحين أن يبدأ بالدعوة إلى التوحيد. وفي ذي القعدة من السنة نفسها أرسل أبا بكر رضي الله عنه أميرًا على الحج، ثم أتبعه عليًّا رضي الله عنه ينادي بأن لا يحج بعد العام مشرك ولا يطوف بالبيت عريان، كما في صحيح البخاري. وجاء وفد نصارى نجران، ونزلت آية المباهلة. وبهذا اتسعت رقعة الإسلام في الجزيرة العربية."]], "lesson": ["التضحية بالمال والنفس في سبيل الله علامة صدق الإيمان، والصدقة القليلة من الفقير عند الله عظيمة.", "الصدق منجاة وإن كان صعبًا في ظاهره، فقد أنجى كعبًا ورفيقيه من الهلاك.", "أخلاق الأخوّة تتجلى في الشدائد، لكن المخالفة تؤدّب، ثم يعود الصف بالتوبة.", "الدعوة بالقدوة والإحسان تفتح القلوب، وقد دخل الناس في دين الله أفواجًا بعد أن رأوا صدق الأمر."], "cat": "seerah"}, {"id": "sr27", "title": "حجة الوداع", "type": "من السيرة النبوية", "verse": "الْيَوْمَ أَكْمَلْتُ لَكُمْ دِينَكُمْ وَأَتْمَمْتُ عَلَيْكُمْ نِعْمَتِي وَرَضِيتُ لَكُمُ الْإِسْلَامَ دِينًا", "source": "سورة المائدة 5:3", "parts": [["الخروج للحج", "في السنة العاشرة للهجرة أعلن النبي ﷺ أنه سيحج، فقدم المدينة خلق كثير يريدون الحج معه والاقتداء به. وروى مسلم عن جابر رضي الله عنه في حديثه الطويل أن النبي ﷺ مكث تسع سنين لم يحج، ثم أذّن في الناس في العاشرة أن رسول الله ﷺ حاجّ، فقدم المدينة بشر كثير كلهم يلتمس أن يأتم برسول الله ﷺ ويعمل مثل عمله. وخرج من المدينة لخمس بقين من ذي القعدة كما في صحيح البخاري عن عائشة رضي الله عنها. وبات بذي الحليفة، وأحرم منها، ولبّى بالتوحيد: «لبيك اللهم لبيك، لبيك لا شريك لك لبيك، إن الحمد والنعمة لك والملك، لا شريك لك». وقال في الحج: «خذوا عني مناسككم»، كما في صحيح مسلم. وتختلف الروايات في عدد الحجاج، وكانوا جمعًا عظيمًا لم يُعهد مثله، وما بين يدي النبي ﷺ من راكب وماشٍ كما وصف جابر رضي الله عنه."], ["دخول مكة والطواف", "دخل النبي ﷺ مكة في الرابع من ذي الحجة، كما ذكر أهل السير، فطاف بالبيت سبعة أشواط، ورمل في الثلاثة الأولى، واستلم الحجر الأسود، ثم صلى خلف المقام ركعتين، وقرأ فيهما ﴿قُلْ يَا أَيُّهَا الْكَافِرُونَ﴾ و﴿قُلْ هُوَ اللَّهُ أَحَدٌ﴾، ثم سعى بين الصفا والمروة. وكان قد ساق الهدي، فأمر من لم يسق هديًا من أصحابه بأن يحلّوا من إحرامهم ويجعلوها عمرة، فتردّد بعضهم، فغضب النبي ﷺ وقال لهم ما قال مبيّنًا حكم الله، فأطاعوا. ثم أحل من لم يكن معه هدي. وفي يوم التروية، وهو الثامن من ذي الحجة، توجه الجميع إلى منى، فصلى بها الظهر والعصر والمغرب والعشاء والفجر. وفي عرفات كان النبي ﷺ قد أمر بضرب قبة له في نمرة، وسار بعد طلوع الشمس إلى هناك، فنزل بها وانتظر حتى زالت الشمس."], ["خطبة عرفة", "بعد الزوال أمر النبي ﷺ براحلته القصواء فرُحلت، فسار حتى أتى بطن الوادي، ثم خطب الناس، كما في صحيح مسلم. ومما قاله فيها: «إن دماءكم وأموالكم عليكم حرام كحرمة يومكم هذا في شهركم هذا في بلدكم هذا». وقال: «ألا إن كل شيء من أمر الجاهلية تحت قدميّ موضوع، ودماء الجاهلية موضوعة، وإن أول دم أضع من دمائنا دم ابن ربيعة بن الحارث»، ثم قال: «وربا الجاهلية موضوع، وأول ربا أضع ربانا ربا عباس بن عبد المطلب فإنه موضوع كله». وأوصى بالنساء فقال: «فاتقوا الله في النساء، فإنكم أخذتموهن بأمانة الله، واستحللتم فروجهن بكلمة الله». ثم قال: «وقد تركت فيكم ما لن تضلوا بعده إن اعتصمتم به: كتاب الله». فهذه الخطبة دستور شامل يحفظ الدماء والأموال والأعراض، ويلغي ظلم الجاهلية، ويرسّخ العدل والوفاء."], ["الشهادة على البلاغ", "ثم قال النبي ﷺ للناس: «وأنتم تُسألون عني، فما أنتم قائلون؟» قالوا: نشهد أنك قد بلّغت وأدّيت ونصحت. فقال بإصبعه السبابة يرفعها إلى السماء وينكتها إلى الناس: «اللهم اشهد، اللهم اشهد»، ثلاث مرات، كما في صحيح مسلم. وهذه اللحظة أعظم مشهد في تاريخ الدعوة: رسول يختم رسالته أمام جمع عظيم يشهد أن ما بلّغه كان أمانة أداها. ثم أذّن بلال رضي الله عنه وأقام، فصلى الظهر والعصر جمعًا وقصرًا، وبعدها وقف بعرفة حتى غربت الشمس. وفي هذا الموقف نزلت آية: ﴿الْيَوْمَ أَكْمَلْتُ لَكُمْ دِينَكُمْ وَأَتْمَمْتُ عَلَيْكُمْ نِعْمَتِي وَرَضِيتُ لَكُمُ الْإِسْلَامَ دِينًا﴾، وجاء في الصحيحين عن عمر رضي الله عنه أنها نزلت وهو واقف بعرفة يوم جمعة، وأن اليهود قالوا لو علينا نزلت هذه الآية لاتخذنا ذلك اليوم عيدًا."], ["مزدلفة ومنى", "دفع النبي ﷺ من عرفة بعد الغروب بسكينة، وأمر الناس بالسكينة، حتى أتى المزدلفة فصلى بها المغرب والعشاء جمعًا بأذان وإقامتين، ثم نام حتى الفجر، فصلى الفجر، ثم أتى المشعر الحرام فاستقبل القبلة، فدعا وكبّر وهلّل حتى أسفر جدًّا. ثم دفع قبل طلوع الشمس إلى منى، فرمى جمرة العقبة بسبع حصيات يكبّر مع كل حصاة. ثم نحر هديه، فنحر ثلاثًا وستين بيده، ثم أعطى عليًّا رضي الله عنه فنحر ما غبر، وأشركه في هديه، كما في صحيح مسلم، وكان الهدي مئة بعير. ثم حلق رأسه وفرّق شعره بين الناس. ثم أفاض إلى البيت فطاف وصلى الظهر بمكة، وعاد إلى منى. وسُئل يومئذ عن تقديم بعض المناسك وتأخيرها، فكان يقول: «افعل ولا حرج»، كما في الصحيحين، رحمة بالناس."], ["خطبة يوم النحر وتوديع الأمة", "خطب النبي ﷺ الناس يوم النحر بمنى، وفي صحيح البخاري من حديث أبي بكرة رضي الله عنه أنه قال: «أي يوم هذا؟» فسكتنا حتى ظننا أنه سيسميه بغير اسمه، قال: «أليس يوم النحر؟» ثم سأل عن الشهر والبلد، ثم قال: «فإن دماءكم وأموالكم وأعراضكم عليكم حرام كحرمة يومكم هذا في شهركم هذا في بلدكم هذا، وستلقون ربكم فيسألكم عن أعمالكم، ألا فلا ترجعوا بعدي كفارًا يضرب بعضكم رقاب بعض، ألا ليبلّغ الشاهد الغائب». وفي هذه الحجة قال النبي ﷺ: «لتأخذوا مناسككم، فإني لا أدري لعلي لا أحج بعد حجتي هذه»، رواه مسلم، فسُميت حجة الوداع. وحين اكتمل الدين وبلّغ الرسالة، لم يبقَ له في الدنيا إلا أشهر قليلة، فرجع إلى المدينة، ثم لحق بالرفيق الأعلى. وخلّف أمة تحمل دينًا كاملًا، وتتوارث الأمانة جيلًا بعد جيل."]], "lesson": ["الاقتداء بالنبي ﷺ في العبادة أصل عظيم، فقد قال: «خذوا عني مناسككم».", "حرمة الدماء والأموال والأعراض من أعظم مقاصد الشريعة، وقد أكّدها النبي ﷺ في آخر عهده.", "الإسلام دين كامل لا ينقصه شيء، وقد أُمرنا بالتمسك بكتاب الله وسنة نبيه ﷺ.", "البلاغ أمانة، وكل مسلم يحمل نصيبًا منها: «فليبلّغ الشاهد الغائب»."], "cat": "seerah"}, {"id": "sr28", "title": "مرض النبي ﷺ ووفاته وخلافة أبي بكر رضي الله عنه", "type": "من السيرة النبوية", "verse": "إِنَّكَ مَيِّتٌ وَإِنَّهُم مَّيِّتُونَ", "source": "سورة الزمر 39:30", "parts": [["بداية المرض", "بعد حجة الوداع عاد النبي ﷺ إلى المدينة، وفي أواخر صفر أو أوائل ربيع الأول من السنة الحادية عشرة بدأ به المرض، وتختلف الروايات في اليوم بالضبط. وكان قد جهّز جيشًا بقيادة أسامة بن زيد رضي الله عنهما إلى حدود الشام. وفي صحيح البخاري عن عائشة رضي الله عنها أنه كان في بيت ميمونة رضي الله عنها حين اشتد وجعه، فاستأذن أزواجه أن يُمرَّض في بيتها، فأذنّ له. وخرج بين رجلين تخطّ رجلاه في الأرض، حتى دخل بيت عائشة رضي الله عنها. وقالت عائشة رضي الله عنها: وارأساه، فقال: «بل أنا وارأساه». وكان يقول: «إني أوعك كما يوعك رجلان منكم»، كما في الصحيحين عن ابن مسعود رضي الله عنه، أي إن الحمى كانت شديدة عليه. وأمر أن تُصبّ عليه سبع قرب من آبار مختلفة لم تُحلل أوكيتهن، لعله يستريح، فصبّوا عليه حتى قال: «حسبكم حسبكم»، وخرج إلى الناس."], ["الخطبة وتخيير العبد", "خرج النبي ﷺ إلى المسجد وهو معصوب الرأس، فجلس على المنبر، وخطب الناس. وفي صحيح البخاري من حديث أبي سعيد الخدري رضي الله عنه أنه قال: «إن عبدًا خيّره الله بين أن يؤتيه من زهرة الدنيا ما شاء وبين ما عنده، فاختار ما عنده». فبكى أبو بكر رضي الله عنه، وقال: فديناك بآبائنا وأمهاتنا. قال أبو سعيد: فعجبنا لبكائه أن يخبر رسول الله ﷺ عن عبد خيّر، فكان رسول الله ﷺ هو المخيَّر، وكان أبو بكر أعلمنا. فقال النبي ﷺ: «إن من أمنّ الناس عليّ في صحبته وماله أبا بكر، ولو كنتُ متخذًا خليلًا غير ربي لاتخذت أبا بكر، ولكن أخوّة الإسلام ومودّته، لا يبقين في المسجد باب إلا سُدّ إلا باب أبي بكر». وفي ذلك دلالة على مكانة أبي بكر رضي الله عنه عند النبي ﷺ."], ["إمامة أبي بكر وآخر وصاياه", "لما اشتد المرض لم يستطع النبي ﷺ أن يصلي بالناس، فأمر أن يصلي أبو بكر رضي الله عنه. وفي الصحيحين أن عائشة رضي الله عنها قالت له إن أبا بكر رجل رقيق إذا قام مقامك لم يسمع الناس من البكاء، فمر عمر، فكرر النبي ﷺ أمره وقال: «إنكن صواحب يوسف، مروا أبا بكر فليصلّ بالناس». فصلى أبو بكر رضي الله عنه بالناس أيامًا في حياة النبي ﷺ. ومن آخر وصاياه ﷺ ما رواه أحمد وابن ماجه بإسناد صحيح أن آخر ما تكلم به: «الصلاة الصلاة، وما ملكت أيمانكم». وفي الصحيحين أنه لعن اليهود والنصارى اتخذوا قبور أنبيائهم مساجد، تحذيرًا لأمته مما صنعوا. وكان رغم شدة المرض يوصي بالتوحيد والصلاة ورعاية الضعفاء. وقد أوصى كذلك بإخراج المشركين من جزيرة العرب، كما في صحيح البخاري."], ["اللحظات الأخيرة", "في صباح يوم الاثنين، وكان المسلمون يصلون الفجر وأبو بكر رضي الله عنه إمامهم، كشف النبي ﷺ ستر حجرة عائشة رضي الله عنها فنظر إليهم وهم صفوف في الصلاة، ثم تبسم يضحك، كما روى أنس رضي الله عنه في الصحيحين. فنكص أبو بكر رضي الله عنه على عقبيه ليصل الصف، وظن أن النبي ﷺ يريد أن يخرج للصلاة، وهمّ المسلمون أن يفتتنوا في صلاتهم فرحًا برؤيته. فأشار إليهم أن أتموا صلاتكم، وأرخى الستر. وفي الصحيحين عن عائشة رضي الله عنها أنه كان عندها قدح فيه ماء يدخل فيه يده فيمسح به وجهه ويقول: «لا إله إلا الله، إن للموت سكرات». ثم رفع يده أو إصبعه وقال: «في الرفيق الأعلى»، ثلاثًا، ثم قُبض ومالت يده. وتوفي ﷺ ضحى يوم الاثنين من ربيع الأول من السنة الحادية عشرة، وله ثلاث وستون سنة، كما في الصحيحين، وتختلف الروايات في تاريخ اليوم من الشهر."], ["صدمة الصحابة وموقف أبي بكر", "وقع خبر الوفاة على الصحابة رضي الله عنهم كالصاعقة. فقام عمر رضي الله عنه ينكر موته ويقول: إن رسول الله ﷺ لم يمت، وإنما ذهب إلى ربه كما ذهب موسى. فأقبل أبو بكر رضي الله عنه، فدخل على النبي ﷺ فكشف عن وجهه وقبّله، وقال: بأبي أنت وأمي، طبتَ حيًّا وميتًا، والذي نفسي بيده لا يذيقك الله الموتتين أبدًا. ثم خرج، فقال: على رسلك يا عمر. ثم حمد الله وأثنى عليه وقال: ألا من كان يعبد محمدًا ﷺ فإن محمدًا قد مات، ومن كان يعبد الله فإن الله حي لا يموت. وتلا قوله تعالى: ﴿وَمَا مُحَمَّدٌ إِلَّا رَسُولٌ قَدْ خَلَتْ مِن قَبْلِهِ الرُّسُلُ﴾. فقال عمر رضي الله عنه: فوالله لكأن الناس لم يعلموا أن الله أنزل هذه الآية حتى تلاها أبو بكر، فتلقاها منه الناس كلهم، فما أسمع بشرًا من الناس إلا يتلوها، كما في صحيح البخاري."], ["بيعة السقيفة", "اجتمعت الأنصار رضي الله عنهم في سقيفة بني ساعدة يتشاورون في أمر الخلافة، فبلغ ذلك أبا بكر وعمر وأبا عبيدة رضي الله عنهم فذهبوا إليهم. وتكلم أبو بكر رضي الله عنه فذكر فضل الأنصار والمهاجرين، وبيّن أن العرب لا تعرف هذا الأمر إلا لهذا الحي من قريش، كما في صحيح البخاري، وقال: قد رضيت لكم أحد هذين الرجلين، عمر أو أبا عبيدة. فقال عمر رضي الله عنه: بل أنت سيدنا وخيرنا وأحبنا إلى رسول الله ﷺ، وأخذ بيده فبايعه، وبايعه الناس. وكان قد قال بعض الأنصار: منا أمير ومنكم أمير، لكنه رجع الأمر إلى الاجتماع. وبايع الصحابة رضي الله عنهم في اليوم التالي بيعة عامة في المسجد. وبهذا اجتمعت كلمة المسلمين على خليفة رسول الله ﷺ، فتم الأمر قبل دفن النبي ﷺ على المشهور."], ["الغسل والدفن وأعمال الخليفة", "غسّل النبي ﷺ أهل بيته، منهم علي والعباس رضي الله عنهما وغيرهما، وكُفّن في ثلاثة أثواب بيض ليس فيها قميص ولا عمامة، كما في الصحيحين عن عائشة رضي الله عنها. وصلى عليه المسلمون أفرادًا. ودُفن في حجرة عائشة رضي الله عنها حيث توفي، وتختلف الروايات في وقت دفنه فقيل ليلة الأربعاء. وبعد ذلك مضى أبو بكر رضي الله عنه في الخلافة بعزم، فأنفذ جيش أسامة رضي الله عنه كما أمر النبي ﷺ، وقال: ما كنت لأحل راية عقدها رسول الله ﷺ. وحين ارتد من ارتد ومنع الزكاة من منعها قال كلمته المشهورة: والله لو منعوني عناقًا كانوا يؤدونها إلى رسول الله ﷺ لقاتلتهم على منعها، كما في الصحيحين. فثبّت الله به الدين، وجمع القرآن في مصحف، ومهّد للفتوح التي جاءت بعد، فكان الصدّيق رضي الله عنه حارس الإسلام بعد نبيه ﷺ."]], "lesson": ["الموت حق على الأنبياء وغيرهم، وهو انتقال إلى الله، فلا يُعبد إلا الله الحي الذي لا يموت.", "ثبات أبي بكر رضي الله عنه في أشد المواقف دليل فقهه وإيمانه، وبه ثبّت الله الأمة.", "الصلاة عماد الدين، وكانت من آخر وصايا النبي ﷺ.", "تشاور المسلمين في الأمر العام واجتماعهم على الحق أصل في بقاء الأمة موحّدة."], "cat": "seerah"}, {"id": "sr29", "title": "أخلاق النبي ﷺ وشمائله", "type": "من السيرة النبوية", "verse": "وَإِنَّكَ لَعَلَىٰ خُلُقٍ عَظِيمٍ", "source": "سورة القلم 68:4", "parts": [["خُلُقه القرآن", "وصف الله نبيه ﷺ بقوله: ﴿وَإِنَّكَ لَعَلَىٰ خُلُقٍ عَظِيمٍ﴾. وحين سُئلت عائشة رضي الله عنها عن خلق النبي ﷺ قالت: «كان خلقه القرآن»، رواه مسلم. أي كان يتأدب بآداب القرآن، فيأتمر بأوامره وينتهي بنواهيه، ويتخلق بما فيه من الأخلاق الكريمة. وروى البخاري عن أنس رضي الله عنه أنه خدم النبي ﷺ عشر سنين، قال: فما قال لي أف قط، ولا قال لشيء فعلته: لم فعلته؟ ولا لشيء لم أفعله: ألا فعلت كذا؟ وقال أنس أيضًا: كان رسول الله ﷺ أحسن الناس خلقًا. وقال النبي ﷺ عن نفسه: «إنما بُعثت لأتمم صالح الأخلاق»، رواه أحمد والبخاري في الأدب المفرد وصححه الألباني. فالأخلاق ليست جانبًا ثانويًّا في الرسالة، بل هي من صميمها، وقد جسّدها النبي ﷺ في بيته وبين أصحابه وفي مجتمعه وفي حربه وسلمه."], ["الحياء والتواضع", "روى البخاري عن أبي سعيد الخدري رضي الله عنه قال: كان النبي ﷺ أشد حياءً من العذراء في خدرها، فإذا رأى شيئًا يكرهه عرفناه في وجهه. وكان على عظيم مكانته يعمل في بيته، فقد سُئلت عائشة رضي الله عنها: ما كان النبي ﷺ يصنع في بيته؟ قالت: كان يكون في مهنة أهله، فإذا حضرت الصلاة قام إلى الصلاة، رواه البخاري. وقد جاء في مسند أحمد بإسناد صحيح أنه كان يخصف نعله ويخيط ثوبه ويعمل في بيته كما يعمل أحدكم في بيته. وكان يقول: «لا تُطروني كما أطرت النصارى ابن مريم، فإنما أنا عبد، فقولوا: عبد الله ورسوله»، كما في صحيح البخاري. وكان يجلس بين أصحابه فيأتي الغريب فلا يعرفه من بينهم حتى يسأل، وكان يركب الحمار ويردف خلفه، ويجيب دعوة الفقير والغني. فمن أراد أن يعرف صورة التواضع فلينظر إلى سيرة النبي ﷺ."], ["الرحمة بالصغار والضعفاء", "من أبرز أخلاقه ﷺ الرحمة. روى البخاري عن أبي هريرة رضي الله عنه أن النبي ﷺ قبّل الحسن بن علي رضي الله عنهما، وعنده الأقرع بن حابس، فقال الأقرع: إن لي عشرة من الولد ما قبّلت منهم أحدًا، فنظر إليه النبي ﷺ ثم قال: «من لا يَرحم لا يُرحم». وفي الصحيحين أنه كان يصلي وهو حامل أمامة بنت زينب رضي الله عنها على عاتقه، فإذا سجد وضعها وإذا قام حملها. وكان يمازح الصغار، فقد كان لأخ أنس رضي الله عنه، وهو أبو عمير، طير صغير يلعب به، فمات، فكان النبي ﷺ يقول له: «يا أبا عمير، ما فعل النغير؟»، كما في الصحيحين. وحين بال أعرابي في المسجد وأراد الصحابة أن يزجروه، قال النبي ﷺ: «دعوه، وأريقوا على بوله سجلًا من ماء، فإنما بُعثتم ميسّرين ولم تبعثوا معسّرين»، كما في صحيح البخاري."], ["الكرم والشجاعة", "كان النبي ﷺ أجود الناس. روى البخاري عن ابن عباس رضي الله عنهما قال: كان النبي ﷺ أجود الناس، وكان أجود ما يكون في رمضان حين يلقاه جبريل، فلَرسول الله ﷺ أجود بالخير من الريح المرسلة. وفي الصحيحين عن جابر رضي الله عنه: ما سُئل رسول الله ﷺ شيئًا قط فقال: لا. وروى مسلم عن أنس رضي الله عنه أن رجلًا سأله فأعطاه غنمًا بين جبلين، فرجع إلى قومه فقال: يا قوم أسلموا، فإن محمدًا يعطي عطاء من لا يخشى الفقر. وأما شجاعته ﷺ فقد قال أنس رضي الله عنه في الصحيحين: كان النبي ﷺ أحسن الناس وأشجع الناس، ولقد فزع أهل المدينة ليلة، فانطلق ناس قبل الصوت، فتلقاهم النبي ﷺ راجعًا وقد سبقهم إلى الصوت وهو على فرس لأبي طلحة عُري في عنقه السيف، وهو يقول: «لم تُراعوا، لم تراعوا». وقال علي رضي الله عنه: كنا إذا حمي البأس واحمرّت الحدق اتقينا برسول الله ﷺ."], ["العفو والرفق", "روت عائشة رضي الله عنها في الصحيحين: ما خُيّر رسول الله ﷺ بين أمرين إلا أخذ أيسرهما ما لم يكن إثمًا، فإن كان إثمًا كان أبعد الناس منه، وما انتقم رسول الله ﷺ لنفسه في شيء قط إلا أن تُنتهك حرمة الله فينتقم لله بها. وفي صحيح البخاري أنه عاد من الطائف مجروحًا، فأرسل الله إليه ملك الجبال يستأذنه أن يطبق عليهم الأخشبين، فقال النبي ﷺ: «بل أرجو أن يُخرج الله من أصلابهم من يعبد الله وحده لا يشرك به شيئًا». وكان يعفو عن المسيء، فقد جاءه أعرابي فجبذ بردائه جبذة شديدة حتى أثّرت حاشية البرد في عنقه، فقال: يا محمد، مُر لي من مال الله الذي عندك، فالتفت إليه النبي ﷺ فضحك ثم أمر له بعطاء، كما في الصحيحين. وقال النبي ﷺ: «ليس الشديد بالصرعة، إنما الشديد الذي يملك نفسه عند الغضب»، رواه البخاري ومسلم."], ["صفته وهيئته وكلامه", "وصف الصحابة رضي الله عنهم النبي ﷺ وصفًا يجمع الجمال والوقار. قال البراء رضي الله عنه في البخاري: كان رسول الله ﷺ أحسن الناس وجهًا وأحسنهم خلقًا، ليس بالطويل البائن ولا بالقصير. وقال أنس رضي الله عنه: كان ربعة من القوم، ليس بالطويل ولا بالقصير، أزهر اللون، ليس بأبيض أمهق ولا آدم، كما في الصحيحين. وقال أنس: ما مسستُ ديباجًا ولا حريرًا ألين من كف رسول الله ﷺ، ولا شممتُ مسكًا ولا عنبرًا أطيب من ريح رسول الله ﷺ، رواه البخاري. وكان كثير التبسم، قال جرير رضي الله عنه: ما حجبني رسول الله ﷺ منذ أسلمتُ، ولا رآني إلا تبسّم في وجهي، كما في الصحيحين. وكان كلامه واضحًا مفصّلًا، قالت عائشة رضي الله عنها: كان يحدّث حديثًا لو عدّه العاد لأحصاه، رواه البخاري. وكان لا يعيب طعامًا قط، إن اشتهاه أكله وإن كرهه تركه."], ["عبادته وشكره لربه", "كان النبي ﷺ أعبد الناس لله، ومع ذلك كان أخشاهم له وأتقاهم. روى البخاري ومسلم عن المغيرة بن شعبة رضي الله عنه أن النبي ﷺ كان يقوم من الليل حتى تتورم قدماه، فقيل له: أتفعل هذا وقد غفر الله لك ما تقدم من ذنبك وما تأخر؟ قال: «أفلا أكون عبدًا شكورًا؟». وكان يقول: «يا أيها الناس، توبوا إلى الله، فإني أتوب في اليوم إليه مئة مرة»، رواه مسلم. وكان ﷺ يذكر الله على كل أحيانه، وكان إذا حزبه أمر فزع إلى الصلاة. وقد قالت عائشة رضي الله عنها إنه كان يبكي في صلاته، ورُوي أنها قالت: كان يُسمع لصدره أزيز كأزيز المرجل، رواه أبو داود والنسائي بإسناد صحيح. فقد جمع النبي ﷺ بين الصلاح الظاهر والخشوع الباطن، وبين الحب الكامل لله والخوف منه والرجاء في رحمته. وفي هذه الشمائل قدوة لكل من أراد أن يصلح خُلقه وعمله."]], "lesson": ["الأخلاق جزء أصيل من الدين، وقد بُعث النبي ﷺ ليتمم مكارم الأخلاق.", "التواضع لا ينقص من قدر صاحبه، فقد كان النبي ﷺ يخدم أهله ويخصف نعله.", "الرحمة بالصغار والضعفاء علامة على رحمة الله بالعبد: «من لا يَرحم لا يُرحم».", "العفو والحلم عند القدرة أعلى منازل الأخلاق، والعبادة والشكر سبيلا القرب من الله."], "cat": "seerah"}, {"id": "sr30", "title": "أمهات المؤمنين وأولاد النبي ﷺ", "type": "من السيرة النبوية", "verse": "وَأَزْوَاجُهُ أُمَّهَاتُهُمْ", "source": "سورة الأحزاب 33:6", "parts": [["مكانة أمهات المؤمنين", "قال الله تعالى في أزواج النبي ﷺ: ﴿النَّبِيُّ أَوْلَىٰ بِالْمُؤْمِنِينَ مِنْ أَنفُسِهِمْ وَأَزْوَاجُهُ أُمَّهَاتُهُمْ﴾، فجعلهن في منزلة الأمهات من حيث الاحترام وتحريم نكاحهن بعد النبي ﷺ، ولا يعني ذلك ثبوت أحكام الأمومة كلها من المحرمية والميراث. وفي سورة الأحزاب أيضًا خطاب لهن: ﴿يَا نِسَاءَ النَّبِيِّ لَسْتُنَّ كَأَحَدٍ مِّنَ النِّسَاءِ إِنِ اتَّقَيْتُنَّ﴾، وفيها بيان لمكانتهن وتحذيرهن من أسباب الفتنة، وأمرهن بالوقار والعبادة والتفقه في آيات الله والسنة التي تُتلى في بيوتهن. وقد كان لهن دور عظيم في نقل علم النبوة، فروت عائشة وأم سلمة وغيرهما كثيرًا من الأحاديث. وسنذكر فيما يلي من تزوج النبي ﷺ على الترتيب المشهور، مع التنبيه إلى أن تواريخ الزواج تختلف فيها الروايات في بعض الأحيان."], ["خديجة وسودة وعائشة", "أولى زوجاته ﷺ خديجة بنت خويلد رضي الله عنها، تزوجها قبل البعثة وهو في الخامسة والعشرين، ولم يتزوج عليها حتى ماتت، وهي أم أولاده كلهم إلا إبراهيم. ثم تزوج سودة بنت زمعة رضي الله عنها بمكة بعد وفاة خديجة، وكانت كبيرة السن، وقد وهبت ليلتها لعائشة رضي الله عنها كما في صحيح البخاري. وتزوج عائشة بنت أبي بكر رضي الله عنهما، فقد روى البخاري أنه تزوجها وهي بنت ست سنين، وبنى بها وهي بنت تسع، وهي الوحيدة التي تزوجها بكرًا. وكانت أحب أزواجه إليه، فقد سُئل: أي الناس أحب إليك؟ قال: «عائشة»، كما في الصحيحين. وكانت عالمة فقيهة روت ألوفًا من الأحاديث، وتوفيت رضي الله عنها سنة سبع وخمسين على المشهور، وتختلف الروايات في سنة وفاتها. وتبرّأت بالقرآن من حادثة الإفك، فنزلت براءتها من فوق سبع سماوات."], ["حفصة وزينب بنت خزيمة وأم سلمة", "تزوج النبي ﷺ حفصة بنت عمر رضي الله عنهما بعد وفاة زوجها خنيس بن حذافة رضي الله عنه الذي استشهد من جراح أحد أو بدر، وكانت حافظة للكتاب، وحُفظت عندها صحف القرآن بعد جمعها في عهد أبي بكر رضي الله عنه. وتزوج زينب بنت خزيمة رضي الله عنها، وكانت تلقب بأم المساكين لكثرة إطعامها وصدقتها، وماتت في حياة النبي ﷺ بعد مدة قصيرة من زواجها. وتزوج أم سلمة، هند بنت أبي أمية رضي الله عنها، بعد وفاة زوجها أبي سلمة رضي الله عنه، وقد كانت من أوائل المهاجرات. وأشارت على النبي ﷺ يوم الحديبية بالرأي الذي حلّ الأزمة. وهي آخر أمهات المؤمنين وفاةً على المشهور، وتختلف الروايات في سنة وفاتها. وكان من حكمة هذه الزيجات رعاية أرامل الشهداء وتكريم من فقدن أزواجهن في سبيل الله."], ["زينب بنت جحش وجويرية", "تزوج النبي ﷺ زينب بنت جحش رضي الله عنها، وكانت ابنة عمته أميمة بنت عبد المطلب، وقد كانت زوجة زيد بن حارثة رضي الله عنه، فلما طلّقها زيد زوّجها الله لنبيه ﷺ، قال تعالى: ﴿فَلَمَّا قَضَىٰ زَيْدٌ مِّنْهَا وَطَرًا زَوَّجْنَاكَهَا لِكَيْ لَا يَكُونَ عَلَى الْمُؤْمِنِينَ حَرَجٌ فِي أَزْوَاجِ أَدْعِيَائِهِمْ﴾. وكان القصد إبطال التبنّي الذي كان معهودًا في الجاهلية وبيان أن زوجة الابن بالتبني ليست كزوجة الابن من الصلب. وهي أول من لحق بالنبي ﷺ بعد وفاته من أزواجه، كما في صحيح مسلم أنه قال: «أسرعكن لحاقًا بي أطولكن يدًا»، وكانت زينب تتصدق بكثرة. وتزوج جويرية بنت الحارث رضي الله عنها، من بني المصطلق، بعد غزوتهم، وتختلف الروايات في سنة الغزوة بين الخامسة والسادسة. وقالت عائشة رضي الله عنها: ما رأيت امرأة أعظم بركة على قومها منها، فقد أُطلق بسببها أسرى بني المصطلق إكرامًا لمصاهرة النبي ﷺ لهم."], ["أم حبيبة وصفية وميمونة", "تزوج النبي ﷺ رملة بنت أبي سفيان رضي الله عنها، وتُكنّى أم حبيبة، وقد هاجرت إلى الحبشة مع زوجها عبيد الله بن جحش، فتنصّر هناك وبقيت على إسلامها، فتزوجها النبي ﷺ وهي بالحبشة، وزوّجه إياها النجاشي، وتختلف الروايات في تفاصيل ذلك وأصحها أنها كانت بأرض الحبشة. وبلغ إسلامها ثباتًا عظيمًا حتى إنها حين زارها أبوها وهو مشرك طوت دونه فراش النبي ﷺ، كما ذكر أهل السير. وتزوج صفية بنت حيي رضي الله عنها بعد خيبر، وأعتقها وجعل عتقها صداقها، كما في الصحيحين، وكانت من بني إسرائيل من سلالة هارون عليه السلام، وقد قال لها النبي ﷺ: «إنك لابنة نبي، وإن عمك لنبي، وإنك لتحت نبي». وتزوج ميمونة بنت الحارث رضي الله عنها بعد عمرة القضاء، وهي آخر من تزوج من أزواجه. وماتت بسَرِف، في الموضع نفسه الذي بنى بها فيه على المشهور."], ["أبناء النبي ﷺ وبناته", "أنجب النبي ﷺ من خديجة رضي الله عنها القاسم وعبد الله، ويسمى الطيب والطاهر، وماتا صغيرين قبل البعثة أو بعدها، وتختلف الروايات في ذلك. وأنجب منها أربع بنات: زينب ورقية وأم كلثوم وفاطمة رضي الله عنهن. وولد له إبراهيم رضي الله عنه من مارية القبطية رضي الله عنها بالمدينة، وقد مات صغيرًا. وفي الصحيحين عن أنس رضي الله عنه أن النبي ﷺ دخل عليه وهو يجود بنفسه، فجعلت عينا النبي ﷺ تذرفان، فقال له عبد الرحمن بن عوف: وأنت يا رسول الله؟ فقال: «يا ابن عوف، إنها رحمة»، ثم قال: «إن العين تدمع، والقلب يحزن، ولا نقول إلا ما يرضي ربنا، وإنا بفراقك يا إبراهيم لمحزونون». وكسفت الشمس يوم موته، فقال الناس: كسفت لموت إبراهيم، فقال النبي ﷺ: «إن الشمس والقمر آيتان من آيات الله، لا ينكسفان لموت أحد ولا لحياته»، رواه البخاري."], ["بنات النبي ﷺ ونسله", "تزوجت زينب رضي الله عنها من أبي العاص بن الربيع، وكان في صحبة غير مسلم ثم أسلم، ورُدّت إليه. وتزوج عثمان بن عفان رضي الله عنه رقية رضي الله عنها، فلما ماتت زوّجه النبي ﷺ أم كلثوم رضي الله عنها، ولذلك لُقّب ذا النورين. وقد تخلّف عثمان رضي الله عنه عن بدر لتمريض رقية رضي الله عنها فضرب له النبي ﷺ بسهمه وأجره، كما في صحيح البخاري. وأما فاطمة رضي الله عنها فتزوجها علي بن أبي طالب رضي الله عنه، وأنجبت الحسن والحسين ومحسنًا وزينب وأم كلثوم، وقال النبي ﷺ فيها: «فاطمة بضعة مني، فمن أغضبها أغضبني»، كما في صحيح البخاري، وقال: «الحسن والحسين سيدا شباب أهل الجنة»، رواه الترمذي وصححه. وماتت فاطمة رضي الله عنها بعد النبي ﷺ بنحو ستة أشهر، كما ثبت في الصحيحين، فكانت أول أهله لحوقًا به. وبهذا استمر نسل النبي ﷺ من فاطمة رضي الله عنها خاصة، وسائر أولاده ماتوا في حياته أو بعد وفاته بقليل."]], "lesson": ["لأمهات المؤمنين مكانة خاصة في الأمة، فهنّ أزواج النبي ﷺ ومعلّمات الأمة بما حفظنه من هديه.", "في بيت النبوة قدوة للأسرة المسلمة: رحمة وحبّ وعبادة وصبر على الشدة.", "حزن النبي ﷺ على ولده إبراهيم يعلّمنا أن البكاء رحمةً مباح، وأن الصبر والرضا بقضاء الله هما الأصل.", "تزوّج النبي ﷺ لحكم شرعية واجتماعية: تشريع، وتكريم الأرامل، وتأليف القلوب، وإبطال عادات الجاهلية."], "cat": "seerah"}];
